import CryptoKit
import Foundation

public let ToriiPdpCommitmentHeader = "sora-pdp-commitment"
public let ToriiAuthorizationHeader = "Authorization"
public let ToriiAPITokenHeader = "X-API-Token"
public let ToriiAccountIdHeader = "X-Account-Id"
public let ToriiDataspaceIdHeader = "X-Dataspace-Id"
public let ToriiAccountOnboardingTokenHeader = "X-Iroha-Onboarding-Token"

private final class ToriiRejectRedirectTaskDelegate: NSObject, URLSessionTaskDelegate, @unchecked Sendable {
    static let shared = ToriiRejectRedirectTaskDelegate()

    func urlSession(_ session: URLSession,
                    task: URLSessionTask,
                    willPerformHTTPRedirection response: HTTPURLResponse,
                    newRequest request: URLRequest,
                    completionHandler: @escaping (URLRequest?) -> Void) {
        completionHandler(nil)
    }
}

public struct ToriiClientAuthentication: Equatable, Sendable {
    public let headers: [String: String]

    public init(headers: [String: String] = [:]) {
        self.headers = Self.normalizedHeaders(headers).filter {
            $0.key.caseInsensitiveCompare(ToriiAccountOnboardingTokenHeader) != .orderedSame
        }
    }

    public static func bearerToken(
        _ token: String,
        accountId: String,
        dataspaceId: String? = nil,
        apiToken: String? = nil,
        additionalHeaders: [String: String] = [:]
    ) throws -> ToriiClientAuthentication {
        var headers = normalizedHeaders(additionalHeaders)
        setHeader(
            &headers,
            key: ToriiAuthorizationHeader,
            value: "Bearer \(try requiredHeaderValue(token, field: "token"))"
        )
        setHeader(
            &headers,
            key: ToriiAccountIdHeader,
            value: try requiredHeaderValue(accountId, field: "accountId")
        )
        if let dataspaceId = try optionalHeaderValue(dataspaceId, field: "dataspaceId") {
            setHeader(&headers, key: ToriiDataspaceIdHeader, value: dataspaceId)
        }
        if let apiToken = try optionalHeaderValue(apiToken, field: "apiToken") {
            setHeader(&headers, key: ToriiAPITokenHeader, value: apiToken)
        }
        return ToriiClientAuthentication(headers: headers)
    }

    public static func authorizationHeader(
        _ value: String,
        accountId: String,
        dataspaceId: String? = nil,
        apiToken: String? = nil,
        additionalHeaders: [String: String] = [:]
    ) throws -> ToriiClientAuthentication {
        var headers = normalizedHeaders(additionalHeaders)
        setHeader(
            &headers,
            key: ToriiAuthorizationHeader,
            value: try requiredHeaderValue(value, field: "authorizationHeader")
        )
        setHeader(
            &headers,
            key: ToriiAccountIdHeader,
            value: try requiredHeaderValue(accountId, field: "accountId")
        )
        if let dataspaceId = try optionalHeaderValue(dataspaceId, field: "dataspaceId") {
            setHeader(&headers, key: ToriiDataspaceIdHeader, value: dataspaceId)
        }
        if let apiToken = try optionalHeaderValue(apiToken, field: "apiToken") {
            setHeader(&headers, key: ToriiAPITokenHeader, value: apiToken)
        }
        return ToriiClientAuthentication(headers: headers)
    }

    fileprivate static func normalizedHeaders(_ headers: [String: String]) -> [String: String] {
        var normalized: [String: String] = [:]
        for (key, value) in headers {
            setHeader(&normalized, key: key, value: value)
        }
        return normalized
    }

    fileprivate static func setHeader(_ headers: inout [String: String], key: String, value: String?) {
        let trimmedKey = key.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedKey.isEmpty else { return }
        let canonical = canonicalHeaderKey(trimmedKey)
        let lower = canonical.lowercased()
        headers = headers.filter { $0.key.lowercased() != lower }
        if let value {
            headers[canonical] = value
        }
    }

    fileprivate static func canonicalHeaderKey(_ key: String) -> String {
        switch key.lowercased() {
        case "authorization": return ToriiAuthorizationHeader
        case "x-api-token": return ToriiAPITokenHeader
        case "x-account-id": return ToriiAccountIdHeader
        case "x-dataspace-id": return ToriiDataspaceIdHeader
        case "x-iroha-onboarding-token": return ToriiAccountOnboardingTokenHeader
        case "content-type": return "Content-Type"
        case "accept": return "Accept"
        default: return key
        }
    }

    private static func requiredHeaderValue(_ value: String, field: String) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
        }
        guard !trimmed.contains(where: { $0 == "\n" || $0 == "\r" }) else {
            throw ToriiClientError.invalidPayload("\(field) must not contain newline characters.")
        }
        return trimmed
    }

    private static func optionalHeaderValue(_ value: String?, field: String) throws -> String? {
        guard let value else { return nil }
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        return try requiredHeaderValue(trimmed, field: field)
    }
}

/// Immutable trust context required by Torii operations that return bytes for local signing.
public struct ToriiLocalSigningContext: Equatable, Sendable {
    /// Exact genesis-header-derived identity expected in every prepared signing payload.
    public let networkId: NetworkId

    public init(networkId: NetworkId) {
        self.networkId = networkId
    }
}

public func decodePdpCommitmentHeader(_ headers: [String: String]) throws -> Data? {
    guard !headers.isEmpty else { return nil }
    for (key, value) in headers {
        if key.caseInsensitiveCompare(ToriiPdpCommitmentHeader) == .orderedSame {
            guard let decoded = Data(base64Encoded: value) else {
                throw ToriiClientError.invalidPayload(
                    "\(ToriiPdpCommitmentHeader) header was not valid base64"
                )
            }
            return decoded
        }
    }
    return nil
}

public func decodePdpCommitmentHeader(from response: HTTPURLResponse) throws -> Data? {
    var normalized: [String: String] = [:]
    for (key, value) in response.allHeaderFields {
        guard let keyString = key as? String else { continue }
        if let stringValue = value as? String {
            normalized[keyString] = stringValue
        } else if let dataValue = value as? Data,
                  let rendered = String(data: dataValue, encoding: .utf8)
        {
            normalized[keyString] = rendered
        }
    }
    return try decodePdpCommitmentHeader(normalized)
}

func exactCanonicalToriiAccountAddress(
    _ raw: String
) throws -> (address: AccountAddress, chainDiscriminant: UInt16) {
    guard !raw.isEmpty,
          raw.utf8.elementsEqual(
              raw.trimmingCharacters(in: .whitespacesAndNewlines).utf8
          ),
          !raw.contains("@"),
          !raw.contains("#"),
          !raw.contains("$") else {
        throw AccountAddressError.unsupportedAddressFormat
    }
    let chainDiscriminant = try AccountAddress
        .inspectI105NetworkPrefix(raw).chainDiscriminant
    let address = try AccountAddress.parseCanonicalI105(
        raw,
        expectedPrefix: chainDiscriminant
    )
    let canonical = try address.toI105(networkPrefix: chainDiscriminant)
    guard canonical.utf8.elementsEqual(raw.utf8) else {
        throw AccountAddressError.unsupportedAddressFormat
    }
    return (address, chainDiscriminant)
}

/// Returns the universal account-controller identity without the I105 display discriminator.
func exactToriiAccountIdentityPayload(_ raw: String) throws -> Data {
    try exactCanonicalToriiAccountAddress(raw).address
        .compactNoritoAccountControllerPayload()
}

/// Compares canonical I105 literals by universal account identity, not display discriminator.
func toriiAccountIdsHaveSameIdentity(_ lhs: String, _ rhs: String) throws -> Bool {
    try exactToriiAccountIdentityPayload(lhs) == exactToriiAccountIdentityPayload(rhs)
}

fileprivate func normalizeToriiAccountIdQueryValue(_ raw: String, field: String) throws -> String {
    let exact = try requireToriiExactNonEmptyQueryValue(raw, field: field)
    if exact.contains("@") {
        return try normalizeToriiAccountAliasLiteral(exact, field: field)
    }
    if exact.contains("%") || exact.contains("/") || exact.contains("?") || exact.contains("#") {
        throw ToriiClientError.invalidPayload(
            "\(field) must be an encoded account id (i105)."
        )
    }
    if let canonical = try? exactCanonicalToriiAccountAddress(exact) {
        return try canonical.address.toI105(
            networkPrefix: canonical.chainDiscriminant
        )
    }
    throw ToriiClientError.invalidPayload(
        "\(field) must be an encoded account id (i105)."
    )
}

fileprivate func requireToriiExactNonEmptyQueryValue(_ raw: String, field: String) throws -> String {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
    }
    guard trimmed == raw else {
        throw ToriiClientError.invalidPayload("\(field) must not contain surrounding whitespace.")
    }
    return raw
}

fileprivate func normalizeToriiParticipantQueryValue(_ raw: String, field: String) throws -> String {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
    }
    guard !trimmed.contains(where: \.isWhitespace),
          !trimmed.contains("%"),
          !trimmed.contains("/"),
          !trimmed.contains("?"),
          !trimmed.contains("#")
    else {
        throw ToriiClientError.invalidPayload("\(field) must not contain whitespace or URL control characters.")
    }
    if trimmed.contains("@") {
        return try normalizeToriiAccountAliasLiteral(trimmed, field: field)
    }
    if let canonical = try? exactCanonicalToriiAccountAddress(trimmed) {
        return try canonical.address.toI105(
            networkPrefix: canonical.chainDiscriminant
        )
    }
    return trimmed
}

fileprivate func normalizeToriiAccountAliasLiteral(_ raw: String, field: String) throws -> String {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
    }
    guard !trimmed.contains(where: \.isWhitespace) else {
        throw ToriiClientError.invalidPayload("\(field) must not contain whitespace.")
    }
    guard !trimmed.contains("%"),
          !trimmed.contains("/"),
          !trimmed.contains("?"),
          !trimmed.contains("#")
    else {
        throw ToriiClientError.invalidPayload(
            "\(field) must use name@dataspace or name@domain.dataspace form."
        )
    }
    let components = trimmed.split(separator: "@", omittingEmptySubsequences: false)
    let scopeComponents = components.count == 2
        ? components[1].split(separator: ".", omittingEmptySubsequences: false)
        : []
    guard components.count == 2,
          !components[0].isEmpty,
          !components[1].isEmpty,
          (1...2).contains(scopeComponents.count),
          !scopeComponents.contains(where: \.isEmpty)
    else {
        throw ToriiClientError.invalidPayload(
            "\(field) must use name@dataspace or name@domain.dataspace form."
        )
    }
    return trimmed
}

fileprivate func normalizeToriiContractAliasLiteral(_ raw: String, field: String) throws -> String {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty, trimmed == raw else {
        throw ToriiClientError.invalidPayload(
            "\(field) must be exact non-empty contract-alias text."
        )
    }
    guard !trimmed.contains(where: \.isWhitespace) else {
        throw ToriiClientError.invalidPayload("\(field) must not contain whitespace.")
    }
    guard !trimmed.contains("%"),
          !trimmed.contains("/"),
          !trimmed.contains("?"),
          !trimmed.contains("#"),
          !trimmed.contains("@")
    else {
        throw ToriiClientError.invalidPayload(
            "\(field) must use name::dataspace or name::domain.dataspace form."
        )
    }
    let components = trimmed.components(separatedBy: "::")
    guard components.count == 2,
          !components[0].isEmpty,
          !components[1].isEmpty
    else {
        throw ToriiClientError.invalidPayload(
            "\(field) must use name::dataspace or name::domain.dataspace form."
        )
    }
    let scopeComponents = components[1].split(separator: ".", omittingEmptySubsequences: false)
    guard (1...2).contains(scopeComponents.count),
          !scopeComponents.contains(where: \.isEmpty)
    else {
        throw ToriiClientError.invalidPayload(
            "\(field) must use name::dataspace or name::domain.dataspace form."
        )
    }
    return trimmed
}

fileprivate func normalizeToriiContractAddressLiteral(_ raw: String, field: String) throws -> String {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty, trimmed == raw else {
        throw ToriiClientError.invalidPayload(
            "\(field) must be exact non-empty contract-address text."
        )
    }
    guard !trimmed.contains(where: \.isWhitespace),
          !trimmed.contains("%"),
          !trimmed.contains("/"),
          !trimmed.contains("?"),
          !trimmed.contains("#"),
          trimmed == trimmed.lowercased()
    else {
        throw ToriiClientError.invalidPayload("\(field) must be a canonical contract address.")
    }
    return trimmed
}

fileprivate func normalizeToriiContractTargetSelector(contractAddress: String?,
                                                      contractAlias: String?,
                                                      field: String) throws -> (contractAddress: String?, contractAlias: String?) {
    let normalizedContractAddress = try contractAddress.map {
        try normalizeToriiContractAddressLiteral($0, field: "\(field).contract_address")
    }
    let normalizedContractAlias = try contractAlias.map {
        try normalizeToriiContractAliasLiteral($0, field: "\(field).contract_alias")
    }
    guard (normalizedContractAddress == nil) != (normalizedContractAlias == nil) else {
        throw ToriiClientError.invalidPayload(
            "\(field) requires exactly one of contract_address or contract_alias."
        )
    }
    return (normalizedContractAddress, normalizedContractAlias)
}

fileprivate func normalizeToriiAssetDefinitionIdValue(_ raw: String, field: String) throws -> String {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
    }
    guard !trimmed.contains(where: \.isWhitespace),
          !trimmed.contains("@"),
          !trimmed.contains("#"),
          !trimmed.contains("%"),
          !trimmed.contains("/"),
          !trimmed.contains("?"),
          !trimmed.contains(":"),
          AssetDefinitionAddress.decode(trimmed) != nil else {
        throw ToriiClientError.invalidPayload(
            "\(field) must use a canonical unprefixed Base58 asset definition id."
        )
    }
    return trimmed
}

fileprivate func normalizeToriiAssetAliasLiteral(_ raw: String, field: String) throws -> String {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
    }
    guard !trimmed.contains(where: \.isWhitespace) else {
        throw ToriiClientError.invalidPayload("\(field) must not contain whitespace.")
    }
    let components = trimmed.split(separator: "#", omittingEmptySubsequences: false)
    let scopeComponents = components.count == 2
        ? components[1].split(separator: ".", omittingEmptySubsequences: false)
        : []
    guard components.count == 2,
          !components[0].isEmpty,
          !components[1].isEmpty,
          (1...2).contains(scopeComponents.count),
          !scopeComponents.contains(where: \.isEmpty),
          !components[0].contains("@")
    else {
        throw ToriiClientError.invalidPayload(
            "\(field) must use name#dataspace or name#domain.dataspace form."
        )
    }
    return trimmed.lowercased()
}

fileprivate func normalizeToriiAssetIdQueryValue(_ raw: String, field: String) throws -> String {
    let exact = try requireToriiExactNonEmptyQueryValue(raw, field: field)
    do {
        let canonical = try CanonicalNorito.canonicalAssetIdLiteral(exact)
        guard canonical == exact else {
            throw ToriiClientError.invalidPayload(
                "\(field) must use its exact canonical asset-id spelling."
            )
        }
        return exact
    } catch let error as ToriiClientError {
        throw error
    } catch {
        throw ToriiClientError.invalidPayload(
            "\(field) must be a canonical public asset identifier."
        )
    }
}

fileprivate func normalizeToriiAssetSelectorQueryValue(_ raw: String, field: String) throws -> String {
    let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else {
        throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
    }
    if AssetDefinitionAddress.decode(trimmed) != nil {
        return try normalizeToriiAssetDefinitionIdValue(trimmed, field: field)
    }
    return try normalizeToriiAssetAliasLiteral(trimmed, field: field)
}

fileprivate func canonicalPublicAssetDefinitionLiteral(_ raw: String?) -> String? {
    let trimmed = raw?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    guard !trimmed.isEmpty else {
        return nil
    }
    guard !trimmed.contains("#"),
          AssetDefinitionAddress.decode(trimmed) != nil else {
        return nil
    }
    return trimmed
}

struct ToriiAnyCodingKey: CodingKey {
    let stringValue: String
    let intValue: Int?

    init(_ stringValue: String) {
        self.stringValue = stringValue
        intValue = nil
    }

    init?(stringValue: String) {
        self.init(stringValue)
    }

    init?(intValue: Int) {
        stringValue = String(intValue)
        self.intValue = intValue
    }
}

fileprivate func rejectUnknownJSONFields(
    from decoder: Decoder,
    allowed: Set<String>,
    debugName: String
) throws {
    let container = try decoder.container(keyedBy: ToriiAnyCodingKey.self)
    guard container.allKeys.allSatisfy({ allowed.contains($0.stringValue) }) else {
        throw DecodingError.dataCorrupted(
            .init(
                codingPath: decoder.codingPath,
                debugDescription: "\(debugName) contains an unknown or retired field"
            )
        )
    }
}

func requireExactJSONFields(
    from decoder: Decoder,
    required: Set<String>,
    optional: Set<String> = [],
    debugName: String
) throws {
    let container = try decoder.container(keyedBy: ToriiAnyCodingKey.self)
    let actual = Set(container.allKeys.map(\.stringValue))
    let allowed = required.union(optional)
    if let unknown = actual.subtracting(allowed).sorted().first {
        throw DecodingError.dataCorruptedError(
            forKey: ToriiAnyCodingKey(unknown),
            in: container,
            debugDescription: "\(debugName) contains unknown field `\(unknown)`"
        )
    }
    if let missing = required.subtracting(actual).sorted().first {
        throw DecodingError.keyNotFound(
            ToriiAnyCodingKey(missing),
            .init(
                codingPath: decoder.codingPath,
                debugDescription: "\(debugName) requires field `\(missing)`"
            )
        )
    }
}

fileprivate func decodeRequiredNullableString<K: CodingKey>(
    from container: KeyedDecodingContainer<K>,
    forKey key: K,
    debugName: String
) throws -> String? {
    if try container.decodeNil(forKey: key) {
        return nil
    }
    do {
        return try container.decode(String.self, forKey: key)
    } catch {
        throw DecodingError.typeMismatch(
            String.self,
            .init(
                codingPath: container.codingPath + [key],
                debugDescription: "\(debugName) must be a string or null.",
                underlyingError: error
            )
        )
    }
}

fileprivate func decodeOmittedOptional<T: Decodable, K: CodingKey>(
    _ type: T.Type,
    from container: KeyedDecodingContainer<K>,
    forKey key: K,
    debugName: String
) throws -> T? {
    guard container.contains(key) else {
        return nil
    }
    if try container.decodeNil(forKey: key) {
        throw DecodingError.dataCorruptedError(
            forKey: key,
            in: container,
            debugDescription: "\(debugName) must be omitted instead of null."
        )
    }
    return try container.decode(T.self, forKey: key)
}

fileprivate func decodeOptionalStringValue(
    from container: KeyedDecodingContainer<ToriiAnyCodingKey>,
    keys: [String]
) throws -> String? {
    for key in keys {
        let codingKey = ToriiAnyCodingKey(key)
        guard container.contains(codingKey) else {
            continue
        }
        let value = try container.decodeIfPresent(String.self, forKey: codingKey)?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if let value, !value.isEmpty {
            return value
        }
    }
    return nil
}

fileprivate func decodeExactToriiAccountId<K: CodingKey>(
    from container: KeyedDecodingContainer<K>,
    forKey key: K,
    debugName: String
) throws -> String {
    let raw = try ToriiIdentifierReceiptWireValue.exactString(
        from: container,
        forKey: key,
        debugName: debugName
    )
    guard !raw.contains("@") else {
        throw DecodingError.dataCorruptedError(
            forKey: key,
            in: container,
            debugDescription: "\(debugName) must be a canonical account identifier."
        )
    }
    let normalized = try normalizeToriiAccountIdQueryValue(raw, field: debugName)
    guard normalized == raw else {
        throw DecodingError.dataCorruptedError(
            forKey: key,
            in: container,
            debugDescription: "\(debugName) must be a canonical account identifier."
        )
    }
    return raw
}

fileprivate func decodeRequiredStringValue(
    from container: KeyedDecodingContainer<ToriiAnyCodingKey>,
    keys: [String],
    decoder: Decoder,
    debugDescription: String
) throws -> String {
    if let value = try decodeOptionalStringValue(from: container, keys: keys) {
        return value
    }
    throw DecodingError.keyNotFound(
        ToriiAnyCodingKey(keys[0]),
        DecodingError.Context(
            codingPath: decoder.codingPath,
            debugDescription: debugDescription
        )
    )
}

func decodeCanonicalToriiQuantity(_ value: String, field: String) throws -> String {
    do {
        return try KotodamaNumericV1Codec.decodeQuantityJSON(value).canonicalString
    } catch let error as KotodamaNumericV1Error {
        throw ToriiClientError.invalidPayload(
            "\(field) must be a canonical non-negative Kotodama V1 quantity (\(error.code.rawValue))."
        )
    }
}

public struct ToriiAssetAliasResolution: Decodable, Sendable {
    public let alias: String
    public let assetDefinitionId: String
    public let assetName: String
    public let description: String?
    public let logo: String?
    public let source: String?
    public let aliasBinding: ToriiAssetDefinitionAliasBinding?

    private enum CodingKeys: String, CodingKey {
        case alias
        case assetDefinitionId = "asset_definition_id"
        case assetName = "asset_name"
        case description
        case logo
        case source
        case aliasBinding = "alias_binding"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        alias = try container.decode(String.self, forKey: .alias)
        let rawAssetDefinitionId = try container.decode(String.self, forKey: .assetDefinitionId)
        assetDefinitionId = canonicalPublicAssetDefinitionLiteral(rawAssetDefinitionId) ?? rawAssetDefinitionId
        assetName = try container.decode(String.self, forKey: .assetName)
        description = try container.decodeIfPresent(String.self, forKey: .description)
        logo = try container.decodeIfPresent(String.self, forKey: .logo)
        source = try container.decodeIfPresent(String.self, forKey: .source)
        aliasBinding = try container.decodeIfPresent(ToriiAssetDefinitionAliasBinding.self, forKey: .aliasBinding)
    }
}

public struct ToriiAssetDefinitionAliasBinding: Decodable, Sendable {
    public let alias: String
    public let status: String
    public let leaseExpiryMs: UInt64?
    public let graceUntilMs: UInt64?
    public let boundAtMs: UInt64

    private enum CodingKeys: String, CodingKey {
        case alias
        case status
        case leaseExpiryMs = "lease_expiry_ms"
        case graceUntilMs = "grace_until_ms"
        case boundAtMs = "bound_at_ms"
    }
}

public struct ToriiAccountAliasResolution: Decodable, Sendable {
    public let alias: String
    public let accountId: String
    public let index: UInt64?
    public let source: String?

    private enum CodingKeys: String, CodingKey {
        case alias
        case accountId = "account_id"
        case index
        case source
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: ["alias", "account_id", "index", "source"],
            debugName: "account alias resolution"
        )
        let decodedAlias = try ToriiIdentifierReceiptWireValue.exactString(
            from: container,
            forKey: .alias,
            debugName: "account alias resolution.alias"
        )
        guard (try? AccountAliasName(parsing: decodedAlias).canonicalText) == decodedAlias else {
            throw DecodingError.dataCorruptedError(
                forKey: .alias,
                in: container,
                debugDescription: "account alias resolution.alias must be canonical"
            )
        }
        alias = decodedAlias
        let decodedAccountId = try ToriiIdentifierReceiptWireValue.exactString(
            from: container,
            forKey: .accountId,
            debugName: "account alias resolution.account_id"
        )
        guard !decodedAccountId.contains("@"),
              (try? normalizeToriiAccountIdQueryValue(
                  decodedAccountId,
                  field: "account_id"
              )) == decodedAccountId else {
            throw DecodingError.dataCorruptedError(
                forKey: .accountId,
                in: container,
                debugDescription:
                    "account alias resolution.account_id must be canonical and domainless"
            )
        }
        accountId = decodedAccountId
        index = try container.decodeIfPresent(UInt64.self, forKey: .index)
        source = try ToriiIdentifierReceiptWireValue.exactOptionalString(
            from: container,
            forKey: .source,
            debugName: "account alias resolution.source"
        )
    }
}

public enum ToriiIdentifierNormalization: String, Codable, Sendable {
    case exact
    case lowercaseTrimmed = "lowercase_trimmed"
    case phoneE164 = "phone_e164"
    case emailAddress = "email_address"
    case accountNumber = "account_number"

    public func normalize(_ value: String, field: String = "identifier") throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
        }
        switch self {
        case .exact:
            return trimmed
        case .lowercaseTrimmed:
            return trimmed.lowercased()
        case .phoneE164:
            let compact = trimmed.filter { !" \t\n\r-().".contains($0) }
            let withoutPrefix: Substring
            if compact.hasPrefix("+") {
                withoutPrefix = compact.dropFirst()
            } else if compact.hasPrefix("00") {
                withoutPrefix = compact.dropFirst(2)
            } else {
                withoutPrefix = Substring(compact)
            }
            guard !withoutPrefix.isEmpty, withoutPrefix.allSatisfy(\.isNumber) else {
                throw ToriiClientError.invalidPayload("\(field) must contain digits with optional leading `+` or `00`.")
            }
            return "+\(withoutPrefix)"
        case .emailAddress:
            let lowered = trimmed.lowercased()
            let components = lowered.split(separator: "@", omittingEmptySubsequences: false)
            guard components.count == 2,
                  !components[0].isEmpty,
                  !components[1].isEmpty
            else {
                throw ToriiClientError.invalidPayload("\(field) must contain exactly one `@` with non-empty local and domain parts.")
            }
            return lowered
        case .accountNumber:
            let normalized = trimmed
                .filter { !" \t\n\r-".contains($0) }
                .uppercased()
            guard !normalized.isEmpty,
                  normalized.allSatisfy({ $0.isASCII && ($0.isLetter || $0.isNumber || $0 == "_" || $0 == "/" || $0 == ".") })
            else {
                throw ToriiClientError.invalidPayload("\(field) must contain ASCII alphanumeric characters, `_`, `/`, or `.`.")
            }
            return normalized
        }
    }
}

public struct ToriiIdentifierPolicySummary: Decodable, Sendable {
    public let policyId: String
    public let programId: String
    public let owner: String
    public let active: Bool
    public let normalization: ToriiIdentifierNormalization
    public let resolverPublicKey: String
    public let outputOpeningPublicKey: String
    public let backend: String
    public let inputEncryption: String?
    public let inputEncryptionPublicParameters: String?
    public let inputEncryptionPublicParametersDecoded: ToriiIdentifierBfvPublicParameters?
    public let ramFheProfile: ToriiIdentifierRamFheProfile?
    public let proofVerifier: ToriiRamLfeProofVerifierMetadata?
    public let note: String?

    private enum CodingKeys: String, CodingKey {
        case policyId = "policy_id"
        case programId = "program_id"
        case owner
        case active
        case normalization
        case resolverPublicKey = "resolver_public_key"
        case outputOpeningPublicKey = "output_opening_public_key"
        case backend
        case inputEncryption = "input_encryption"
        case inputEncryptionPublicParameters = "input_encryption_public_parameters"
        case inputEncryptionPublicParametersDecoded = "input_encryption_public_parameters_decoded"
        case ramFheProfile = "ram_fhe_profile"
        case proofVerifier = "proof_verifier"
        case note
    }

    public init(policyId: String,
                programId: String,
                owner: String,
                active: Bool,
                normalization: ToriiIdentifierNormalization,
                resolverPublicKey: String,
                outputOpeningPublicKey: String,
                backend: String,
                inputEncryption: String?,
                inputEncryptionPublicParameters: String?,
                inputEncryptionPublicParametersDecoded: ToriiIdentifierBfvPublicParameters?,
                ramFheProfile: ToriiIdentifierRamFheProfile?,
                proofVerifier: ToriiRamLfeProofVerifierMetadata?,
                note: String?) {
        self.policyId = policyId
        self.programId = programId
        self.owner = owner
        self.active = active
        self.normalization = normalization
        self.resolverPublicKey = resolverPublicKey
        self.outputOpeningPublicKey = outputOpeningPublicKey
        self.backend = backend
        self.inputEncryption = inputEncryption
        self.inputEncryptionPublicParameters = inputEncryptionPublicParameters
        self.inputEncryptionPublicParametersDecoded = inputEncryptionPublicParametersDecoded
        self.ramFheProfile = ramFheProfile
        self.proofVerifier = proofVerifier
        self.note = note
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let normalizationRaw = try ToriiIdentifierReceiptWireValue.exactLowercaseString(
            from: container,
            forKey: .normalization,
            debugName: "identifier policy.normalization"
        )
        guard let normalization = ToriiIdentifierNormalization(rawValue: normalizationRaw) else {
            throw DecodingError.dataCorruptedError(
                forKey: .normalization,
                in: container,
                debugDescription: "identifier policy.normalization must be a supported wire value."
            )
        }
        let inputEncryption = try ToriiIdentifierReceiptWireValue.exactOptionalString(
            from: container,
            forKey: .inputEncryption,
            debugName: "identifier policy.input_encryption"
        )
        if let inputEncryption, inputEncryption != inputEncryption.lowercased() {
            throw DecodingError.dataCorruptedError(
                forKey: .inputEncryption,
                in: container,
                debugDescription: "identifier policy.input_encryption must be an exact lowercase wire value."
            )
        }
        self.init(
            policyId: try ToriiIdentifierReceiptWireValue.exactPolicyId(
                from: container,
                forKey: .policyId,
                debugName: "identifier policy.policy_id"
            ),
            programId: try ToriiIdentifierReceiptWireValue.requiredPolicyBinding(
                from: container,
                forKey: .programId,
                debugName: "identifier policy.program_id"
            ),
            owner: try ToriiIdentifierReceiptWireValue.exactAccountId(
                from: container,
                forKey: .owner,
                debugName: "identifier policy.owner"
            ),
            active: try container.decode(Bool.self, forKey: .active),
            normalization: normalization,
            resolverPublicKey: try ToriiIdentifierReceiptWireValue.exactString(
                from: container,
                forKey: .resolverPublicKey,
                debugName: "identifier policy.resolver_public_key"
            ),
            outputOpeningPublicKey: try ToriiIdentifierReceiptWireValue.requiredPolicyBinding(
                from: container,
                forKey: .outputOpeningPublicKey,
                debugName: "identifier policy.output_opening_public_key"
            ),
            backend: try ToriiIdentifierReceiptWireValue.exactRamLfeTag(
                from: container,
                forKey: .backend,
                debugName: "identifier policy.backend",
                kind: .backend
            ),
            inputEncryption: inputEncryption,
            inputEncryptionPublicParameters: try ToriiIdentifierReceiptWireValue.exactOptionalEvenLengthHex(
                from: container,
                forKey: .inputEncryptionPublicParameters,
                debugName: "identifier policy.input_encryption_public_parameters"
            ),
            inputEncryptionPublicParametersDecoded: try container.decodeIfPresent(
                ToriiIdentifierBfvPublicParameters.self,
                forKey: .inputEncryptionPublicParametersDecoded
            ),
            ramFheProfile: try container.decodeIfPresent(
                ToriiIdentifierRamFheProfile.self,
                forKey: .ramFheProfile
            ),
            proofVerifier: try container.decodeIfPresent(
                ToriiRamLfeProofVerifierMetadata.self,
                forKey: .proofVerifier
            ),
            note: try ToriiIdentifierReceiptWireValue.exactOptionalString(
                from: container,
                forKey: .note,
                debugName: "identifier policy.note"
            )
        )
    }

    public func withProgramPolicy(_ programPolicy: ToriiRamLfeProgramPolicySummary) -> ToriiIdentifierPolicySummary {
        ToriiIdentifierPolicySummary(
            policyId: policyId,
            programId: programPolicy.programId,
            owner: owner,
            active: active,
            normalization: normalization,
            resolverPublicKey: resolverPublicKey,
            outputOpeningPublicKey: outputOpeningPublicKey,
            backend: backend,
            inputEncryption: inputEncryption,
            inputEncryptionPublicParameters: inputEncryptionPublicParameters,
            inputEncryptionPublicParametersDecoded: inputEncryptionPublicParametersDecoded,
            ramFheProfile: ramFheProfile,
            proofVerifier: proofVerifier,
            note: note
        )
    }
}

