fileprivate enum ToriiIdentifierReceiptWireValue {
    enum RamLfeTagKind {
        case backend
        case verificationMode

        var allowedValues: [String] {
            switch self {
            case .backend:
                return ["hkdf-sha3-512-prf-v1", "bfv-affine-v1", "bfv-programmed-v1"]
            case .verificationMode:
                return ["signed", "proof"]
            }
        }
    }

    static func exactRamLfeTag<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String,
        kind: RamLfeTagKind
    ) throws -> String {
        let raw = try exactLowercaseString(from: container, forKey: key, debugName: debugName)
        guard kind.allowedValues.contains(raw) else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must be one of: \(kind.allowedValues.joined(separator: ", "))."
            )
        }
        return raw
    }

    static func normalizedHash(_ raw: String, field: String) throws -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed == raw else {
            throw ToriiClientError.invalidPayload("\(field) must not contain surrounding whitespace.")
        }
        var body = raw
        if body.lowercased().hasPrefix("hash:") {
            body = String(body.dropFirst("hash:".count))
        }
        if let suffix = body.firstIndex(of: "#") {
            body = String(body[..<suffix])
        }
        if body.hasPrefix("0x") || body.hasPrefix("0X") {
            body = String(body.dropFirst(2))
        }
        return body.lowercased()
    }

    static func normalizedOpaqueId(_ raw: String, field: String = "payload.opaque_id") throws -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed == raw else {
            throw ToriiClientError.invalidPayload("\(field) must not contain surrounding whitespace.")
        }
        let lower = raw.lowercased()
        guard lower.hasPrefix("opaque:") else {
            return lower
        }
        return "opaque:\(try normalizedHash(String(raw.dropFirst(7)), field: field))"
    }

    static func normalizedUaid(_ raw: String, field: String = "payload.uaid") throws -> String {
        let lowercaseHex = CharacterSet(charactersIn: "0123456789abcdef")
        let digest = raw.hasPrefix("uaid:") ? String(raw.dropFirst(5)) : ""
        guard raw.count == 69,
              digest.count == 64,
              digest.unicodeScalars.allSatisfy({ lowercaseHex.contains($0) }) else {
            throw ToriiClientError.invalidPayload(
                "\(field) must be an exact canonical uaid:<64 lowercase hex> literal."
            )
        }
        guard let last = digest.last,
              "13579bdf".contains(last) else {
            throw ToriiClientError.invalidPayload(
                "\(field) must have least significant bit set to 1."
            )
        }
        return raw
    }

    static func normalizedPolicyId<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K
    ) throws -> String {
        try container.decode(String.self, forKey: key)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    static func exactReceiptPolicyId<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K
    ) throws -> String {
        try exactPolicyId(from: container, forKey: key, debugName: "payload.policy_id")
    }

    static func exactPolicyId<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String {
        let raw = try container.decode(String.self, forKey: key)
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not be empty."
            )
        }
        guard trimmed == raw else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not contain surrounding whitespace."
            )
        }
        let parts = raw.split(
            separator: "#",
            maxSplits: 1,
            omittingEmptySubsequences: false
        )
        guard parts.count == 2, !parts[0].isEmpty, !parts[1].isEmpty else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must use `kind#rule`."
            )
        }
        let kind = String(parts[0])
        let rule = String(parts[1])
        guard kind.trimmingCharacters(in: .whitespacesAndNewlines) == kind else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName).kind must not contain surrounding whitespace."
            )
        }
        guard rule.trimmingCharacters(in: .whitespacesAndNewlines) == rule else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName).rule must not contain surrounding whitespace."
            )
        }
        return raw
    }

    static func normalizedProgramId<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K
    ) throws -> String? {
        guard container.contains(key) else {
            return nil
        }
        return try container.decode(String.self, forKey: key)
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    static func requiredPolicyBinding<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String {
        let raw = try exactString(from: container, forKey: key, debugName: debugName)
        guard !raw.unicodeScalars.contains(where: {
            CharacterSet.whitespacesAndNewlines.contains($0) || CharacterSet.controlCharacters.contains($0)
        }) else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not contain whitespace or control characters."
            )
        }
        return raw
    }

    static func exactProgramId<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String? {
        guard container.contains(key) else {
            return nil
        }
        let raw = try container.decode(String.self, forKey: key)
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not be empty."
            )
        }
        guard trimmed == raw else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not contain surrounding whitespace."
            )
        }
        return raw
    }

    static func normalizedVerificationMode<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K
    ) throws -> String? {
        guard container.contains(key) else {
            return nil
        }
        return try exactRamLfeTag(
            from: container,
            forKey: key,
            debugName: "payload.execution.verification_mode",
            kind: .verificationMode
        )
    }

    static func normalizedHashValue<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K
    ) throws -> String? {
        guard container.contains(key) else {
            return nil
        }
        return try normalizedHash(try container.decode(String.self, forKey: key), field: key.stringValue)
    }

    static func normalizedOpaqueId<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K
    ) throws -> String {
        try normalizedOpaqueId(try container.decode(String.self, forKey: key), field: key.stringValue)
    }

    static func normalizedUaid<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K
    ) throws -> String {
        try normalizedUaid(try container.decode(String.self, forKey: key), field: key.stringValue)
    }

    static func exactAccountId<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String {
        let raw = try container.decode(String.self, forKey: key)
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not be empty."
            )
        }
        guard trimmed == raw else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not contain surrounding whitespace."
            )
        }
        do {
            _ = try exactCanonicalToriiAccountAddress(raw)
        } catch {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must be a canonical account identifier."
            )
        }
        return raw
    }

    static func exactString<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String {
        let raw = try container.decode(String.self, forKey: key)
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not be empty."
            )
        }
        guard trimmed == raw else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not contain surrounding whitespace."
            )
        }
        return raw
    }

    static func exactOptionalString<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String? {
        guard let raw = try container.decodeIfPresent(String.self, forKey: key) else {
            return nil
        }
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not be empty."
            )
        }
        guard trimmed == raw else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must not contain surrounding whitespace."
            )
        }
        return raw
    }

    static func exactLowercaseString<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String {
        let raw = try exactString(from: container, forKey: key, debugName: debugName)
        guard raw == raw.lowercased() else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must be an exact lowercase RAM-LFE tag."
            )
        }
        return raw
    }

    static func exactHash<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String {
        let normalized = try normalizedHash(
            try container.decode(String.self, forKey: key),
            field: debugName
        )
        guard normalized.count == 64, normalized.allSatisfy(\.isHexDigit) else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must be a 32-byte hex string."
            )
        }
        return normalized
    }

    static func exactEvenLengthHex<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String {
        let raw = try exactString(from: container, forKey: key, debugName: debugName)
        let body: String
        if raw.hasPrefix("0x") || raw.hasPrefix("0X") {
            body = String(raw.dropFirst(2))
        } else {
            body = raw
        }
        guard !body.isEmpty, body.count.isMultiple(of: 2), body.allSatisfy(\.isHexDigit) else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must be an even-length hex string."
            )
        }
        return body
    }

    static func exactOptionalEvenLengthHex<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        forKey key: K,
        debugName: String
    ) throws -> String? {
        guard let raw = try exactOptionalString(from: container, forKey: key, debugName: debugName) else {
            return nil
        }
        let body: String
        if raw.hasPrefix("0x") || raw.hasPrefix("0X") {
            body = String(raw.dropFirst(2))
        } else {
            body = raw
        }
        guard !body.isEmpty, body.count.isMultiple(of: 2), body.allSatisfy(\.isHexDigit) else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(debugName) must be an even-length hex string."
            )
        }
        return body
    }
}

enum ToriiIdentifierReceiptCanonicalEncoder {
    static func canonicalPayloadBytes(
        for receipt: ToriiIdentifierResolutionReceipt
    ) throws -> Data {
        try encodePayload(receipt.payload)
    }

    static func encodePayload(_ payload: ToriiIdentifierResolutionPayload) throws -> Data {
        let (policyKind, businessRule) = try parsePolicyId(payload.policyId)
        let execution = payload.execution

        var policyId = CompactNoritoWriter()
        policyId.writeField(CompactNorito.encodeString(policyKind))
        policyId.writeField(CompactNorito.encodeString(businessRule))

        var programId = CompactNoritoWriter()
        programId.writeField(
            CompactNorito.encodeString(
                try exactNonEmpty(
                    execution.programId,
                    field: "payload.execution.programId"
                )
            )
        )

        var executionPayload = CompactNoritoWriter()
        executionPayload.writeField(programId.data)
        executionPayload.writeField(
            try encodeHash(
                execution.programDigest,
                field: "payload.execution.programDigest"
            )
        )
        executionPayload.writeField(
            CompactNorito.encodeUInt32(try backendTag(execution.backend))
        )
        executionPayload.writeField(
            CompactNorito.encodeUInt32(
                try verificationModeTag(execution.verificationMode)
            )
        )
        executionPayload.writeField(
            try encodeHash(
                execution.inputCiphertextHash,
                field: "payload.execution.inputCiphertextHash"
            )
        )
        executionPayload.writeField(
            try encodeHash(
                execution.outputCiphertextHash,
                field: "payload.execution.outputCiphertextHash"
            )
        )
        executionPayload.writeField(
            try encodeHash(
                execution.parameterDigest,
                field: "payload.execution.parameterDigest"
            )
        )
        executionPayload.writeField(
            try encodeHash(
                execution.evaluationKeyDigest,
                field: "payload.execution.evaluationKeyDigest"
            )
        )
        executionPayload.writeField(
            try encodeHash(
                execution.outputHash,
                field: "payload.execution.outputHash"
            )
        )
        executionPayload.writeField(
            try encodeHash(
                execution.associatedDataHash,
                field: "payload.execution.associatedDataHash"
            )
        )
        executionPayload.writeField(CompactNorito.encodeUInt64(execution.executedAtMs))
        executionPayload.writeField(
            try CompactNorito.encodeOption(
                execution.expiresAtMs,
                encode: CompactNorito.encodeUInt64
            )
        )

        let opening = payload.opening
        var openingProgramId = CompactNoritoWriter()
        openingProgramId.writeField(
            CompactNorito.encodeString(
                try exactNonEmpty(
                    opening.payload.programId,
                    field: "payload.opening.payload.programId"
                )
            )
        )
        var openingPayload = CompactNoritoWriter()
        openingPayload.writeField(openingProgramId.data)
        openingPayload.writeField(
            try encodeHash(
                opening.payload.inputCiphertextHash,
                field: "payload.opening.payload.inputCiphertextHash"
            )
        )
        openingPayload.writeField(
            try encodeHash(
                opening.payload.outputCiphertextHash,
                field: "payload.opening.payload.outputCiphertextHash"
            )
        )
        openingPayload.writeField(
            try encodeHash(
                opening.payload.parameterDigest,
                field: "payload.opening.payload.parameterDigest"
            )
        )
        openingPayload.writeField(
            try encodeHash(
                opening.payload.evaluationKeyDigest,
                field: "payload.opening.payload.evaluationKeyDigest"
            )
        )
        openingPayload.writeField(
            try encodeHash(
                opening.payload.openedOutputHash,
                field: "payload.opening.payload.openedOutputHash"
            )
        )
        openingPayload.writeField(CompactNorito.encodeUInt64(opening.payload.openedAtMs))
        openingPayload.writeField(
            try CompactNorito.encodeOption(
                opening.payload.expiresAtMs,
                encode: CompactNorito.encodeUInt64
            )
        )
        var openingWriter = CompactNoritoWriter()
        openingWriter.writeField(openingPayload.data)
        openingWriter.writeField(
            encodeConstVec(
                try decodeHex(opening.signature, field: "payload.opening.signature")
            )
        )

        var payloadWriter = CompactNoritoWriter()
        payloadWriter.writeField(policyId.data)
        payloadWriter.writeField(executionPayload.data)
        payloadWriter.writeField(openingWriter.data)
        payloadWriter.writeField(
            try encodePrefixedHash(
                payload.opaqueId,
                prefix: "opaque:",
                field: "payload.opaqueId"
            )
        )
        payloadWriter.writeField(
            try encodeHash(payload.receiptHash, field: "payload.receiptHash")
        )
        payloadWriter.writeField(
            try encodePrefixedHash(
                payload.uaid,
                prefix: "uaid:",
                field: "payload.uaid"
            )
        )
        payloadWriter.writeField(try encodeAccountId(payload.accountId))
        return payloadWriter.data
    }

    static func encodeAttestation(_ attestation: ToriiIdentifierReceiptAttestation) throws -> Data {
        var writer = CompactNoritoWriter()
        switch attestation.kind {
        case "signed":
            guard let signature = attestation.signature else {
                throw ToriiClientError.invalidPayload("signed attestation requires signature.")
            }
            writer.writeUInt32LE(0)
            writer.writeField(
                encodeConstVec(
                    try decodeHex(signature, field: "attestation.signature")
                )
            )
        case "proof":
            guard let proofBackend = attestation.proofBackend,
                  !proofBackend.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                  proofBackend.trimmingCharacters(in: .whitespacesAndNewlines) == proofBackend,
                  let proofB64 = attestation.proofB64,
                  let proofBytes = Data(base64Encoded: proofB64) else {
                throw ToriiClientError.invalidPayload(
                    "proof attestation requires exact proof_backend and proof_b64."
                )
            }
            var proofBox = CompactNoritoWriter()
            proofBox.writeField(CompactNorito.encodeString(proofBackend))
            proofBox.writeField(encodeRawByteVec(proofBytes))
            writer.writeUInt32LE(1)
            writer.writeField(proofBox.data)
        default:
            throw ToriiClientError.invalidPayload("attestation.kind must be signed or proof.")
        }
        return writer.data
    }

    private static func parsePolicyId(_ raw: String) throws -> (String, String) {
        guard raw.trimmingCharacters(in: .whitespacesAndNewlines) == raw else {
            throw ToriiClientError.invalidPayload(
                "payload.policyId must not contain surrounding whitespace."
            )
        }
        let parts = raw.split(
            separator: "#",
            maxSplits: 1,
            omittingEmptySubsequences: false
        )
        guard parts.count == 2 else {
            throw ToriiClientError.invalidPayload(
                "payload.policyId must use `kind#rule`."
            )
        }
        let kind = try exactNonEmpty(String(parts[0]), field: "payload.policyId.kind")
        let businessRule = try exactNonEmpty(String(parts[1]), field: "payload.policyId.businessRule")
        return (kind, businessRule)
    }

    private static func normalizedNonEmpty(_ raw: String, field: String) throws -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must not be empty.")
        }
        return trimmed
    }

    private static func exactNonEmpty(_ raw: String, field: String) throws -> String {
        guard !raw.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must not be empty.")
        }
        guard raw.trimmingCharacters(in: .whitespacesAndNewlines) == raw else {
            throw ToriiClientError.invalidPayload(
                "\(field) must not contain surrounding whitespace."
            )
        }
        return raw
    }

    private static func encodeHash(_ raw: String, field: String) throws -> Data {
        let normalized = try ToriiIdentifierReceiptWireValue.normalizedHash(raw, field: field)
        do {
            return try CompactNorito.encodeHash(try decodeHex(normalized, field: field))
        } catch {
            throw ToriiClientError.invalidPayload(
                "\(field) must be a canonical 32-byte Iroha hash."
            )
        }
    }

    private static func encodePrefixedHash(
        _ raw: String,
        prefix: String,
        field: String
    ) throws -> Data {
        let normalized: String
        switch prefix {
        case "opaque:":
            normalized = try ToriiIdentifierReceiptWireValue.normalizedOpaqueId(raw, field: field)
        case "uaid:":
            normalized = try ToriiIdentifierReceiptWireValue.normalizedUaid(raw, field: field)
        default:
            throw ToriiClientError.invalidPayload("Unsupported receipt hash prefix \(prefix).")
        }
        guard normalized.lowercased().hasPrefix(prefix) else {
            throw ToriiClientError.invalidPayload("\(field) must use the \(prefix) prefix.")
        }
        var writer = CompactNoritoWriter()
        writer.writeField(try encodeHash(String(normalized.dropFirst(prefix.count)), field: field))
        return writer.data
    }

    private static func decodeHex(_ raw: String, field: String) throws -> Data {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed == raw else {
            throw ToriiClientError.invalidPayload("\(field) must contain exact hexadecimal bytes.")
        }
        let normalized: String
        if trimmed.hasPrefix("0x") || trimmed.hasPrefix("0X") {
            normalized = String(trimmed.dropFirst(2))
        } else {
            normalized = trimmed
        }
        guard !normalized.isEmpty, let bytes = Data(hexString: normalized) else {
            throw ToriiClientError.invalidPayload("\(field) must contain valid hexadecimal bytes.")
        }
        return bytes
    }

    private static func encodeConstVec(_ bytes: Data) -> Data {
        var writer = CompactNoritoWriter()
        writer.writeUInt64LE(UInt64(bytes.count))
        writer.writeByteFields(bytes)
        return writer.data
    }

    private static func encodeRawByteVec(_ bytes: Data) -> Data {
        var writer = CompactNoritoWriter()
        writer.writeUInt64LE(UInt64(bytes.count))
        writer.writeBytes(bytes)
        return writer.data
    }

    private static func encodeAccountId(_ raw: String) throws -> Data {
        do {
            let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty, trimmed == raw else {
                throw ToriiClientError.invalidPayload(
                    "payload.accountId must be an exact canonical account identifier."
                )
            }
            return try exactCanonicalToriiAccountAddress(raw).address
                .compactNoritoAccountControllerPayload()
        } catch {
            throw ToriiClientError.invalidPayload(
                "payload.accountId must be a canonical account identifier."
            )
        }
    }

    private static func backendTag(_ raw: String) throws -> UInt32 {
        let normalized = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !normalized.isEmpty, normalized == raw else {
            throw ToriiClientError.invalidPayload(
                "payload.execution.backend must be an exact lowercase RAM-LFE backend tag."
            )
        }
        switch raw {
        case "hkdf-sha3-512-prf-v1":
            return 0
        case "bfv-affine-v1":
            return 1
        case "bfv-programmed-v1":
            return 2
        default:
            throw ToriiClientError.invalidPayload(
                "Unsupported identifier receipt backend `\(raw)`."
            )
        }
    }

    private static func verificationModeTag(_ raw: String) throws -> UInt32 {
        let normalized = raw.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard !normalized.isEmpty, normalized == raw else {
            throw ToriiClientError.invalidPayload(
                "payload.execution.verificationMode must be an exact lowercase RAM-LFE verification mode."
            )
        }
        switch raw {
        case "signed":
            return 0
        case "proof":
            return 1
        default:
            throw ToriiClientError.invalidPayload(
                "Unsupported identifier receipt verification mode `\(raw)`."
            )
        }
    }
}

public struct ToriiRamLfeOutputOpeningPayload: Codable, Sendable {
    public let programId: String
    public let inputCiphertextHash: String
    public let outputCiphertextHash: String
    public let parameterDigest: String
    public let evaluationKeyDigest: String
    public let openedOutputHash: String
    public let openedAtMs: UInt64
    public let expiresAtMs: UInt64?

    private enum CodingKeys: String, CodingKey {
        case programId = "program_id"
        case inputCiphertextHash = "input_ciphertext_hash"
        case outputCiphertextHash = "output_ciphertext_hash"
        case parameterDigest = "parameter_digest"
        case evaluationKeyDigest = "evaluation_key_digest"
        case openedOutputHash = "opened_output_hash"
        case openedAtMs = "opened_at_ms"
        case expiresAtMs = "expires_at_ms"
    }

    public init(programId: String,
                inputCiphertextHash: String,
                outputCiphertextHash: String,
                parameterDigest: String,
                evaluationKeyDigest: String,
                openedOutputHash: String,
                openedAtMs: UInt64,
                expiresAtMs: UInt64?) {
        self.programId = programId
        self.inputCiphertextHash = inputCiphertextHash
        self.outputCiphertextHash = outputCiphertextHash
        self.parameterDigest = parameterDigest
        self.evaluationKeyDigest = evaluationKeyDigest
        self.openedOutputHash = openedOutputHash
        self.openedAtMs = openedAtMs
        self.expiresAtMs = expiresAtMs
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        guard let programId = try ToriiIdentifierReceiptWireValue.exactProgramId(
            from: container,
            forKey: .programId,
            debugName: "opening.payload.program_id"
        ) else {
            throw DecodingError.dataCorruptedError(
                forKey: .programId,
                in: container,
                debugDescription: "opening.payload.program_id is required."
            )
        }
        self.programId = programId
        inputCiphertextHash = try Self.requiredHash(container, .inputCiphertextHash)
        outputCiphertextHash = try Self.requiredHash(container, .outputCiphertextHash)
        parameterDigest = try Self.requiredHash(container, .parameterDigest)
        evaluationKeyDigest = try Self.requiredHash(container, .evaluationKeyDigest)
        openedOutputHash = try Self.requiredHash(container, .openedOutputHash)
        openedAtMs = try container.decode(UInt64.self, forKey: .openedAtMs)
        expiresAtMs = try container.decodeIfPresent(UInt64.self, forKey: .expiresAtMs)
    }

    private static func requiredHash(
        _ container: KeyedDecodingContainer<CodingKeys>,
        _ key: CodingKeys
    ) throws -> String {
        guard let value = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: key
        ) else {
            throw DecodingError.keyNotFound(
                key,
                DecodingError.Context(
                    codingPath: container.codingPath,
                    debugDescription: "\(key.stringValue) is required."
                )
            )
        }
        return value
    }
}

public struct ToriiRamLfeOutputOpening: Codable, Sendable {
    public let payload: ToriiRamLfeOutputOpeningPayload
    public let signature: String

    private enum CodingKeys: String, CodingKey {
        case payload
        case signature
    }

    public init(payload: ToriiRamLfeOutputOpeningPayload, signature: String) {
        self.payload = payload
        var normalized = signature.trimmingCharacters(in: .whitespacesAndNewlines)
        if normalized.hasPrefix("0x") || normalized.hasPrefix("0X") {
            normalized = String(normalized.dropFirst(2))
        }
        self.signature = normalized.lowercased()
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        payload = try container.decode(ToriiRamLfeOutputOpeningPayload.self, forKey: .payload)
        let rawSignature = try container.decode(String.self, forKey: .signature)
        if rawSignature.trimmingCharacters(in: .whitespacesAndNewlines) != rawSignature {
            throw DecodingError.dataCorruptedError(
                forKey: .signature,
                in: container,
                debugDescription: "opening.signature must be exact and contain no surrounding whitespace."
            )
        }
        signature = try ToriiRequestValidation.normalizedEvenLengthHex(
            rawSignature,
            field: "opening.signature"
        )
    }
}

public struct ToriiIdentifierResolutionExecutionPayload: Codable, Sendable {
    public let programId: String
    public let programDigest: String
    public let backend: String
    public let verificationMode: String
    public let inputCiphertextHash: String
    public let outputCiphertextHash: String
    public let parameterDigest: String
    public let evaluationKeyDigest: String
    public let outputHash: String
    public let associatedDataHash: String
    public let executedAtMs: UInt64
    public let expiresAtMs: UInt64?

    private enum CodingKeys: String, CodingKey {
        case programId = "program_id"
        case programDigest = "program_digest"
        case backend
        case verificationMode = "verification_mode"
        case inputCiphertextHash = "input_ciphertext_hash"
        case outputCiphertextHash = "output_ciphertext_hash"
        case parameterDigest = "parameter_digest"
        case evaluationKeyDigest = "evaluation_key_digest"
        case outputHash = "output_hash"
        case associatedDataHash = "associated_data_hash"
        case executedAtMs = "executed_at_ms"
        case expiresAtMs = "expires_at_ms"
    }

    public init(programId: String,
                programDigest: String,
                backend: String,
                verificationMode: String,
                inputCiphertextHash: String,
                outputCiphertextHash: String,
                parameterDigest: String,
                evaluationKeyDigest: String,
                outputHash: String,
                associatedDataHash: String,
                executedAtMs: UInt64,
                expiresAtMs: UInt64?) {
        self.programId = programId
        self.programDigest = programDigest
        self.backend = backend
        self.verificationMode = verificationMode
        self.inputCiphertextHash = inputCiphertextHash
        self.outputCiphertextHash = outputCiphertextHash
        self.parameterDigest = parameterDigest
        self.evaluationKeyDigest = evaluationKeyDigest
        self.outputHash = outputHash
        self.associatedDataHash = associatedDataHash
        self.executedAtMs = executedAtMs
        self.expiresAtMs = expiresAtMs
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        guard let programId = try ToriiIdentifierReceiptWireValue.exactProgramId(
            from: container,
            forKey: .programId,
            debugName: "payload.execution.program_id"
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.programId,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.program_id is required."
                )
            )
        }
        self.programId = programId
        guard let programDigest = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: .programDigest
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.programDigest,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.program_digest is required."
                )
            )
        }
        self.programDigest = programDigest
        self.backend = try ToriiIdentifierReceiptWireValue.exactRamLfeTag(
            from: container,
            forKey: .backend,
            debugName: "payload.execution.backend",
            kind: .backend
        )
        guard let verificationMode = try ToriiIdentifierReceiptWireValue.normalizedVerificationMode(
            from: container,
            forKey: .verificationMode
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.verificationMode,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.verification_mode is required."
                )
            )
        }
        self.verificationMode = verificationMode
        guard let inputCiphertextHash = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: .inputCiphertextHash
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.inputCiphertextHash,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.input_ciphertext_hash is required."
                )
            )
        }
        self.inputCiphertextHash = inputCiphertextHash
        guard let outputCiphertextHash = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: .outputCiphertextHash
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.outputCiphertextHash,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.output_ciphertext_hash is required."
                )
            )
        }
        self.outputCiphertextHash = outputCiphertextHash
        guard let parameterDigest = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: .parameterDigest
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.parameterDigest,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.parameter_digest is required."
                )
            )
        }
        self.parameterDigest = parameterDigest
        guard let evaluationKeyDigest = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: .evaluationKeyDigest
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.evaluationKeyDigest,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.evaluation_key_digest is required."
                )
            )
        }
        self.evaluationKeyDigest = evaluationKeyDigest
        guard let outputHash = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: .outputHash
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.outputHash,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.output_hash is required."
                )
            )
        }
        self.outputHash = outputHash
        guard let associatedDataHash = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: .associatedDataHash
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.associatedDataHash,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.execution.associated_data_hash is required."
                )
            )
        }
        self.associatedDataHash = associatedDataHash
        executedAtMs = try container.decode(UInt64.self, forKey: .executedAtMs)
        expiresAtMs = try container.decodeIfPresent(UInt64.self, forKey: .expiresAtMs)
    }
}

public struct ToriiIdentifierResolutionPayload: Codable, Sendable {
    public let policyId: String
    public let opaqueId: String
    public let receiptHash: String
    public let uaid: String
    public let accountId: String
    public let resolvedAtMs: UInt64
    public let expiresAtMs: UInt64?
    public let execution: ToriiIdentifierResolutionExecutionPayload
    public let opening: ToriiRamLfeOutputOpening

    private enum CodingKeys: String, CodingKey {
        case policyId = "policy_id"
        case execution
        case opening
        case opaqueId = "opaque_id"
        case receiptHash = "receipt_hash"
        case uaid
        case accountId = "account_id"
        case resolvedAtMs = "resolved_at_ms"
        case expiresAtMs = "expires_at_ms"
    }

    public init(policyId: String,
                opaqueId: String,
                receiptHash: String,
                uaid: String,
                accountId: String,
                execution: ToriiIdentifierResolutionExecutionPayload,
                opening: ToriiRamLfeOutputOpening) {
        self.policyId = policyId
        self.opaqueId = opaqueId
        self.receiptHash = receiptHash
        self.uaid = uaid
        self.accountId = accountId
        self.resolvedAtMs = execution.executedAtMs
        self.expiresAtMs = execution.expiresAtMs
        self.execution = execution
        self.opening = opening
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        policyId = try ToriiIdentifierReceiptWireValue.exactReceiptPolicyId(
            from: container,
            forKey: .policyId
        )
        opaqueId = try ToriiIdentifierReceiptWireValue.normalizedOpaqueId(
            from: container,
            forKey: .opaqueId
        )
        guard let normalizedReceiptHash = try ToriiIdentifierReceiptWireValue.normalizedHashValue(
            from: container,
            forKey: .receiptHash
        ) else {
            throw DecodingError.keyNotFound(
                CodingKeys.receiptHash,
                DecodingError.Context(
                    codingPath: decoder.codingPath,
                    debugDescription: "payload.receipt_hash is required."
                )
            )
        }
        receiptHash = normalizedReceiptHash
        uaid = try ToriiIdentifierReceiptWireValue.normalizedUaid(
            from: container,
            forKey: .uaid
        )
        let rawAccountId = try container.decode(String.self, forKey: .accountId)
        let trimmedAccountId = rawAccountId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedAccountId.isEmpty else {
            throw DecodingError.dataCorruptedError(
                forKey: .accountId,
                in: container,
                debugDescription: "payload.account_id must not be empty."
            )
        }
        guard trimmedAccountId == rawAccountId else {
            throw DecodingError.dataCorruptedError(
                forKey: .accountId,
                in: container,
                debugDescription: "payload.account_id must not contain surrounding whitespace."
            )
        }
        accountId = rawAccountId
        execution = try container.decode(
            ToriiIdentifierResolutionExecutionPayload.self,
            forKey: .execution
        )
        opening = try container.decode(ToriiRamLfeOutputOpening.self, forKey: .opening)
        resolvedAtMs = execution.executedAtMs
        expiresAtMs = execution.expiresAtMs
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(policyId, forKey: .policyId)
        try container.encode(opaqueId, forKey: .opaqueId)
        try container.encode(receiptHash, forKey: .receiptHash)
        try container.encode(uaid, forKey: .uaid)
        try container.encode(accountId, forKey: .accountId)
        try container.encode(execution, forKey: .execution)
        try container.encode(opening, forKey: .opening)
    }
}

