public extension ToriiIdentifierResolutionReceipt {
    func verifyAttestation(using policy: ToriiIdentifierPolicySummary) throws -> Bool {
        let trimmedPolicyId = policy.policyId.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedPolicyId.isEmpty, trimmedPolicyId == policy.policyId else {
            throw ToriiClientError.invalidPayload("policy.policy_id must not contain surrounding whitespace.")
        }
        guard policy.policyId == payload.policyId else {
            throw ToriiClientError.invalidPayload(
                "Identifier receipt policy \(payload.policyId) does not match policy summary \(policy.policyId)."
            )
        }
        guard attestation.kind == "signed", let signature = attestation.signature else {
            throw ToriiClientError.invalidPayload(
                "Only signed identifier receipt attestations can be verified with a resolver public key."
            )
        }
        let payloadBytes = try ToriiIdentifierReceiptCanonicalEncoder.canonicalPayloadBytes(for: self)
        guard signature.trimmingCharacters(in: .whitespacesAndNewlines) == signature else {
            throw ToriiClientError.invalidPayload("attestation.signature must be exact hex.")
        }
        let signatureBody: String
        if signature.hasPrefix("0x") || signature.hasPrefix("0X") {
            signatureBody = String(signature.dropFirst(2))
        } else {
            signatureBody = signature
        }
        guard let signatureBytes = Data(hexString: signatureBody) else {
            throw ToriiClientError.invalidPayload("attestation.signature must be valid hex.")
        }
        let verifyingKey = try ToriiIdentifierReceiptVerifier.parsePublicKey(policy.resolverPublicKey)
        let message = ToriiIdentifierReceiptVerifier.prehash(payloadBytes)
        return try ToriiIdentifierReceiptVerifier.verify(
            algorithm: verifyingKey.algorithm,
            publicKey: verifyingKey.publicKey,
            message: message,
            signature: signatureBytes
        )
    }
}

private enum ToriiIdentifierReceiptVerifier {
    fileprivate struct ParsedPublicKey {
        let algorithm: SigningAlgorithm
        let publicKey: Data
    }

    static func prehash(_ payload: Data) -> Data {
        var digest = Blake2b.hash256(payload)
        if !digest.isEmpty {
            digest[digest.count - 1] |= 0x01
        }
        return digest
    }

    static func parsePublicKey(_ literal: String) throws -> ParsedPublicKey {
        let trimmed = literal.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("resolverPublicKey must not be empty.")
        }
        guard trimmed == literal else {
            throw ToriiClientError.invalidPayload("resolverPublicKey must not contain surrounding whitespace.")
        }
        let rawHex: String
        var prefixedAlgorithm: SigningAlgorithm?
        if let separator = literal.firstIndex(of: ":") {
            let rawPrefix = String(literal[..<separator])
            guard !rawPrefix.isEmpty, rawPrefix.utf8.allSatisfy({ byte in
                (byte >= 0x30 && byte <= 0x39)
                    || (byte >= 0x41 && byte <= 0x5A)
                    || (byte >= 0x61 && byte <= 0x7A)
                    || byte == 0x2D
                    || byte == 0x5F
            }) else {
                throw ToriiClientError.invalidPayload(
                    "Unsupported resolver public-key prefix \(rawPrefix)."
                )
            }
            let prefix = rawPrefix.lowercased()
            rawHex = String(literal[literal.index(after: separator)...])
            switch prefix {
            case "ed25519":
                prefixedAlgorithm = .ed25519
            case "secp256k1":
                prefixedAlgorithm = .secp256k1
            case "ml-dsa", "mldsa", "mldsa65", "ml-dsa-65", "ml_dsa_65", "ml_dsa-65":
                prefixedAlgorithm = .mlDsa
            case "bls_normal", "bls-normal", "blsnormal":
                prefixedAlgorithm = .blsNormal
            case "bls_small", "bls-small", "blssmall":
                prefixedAlgorithm = .blsSmall
            case "gost256a", "gost-256-a", "gost3410-2012-256-paramset-a":
                prefixedAlgorithm = .gost2012_256A
            case "gost256b", "gost-256-b", "gost3410-2012-256-paramset-b":
                prefixedAlgorithm = .gost2012_256B
            case "gost256c", "gost-256-c", "gost3410-2012-256-paramset-c":
                prefixedAlgorithm = .gost2012_256C
            case "gost512a", "gost-512-a", "gost3410-2012-512-paramset-a":
                prefixedAlgorithm = .gost2012_512A
            case "gost512b", "gost-512-b", "gost3410-2012-512-paramset-b":
                prefixedAlgorithm = .gost2012_512B
            case "sm2":
                prefixedAlgorithm = .sm2
            default:
                throw ToriiClientError.invalidPayload("Unsupported resolver public-key prefix \(prefix).")
            }
        } else {
            rawHex = literal
        }
        guard let bytes = Data(hexString: rawHex) else {
            throw ToriiClientError.invalidPayload("resolverPublicKey must be valid multihash hex.")
        }
        let decoded = try decodePublicKeyMultihash(bytes)
        if let prefixedAlgorithm, decoded.algorithm != prefixedAlgorithm {
            throw ToriiClientError.invalidPayload("resolverPublicKey prefix does not match its multihash payload.")
        }
        return decoded
    }

    private static func decodePublicKeyMultihash(_ bytes: Data) throws -> ParsedPublicKey {
        let raw = [UInt8](bytes)
        let (functionCode, functionEnd) = try decodeVarint(raw, startIndex: 0)
        let (length, lengthEnd) = try decodeVarint(raw, startIndex: functionEnd)
        guard lengthEnd <= raw.count else {
            throw ToriiClientError.invalidPayload("resolverPublicKey multihash is truncated.")
        }
        let payload = Data(raw[lengthEnd...])
        guard payload.count == Int(length) else {
            throw ToriiClientError.invalidPayload("resolverPublicKey multihash length does not match its payload.")
        }
        let algorithm: SigningAlgorithm
        switch functionCode {
        case 0xed:
            algorithm = .ed25519
        case 0xe7:
            algorithm = .secp256k1
        case 0xea:
            algorithm = .blsNormal
        case 0xeb:
            algorithm = .blsSmall
        case 0xee:
            algorithm = .mlDsa
        case 0x1200:
            algorithm = .gost2012_256A
        case 0x1201:
            algorithm = .gost2012_256B
        case 0x1202:
            algorithm = .gost2012_256C
        case 0x1203:
            algorithm = .gost2012_512A
        case 0x1204:
            algorithm = .gost2012_512B
        case 0x1306:
            algorithm = .sm2
        default:
            throw ToriiClientError.invalidPayload(
                String(format: "resolverPublicKey uses unsupported multihash code 0x%X.", functionCode)
            )
        }
        if algorithm == .ed25519, !Ed25519PublicKeyAdmission.isValidPublicKey(payload) {
            throw ToriiClientError.invalidPayload("resolverPublicKey is not a valid Ed25519 public key.")
        }
        return ParsedPublicKey(algorithm: algorithm, publicKey: payload)
    }

    private static func decodeVarint(_ bytes: [UInt8], startIndex: Int) throws -> (UInt64, Int) {
        var value: UInt64 = 0
        var shift: UInt64 = 0
        var index = startIndex
        while index < bytes.count {
            let byte = bytes[index]
            let chunk = UInt64(byte & 0x7F)
            if shift >= 64 {
                throw ToriiClientError.invalidPayload("resolverPublicKey multihash varint overflowed.")
            }
            value |= chunk << shift
            index += 1
            if (byte & 0x80) == 0 {
                return (value, index)
            }
            shift += 7
        }
        throw ToriiClientError.invalidPayload("resolverPublicKey multihash varint is truncated.")
    }

    static func verify(algorithm: SigningAlgorithm,
                       publicKey: Data,
                       message: Data,
                       signature: Data,
                       sm2Distid: String? = nil) throws -> Bool {
        switch algorithm {
        case .ed25519:
            guard #available(macOS 10.15, iOS 13.0, *) else {
                throw ToriiClientError.invalidPayload("Ed25519 receipt verification requires iOS 13/macOS 10.15.")
            }
            guard Ed25519SignatureAdmission.isValidSignature(signature) else {
                return false
            }
            guard Ed25519PublicKeyAdmission.isValidPublicKey(publicKey) else {
                throw ToriiClientError.invalidPayload("resolverPublicKey is not a valid Ed25519 public key.")
            }
            let ed25519Key: Curve25519.Signing.PublicKey
            do {
                ed25519Key = try Curve25519.Signing.PublicKey(rawRepresentation: publicKey)
            } catch {
                throw ToriiClientError.invalidPayload("resolverPublicKey is not a valid Ed25519 public key.")
            }
            return ed25519Key.isValidSignature(signature, for: message)
        case .secp256k1:
            if let verified = NoritoNativeBridge.shared.verifyDetached(
                algorithm: .secp256k1,
                publicKey: publicKey,
                message: message,
                signature: signature
            ) ?? NoritoNativeBridge.shared.secp256k1Verify(
                publicKey: publicKey,
                message: message,
                signature: signature
            ) {
                return verified
            }
            throw ToriiClientError.invalidPayload("Secp256k1 receipt verification is unavailable.")
        case .sm2:
            if let verified = NoritoNativeBridge.shared.verifyDetached(
                algorithm: .sm2,
                publicKey: publicKey,
                message: message,
                signature: signature
            ) ?? NoritoNativeBridge.shared.sm2Verify(
                distid: sm2Distid ?? Sm2Keypair.defaultDistid(),
                publicKey: publicKey,
                message: message,
                signature: signature
            ) {
                return verified
            }
            throw ToriiClientError.invalidPayload("SM2 receipt verification is unavailable.")
        case .mlDsa:
            // The protocol discriminant is fixed to ML-DSA-65 even though the
            // general-purpose bridge also exposes suites 44 and 87.
            let suite = MlDsaSuite.mlDsa65
            let params = suite.parameters()
            guard publicKey.count == params.publicKeyLength,
                  signature.count == params.signatureLength else {
                return false
            }
            if let verified = NoritoNativeBridge.shared.verifyDetached(
                algorithm: .mlDsa,
                publicKey: publicKey,
                message: message,
                signature: signature
            ) {
                return verified
            }
            guard let verified = NoritoNativeBridge.shared.mldsaVerify(
                suiteId: suite.rawValue,
                publicKey: publicKey,
                message: message,
                signature: signature
            ) else {
                throw ToriiClientError.invalidPayload("ML-DSA receipt verification is unavailable.")
            }
            return verified
        case .blsNormal, .blsSmall,
             .gost2012_256A, .gost2012_256B, .gost2012_256C,
             .gost2012_512A, .gost2012_512B:
            if let verified = NoritoNativeBridge.shared.verifyDetached(
                algorithm: algorithm,
                publicKey: publicKey,
                message: message,
                signature: signature
            ) {
                return verified
            }
            throw ToriiClientError.invalidPayload("\(algorithm.wireName) receipt verification is unavailable.")
        }
    }
}

private struct ToriiAssetAliasResolveRequest: Encodable {
    let alias: String
}

private struct ToriiAccountAliasResolveRequest: Encodable {
    let alias: String
}

private struct ToriiAliasResolveIndexRequest: Encodable {
    let index: UInt64
}

/// One exact account-alias index resolution.
public struct ToriiAliasIndexResolution: Decodable, Equatable, Sendable {
    public let index: UInt64
    public let alias: String
    public let accountId: String
    public let source: String?

    private enum CodingKeys: String, CodingKey {
        case index, alias, source
        case accountId = "account_id"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: ["index", "alias", "account_id", "source"],
            debugName: "alias index response"
        )
        index = try container.decode(UInt64.self, forKey: .index)
        let alias = try container.decode(String.self, forKey: .alias)
        guard (try? AccountAliasName(parsing: alias).canonicalText) == alias else {
            throw DecodingError.dataCorruptedError(
                forKey: .alias,
                in: container,
                debugDescription: "alias index response must carry a canonical account alias"
            )
        }
        let accountId = try container.decode(String.self, forKey: .accountId)
        guard !accountId.contains("@"),
              (try? normalizeToriiAccountIdQueryValue(accountId, field: "account_id")) == accountId else {
            throw DecodingError.dataCorruptedError(
                forKey: .accountId,
                in: container,
                debugDescription: "alias index response must carry a canonical domainless account id"
            )
        }
        self.alias = alias
        self.accountId = accountId
        let decodedSource = try container.decodeIfPresent(String.self, forKey: .source)
        if let decodedSource {
            guard !decodedSource.isEmpty,
                  decodedSource == decodedSource.trimmingCharacters(in: .whitespacesAndNewlines),
                  !decodedSource.unicodeScalars.contains(where: {
                      CharacterSet.controlCharacters.contains($0)
                  }) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .source,
                    in: container,
                    debugDescription: "alias index source must be exact non-blank text"
                )
            }
        }
        source = decodedSource
    }
}

/// Exact reverse-alias lookup request with optional canonical scope filters.
public struct ToriiAliasesByAccountRequest: Encodable, Equatable, Sendable {
    public let accountId: String
    public let dataspace: String?
    public let domain: String?

    public init(accountId: String, dataspace: String? = nil, domain: String? = nil) throws {
        guard domain == nil || dataspace != nil else {
            throw ToriiClientError.invalidPayload(
                "domain requires an exact dataspace filter."
            )
        }
        let canonicalAccount = try normalizeToriiAccountIdQueryValue(accountId, field: "account_id")
        guard !accountId.contains("@"), canonicalAccount == accountId else {
            throw ToriiClientError.invalidPayload(
                "account_id must use its canonical domainless representation."
            )
        }
        if let dataspace {
            let scope = try AccountAliasName(
                label: "filter",
                domain: domain,
                dataspace: dataspace
            )
            self.dataspace = scope.dataspace
            self.domain = scope.domain
        } else {
            self.dataspace = nil
            self.domain = nil
        }
        self.accountId = canonicalAccount
    }

    private enum CodingKeys: String, CodingKey {
        case accountId = "account_id"
        case dataspace, domain
    }
}

/// One visible alias returned by an exact reverse-account lookup.
public struct ToriiAliasByAccountItem: Decodable, Equatable, Sendable {
    public let alias: String
    public let dataspace: String
    public let domain: String?
    public let isPrimary: Bool

    private enum CodingKeys: String, CodingKey {
        case alias, dataspace, domain
        case isPrimary = "is_primary"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: ["alias", "dataspace", "domain", "is_primary"],
            debugName: "reverse-alias row"
        )
        let alias = try container.decode(String.self, forKey: .alias)
        let parsed = try AccountAliasName(parsing: alias)
        let dataspace = try container.decode(String.self, forKey: .dataspace)
        let domain = try container.decodeIfPresent(String.self, forKey: .domain)
        guard parsed.canonicalText == alias,
              parsed.dataspace == dataspace,
              parsed.domain == domain else {
            throw DecodingError.dataCorruptedError(
                forKey: .alias,
                in: container,
                debugDescription: "reverse-alias row scope does not match its canonical alias"
            )
        }
        self.alias = alias
        self.dataspace = dataspace
        self.domain = domain
        isPrimary = try container.decode(Bool.self, forKey: .isPrimary)
    }
}

/// Visibility-filtered aliases for one canonical account.
public struct ToriiAliasesByAccountResponse: Decodable, Equatable, Sendable {
    public let accountId: String
    public let total: UInt64
    public let items: [ToriiAliasByAccountItem]
    public let source: String?

    private enum CodingKeys: String, CodingKey {
        case total, items, source
        case accountId = "account_id"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: ["account_id", "total", "items", "source"],
            debugName: "reverse-alias response"
        )
        let accountId = try container.decode(String.self, forKey: .accountId)
        guard !accountId.contains("@"),
              (try? normalizeToriiAccountIdQueryValue(accountId, field: "account_id")) == accountId else {
            throw DecodingError.dataCorruptedError(
                forKey: .accountId,
                in: container,
                debugDescription: "reverse-alias response must carry a canonical domainless account id"
            )
        }
        let items = try container.decode([ToriiAliasByAccountItem].self, forKey: .items)
        let total = try container.decode(UInt64.self, forKey: .total)
        guard total == UInt64(items.count) else {
            throw DecodingError.dataCorruptedError(
                forKey: .total,
                in: container,
                debugDescription: "reverse-alias total must be computed after visibility filtering"
            )
        }
        guard zip(items, items.dropFirst()).allSatisfy({ previous, next in
            previous.alias <= next.alias
        }) else {
            throw DecodingError.dataCorruptedError(
                forKey: .items,
                in: container,
                debugDescription: "reverse-alias items must use canonical alias order"
            )
        }
        self.accountId = accountId
        self.total = total
        self.items = items
        let decodedSource = try container.decodeIfPresent(String.self, forKey: .source)
        if let decodedSource {
            guard !decodedSource.isEmpty,
                  decodedSource == decodedSource.trimmingCharacters(in: .whitespacesAndNewlines),
                  !decodedSource.unicodeScalars.contains(where: {
                      CharacterSet.controlCharacters.contains($0)
                  }) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .source,
                    in: container,
                    debugDescription: "reverse-alias source must be exact non-blank text"
                )
            }
        }
        source = decodedSource
    }
}

public struct ToriiAccountOnboardingPlanRequest: Codable, Equatable, Sendable {
    public static let version: UInt8 = 1

    public let version: UInt8
    public let alias: String
    public let accountId: String
    public let permissions: [String]

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case version, alias, permissions
        case accountId = "account_id"
    }

    public init(alias: String, accountId: String, permissions: [String] = []) throws {
        let canonicalAlias = try AccountAliasName(parsing: alias).canonicalText
        guard !accountId.contains("@") else {
            throw ToriiClientError.invalidPayload(
                "account_id must be a canonical encoded account id (i105), not an alias."
            )
        }
        let canonicalAccountId = try normalizeToriiAccountIdQueryValue(
            accountId,
            field: "account_id"
        )
        guard canonicalAccountId == accountId else {
            throw ToriiClientError.invalidPayload(
                "account_id must use its canonical domainless representation."
            )
        }
        guard permissions.allSatisfy({ permission in
            !permission.isEmpty
                && permission == permission.trimmingCharacters(in: .whitespacesAndNewlines)
        }) else {
            throw ToriiClientError.invalidPayload(
                "permissions must contain exact non-empty names without surrounding whitespace."
            )
        }
        let canonicalPermissions = Array(Set(permissions)).sorted {
            Data($0.utf8).lexicographicallyPrecedes(Data($1.utf8))
        }
        guard permissions == canonicalPermissions else {
            throw ToriiClientError.invalidPayload(
                "permissions must be unique and sorted in canonical order."
            )
        }
        self.version = Self.version
        self.alias = canonicalAlias
        self.accountId = canonicalAccountId
        self.permissions = canonicalPermissions
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: Set(CodingKeys.allCases.map(\.rawValue)),
            debugName: "account onboarding plan request"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        guard try container.decode(UInt8.self, forKey: .version) == Self.version else {
            throw DecodingError.dataCorruptedError(
                forKey: .version,
                in: container,
                debugDescription: "unsupported onboarding request version"
            )
        }
        try self.init(
            alias: container.decode(String.self, forKey: .alias),
            accountId: container.decode(String.self, forKey: .accountId),
            permissions: container.decodeIfPresent([String].self, forKey: .permissions) ?? []
        )
    }
}

public struct ToriiAccountOnboardingPlanBody: Codable, Equatable, Sendable {
    public static let version: UInt8 = 1

    public let version: UInt8
    public let request: ToriiAccountOnboardingPlanRequest
    public let authority: String
    public let networkId: NetworkId
    public let anchor: AliasPlanAnchorV1
    public let resource: AliasPlanResourceV1
    public let acquisition: AliasLeaseAcquisitionV1
    public let quoteGuard: AliasQuoteGuardV1
    public let instructions: [AliasFramedInstructionV1]
    public let ownerAutoRenewInstruction: AliasFramedInstructionV1?
    public let validUntilMs: UInt64

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case version, request, authority, anchor, resource, acquisition, instructions
        case networkId = "network_id"
        case quoteGuard = "quote_guard"
        case ownerAutoRenewInstruction = "owner_auto_renew_instruction"
        case validUntilMs = "valid_until_ms"
    }

    public init(
        version: UInt8,
        request: ToriiAccountOnboardingPlanRequest,
        authority: String,
        networkId: NetworkId,
        anchor: AliasPlanAnchorV1,
        resource: AliasPlanResourceV1,
        acquisition: AliasLeaseAcquisitionV1,
        quoteGuard: AliasQuoteGuardV1,
        instructions: [AliasFramedInstructionV1],
        ownerAutoRenewInstruction: AliasFramedInstructionV1?,
        validUntilMs: UInt64
    ) {
        self.version = version
        self.request = request
        self.authority = authority
        self.networkId = networkId
        self.anchor = anchor
        self.resource = resource
        self.acquisition = acquisition
        self.quoteGuard = quoteGuard
        self.instructions = instructions
        self.ownerAutoRenewInstruction = ownerAutoRenewInstruction
        self.validUntilMs = validUntilMs
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: Set(CodingKeys.allCases.map(\.rawValue)),
            debugName: "account onboarding receipt body"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        guard container.contains(.ownerAutoRenewInstruction) else {
            throw DecodingError.keyNotFound(
                CodingKeys.ownerAutoRenewInstruction,
                .init(
                    codingPath: container.codingPath,
                    debugDescription: "owner_auto_renew_instruction must be present, including when null"
                )
            )
        }
        self.init(
            version: try container.decode(UInt8.self, forKey: .version),
            request: try container.decode(ToriiAccountOnboardingPlanRequest.self, forKey: .request),
            authority: try container.decode(String.self, forKey: .authority),
            networkId: try container.decode(NetworkId.self, forKey: .networkId),
            anchor: try container.decode(AliasPlanAnchorV1.self, forKey: .anchor),
            resource: try container.decode(AliasPlanResourceV1.self, forKey: .resource),
            acquisition: try container.decode(AliasLeaseAcquisitionV1.self, forKey: .acquisition),
            quoteGuard: try container.decode(AliasQuoteGuardV1.self, forKey: .quoteGuard),
            instructions: try container.decode([AliasFramedInstructionV1].self, forKey: .instructions),
            ownerAutoRenewInstruction: try container.decodeIfPresent(AliasFramedInstructionV1.self, forKey: .ownerAutoRenewInstruction),
            validUntilMs: try container.decode(UInt64.self, forKey: .validUntilMs)
        )
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(version, forKey: .version)
        try container.encode(request, forKey: .request)
        try container.encode(authority, forKey: .authority)
        try container.encode(networkId, forKey: .networkId)
        try container.encode(anchor, forKey: .anchor)
        try container.encode(resource, forKey: .resource)
        try container.encode(acquisition, forKey: .acquisition)
        try container.encode(quoteGuard, forKey: .quoteGuard)
        try container.encode(instructions, forKey: .instructions)
        if let ownerAutoRenewInstruction {
            try container.encode(ownerAutoRenewInstruction, forKey: .ownerAutoRenewInstruction)
        } else {
            try container.encodeNil(forKey: .ownerAutoRenewInstruction)
        }
        try container.encode(validUntilMs, forKey: .validUntilMs)
    }
}

public struct ToriiAccountOnboardingPlanReceipt: Codable, Equatable, Sendable {
    public let body: ToriiAccountOnboardingPlanBody
    public let planHash: String
    public let signature: ToriiJSONValue

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case body, signature
        case planHash = "plan_hash"
    }

    public init(body: ToriiAccountOnboardingPlanBody, planHash: String, signature: ToriiJSONValue) {
        self.body = body
        self.planHash = planHash
        self.signature = signature
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: Set(CodingKeys.allCases.map(\.rawValue)),
            debugName: "account onboarding plan receipt"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.init(
            body: try container.decode(ToriiAccountOnboardingPlanBody.self, forKey: .body),
            planHash: try container.decode(String.self, forKey: .planHash),
            signature: try container.decode(ToriiJSONValue.self, forKey: .signature)
        )
    }

    fileprivate func validate(for request: ToriiAccountOnboardingPlanRequest) throws {
        guard body.version == ToriiAccountOnboardingPlanBody.version,
              body.request.version == request.version,
              body.request.alias == request.alias,
              body.request.permissions == request.permissions,
              try toriiAccountIdsHaveSameIdentity(
                  body.request.accountId,
                  request.accountId
              ),
              body.quoteGuard.validUntilMs == body.validUntilMs,
              !planHash.isEmpty,
              signature != .null else {
            throw ToriiClientError.invalidResponse
        }
        guard case let .accountAlias(intent) = body.resource.intent,
              intent.alias.canonicalName.canonicalText == request.alias,
              try toriiAccountIdsHaveSameIdentity(
                  intent.targetAccount,
                  request.accountId
              ),
              intent.provision == .create,
              intent.role == .primary,
              body.resource.disposition != .conflict else {
            throw ToriiClientError.invalidResponse
        }
        if body.instructions.isEmpty {
            guard body.resource.disposition == .noOp,
                  body.resource.instructionIndex == nil else {
                throw ToriiClientError.invalidResponse
            }
        } else {
            guard body.resource.instructionIndex == 0,
                  body.instructions[0].wireId == EnsureAlias.wireId else {
                throw ToriiClientError.invalidResponse
            }
        }
    }
}

/// Canonical Norito encoder for the exact sponsored-onboarding receipt body.
public typealias ToriiAccountOnboardingPlanBodyEncoder =
    (ToriiAccountOnboardingPlanBody) throws -> Data

/// Fail-closed sponsored-onboarding receipt verification failures.
public enum ToriiAccountOnboardingReceiptVerificationError: Error, Equatable, Sendable {
    case canonicalBodyEncodingUnavailable
    case canonicalBodyEncodingFailed
    case emptyCanonicalBody
    case invalidPlanHash
    case planHashMismatch
    case invalidSignature
    case signatureMismatch
    case invalidAuthority
    case authorityMismatch
    case networkIdMismatch
}

/// Production canonical encoder backed by the bundled Norito registry bridge.
///
/// The required bridge must expose the V1 onboarding-body symbol. A missing
/// symbol fails closed without substituting a non-Norito representation.
public enum ToriiAccountOnboardingPlanBodyNorito {
    public static func encode(_ body: ToriiAccountOnboardingPlanBody) throws -> Data {
        do {
            return try NoritoNativeBridge.shared.encodeAccountOnboardingPlanBody(body)
        } catch NativeBridgeError.bridgeUnavailable {
            throw ToriiAccountOnboardingReceiptVerificationError
                .canonicalBodyEncodingUnavailable
        } catch {
            throw ToriiAccountOnboardingReceiptVerificationError
                .canonicalBodyEncodingFailed
        }
    }
}

/// Canonical hash and authority-signature verification for onboarding receipts.
public enum ToriiAccountOnboardingReceiptVerifier {
    private static let hashDomain = Data(
        "iroha:account-onboarding-plan-receipt:v1\0".utf8
    )

    /// Hashes the exact Norito receipt-body bytes with the V1 domain separator.
    public static func canonicalHash(canonicalBodyNorito: Data) throws -> Data {
        guard !canonicalBodyNorito.isEmpty else {
            throw ToriiAccountOnboardingReceiptVerificationError.emptyCanonicalBody
        }
        return IrohaHash.hash(hashDomain + canonicalBodyNorito)
    }

    /// Renders the canonical checksummed `hash:...#....` receipt commitment.
    public static func canonicalHashLiteral(canonicalBodyNorito: Data) throws -> String {
        let hash = try canonicalHash(canonicalBodyNorito: canonicalBodyNorito)
        guard let literal = ToriiCanonicalHashLiteral.literal(
            fromNormalizedHex: hash.hexEncodedString()
        ) else {
            throw ToriiAccountOnboardingReceiptVerificationError.invalidPlanHash
        }
        return literal
    }

    /// Verifies body shape, canonical hash, and the returned authority's signature.
    ///
    /// The expected authority and exact NetworkId are mandatory local trust anchors.
    /// The authority account ID carries the single-controller algorithm and
    /// public key used for verification.
    public static func verify(
        _ receipt: ToriiAccountOnboardingPlanReceipt,
        for request: ToriiAccountOnboardingPlanRequest,
        canonicalBodyNorito: Data,
        expectedAuthority: String,
        expectedNetworkId: NetworkId
    ) throws {
        let authority = try validatedAuthority(
            receipt,
            for: request,
            expectedAuthority: expectedAuthority,
            expectedNetworkId: expectedNetworkId
        )
        try verifyHashAndSignature(
            receipt,
            canonicalBodyNorito: canonicalBodyNorito,
            authority: authority
        )
    }

    /// Encodes and verifies the exact typed body in one operation.
    public static func verify(
        _ receipt: ToriiAccountOnboardingPlanReceipt,
        for request: ToriiAccountOnboardingPlanRequest,
        expectedAuthority: String,
        expectedNetworkId: NetworkId,
        bodyEncoder: ToriiAccountOnboardingPlanBodyEncoder
    ) throws {
        let authority = try validatedAuthority(
            receipt,
            for: request,
            expectedAuthority: expectedAuthority,
            expectedNetworkId: expectedNetworkId
        )
        let canonicalBodyNorito = try bodyEncoder(receipt.body)
        try verifyHashAndSignature(
            receipt,
            canonicalBodyNorito: canonicalBodyNorito,
            authority: authority
        )
    }

    static func validateTrustPins(
        expectedAuthority: String,
        expectedNetworkId: NetworkId
    ) throws {
        _ = try canonicalController(expectedAuthority)
        _ = expectedNetworkId
    }

    private static func validatedAuthority(
        _ receipt: ToriiAccountOnboardingPlanReceipt,
        for request: ToriiAccountOnboardingPlanRequest,
        expectedAuthority: String,
        expectedNetworkId: NetworkId
    ) throws -> Controller {
        try validateTrustPins(
            expectedAuthority: expectedAuthority,
            expectedNetworkId: expectedNetworkId
        )
        try receipt.validate(for: request)

        let authority = try canonicalController(receipt.body.authority)
        let expected = try canonicalController(expectedAuthority)
        guard try toriiAccountIdsHaveSameIdentity(
                  receipt.body.authority,
                  expectedAuthority
              ),
              expected.algorithm == authority.algorithm,
              expected.publicKey == authority.publicKey else {
            throw ToriiAccountOnboardingReceiptVerificationError.authorityMismatch
        }
        guard receipt.body.networkId == expectedNetworkId else {
            throw ToriiAccountOnboardingReceiptVerificationError.networkIdMismatch
        }
        return authority
    }

    private static func verifyHashAndSignature(
        _ receipt: ToriiAccountOnboardingPlanReceipt,
        canonicalBodyNorito: Data,
        authority: Controller
    ) throws {
        let expectedHash = try canonicalHash(canonicalBodyNorito: canonicalBodyNorito)
        guard let carriedHash = decodeCanonicalHash(receipt.planHash) else {
            throw ToriiAccountOnboardingReceiptVerificationError.invalidPlanHash
        }
        guard carriedHash == expectedHash else {
            throw ToriiAccountOnboardingReceiptVerificationError.planHashMismatch
        }

        guard case let .string(signatureHex) = receipt.signature,
              signatureHex == signatureHex.uppercased(),
              let signature = Data(hexString: signatureHex),
              !signature.isEmpty,
              signature.contains(where: { $0 != 0 }) else {
            throw ToriiAccountOnboardingReceiptVerificationError.invalidSignature
        }
        guard try ToriiIdentifierReceiptVerifier.verify(
            algorithm: authority.algorithm,
            publicKey: authority.publicKey,
            message: carriedHash,
            signature: signature,
            sm2Distid: authority.sm2Distid
        ) else {
            throw ToriiAccountOnboardingReceiptVerificationError.signatureMismatch
        }
    }

    private struct Controller {
        let algorithm: SigningAlgorithm
        let publicKey: Data
        let sm2Distid: String?
    }

    private static func canonicalController(_ literal: String) throws -> Controller {
        do {
            guard literal == literal.trimmingCharacters(in: .whitespacesAndNewlines) else {
                throw ToriiAccountOnboardingReceiptVerificationError.invalidAuthority
            }
            let canonical = try exactCanonicalToriiAccountAddress(literal)
            guard let controller = canonical.address.singleControllerInfo() else {
                throw ToriiAccountOnboardingReceiptVerificationError.invalidAuthority
            }
            let keyMaterial = try splitControllerKey(
                algorithm: controller.algorithm,
                payload: controller.publicKey
            )
            return Controller(
                algorithm: controller.algorithm,
                publicKey: keyMaterial.publicKey,
                sm2Distid: keyMaterial.sm2Distid
            )
        } catch let error as ToriiAccountOnboardingReceiptVerificationError {
            throw error
        } catch {
            throw ToriiAccountOnboardingReceiptVerificationError.invalidAuthority
        }
    }

    private static func splitControllerKey(
        algorithm: SigningAlgorithm,
        payload: Data
    ) throws -> (publicKey: Data, sm2Distid: String?) {
        guard algorithm == .sm2 else { return (payload, nil) }
        let bytes = [UInt8](payload)
        guard bytes.count >= 2 else {
            throw ToriiAccountOnboardingReceiptVerificationError.invalidAuthority
        }
        let distidLength = (Int(bytes[0]) << 8) | Int(bytes[1])
        let publicKeyStart = 2 + distidLength
        guard publicKeyStart < bytes.count,
              let distid = String(bytes: bytes[2..<publicKeyStart], encoding: .utf8),
              !distid.isEmpty else {
            throw ToriiAccountOnboardingReceiptVerificationError.invalidAuthority
        }
        return (Data(bytes[publicKeyStart...]), distid)
    }

    private static func decodeCanonicalHash(_ literal: String) -> Data? {
        guard let normalized = ToriiCanonicalHashLiteral.normalizedHex(from: literal),
              let bytes = Data(hexString: normalized) else {
            return nil
        }
        return bytes
    }
}

extension ToriiClient {
    static func prettyPrintedJSON(from data: Data) throws -> Data {
        let object = try JSONSerialization.jsonObject(with: data, options: [])
        return try JSONSerialization.data(withJSONObject: object,
                                          options: [.prettyPrinted, .sortedKeys])
    }

    static func persistDaRequestArtifacts(body: Data,
                                          directory: URL,
                                          fileManager: FileManager) throws {
        try fileManager.createDirectory(at: directory, withIntermediateDirectories: true, attributes: nil)
        let requestURL = directory.appendingPathComponent("da_request.json")
        let rendered = try prettyPrintedJSON(from: body)
        try rendered.write(to: requestURL, options: .atomic)
    }

    static func persistDaReceiptArtifacts(responseBody: Data,
                                          pdpHeader: String?,
                                          directory: URL,
                                          fileManager: FileManager) throws {
        try fileManager.createDirectory(at: directory, withIntermediateDirectories: true, attributes: nil)
        let receiptURL = directory.appendingPathComponent("da_receipt.json")
        let rendered = try prettyPrintedJSON(from: responseBody)
        try rendered.write(to: receiptURL, options: .atomic)
        if let header = pdpHeader {
            let headerURL = directory.appendingPathComponent("da_response_headers.json")
            let headersObject = [ToriiPdpCommitmentHeader: header]
            let headerData = try JSONSerialization.data(withJSONObject: headersObject,
                                                        options: [.prettyPrinted, .sortedKeys])
            try headerData.write(to: headerURL, options: .atomic)
        }
    }

    static func sanitizeDaLabel(_ raw: String?) throws -> String {
        guard var label = raw?.trimmingCharacters(in: .whitespacesAndNewlines), !label.isEmpty else {
            throw ToriiClientError.invalidPayload("DA ticket label must not be empty")
        }
        if label.hasPrefix("0x") || label.hasPrefix("0X") {
            label = String(label.dropFirst(2))
        }
        label = label.lowercased()
        let allowed = CharacterSet(charactersIn: "abcdefghijklmnopqrstuvwxyz0123456789-_")
        if label.rangeOfCharacter(from: allowed.inverted) != nil {
            throw ToriiClientError.invalidPayload("DA ticket label contains unsupported characters")
        }
        return label
    }

    static func persistDaManifestBundle(_ bundle: ToriiDaManifestBundle,
                                        outputDir: URL,
                                        label: String?,
                                        fileManager: FileManager) throws -> ToriiDaManifestPersistedPaths {
        let sanitized = try sanitizeDaLabel(label ?? bundle.storageTicketHex)
        try fileManager.createDirectory(at: outputDir, withIntermediateDirectories: true, attributes: nil)
        let manifestURL = outputDir.appendingPathComponent("manifest_\(sanitized).norito")
        let manifestJsonURL = outputDir.appendingPathComponent("manifest_\(sanitized).json")
        let chunkPlanURL = outputDir.appendingPathComponent("chunk_plan_\(sanitized).json")

        try bundle.manifestBytes.write(to: manifestURL, options: Data.WritingOptions.atomic)
        if let manifestJson = bundle.manifestJson {
            let data = try manifestJson.encodedData(prettyPrinted: true)
            try data.write(to: manifestJsonURL, options: Data.WritingOptions.atomic)
        } else {
            try Data("null\n".utf8).write(to: manifestJsonURL, options: Data.WritingOptions.atomic)
        }
        let chunkPlanString = try bundle.chunkPlanJSONString(prettyPrinted: true)
        if let chunkData = chunkPlanString.data(using: .utf8) {
            try chunkData.write(to: chunkPlanURL, options: Data.WritingOptions.atomic)
        }

        return ToriiDaManifestPersistedPaths(manifestURL: manifestURL,
                                             manifestJsonURL: manifestJsonURL,
                                             chunkPlanURL: chunkPlanURL,
                                             label: sanitized)
    }
}

