        if let wsPerIpMaxSessions { record["ws_per_ip_max_sessions"] = .number(Double(wsPerIpMaxSessions)) }
        if let wsRatePerIpPerMin { record["ws_rate_per_ip_per_min"] = .number(Double(wsRatePerIpPerMin)) }
