public struct ToriiVerifyingKeyListQuery: Sendable {
    public var backend: String?
    public var status: ToriiVerifyingKeyStatus?
    public var nameContains: String?
    public var limit: Int?
    public var offset: Int?
    public enum Order: String, Sendable {
        case ascending = "asc"
        case descending = "desc"
    }
    public var order: Order?
    public var idsOnly: Bool?

    public init(backend: String? = nil,
                status: ToriiVerifyingKeyStatus? = nil,
                nameContains: String? = nil,
                limit: Int? = nil,
                offset: Int? = nil,
                order: Order? = nil,
                idsOnly: Bool? = nil) {
        self.backend = backend
        self.status = status
        self.nameContains = nameContains
        self.limit = limit
        self.offset = offset
        self.order = order
        self.idsOnly = idsOnly
    }

    public func queryItems() throws -> [URLQueryItem]? {
        var items: [URLQueryItem] = []
        if let backend {
            let normalizedBackend = try ToriiVerifyingKeyRequestValidation.normalizedBackend(backend,
                                                                                            field: "backend")
            items.append(URLQueryItem(name: "backend", value: normalizedBackend))
        }
        if let status {
            items.append(URLQueryItem(name: "status", value: status.rawValue))
        }
        if let nameContains {
            items.append(URLQueryItem(name: "name_contains", value: nameContains))
        }
        if let limit, limit >= 0 {
            items.append(URLQueryItem(name: "limit", value: String(limit)))
        }
        if let offset, offset >= 0 {
            items.append(URLQueryItem(name: "offset", value: String(offset)))
        }
        if let order {
            items.append(URLQueryItem(name: "order", value: order.rawValue))
        }
        if let idsOnly {
            items.append(URLQueryItem(name: "ids_only", value: idsOnly ? "true" : "false"))
        }
        return items.isEmpty ? nil : items
    }
}

public struct ToriiVerifyingKeyRegisterRequest: Encodable, Sendable {
    public var authority: String
    public var backend: String
    public var name: String
    public var version: UInt32
    public var circuitId: String
    public var publicInputsSchemaHashHex: String
    public var curve: String?
    public var gasScheduleId: String
    public var verifyingKeyLength: UInt32?
    public var maxProofBytes: UInt32?
    public var metadataUriCid: String?
    public var verifyingKeyBytesCid: String?
    public var activationHeight: UInt64?
    public var withdrawHeight: UInt64?
    public var commitmentHex: String?
    public var verifyingKeyBytes: Data?
    public var status: ToriiVerifyingKeyStatus?

    public init(authority: String,
                backend: String,
                name: String,
                version: UInt32,
                circuitId: String,
                publicInputsSchemaHashHex: String,
                gasScheduleId: String,
                verifyingKeyBytes: Data? = nil,
                verifyingKeyLength: UInt32? = nil,
                status: ToriiVerifyingKeyStatus? = nil) {
        self.authority = authority
        self.backend = backend
        self.name = name
        self.version = version
        self.circuitId = circuitId
        self.publicInputsSchemaHashHex = publicInputsSchemaHashHex
        self.curve = nil
        self.gasScheduleId = gasScheduleId
        self.verifyingKeyLength = verifyingKeyLength
        self.maxProofBytes = nil
        self.metadataUriCid = nil
        self.verifyingKeyBytesCid = nil
        self.activationHeight = nil
        self.withdrawHeight = nil
        self.commitmentHex = nil
        self.verifyingKeyBytes = verifyingKeyBytes
        self.status = status
    }

    private enum CodingKeys: String, CodingKey {
        case authority
        case backend
        case name
        case version
        case circuitId = "circuit_id"
        case publicInputsSchemaHashHex = "public_inputs_schema_hash_hex"
        case curve
        case gasScheduleId = "gas_schedule_id"
        case verifyingKeyLength = "vk_len"
        case maxProofBytes = "max_proof_bytes"
        case metadataUriCid = "metadata_uri_cid"
        case verifyingKeyBytesCid = "vk_bytes_cid"
        case activationHeight = "activation_height"
        case withdrawHeight = "withdraw_height"
        case commitmentHex = "commitment_hex"
        case verifyingKeyBytes = "vk_bytes"
        case status
    }

    public func encode(to encoder: Encoder) throws {
        let normalizedAuthority = try ToriiVerifyingKeyRequestValidation.normalizedNonEmpty(authority,
                                                                                            field: "authority")
        let normalizedBackend = try ToriiVerifyingKeyRequestValidation.normalizedBackend(backend, field: "backend")
        let normalizedName = try ToriiVerifyingKeyRequestValidation.normalizedName(name, field: "name")
        let normalizedCircuitId = try ToriiVerifyingKeyRequestValidation.normalizedExactNonEmpty(circuitId,
                                                                                                  field: "circuit_id")
        let normalizedSchemaHash = try ToriiVerifyingKeyRequestValidation.normalized32ByteHex(
            publicInputsSchemaHashHex,
            field: "public_inputs_schema_hash_hex"
        )
        let normalizedCurve = try ToriiVerifyingKeyRequestValidation.normalizedOptionalNonEmpty(curve,
                                                                                                field: "curve")
        let normalizedGasSchedule = try ToriiVerifyingKeyRequestValidation.normalizedExactNonEmpty(gasScheduleId,
                                                                                                    field: "gas_schedule_id")
        let normalizedCommitment = try ToriiVerifyingKeyRequestValidation.normalizedOptional32ByteHex(
            commitmentHex,
            field: "commitment_hex"
        )
        let normalizedMetadataCid = try ToriiVerifyingKeyRequestValidation.normalizedOptionalNonEmpty(
            metadataUriCid,
            field: "metadata_uri_cid"
        )
        let normalizedVkBytesCid = try ToriiVerifyingKeyRequestValidation.normalizedOptionalNonEmpty(
            verifyingKeyBytesCid,
            field: "vk_bytes_cid"
        )
        let vkPayload = try ToriiVerifyingKeyRequestValidation.verifyingKeyPayload(
            bytes: verifyingKeyBytes,
            explicitLength: verifyingKeyLength
        )
        try ToriiVerifyingKeyRequestValidation.validateVerifierMaterial(
            payload: vkPayload,
            commitmentHex: normalizedCommitment,
            explicitLength: verifyingKeyLength
        )
        try ToriiVerifyingKeyRequestValidation.validateInlineCommitment(
            backend: normalizedBackend,
            commitmentHex: normalizedCommitment,
            payload: vkPayload,
            field: "commitment_hex"
        )
        try ToriiVerifyingKeyRequestValidation.validateHeightRange(
            activationHeight: activationHeight,
            withdrawHeight: withdrawHeight,
            field: "withdraw_height"
        )
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(normalizedAuthority, forKey: .authority)
        try container.encode(normalizedBackend, forKey: .backend)
        try container.encode(normalizedName, forKey: .name)
        try container.encode(version, forKey: .version)
        try container.encode(normalizedCircuitId, forKey: .circuitId)
        try container.encode(normalizedSchemaHash, forKey: .publicInputsSchemaHashHex)
        try container.encodeIfPresent(normalizedCurve, forKey: .curve)
        try container.encode(normalizedGasSchedule, forKey: .gasScheduleId)
        if let vkPayload {
            try container.encode(vkPayload.bytesBase64, forKey: .verifyingKeyBytes)
            try container.encode(vkPayload.length, forKey: .verifyingKeyLength)
        } else if let len = verifyingKeyLength {
            try container.encode(len, forKey: .verifyingKeyLength)
        }
        try container.encodeIfPresent(maxProofBytes, forKey: .maxProofBytes)
        try container.encodeIfPresent(normalizedMetadataCid, forKey: .metadataUriCid)
        try container.encodeIfPresent(normalizedVkBytesCid, forKey: .verifyingKeyBytesCid)
        try container.encodeIfPresent(activationHeight, forKey: .activationHeight)
        try container.encodeIfPresent(withdrawHeight, forKey: .withdrawHeight)
        try container.encodeIfPresent(normalizedCommitment, forKey: .commitmentHex)
        if let status {
            try container.encode(status.rawValue, forKey: .status)
        }
    }
}

public struct ToriiVerifyingKeyUpdateRequest: Encodable, Sendable {
    public var authority: String
    public var backend: String
    public var name: String
    public var version: UInt32
    public var circuitId: String
    public var publicInputsSchemaHashHex: String
    public var curve: String?
    public var gasScheduleId: String?
    public var commitmentHex: String?
    public var verifyingKeyLength: UInt32?
    public var maxProofBytes: UInt32?
    public var metadataUriCid: String?
    public var verifyingKeyBytesCid: String?
    public var activationHeight: UInt64?
    public var withdrawHeight: UInt64?
    public var verifyingKeyBytes: Data?
    public var status: ToriiVerifyingKeyStatus?

    public init(authority: String,
                backend: String,
                name: String,
                version: UInt32,
                circuitId: String,
                publicInputsSchemaHashHex: String) {
        self.authority = authority
        self.backend = backend
        self.name = name
        self.version = version
        self.circuitId = circuitId
        self.publicInputsSchemaHashHex = publicInputsSchemaHashHex
    }

    private enum CodingKeys: String, CodingKey {
        case authority
        case backend
        case name
        case version
        case circuitId = "circuit_id"
        case publicInputsSchemaHashHex = "public_inputs_schema_hash_hex"
        case curve
        case gasScheduleId = "gas_schedule_id"
        case commitmentHex = "commitment_hex"
        case verifyingKeyLength = "vk_len"
        case maxProofBytes = "max_proof_bytes"
        case metadataUriCid = "metadata_uri_cid"
        case verifyingKeyBytesCid = "vk_bytes_cid"
        case activationHeight = "activation_height"
        case withdrawHeight = "withdraw_height"
        case verifyingKeyBytes = "vk_bytes"
        case status
    }

    public func encode(to encoder: Encoder) throws {
        let normalizedAuthority = try ToriiVerifyingKeyRequestValidation.normalizedNonEmpty(authority,
                                                                                            field: "authority")
        let normalizedBackend = try ToriiVerifyingKeyRequestValidation.normalizedBackend(backend, field: "backend")
        let normalizedName = try ToriiVerifyingKeyRequestValidation.normalizedName(name, field: "name")
        let normalizedCircuitId = try ToriiVerifyingKeyRequestValidation.normalizedExactNonEmpty(circuitId,
                                                                                                  field: "circuit_id")
        let normalizedSchemaHash = try ToriiVerifyingKeyRequestValidation.normalized32ByteHex(
            publicInputsSchemaHashHex,
            field: "public_inputs_schema_hash_hex"
        )
        let normalizedCurve = try ToriiVerifyingKeyRequestValidation.normalizedOptionalNonEmpty(curve,
                                                                                                field: "curve")
        let normalizedGasSchedule = try ToriiVerifyingKeyRequestValidation.normalizedOptionalExactNonEmpty(
            gasScheduleId,
            field: "gas_schedule_id"
        )
        let normalizedCommitment = try ToriiVerifyingKeyRequestValidation.normalizedOptional32ByteHex(
            commitmentHex,
            field: "commitment_hex"
        )
        let normalizedMetadataCid = try ToriiVerifyingKeyRequestValidation.normalizedOptionalNonEmpty(
            metadataUriCid,
            field: "metadata_uri_cid"
        )
        let normalizedVkBytesCid = try ToriiVerifyingKeyRequestValidation.normalizedOptionalNonEmpty(
            verifyingKeyBytesCid,
            field: "vk_bytes_cid"
        )
        let vkPayload = try ToriiVerifyingKeyRequestValidation.verifyingKeyPayload(
            bytes: verifyingKeyBytes,
            explicitLength: verifyingKeyLength
        )
        try ToriiVerifyingKeyRequestValidation.validateVerifierMaterial(
            payload: vkPayload,
            commitmentHex: normalizedCommitment,
            explicitLength: verifyingKeyLength
        )
        try ToriiVerifyingKeyRequestValidation.validateInlineCommitment(
            backend: normalizedBackend,
            commitmentHex: normalizedCommitment,
            payload: vkPayload,
            field: "commitment_hex"
        )
        try ToriiVerifyingKeyRequestValidation.validateHeightRange(
            activationHeight: activationHeight,
            withdrawHeight: withdrawHeight,
            field: "withdraw_height"
        )
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(normalizedAuthority, forKey: .authority)
        try container.encode(normalizedBackend, forKey: .backend)
        try container.encode(normalizedName, forKey: .name)
        try container.encode(version, forKey: .version)
        try container.encode(normalizedCircuitId, forKey: .circuitId)
        try container.encode(normalizedSchemaHash, forKey: .publicInputsSchemaHashHex)
        try container.encodeIfPresent(normalizedCurve, forKey: .curve)
        try container.encodeIfPresent(normalizedGasSchedule, forKey: .gasScheduleId)
        try container.encodeIfPresent(normalizedCommitment, forKey: .commitmentHex)
        if let vkPayload {
            try container.encode(vkPayload.bytesBase64, forKey: .verifyingKeyBytes)
            try container.encode(vkPayload.length, forKey: .verifyingKeyLength)
        } else if let len = verifyingKeyLength {
            try container.encode(len, forKey: .verifyingKeyLength)
        }
        try container.encodeIfPresent(maxProofBytes, forKey: .maxProofBytes)
        try container.encodeIfPresent(normalizedMetadataCid, forKey: .metadataUriCid)
        try container.encodeIfPresent(normalizedVkBytesCid, forKey: .verifyingKeyBytesCid)
        try container.encodeIfPresent(activationHeight, forKey: .activationHeight)
        try container.encodeIfPresent(withdrawHeight, forKey: .withdrawHeight)
        if let status {
            try container.encode(status.rawValue, forKey: .status)
        }
    }
}

/// Unsigned transaction material returned by verifying-key register/update routes.
///
/// `transactionPayload` is the canonical Norito `TransactionPayload` to pass to
/// SDK signing abstractions that apply the Iroha prehash themselves.
/// `signingMessage` is the already-prehashed 32-byte message intended for raw
/// signature primitives and other low-level signer interfaces.
public struct ToriiVerifyingKeyTransactionDraft: Sendable, Equatable {
    public let submitted: Bool
    public let transactionPayloadB64: String
    public let signingMessageB64: String
    public let transactionPayload: Data
    public let signingMessage: Data

    fileprivate init(envelope: ToriiVerifyingKeyTransactionDraftEnvelope) {
        submitted = false
        transactionPayloadB64 = envelope.transactionPayloadB64
        signingMessageB64 = envelope.signingMessageB64
        transactionPayload = envelope.transactionPayload
        signingMessage = envelope.signingMessage
    }
}

fileprivate struct ToriiVerifyingKeyTransactionDraftEnvelope: Decodable {
    let transactionPayloadB64: String
    let signingMessageB64: String
    let transactionPayload: Data
    let signingMessage: Data

    private enum CodingKeys: String, CodingKey {
        case submitted
        case transactionPayloadB64 = "transaction_payload_b64"
        case signingMessageB64 = "signing_message_b64"
    }

    public init(from decoder: Decoder) throws {
        let raw = try decoder.container(keyedBy: ToriiAnyCodingKey.self)
        let expectedFields: Set<String> = [
            CodingKeys.submitted.rawValue,
            CodingKeys.transactionPayloadB64.rawValue,
            CodingKeys.signingMessageB64.rawValue,
        ]
        let actualFields = Set(raw.allKeys.map(\.stringValue))
        guard actualFields == expectedFields else {
            let unexpected = actualFields.subtracting(expectedFields).sorted()
            let missing = expectedFields.subtracting(actualFields).sorted()
            let details = [
                unexpected.isEmpty ? nil : "unknown fields \(unexpected.joined(separator: ", "))",
                missing.isEmpty ? nil : "missing fields \(missing.joined(separator: ", "))",
            ].compactMap { $0 }.joined(separator: "; ")
            throw DecodingError.dataCorrupted(
                .init(
                    codingPath: decoder.codingPath,
                    debugDescription:
                        "verifying-key transaction draft must contain exactly submitted, transaction_payload_b64, and signing_message_b64 (\(details))"
                )
            )
        }

        let container = try decoder.container(keyedBy: CodingKeys.self)
        let submitted = try container.decode(Bool.self, forKey: .submitted)
        guard !submitted else {
            throw DecodingError.dataCorruptedError(
                forKey: .submitted,
                in: container,
                debugDescription: "submitted must be false for an unsigned transaction draft"
            )
        }
        let transactionPayloadB64 = try container.decode(String.self, forKey: .transactionPayloadB64)
        let signingMessageB64 = try container.decode(String.self, forKey: .signingMessageB64)
        let decoded: ToriiCanonicalTransactionDraft
        do {
            decoded = try ToriiCanonicalTransactionDraft.decode(
                transactionPayloadB64: transactionPayloadB64,
                signingMessageB64: signingMessageB64,

                context: "verifying-key transaction draft"
            )
        } catch {
            throw DecodingError.dataCorruptedError(
                forKey: .signingMessageB64,
                in: container,
                debugDescription: "verifying-key transaction draft is not one canonical unsigned TransactionPayload: \(error)"
            )
        }

        self.transactionPayloadB64 = transactionPayloadB64
        self.signingMessageB64 = signingMessageB64
        transactionPayload = decoded.transactionPayload
        signingMessage = decoded.signingMessage
    }
}

fileprivate enum ToriiVerifyingKeyRequestValidation {
    struct VkPayload {
        let bytes: Data
        let bytesBase64: String
        let length: UInt32
    }

    static func normalizedNonEmpty(_ value: String, field: String) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
        }
        return trimmed
    }

    static func normalizedExactNonEmpty(_ value: String, field: String) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
        }
        guard trimmed == value else {
            throw ToriiClientError.invalidPayload("\(field) must not contain surrounding whitespace.")
        }
        return value
    }

    static func normalizedBackend(_ value: String, field: String) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
        }
        guard trimmed == value else {
            throw ToriiClientError.invalidPayload("\(field) must not contain surrounding whitespace.")
        }
        guard VerifyingKeyBackendTag.isProductionVerifyBackendLabel(value) else {
            throw ToriiClientError.invalidPayload(
                "\(field) is not an exact supported verifier-registry label: \(value)."
            )
        }
        return value
    }

    static func normalizedName(_ value: String, field: String) throws -> String {
        let exact = try normalizedExactNonEmpty(value, field: field)
        if exact.contains(":") {
            throw ToriiClientError.invalidPayload("\(field) must not contain ':' characters.")
        }
        return exact
    }

    static func normalizedOptionalNonEmpty(_ value: String?, field: String) throws -> String? {
        guard let value else { return nil }
        return try normalizedNonEmpty(value, field: field)
    }

    static func normalizedOptionalExactNonEmpty(_ value: String?, field: String) throws -> String? {
        guard let value else { return nil }
        return try normalizedExactNonEmpty(value, field: field)
    }

    static func normalized32ByteHex(_ value: String, field: String) throws -> String {
        var trimmed = try normalizedNonEmpty(value, field: field)
        if trimmed.hasPrefix("0x") || trimmed.hasPrefix("0X") {
            trimmed = String(trimmed.dropFirst(2))
        }
        guard trimmed.count == 64, Data(hexString: trimmed) != nil else {
            throw ToriiClientError.invalidPayload("\(field) must be a 32-byte hex string.")
        }
        return trimmed.lowercased()
    }

    static func exactLowercase32ByteHex(_ value: String, field: String) throws -> String {
        guard value.count == 64,
              value == value.lowercased(),
              value.unicodeScalars.allSatisfy({ scalar in
                  (scalar.value >= 48 && scalar.value <= 57)
                      || (scalar.value >= 97 && scalar.value <= 102)
              }) else {
            throw ToriiClientError.invalidPayload(
                "\(field) must be exactly 64 lowercase hexadecimal characters."
            )
        }
        return value
    }

    static func normalizedOptional32ByteHex(_ value: String?, field: String) throws -> String? {
        guard let value else { return nil }
        return try normalized32ByteHex(value, field: field)
    }

    static func verifyingKeyPayload(bytes: Data?, explicitLength: UInt32?) throws -> VkPayload? {
        guard let bytes else {
            return nil
        }
        guard !bytes.isEmpty else {
            throw ToriiClientError.invalidPayload("vk_bytes must not be empty.")
        }
        guard bytes.count <= Int(UInt32.max) else {
            throw ToriiClientError.invalidPayload("vk_bytes length must fit in a u32.")
        }
        let length = UInt32(bytes.count)
        if let explicitLength, explicitLength != length {
            throw ToriiClientError.invalidPayload("vk_len must match vk_bytes length.")
        }
        return VkPayload(bytes: bytes,
                         bytesBase64: bytes.base64EncodedString(),
                         length: explicitLength ?? length)
    }

    static func validateInlineCommitment(backend: String,
                                         commitmentHex: String?,
                                         payload: VkPayload?,
                                         field: String) throws {
        guard let commitmentHex, let payload else {
            return
        }
        let expected = verifyingKeyCommitmentHex(backend: backend, bytes: payload.bytes)
        guard commitmentHex == expected else {
            throw ToriiClientError.invalidPayload(
                "\(field) must match domain-separated SHA-256 of backend and vk_bytes."
            )
        }
    }

    static func validateVerifierMaterial(payload: VkPayload?,
                                         commitmentHex: String?,
                                         explicitLength: UInt32?) throws {
        guard payload == nil else {
            return
        }
        guard commitmentHex != nil else {
            throw ToriiClientError.invalidPayload(
                "commitment_hex is required when vk_bytes is omitted."
            )
        }
        guard let explicitLength, explicitLength > 0 else {
            throw ToriiClientError.invalidPayload(
                "vk_len is required when vk_bytes is omitted."
            )
        }
    }

    private static func verifyingKeyCommitmentHex(backend: String, bytes: Data) -> String {
        let backendBytes = Data(backend.utf8)
        var preimage = Data("iroha:zk:v1:vk".utf8)
        preimage.append(u64BigEndianData(UInt64(backendBytes.count)))
        preimage.append(backendBytes)
        preimage.append(u64BigEndianData(UInt64(bytes.count)))
        preimage.append(bytes)
        return Data(SHA256.hash(data: preimage)).hexEncodedString()
    }

    private static func u64BigEndianData(_ value: UInt64) -> Data {
        var bigEndian = value.bigEndian
        return withUnsafeBytes(of: &bigEndian) { Data($0) }
    }

    static func validateHeightRange(activationHeight: UInt64?,
                                    withdrawHeight: UInt64?,
                                    field: String) throws {
        if let activationHeight, let withdrawHeight, withdrawHeight < activationHeight {
            throw ToriiClientError.invalidPayload(
                "\(field) must be greater than or equal to activation_height."
            )
        }
    }
}

fileprivate enum ToriiVerifyingKeyDraftOperation {
    case register
    case update

    var wireName: String {
        switch self {
        case .register:
            return "iroha.instruction.v1::verifying_keys::RegisterVerifyingKey"
        case .update:
            return "iroha.instruction.v1::verifying_keys::UpdateVerifyingKey"
        }
    }
}

fileprivate struct ToriiVerifyingKeyExpectedRequest: Decodable {
    let authority: String
    let backend: String
    let name: String
    let version: UInt32
    let circuitId: String
    let publicInputsSchemaHashHex: String
    let curve: String?
    let gasScheduleId: String?
    let verifyingKeyLength: UInt32?
    let maxProofBytes: UInt32?
    let metadataUriCid: String?
    let verifyingKeyBytesCid: String?
    let activationHeight: UInt64?
    let withdrawHeight: UInt64?
    let commitmentHex: String?
    let verifyingKeyBytes: Data?
    let status: ToriiVerifyingKeyStatus?

    private enum CodingKeys: String, CodingKey {
        case authority
        case backend
        case name
        case version
        case circuitId = "circuit_id"
        case publicInputsSchemaHashHex = "public_inputs_schema_hash_hex"
        case curve
        case gasScheduleId = "gas_schedule_id"
        case verifyingKeyLength = "vk_len"
        case maxProofBytes = "max_proof_bytes"
        case metadataUriCid = "metadata_uri_cid"
        case verifyingKeyBytesCid = "vk_bytes_cid"
        case activationHeight = "activation_height"
        case withdrawHeight = "withdraw_height"
        case commitmentHex = "commitment_hex"
        case verifyingKeyBytes = "vk_bytes"
        case status
    }
}

fileprivate struct ToriiVerifyingKeyExpectedRecord {
    let version: UInt32
    let circuitId: String
    let backendTag: UInt32
    let curve: String
    let publicInputsSchemaHash: Data
    let commitment: Data
    let verifyingKeyLength: UInt32
    let maxProofBytes: UInt32
    let gasScheduleId: String?
    let metadataUriCid: String?
    let verifyingKeyBytesCid: String?
    let activationHeight: UInt64?
    let withdrawHeight: UInt64?
    let keyBackend: String?
    let keyBytes: Data?
    let status: UInt8
}

fileprivate enum ToriiVerifyingKeyDraftValidation {
    private static let maximumInstructionArchiveBytes = 16 * 1024 * 1024

    static func validate(
        _ envelope: ToriiVerifyingKeyTransactionDraftEnvelope,
        requestJSON: Data,
        expectedNetworkId: NetworkId,
        operation: ToriiVerifyingKeyDraftOperation
    ) throws -> ToriiVerifyingKeyTransactionDraft {
        let request: ToriiVerifyingKeyExpectedRequest
        do {
            request = try JSONDecoder().decode(ToriiVerifyingKeyExpectedRequest.self, from: requestJSON)
        } catch {
            throw ToriiClientError.decoding(error)
        }
        let expectedRecord = try makeExpectedRecord(request)
        var transaction = ToriiVerifyingKeyCompactReader(envelope.transactionPayload)
        let domain = try transaction.takeField("domain")
        let authority = try transaction.takeField("authority")
        let creationTime = try transaction.takeField("creation_time_ms")
        let executable = try transaction.takeField("executable")
        let timeToLive = try transaction.takeField("time_to_live_ms")
        let nonce = try transaction.takeField("nonce")
        let feePayment = try transaction.takeField("fee_payment")

        let metadata = try transaction.takeField("metadata")
        let attachments = try transaction.takeField("attachments")
        guard transaction.isFinished,
              creationTime.count == MemoryLayout<UInt64>.size else {
            throw invalid("transaction_payload_b64 must contain exactly one canonical nine-field TransactionPayload")
        }

        let decodedNetworkId = try decodeNetworkDomain(domain)
        guard decodedNetworkId == expectedNetworkId else {
            throw invalid("verifying-key transaction draft changed the configured network")
        }
        let expectedAuthority = try AccountAddress.parseEncoded(request.authority)
            .compactNoritoAccountControllerPayload()
        guard authority == expectedAuthority else {
            throw invalid("verifying-key transaction draft changed the requested authority")
        }
        try requireCanonicalNonZeroOption(
            timeToLive,
            width: MemoryLayout<UInt64>.size,
            required: true,
            field: "time_to_live_ms"
        )
        try requireCanonicalNonZeroOption(
            nonce,
            width: MemoryLayout<UInt32>.size,
            required: false,
            field: "nonce"
        )
        do {
            try TransactionFeePaymentValidation.requireCanonicalTransactionFeePayment(feePayment)
            try TransactionFeePaymentValidation.requireEmptyTransactionMetadata(metadata)
        } catch {
            throw invalid("verifying-key transaction fee payment or metadata is not canonical")
        }
        try requireAbsentOption(attachments, field: "attachments")
        try requireRequestedInstruction(
            executable,
            operation: operation,
            request: request,
            expectedRecord: expectedRecord
        )
        return ToriiVerifyingKeyTransactionDraft(envelope: envelope)
    }

    private static func makeExpectedRecord(
        _ request: ToriiVerifyingKeyExpectedRequest
    ) throws -> ToriiVerifyingKeyExpectedRecord {
        guard let schemaHash = Data(hexString: request.publicInputsSchemaHashHex),
              schemaHash.count == 32 else {
            throw invalid("request public_inputs_schema_hash_hex is not a 32-byte hash")
        }
        let commitment: Data
        if let keyBytes = request.verifyingKeyBytes {
            commitment = verifyingKeyCommitment(backend: request.backend, bytes: keyBytes)
        } else {
            guard let commitmentHex = request.commitmentHex,
                  let decoded = Data(hexString: commitmentHex),
                  decoded.count == 32 else {
                throw invalid("request commitment material is missing")
            }
            commitment = decoded
        }
        let keyLength: UInt32
        if let keyBytes = request.verifyingKeyBytes {
            guard keyBytes.count <= Int(UInt32.max) else {
                throw invalid("request verifying key exceeds the UInt32 wire bound")
            }
            keyLength = UInt32(keyBytes.count)
        } else if let explicitLength = request.verifyingKeyLength {
            keyLength = explicitLength
        } else {
            throw invalid("request vk_len is missing")
        }
        let status: UInt8
        switch request.status ?? .active {
        case .proposed:
            status = 0
        case .active:
            status = 1
        case .withdrawn:
            status = 2
        }
        let backendTag: UInt32 = request.backend.hasPrefix("stark/")
            ? VerifyingKeyBackendTag.stark.noritoDiscriminant
            : VerifyingKeyBackendTag.halo2IpaPasta.noritoDiscriminant
        return ToriiVerifyingKeyExpectedRecord(
            version: request.version,
            circuitId: request.circuitId,
            backendTag: backendTag,
            curve: request.curve ?? "unknown",
            publicInputsSchemaHash: schemaHash,
            commitment: commitment,
            verifyingKeyLength: keyLength,
            maxProofBytes: request.maxProofBytes ?? 0,
            gasScheduleId: request.gasScheduleId,
            metadataUriCid: request.metadataUriCid,
            verifyingKeyBytesCid: request.verifyingKeyBytesCid,
            activationHeight: request.activationHeight,
            withdrawHeight: request.withdrawHeight,
            keyBackend: request.verifyingKeyBytes == nil ? nil : request.backend,
            keyBytes: request.verifyingKeyBytes,
            status: status
        )
    }

    private static func verifyingKeyCommitment(backend: String, bytes: Data) -> Data {
        let backendBytes = Data(backend.utf8)
        var preimage = Data("iroha:zk:v1:vk".utf8)
        var backendLength = UInt64(backendBytes.count).bigEndian
        var keyLength = UInt64(bytes.count).bigEndian
        preimage.append(withUnsafeBytes(of: &backendLength) { Data($0) })
        preimage.append(backendBytes)
        preimage.append(withUnsafeBytes(of: &keyLength) { Data($0) })
        preimage.append(bytes)
        return Data(SHA256.hash(data: preimage))
    }

    private static func decodeNetworkDomain(_ payload: Data) throws -> NetworkId {
        var domain = ToriiVerifyingKeyCompactReader(payload)
        guard try domain.takeUInt32("domain.kind") == 0 else {
            throw invalid("transaction domain must use TransactionDomain::Network")
        }
        let networkIdBytes = try domain.takeField("domain.value")
        guard domain.isFinished else {
            throw invalid("transaction domain must contain exactly one NetworkId")
        }
        do {
            return try NetworkId(bytes: networkIdBytes)
        } catch {
            throw invalid("transaction domain contains an invalid canonical NetworkId")
        }
    }

    private static func requireRequestedInstruction(
        _ payload: Data,
        operation: ToriiVerifyingKeyDraftOperation,
        request: ToriiVerifyingKeyExpectedRequest,
        expectedRecord: ToriiVerifyingKeyExpectedRecord
    ) throws {
        var executable = ToriiVerifyingKeyCompactReader(payload)
        guard try executable.takeUInt32("executable.kind") == 0 else {
            throw invalid("verifying-key transaction executable must contain native instructions")
        }
        var instructions = ToriiVerifyingKeyCompactReader(
            try executable.takeField("executable.instructions")
        )
        guard executable.isFinished,
              try instructions.takeUInt64("executable.instructions.count") == 1 else {
            throw invalid("verifying-key transaction must contain exactly one instruction")
        }
        var instruction = ToriiVerifyingKeyCompactReader(
            try instructions.takeField("executable.instruction")
        )
        let wireName = try decodeString(
            try instruction.takeField("executable.instruction.wire_name"),
            field: "executable.instruction.wire_name"
        )
        let archive = try decodeByteVector(
            try instruction.takeField("executable.instruction.payload"),
            field: "executable.instruction.payload"
        )
        guard instructions.isFinished, instruction.isFinished,
              wireName == operation.wireName else {
            throw invalid("verifying-key transaction does not contain the requested registry operation")
        }
        try requireInstructionArchive(
            archive,
            wireName: wireName,
            request: request,
            expectedRecord: expectedRecord
        )
    }

    private static func requireInstructionArchive(
        _ archive: Data,
        wireName: String,
        request: ToriiVerifyingKeyExpectedRequest,
        expectedRecord: ToriiVerifyingKeyExpectedRecord
    ) throws {
        guard !archive.isEmpty,
              archive.count <= maximumInstructionArchiveBytes,
              let frame = noritoDecodeFrame(archive),
              frame.header.schema == noritoSchemaHash(forTypeName: wireName),
              frame.header.compression == .none,
              frame.header.flags == NoritoHeader.compactLen,
              frame.paddingLength == 0,
              !frame.payload.isEmpty,
              noritoEncode(
                  typeName: wireName,
                  payload: frame.payload,
                  flags: NoritoHeader.compactLen
              ) == archive else {
            throw invalid("verifying-key instruction archive is not canonical for \(wireName)")
        }
        var instruction = ToriiVerifyingKeyCompactReader(frame.payload)
        let id = try instruction.takeField("verifying_key.id")
        let record = try instruction.takeField("verifying_key.record")
        guard instruction.isFinished else {
            throw invalid("verifying-key instruction contains trailing fields")
        }
        try requireIdentifier(id, backend: request.backend, name: request.name)
        try requireRecord(record, expected: expectedRecord)
    }

    private static func requireIdentifier(
        _ payload: Data,
        backend: String,
        name: String
    ) throws {
        var id = ToriiVerifyingKeyCompactReader(payload)
        let decodedBackend = try decodeString(try id.takeField("id.backend"), field: "id.backend")
        let decodedName = try decodeString(try id.takeField("id.name"), field: "id.name")
        guard id.isFinished, decodedBackend == backend, decodedName == name else {
            throw invalid("verifying-key instruction identifier does not match the request")
        }
    }

    private static func requireRecord(
        _ payload: Data,
        expected: ToriiVerifyingKeyExpectedRecord
    ) throws {
        var record = ToriiVerifyingKeyCompactReader(payload)
        let version = try decodeUInt32(try record.takeField("record.version"), field: "record.version")
        let circuitId = try decodeString(try record.takeField("record.circuit_id"),
                                         field: "record.circuit_id")
        let ownerManifestId = try decodeOptionalString(
            try record.takeField("record.owner_manifest_id"),
            field: "record.owner_manifest_id"
        )
        let namespace = try decodeString(try record.takeField("record.namespace"),
                                         field: "record.namespace")
        let backendTag = try decodeUInt32(try record.takeField("record.backend"),
                                          field: "record.backend")
        let curve = try decodeString(try record.takeField("record.curve"), field: "record.curve")
        let schemaHash = try fixedBytes(
            try record.takeField("record.public_inputs_schema_hash"),
            count: 32,
            field: "record.public_inputs_schema_hash"
        )
        let commitment = try fixedBytes(
            try record.takeField("record.commitment"),
            count: 32,
            field: "record.commitment"
        )
        let keyLength = try decodeUInt32(try record.takeField("record.vk_len"),
                                         field: "record.vk_len")
        let maxProofBytes = try decodeUInt32(try record.takeField("record.max_proof_bytes"),
                                             field: "record.max_proof_bytes")
        let gasScheduleId = try decodeOptionalString(
            try record.takeField("record.gas_schedule_id"),
            field: "record.gas_schedule_id"
        )
        let metadataUriCid = try decodeOptionalString(
            try record.takeField("record.metadata_uri_cid"),
            field: "record.metadata_uri_cid"
        )
        let verifyingKeyBytesCid = try decodeOptionalString(
            try record.takeField("record.vk_bytes_cid"),
            field: "record.vk_bytes_cid"
        )
        let activationHeight = try decodeOptionalUInt64(
            try record.takeField("record.activation_height"),
            field: "record.activation_height"
        )
        let withdrawHeight = try decodeOptionalUInt64(
            try record.takeField("record.withdraw_height"),
            field: "record.withdraw_height"
        )
        let key = try decodeOptionalVerifyingKey(
            try record.takeField("record.key"),
            field: "record.key"
        )
        let status = try decodeUInt8(try record.takeField("record.status"), field: "record.status")
        guard record.isFinished,
              version == expected.version,
              circuitId == expected.circuitId,
              ownerManifestId == nil,
              namespace == "core",
              backendTag == expected.backendTag,
              curve == expected.curve,
              schemaHash == expected.publicInputsSchemaHash,
              commitment == expected.commitment,
              keyLength == expected.verifyingKeyLength,
              maxProofBytes == expected.maxProofBytes,
              gasScheduleId == expected.gasScheduleId,
              metadataUriCid == expected.metadataUriCid,
              verifyingKeyBytesCid == expected.verifyingKeyBytesCid,
              activationHeight == expected.activationHeight,
              withdrawHeight == expected.withdrawHeight,
              key?.backend == expected.keyBackend,
              key?.bytes == expected.keyBytes,
              status == expected.status else {
            throw invalid("verifying-key instruction record does not match the full requested record")
        }
    }

    private static func decodeString(_ payload: Data, field: String) throws -> String {
        var value = ToriiVerifyingKeyCompactReader(payload)
        let length = try value.takeLength("\(field).length")
        guard length <= UInt64(Int.max) else {
            throw invalid("\(field) exceeds the runtime bound")
        }
        let bytes = try value.takeBytes(Int(length), field: field)
        guard value.isFinished, let decoded = String(data: bytes, encoding: .utf8) else {
            throw invalid("\(field) is not one canonical UTF-8 string")
        }
        return decoded
    }

    private static func decodeByteVector(_ payload: Data, field: String) throws -> Data {
        var value = ToriiVerifyingKeyCompactReader(payload)
        let length = try value.takeUInt64("\(field).length")
        guard length > 0, length <= UInt64(Int.max) else {
            throw invalid("\(field) length is invalid")
        }
        let bytes = try value.takeBytes(Int(length), field: field)
        guard value.isFinished else {
            throw invalid("\(field) contains trailing bytes")
        }
        return bytes
    }

    private static func decodeUInt8(_ payload: Data, field: String) throws -> UInt8 {
        var value = ToriiVerifyingKeyCompactReader(payload)
        let decoded = try value.takeUInt8(field)
        guard value.isFinished else {
            throw invalid("\(field) contains trailing bytes")
        }
        return decoded
    }

    private static func decodeUInt32(_ payload: Data, field: String) throws -> UInt32 {
        var value = ToriiVerifyingKeyCompactReader(payload)
        let decoded = try value.takeUInt32(field)
        guard value.isFinished else {
            throw invalid("\(field) contains trailing bytes")
        }
        return decoded
    }

    private static func decodeUInt64(_ payload: Data, field: String) throws -> UInt64 {
        var value = ToriiVerifyingKeyCompactReader(payload)
        let decoded = try value.takeUInt64(field)
        guard value.isFinished else {
            throw invalid("\(field) contains trailing bytes")
        }
        return decoded
    }

    private static func fixedBytes(_ payload: Data, count: Int, field: String) throws -> Data {
        guard payload.count == count else {
            throw invalid("\(field) must contain exactly \(count) bytes")
        }
        return payload
    }

    private static func decodeOptionalString(_ payload: Data, field: String) throws -> String? {
        try decodeOption(payload, field: field) { try decodeString($0, field: field) }
    }

    private static func decodeOptionalUInt64(_ payload: Data, field: String) throws -> UInt64? {
        try decodeOption(payload, field: field) { try decodeUInt64($0, field: field) }
    }

    private static func decodeOptionalVerifyingKey(
        _ payload: Data,
        field: String
    ) throws -> (backend: String, bytes: Data)? {
        try decodeOption(payload, field: field) { value in
            var key = ToriiVerifyingKeyCompactReader(value)
            let backend = try decodeString(try key.takeField("\(field).backend"),
                                           field: "\(field).backend")
            let bytes = try decodeByteVector(try key.takeField("\(field).bytes"),
                                             field: "\(field).bytes")
            guard key.isFinished else {
                throw invalid("\(field) contains trailing fields")
            }
            return (backend, bytes)
        }
    }

    private static func decodeOption<T>(
        _ payload: Data,
        field: String,
        decode: (Data) throws -> T
    ) throws -> T? {
        var option = ToriiVerifyingKeyCompactReader(payload)
        switch try option.takeUInt8("\(field).tag") {
        case 0:
            guard option.isFinished else {
                throw invalid("\(field) None encoding contains trailing bytes")
            }
            return nil
        case 1:
            let value = try decode(try option.takeField("\(field).value"))
            guard option.isFinished else {
                throw invalid("\(field) Some encoding contains trailing bytes")
            }
            return value
        default:
            throw invalid("\(field) has an invalid option tag")
        }
    }

    private static func requireCanonicalNonZeroOption(
        _ payload: Data,
        width: Int,
        required: Bool,
        field: String
    ) throws {
        var option = ToriiVerifyingKeyCompactReader(payload)
        switch try option.takeUInt8("\(field).tag") {
        case 0:
            guard !required, option.isFinished else {
                throw invalid("\(field) must contain one canonical nonzero integer")
            }
        case 1:
            let value = try option.takeField("\(field).value")
            guard option.isFinished, value.count == width,
                  value.contains(where: { $0 != 0 }) else {
                throw invalid("\(field) Some value is not a canonical nonzero integer")
            }
        default:
            throw invalid("\(field) has an invalid option tag")
        }
    }

    private static func requireAbsentOption(_ payload: Data, field: String) throws {
        var option = ToriiVerifyingKeyCompactReader(payload)
        guard try option.takeUInt8("\(field).tag") == 0,
              option.isFinished else {
            throw invalid("\(field) must use the exact None encoding")
        }
    }

    private static func invalid(_ message: String) -> ToriiClientError {
        .invalidPayload(message)
    }
}

struct ToriiVerifyingKeyCompactReader {
    private let data: Data
    private var offset = 0

    init(_ data: Data) {
        self.data = data
    }

    var isFinished: Bool { offset == data.count }

    mutating func takeUInt8(_ field: String) throws -> UInt8 {
        guard offset < data.count else {
            throw ToriiClientError.invalidPayload("\(field) is truncated")
        }
        defer { offset += 1 }
        return data[data.startIndex + offset]
    }

    mutating func takeUInt32(_ field: String) throws -> UInt32 {
        let bytes = try takeBytes(MemoryLayout<UInt32>.size, field: field)
        return bytes.withUnsafeBytes {
            UInt32(littleEndian: $0.loadUnaligned(as: UInt32.self))
        }
    }

    mutating func takeUInt64(_ field: String) throws -> UInt64 {
        let bytes = try takeBytes(MemoryLayout<UInt64>.size, field: field)
        return bytes.withUnsafeBytes {
            UInt64(littleEndian: $0.loadUnaligned(as: UInt64.self))
        }
    }

    mutating func takeLength(_ field: String) throws -> UInt64 {
        var value: UInt64 = 0
        var shift: UInt64 = 0
        for count in 1...10 {
            let byte = try takeUInt8(field)
            let chunk = UInt64(byte & 0x7f)
            guard shift < 64, chunk <= UInt64.max >> shift else {
                throw ToriiClientError.invalidPayload("\(field) compact length overflows UInt64")
            }
            value |= chunk << shift
            if byte & 0x80 == 0 {
                guard count == 1 || chunk != 0 else {
                    throw ToriiClientError.invalidPayload("\(field) compact length is overlong")
                }
                return value
            }
            shift += 7
        }
        throw ToriiClientError.invalidPayload("\(field) compact length is overlong")
    }

    mutating func takeField(_ field: String) throws -> Data {
        let length = try takeLength("\(field).length")
        guard length <= UInt64(Int.max) else {
            throw ToriiClientError.invalidPayload("\(field) exceeds the runtime bound")
        }
        return try takeBytes(Int(length), field: field)
    }

    mutating func takeBytes(_ count: Int, field: String) throws -> Data {
        guard count >= 0, count <= data.count - offset else {
            throw ToriiClientError.invalidPayload("\(field) is truncated")
        }
        defer { offset += count }
        let start = data.startIndex + offset
        return Data(data[start..<(start + count)])
    }
}

enum ToriiRequestValidation {
    static func normalizedNonEmpty(_ value: String, field: String) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
        }
        return trimmed
    }

    static func exactToken(_ value: String, field: String) throws -> String {
        guard !value.isEmpty,
              value.rangeOfCharacter(from: .whitespacesAndNewlines) == nil,
              value.rangeOfCharacter(from: .controlCharacters) == nil else {
            throw ToriiClientError.invalidPayload(
                "\(field) must be exact non-empty text without whitespace or control characters."
            )
        }
        return value
    }

    static func governanceSelector(_ value: String, field: String) throws -> String {
        guard GovernanceSelectorV1.isValid(value) else {
            throw ToriiClientError.invalidPayload(
                "\(field) must be 1-128 RFC 3986 unreserved ASCII characters and must not start with a dot."
            )
        }
        return value
    }

    static func normalizedOptionalNonEmpty(_ value: String?, field: String) throws -> String? {
        guard let value else { return nil }
        return try normalizedNonEmpty(value, field: field)
    }

    static func exactLowercase32ByteHex(_ value: String, field: String) throws -> String {
        guard value.count == 64,
              value.unicodeScalars.allSatisfy({ scalar in
                  (48...57).contains(scalar.value) || (97...102).contains(scalar.value)
              }) else {
            throw ToriiClientError.invalidPayload(
                "\(field) must be exactly 64 lowercase hexadecimal characters."
            )
        }
        return value
    }

    static func exactTransactionHashHex(_ value: String, field: String) throws -> String {
        let exact = try exactLowercase32ByteHex(value, field: field)
        guard let marker = exact.unicodeScalars.last,
              "13579bdf".unicodeScalars.contains(marker) else {
            throw ToriiClientError.invalidPayload(
                "\(field) must be one canonical typed transaction hash ending in an odd hexadecimal marker."
            )
        }
        return exact
    }

    static func normalized32ByteHex(_ value: String, field: String) throws -> String {
        var trimmed = try normalizedNonEmpty(value, field: field)
        if trimmed.hasPrefix("0x") || trimmed.hasPrefix("0X") {
            trimmed = String(trimmed.dropFirst(2))
        }
        guard trimmed.count == 64, Data(hexString: trimmed) != nil else {
            throw ToriiClientError.invalidPayload("\(field) must be a 32-byte hex string.")
        }
        return trimmed.lowercased()
    }

    static func normalized16ByteHex(_ value: String, field: String) throws -> String {
        var trimmed = try normalizedNonEmpty(value, field: field)
        if trimmed.hasPrefix("0x") || trimmed.hasPrefix("0X") {
            trimmed = String(trimmed.dropFirst(2))
        }
        guard trimmed.count == 32, Data(hexString: trimmed) != nil else {
            throw ToriiClientError.invalidPayload("\(field) must be a 16-byte hex string.")
        }
        return trimmed.lowercased()
    }

    static func normalizedOptional32ByteHex(_ value: String?, field: String) throws -> String? {
        guard let value else { return nil }
        return try normalized32ByteHex(value, field: field)
    }

    static func normalizedEvenLengthHex(_ value: String, field: String) throws -> String {
        var trimmed = try normalizedNonEmpty(value, field: field)
        if trimmed.hasPrefix("0x") || trimmed.hasPrefix("0X") {
            trimmed = String(trimmed.dropFirst(2))
        }
        guard !trimmed.isEmpty, trimmed.count.isMultiple(of: 2), Data(hexString: trimmed) != nil else {
            throw ToriiClientError.invalidPayload("\(field) must be an even-length hex string.")
        }
        return trimmed.lowercased()
    }

    static func normalizedBase64(_ value: String, field: String) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be a non-empty base64 string.")
        }
        guard let data = Data(base64Encoded: trimmed), !data.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be valid base64.")
        }
        return trimmed
    }

    static func normalizedExactBase64(_ value: String, field: String) throws -> String {
        guard !value.isEmpty, value == value.trimmingCharacters(in: .whitespacesAndNewlines) else {
            throw ToriiClientError.invalidPayload("\(field) must be exact standard-base64.")
        }
        guard let data = Data(base64Encoded: value), !data.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be valid base64.")
        }
        guard data.base64EncodedString() == value else {
            throw ToriiClientError.invalidPayload("\(field) must be exact standard-base64.")
        }
        return value
    }
}

fileprivate enum ToriiValidation {
    static func normalizedNonEmpty(_ value: String,
                                   field: String,
                                   codingPath: [CodingKey]) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must be a non-empty string"
                )
            )
        }
        return trimmed
    }

    static func normalizedExactNonEmpty(_ value: String,
                                        field: String,
                                        codingPath: [CodingKey]) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must be a non-empty string"
                )
            )
        }
        guard trimmed == value else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must not contain surrounding whitespace"
                )
            )
        }
        return value
    }

    static func normalizedBackend(_ value: String,
                                  field: String,
                                  codingPath: [CodingKey]) throws -> String {
        let trimmed = try normalizedNonEmpty(value, field: field, codingPath: codingPath)
        if trimmed.contains(":") {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must not contain ':' characters"
                )
            )
        }
        return trimmed
    }

    static func normalizedProductionVerifyBackend(_ value: String,
                                                  field: String,
                                                  codingPath: [CodingKey]) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must be a non-empty string"
                )
            )
        }
        guard trimmed == value else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must not contain surrounding whitespace"
                )
            )
        }
        guard VerifierBackendRegistryLabels.isSupported(value) else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) is not an exact supported verifier-registry label: \(value)"
                )
            )
        }
        return value
    }

    static func normalized32ByteHex(_ value: String,
                                    field: String,
                                    codingPath: [CodingKey]) throws -> String {
        var trimmed = try normalizedNonEmpty(value, field: field, codingPath: codingPath)
        if trimmed.hasPrefix("0x") || trimmed.hasPrefix("0X") {
            trimmed = String(trimmed.dropFirst(2))
        }
        guard trimmed.count == 64, Data(hexString: trimmed) != nil else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must be a 32-byte hex string"
                )
            )
        }
        return trimmed.lowercased()
    }

    static func normalizedBase64(_ value: String,
                                 field: String,
                                 codingPath: [CodingKey]) throws -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, let data = Data(base64Encoded: trimmed), !data.isEmpty else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must be valid base64"
                )
            )
        }
        return trimmed
    }

    static func validatedUInt32(_ value: Int,
                                field: String,
                                codingPath: [CodingKey]) throws -> Int {
        guard value >= 0, value <= Int(UInt32.max) else {
            throw DecodingError.dataCorrupted(
                DecodingError.Context(
                    codingPath: codingPath,
                    debugDescription: "\(field) must fit in a u32"
                )
            )
        }
        return value
    }
}

/// Proof events to deliver from `streamProofEvents(filter:)`.
///
/// `backend`, `callHashHex` and `envelopeHashHex` narrow the stream on Torii
/// through the event-stream text filter (`proof_backend`, `proof_call_hash`,
/// `proof_envelope_hash`); the event kinds and `proofHashHex`, which the
/// grammar does not expose, are applied to each decoded event. A pruning event
/// matches by backend and, for `proofHashHex`, by its removed proofs; like
/// Torii, a call or envelope hash criterion excludes pruning events.
public struct ToriiProofEventFilter: Sendable, Equatable {
    public var backend: String?
    public var proofHashHex: String?
    public var callHashHex: String?
    public var envelopeHashHex: String?
    public var includeVerified: Bool
    public var includeRejected: Bool
    public var includePruned: Bool

    public init(backend: String? = nil,
                proofHashHex: String? = nil,
                callHashHex: String? = nil,
                envelopeHashHex: String? = nil,
                includeVerified: Bool = true,
                includeRejected: Bool = true,
                includePruned: Bool = true) {
        self.backend = backend
        self.proofHashHex = proofHashHex
        self.callHashHex = callHashHex
        self.envelopeHashHex = envelopeHashHex
        self.includeVerified = includeVerified
        self.includeRejected = includeRejected
        self.includePruned = includePruned
    }

    /// The event-stream filter Torii applies, or `nil` when no server-side field is set.
    ///
    /// - Throws: `ToriiClientError.invalidPayload` for an unsupported backend
    ///   or a malformed hash, or when no event kind is enabled.
    public func serverFilter() throws -> ToriiFilter? {
        guard includeVerified || includeRejected || includePruned else {
            throw ToriiClientError.invalidPayload("Enable at least one proof event type.")
        }
        var conditions: [ToriiFilter] = []
        if let backend {
            let normalized = try ToriiVerifyingKeyRequestValidation.normalizedBackend(backend, field: "backend")
            conditions.append(ToriiEventFields.proofBackend == normalized)
        }
        if let callHashHex {
            conditions.append(ToriiEventFields.proofCallHash == (try Self.normalizedHashHex(callHashHex, field: "callHashHex")))
        }
        if let envelopeHashHex {
            conditions.append(
                ToriiEventFields.proofEnvelopeHash == (try Self.normalizedHashHex(envelopeHashHex, field: "envelopeHashHex"))
            )
        }
        if let proofHashHex {
            _ = try Self.normalizedHashHex(proofHashHex, field: "proofHashHex")
        }
        return ToriiFilter.all(conditions)
    }

    /// Whether `event` satisfies every criterion.
    public func matches(_ event: ToriiProofEvent) -> Bool {
        let normalizedBackend = backend.map {
            (try? ToriiVerifyingKeyRequestValidation.normalizedBackend($0, field: "backend")) ?? $0
        }
        func same(_ expected: String?, _ actual: String?) -> Bool {
            guard let expected else { return true }
            return (try? Self.normalizedHashHex(expected, field: "hash")) == actual?.lowercased()
        }
        let body: ToriiProofEventBody
        switch event {
        case let .verified(eventBody):
            guard includeVerified else { return false }
            body = eventBody
        case let .rejected(eventBody):
            guard includeRejected else { return false }
            body = eventBody
        case let .pruned(pruned):
            guard includePruned, callHashHex == nil, envelopeHashHex == nil else { return false }
            if let normalizedBackend, pruned.backend != normalizedBackend {
                return false
            }
            guard proofHashHex != nil else { return true }
            return pruned.removed.contains { same(proofHashHex, $0.proofHashHex) }
        }
        if let normalizedBackend, body.id.backend != normalizedBackend {
            return false
        }
        return same(proofHashHex, body.id.proofHashHex)
            && same(callHashHex, body.callHashHex)
            && same(envelopeHashHex, body.envelopeHashHex)
    }

    private static func normalizedHashHex(_ value: String, field: String) throws -> String {
        var trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else {
            throw ToriiClientError.invalidPayload("\(field) must be a non-empty string.")
        }
        if trimmed.hasPrefix("0x") || trimmed.hasPrefix("0X") {
            trimmed = String(trimmed.dropFirst(2))
        }
        guard trimmed.count == 64, Data(hexString: trimmed) != nil else {
            throw ToriiClientError.invalidPayload("Expected a 32-byte \(field) in hex form.")
        }
        return trimmed.lowercased()
    }
}

enum ToriiCanonicalHashLiteral {
    private static let tag = "hash"
    private static let prefix = "hash:"
    private static let bodyLength = 64
    private static let checksumLength = 4
    private static let crcPolynomial: UInt16 = 0x1021

    static func normalizedHex(from literal: String) -> String? {
        let bytes = Array(literal.utf8)
        let prefixBytes = Array(prefix.utf8)
        let expectedLength = prefixBytes.count + bodyLength + 1 + checksumLength
        guard bytes.count == expectedLength,
              Array(bytes.prefix(prefixBytes.count)) == prefixBytes else {
            return nil
        }
        let bodyStart = prefixBytes.count
        let bodyEnd = bodyStart + bodyLength
        guard bytes[bodyEnd] == 0x23 else {
            return nil
        }
        let bodyBytes = Array(bytes[bodyStart..<bodyEnd])
        let checksumBytes = Array(bytes[(bodyEnd + 1)...])
        guard bodyBytes.allSatisfy(isUppercaseHex),
              checksumBytes.allSatisfy(isUppercaseHex),
              let body = String(bytes: bodyBytes, encoding: .utf8),
              let checksum = String(bytes: checksumBytes, encoding: .utf8),
              let parsedChecksum = UInt16(checksum, radix: 16),
              parsedChecksum == crc16(body: body),
              let hashBytes = Data(hexString: body),
              hashBytes.count == 32,
              hashBytes.last.map({ $0 & 1 == 1 }) == true else {
            return nil
        }
        return body.lowercased()
    }

    static func literal(fromNormalizedHex value: String) -> String? {
        guard normalizedConvenienceHex(value) != nil else {
            return nil
        }
        let body = value.uppercased()
        return "\(prefix)\(body)#\(String(format: "%04X", crc16(body: body)))"
    }

    static func normalizedConvenienceHex(_ value: String) -> String? {
        let bodyBytes = Array(value.utf8)
        guard bodyBytes.count == bodyLength,
              bodyBytes.allSatisfy(isLowercaseHex),
              let hashBytes = Data(hexString: value),
              hashBytes.count == 32,
              hashBytes.last.map({ $0 & 1 == 1 }) == true else {
            return nil
        }
        return value
    }

    private static func isUppercaseHex(_ byte: UInt8) -> Bool {
        (48...57).contains(byte) || (65...70).contains(byte)
    }

    private static func isLowercaseHex(_ byte: UInt8) -> Bool {
        (48...57).contains(byte) || (97...102).contains(byte)
    }

    private static func crc16(body: String) -> UInt16 {
        var crc: UInt16 = 0xFFFF
        for byte in "\(tag):\(body)".utf8 {
            crc ^= UInt16(byte) << 8
            for _ in 0..<8 {
                crc = (crc & 0x8000) != 0
                    ? (crc &<< 1) ^ crcPolynomial
                    : crc &<< 1
            }
        }
        return crc
    }
}

fileprivate func rejectUnknownContractManifestFields(
    from decoder: Decoder,
    allowed: Set<String>,
    context: String
) throws {
    let container = try decoder.container(keyedBy: ToriiAnyCodingKey.self)
    if let unknown = container.allKeys.first(where: { !allowed.contains($0.stringValue) }) {
        throw DecodingError.dataCorruptedError(
            forKey: unknown,
            in: container,
            debugDescription: "\(context) contains unknown field `\(unknown.stringValue)`"
        )
    }
}

func isExactContractManifestString(_ value: String, allowEmpty: Bool = false) -> Bool {
    guard (allowEmpty || !value.isEmpty),
          value == value.trimmingCharacters(in: .whitespacesAndNewlines) else {
        return false
    }
    return !value.unicodeScalars.contains { CharacterSet.controlCharacters.contains($0) }
}

fileprivate func isCanonicalContractManifestBase64(_ value: String) -> Bool {
    guard isExactContractManifestString(value),
          let bytes = Data(base64Encoded: value),
          !bytes.isEmpty else {
        return false
    }
    return bytes.base64EncodedString() == value
}

public struct ToriiContractDynamicAccessHint: Codable, Sendable, Equatable {
    public var baseKey: String
    public var keyType: String
    public var boundKind: String
    public var maxKeys: UInt32

    public init(baseKey: String, keyType: String, boundKind: String, maxKeys: UInt32) {
        self.baseKey = baseKey
        self.keyType = keyType
        self.boundKind = boundKind
        self.maxKeys = maxKeys
    }

    private enum CodingKeys: String, CodingKey {
        case baseKey = "base_key"
        case keyType = "key_type"
        case boundKind = "bound_kind"
        case maxKeys = "max_keys"
    }

    private var hasCanonicalBaseKey: Bool {
        let prefix = "state:"
        guard baseKey.hasPrefix(prefix),
              isExactContractManifestString(baseKey) else {
            return false
        }
        return ToriiEntrypointValueTypeV1.isCanonicalDeclarationIdentifier(
            String(baseKey.dropFirst(prefix.count))
        )
    }

    private var hasCanonicalKeyType: Bool {
        ToriiEntrypointValueTypeV1.isCanonicalStateMapKeyType(keyType)
    }

    private var hasCanonicalBoundKind: Bool {
        ToriiEntrypointValueTypeV1.isCanonicalDynamicAccessBoundKind(boundKind)
    }

    private var hasCanonicalMaximum: Bool {
        ToriiEntrypointValueTypeV1.isCanonicalDynamicAccessMaximum(maxKeys)
    }

    private var isCanonical: Bool {
        hasCanonicalBaseKey
            && hasCanonicalKeyType
            && hasCanonicalBoundKind
            && hasCanonicalMaximum
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: ["base_key", "key_type", "bound_kind", "max_keys"],
            context: "dynamic access hint"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        baseKey = try container.decode(String.self, forKey: .baseKey)
        keyType = try container.decode(String.self, forKey: .keyType)
        boundKind = try container.decode(String.self, forKey: .boundKind)
        maxKeys = try container.decode(UInt32.self, forKey: .maxKeys)
        guard hasCanonicalBaseKey else {
            throw DecodingError.dataCorruptedError(
                forKey: .baseKey,
                in: container,
                debugDescription:
                    "dynamic access hint base_key must be state: followed by one "
                    + "canonical state declaration identifier"
            )
        }
        guard hasCanonicalKeyType else {
            throw DecodingError.dataCorruptedError(
                forKey: .keyType,
                in: container,
                debugDescription:
                    "dynamic access hint key_type must be an exact canonical StateMap key type"
            )
        }
        guard hasCanonicalBoundKind else {
            throw DecodingError.dataCorruptedError(
                forKey: .boundKind,
                in: container,
                debugDescription: "dynamic access hint bound_kind must be take or page"
            )
        }
        guard hasCanonicalMaximum else {
            throw DecodingError.dataCorruptedError(
                forKey: .maxKeys,
                in: container,
                debugDescription: "dynamic access hint max_keys must be in 1...64"
            )
        }
    }

    public func encode(to encoder: Encoder) throws {
        guard isCanonical else {
            throw EncodingError.invalidValue(
                self,
                .init(codingPath: encoder.codingPath,
                      debugDescription:
                          "dynamic access hint must use a canonical state declaration, "
                          + "StateMap key type, take/page bound, and max_keys in 1...64")
            )
        }
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(baseKey, forKey: .baseKey)
        try container.encode(keyType, forKey: .keyType)
        try container.encode(boundKind, forKey: .boundKind)
        try container.encode(maxKeys, forKey: .maxKeys)
    }
}

public struct ToriiContractAccessSetHints: Codable, Sendable, Equatable {
    public var readKeys: [String]
    public var writeKeys: [String]
    public var dynamicReads: [ToriiContractDynamicAccessHint]
    public var dynamicWrites: [ToriiContractDynamicAccessHint]

    public init(readKeys: [String] = [],
                writeKeys: [String] = [],
                dynamicReads: [ToriiContractDynamicAccessHint] = [],
                dynamicWrites: [ToriiContractDynamicAccessHint] = []) {
        self.readKeys = readKeys
        self.writeKeys = writeKeys
        self.dynamicReads = dynamicReads
        self.dynamicWrites = dynamicWrites
    }

    private enum CodingKeys: String, CodingKey {
        case readKeys = "read_keys"
        case writeKeys = "write_keys"
        case dynamicReads = "dynamic_reads"
        case dynamicWrites = "dynamic_writes"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: ["read_keys", "write_keys", "dynamic_reads", "dynamic_writes"],
            context: "contract access-set hints"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        readKeys = try container.decode([String].self, forKey: .readKeys)
        writeKeys = try container.decode([String].self, forKey: .writeKeys)
        dynamicReads = try container.decodeIfPresent(
            [ToriiContractDynamicAccessHint].self,
            forKey: .dynamicReads
        ) ?? []
        dynamicWrites = try container.decodeIfPresent(
            [ToriiContractDynamicAccessHint].self,
            forKey: .dynamicWrites
        ) ?? []
        guard readKeys.allSatisfy({ isExactContractManifestString($0) }),
              writeKeys.allSatisfy({ isExactContractManifestString($0) }) else {
            throw DecodingError.dataCorrupted(
                .init(codingPath: container.codingPath,
                      debugDescription: "contract access-set keys must be exact non-empty strings")
            )
        }
    }

    public func encode(to encoder: Encoder) throws {
        guard readKeys.allSatisfy({ isExactContractManifestString($0) }),
              writeKeys.allSatisfy({ isExactContractManifestString($0) }) else {
            throw EncodingError.invalidValue(
                self,
                .init(codingPath: encoder.codingPath,
                      debugDescription: "contract access-set keys must be exact non-empty strings")
            )
        }
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(readKeys, forKey: .readKeys)
        try container.encode(writeKeys, forKey: .writeKeys)
        try container.encode(dynamicReads, forKey: .dynamicReads)
        try container.encode(dynamicWrites, forKey: .dynamicWrites)
    }
}

