        func component(_ value: String) -> Bool {
            func identifierByte(_ byte: UInt8) -> Bool {
                (65...90).contains(byte) || (97...122).contains(byte)
                    || (48...57).contains(byte) || byte == 95
            }
            guard let first = value.utf8.first, identifierByte(first) else { return false }
            return value.utf8.allSatisfy { identifierByte($0) || $0 == 46 || $0 == 45 }
        }
        let package = parts[0].components(separatedBy: "@")
        return (1...2).contains(package.count)
            && package[0].components(separatedBy: "/").allSatisfy(component)
            && (package.count == 1 || component(package[1]))
    }

    private static func isCanonicalUserStructIdentifier(_ value: String) -> Bool {
        value.utf8.count <= 1024
            && (isCanonicalTypeDeclarationIdentifier(value) || isCanonicalQualifiedStructIdentifier(value))
    }

    fileprivate static func isCanonicalStateMapKeyType(_ value: String) -> Bool {
        stateMapKeyTypeNames.contains(value)
    }

    fileprivate static func isCanonicalDynamicAccessBoundKind(_ value: String) -> Bool {
        dynamicAccessBoundKinds.contains(value)
    }

    fileprivate static func isCanonicalDynamicAccessMaximum(_ value: UInt32) -> Bool {
        (1...maximumDynamicAccessKeys).contains(value)
    }

    fileprivate static func isCanonicalStateTypeName(_ value: String, errorIdentities: Set<String>? = nil) -> Bool {
        guard !value.isEmpty else {
            return false
        }

        let bytes = Array(value.utf8)
        var cursor = 0
        var nodes = 0

        func isASCIILetter(_ byte: UInt8) -> Bool {
            (65...90).contains(byte) || (97...122).contains(byte)
        }

        func isASCIIDigit(_ byte: UInt8) -> Bool {
            (48...57).contains(byte)
        }

        func consume(_ literal: String) -> Bool {
            let token = literal.utf8
            guard cursor + token.count <= bytes.count else {
                return false
            }
            for (offset, byte) in token.enumerated() where bytes[cursor + offset] != byte {
                return false
            }
            cursor += token.count
            return true
        }

        func identifier() -> String? {
            let start = cursor
            guard cursor < bytes.count,
                  bytes[cursor] == 95 || isASCIILetter(bytes[cursor]) else {
                return nil
            }
            cursor += 1
            while cursor < bytes.count {
                let byte = bytes[cursor]
                guard byte == 95 || isASCIILetter(byte) || isASCIIDigit(byte) else {
                    break
                }
                cursor += 1
            }
            return String(decoding: bytes[start..<cursor], as: UTF8.self)
        }

        func listCapacity() -> Bool {
            let start = cursor
            var capacity = 0
            var exceededMaximum = false
            while cursor < bytes.count, isASCIIDigit(bytes[cursor]) {
                if !exceededMaximum {
                    capacity = capacity * 10 + Int(bytes[cursor] - 48)
                    exceededMaximum = capacity > 64
                }
                cursor += 1
            }
            guard cursor != start,
                  !(cursor - start > 1 && bytes[start] == 48) else {
                return false
            }
            return !exceededMaximum && (1...64).contains(capacity)
        }

        func parseType(allowStateMap: Bool, depth: Int) -> String? {
            nodes += 1
            guard depth <= maximumStateTypeDepth,
                  nodes <= maximumStateTypeNodes else {
                return nil
            }

            if consume("()") { return "unit" }
            let errorStart = cursor
            var errorEnd = cursor
            let identityPunctuation = Set("_:/@.-".utf8)
            while errorEnd < bytes.count && (bytes[errorEnd] >= 128 || isASCIILetter(bytes[errorEnd]) || isASCIIDigit(bytes[errorEnd]) || identityPunctuation.contains(bytes[errorEnd])) { errorEnd += 1 }
            let errorIdentity = String(decoding: bytes[errorStart..<errorEnd], as: UTF8.self)
            let qualifiedStructName = errorEnd < bytes.count && bytes[errorEnd] == 123
                && isCanonicalQualifiedStructIdentifier(errorIdentity) ? errorIdentity : nil
            if qualifiedStructName != nil {
                cursor = errorEnd
            } else if errorIdentity.contains("::"), ToriiContractErrorTypeDescriptor.isCanonicalIdentity(errorIdentity) {
                if let errorIdentities, !errorIdentities.contains(errorIdentity) { return nil }
                cursor = errorEnd
                return "error"
            }
            if consume("(") {
                guard parseType(allowStateMap: false, depth: depth + 1) != nil,
                      consume(", "),
                      parseType(allowStateMap: false, depth: depth + 1) != nil else {
                    return nil
                }
                while consume(", ") {
                    guard parseType(allowStateMap: false, depth: depth + 1) != nil else {
                        return nil
                    }
                }
                return consume(")") ? "" : nil
            }

            guard let name = qualifiedStructName ?? identifier() else {
                return nil
            }
            if stateScalarTypeNames.contains(name) {
                return name
            }
            if name == "Option" {
                guard consume("<"),
                      parseType(allowStateMap: false, depth: depth + 1) != nil,
                      consume(">") else {
                    return nil
                }
                return ""
            }
            if name == "Result" {
                guard consume("<"),
                      parseType(allowStateMap: false, depth: depth + 1) != nil,
                      consume(", "),
                      parseType(allowStateMap: false, depth: depth + 1) != nil,
                      consume(">") else {
                    return nil
                }
                return ""
            }
            if name == "List" {
                guard consume("<"),
                      parseType(allowStateMap: false, depth: depth + 1) != nil,
                      consume(", "),
                      listCapacity(),
                      consume(">") else {
                    return nil
                }
                return ""
            }
            if name == "StateCursor" {
                guard consume("<"), let key = identifier(), Self.isCanonicalStateMapKeyType(key), consume(">") else { return nil }
                return "aggregate"
            }
            if name == "StateMap" {
                guard allowStateMap,
                      consume("<") else {
                    return nil
                }
                // Runtime reconstructs only V as StateValueSchemaV1, so the
                // wrapper and scalar key do not consume value-schema nodes.
                nodes -= 1
                // EmbeddedStateType depth still includes the map wrapper.
                guard let keyType = identifier(),
                      stateMapKeyTypeNames.contains(keyType),
                      consume(", "),
                      parseType(allowStateMap: false, depth: depth + 1) != nil,
                      consume(">") else {
                    return nil
                }
                return ""
            }
            if name == "StatePage" {
                nodes += 5 // List, Tuple, scalar key, Option, StateCursor.
                guard nodes <= maximumStateTypeNodes, depth + 3 <= maximumStateTypeDepth,
                      consume("{items: List<("), let key = identifier(), stateMapKeyTypeNames.contains(key),
                      consume(", "), parseType(allowStateMap: false, depth: depth + 3) != nil,
                      consume("), "), listCapacity(), consume(">, next: Option<StateCursor<"),
                      consume(key), consume(">>}") else { return nil }
                return "aggregate"
            }
            guard isCanonicalUserStructIdentifier(name),
                  consume("{") else {
                return nil
            }
            // Empty products retain their validated nominal name and have no fields.
            if consume("}") { return "" }
            var fields: Set<String> = []
            while true {
                guard let field = identifier(),
                      isCanonicalIdentifier(field),
                      fields.insert(field).inserted,
                      consume(": "),
                      parseType(allowStateMap: false, depth: depth + 1) != nil else {
                    return nil
                }
                if consume("}") {
                    return ""
                }
                guard consume(", ") else {
                    return nil
                }
            }
        }

        return parseType(allowStateMap: true, depth: 1) != nil && cursor == bytes.count
    }

    fileprivate static func topLevelStateMapKeyType(_ value: String) -> String? {
        let prefix = "StateMap<"
        guard value.hasPrefix(prefix),
              isCanonicalStateTypeName(value) else {
            return nil
        }
        let keyStart = value.index(value.startIndex, offsetBy: prefix.count)
        guard let separator = value.range(
            of: ", ",
            range: keyStart..<value.endIndex
        ) else {
            return nil
        }
        let keyType = String(value[keyStart..<separator.lowerBound])
        return stateMapKeyTypeNames.contains(keyType) ? keyType : nil
    }

    fileprivate static func isCanonicalEntrypointName(_ value: String) -> Bool {
        value == "hajimari" || value == "始まり" || value == "kaizen" || value == "改善"
            || isCanonicalDeclarationIdentifier(value)
    }

    private static func canonicalLeafName(_ kind: ToriiEntrypointValueKindV1) -> String {
        switch kind {
        case .int: return "int"
        case .decimal: return "decimal"
        case .quantity: return "quantity"
        case .bool: return "bool"
        case .string: return "string"
        case .json: return "Json"
        case .name: return "Name"
        case .accountId: return "AccountId"
        case .assetDefinitionId: return "AssetDefinitionId"
        case .assetId: return "AssetId"
        case .domainId: return "DomainId"
        case .nftId: return "NftId"
        case .dataSpaceId: return "DataSpaceId"
        case .blob: return "bytes"
        }
    }

    private static func isExactCoreQueryView(
        _ descriptor: ToriiEntrypointStructTypeNodeV1,
        childTypeNames: [String]
    ) -> Bool {
        let expected: ([String], [String])?
        switch descriptor.name {
        case "AccountView":
            expected = (["id", "metadata"], ["AccountId", "Json"])
        case "AssetView":
            expected = (["id", "amount"], ["AssetId", "quantity"])
        case "AssetDefinitionView":
            expected = (
                ["id", "name", "description", "owned_by", "total_quantity", "numeric_scale", "metadata"],
                ["AssetDefinitionId", "string", "Option<string>", "AccountId", "quantity", "Option<int>", "Json"]
            )
        case "DomainView":
            expected = (
                ["id", "owned_by", "metadata"],
                ["DomainId", "AccountId", "Json"]
            )
        case "NftView":
            expected = (
                ["id", "owned_by", "content"],
                ["NftId", "AccountId", "Json"]
            )
        default:
            expected = nil
        }
        guard let expected else {
            return false
        }
        return descriptor.fields == expected.0 && childTypeNames == expected.1
    }

    private struct AnalysisFrame {
        var remainingChildren: Int
        var suppressWords: Bool
    }

    private struct RenderedType {
        var canonicalTypeName: String
        var coreQueryViewName: String?
        var listCapacity: UInt8?
        var listElementCoreQueryViewName: String?
    }

    private static func childCount(of node: ToriiEntrypointValueTypeNodeV1) -> Int {
        switch node {
        case .structType(let descriptor):
            return descriptor.fields.count
        case .tuple(let arity):
            return Int(arity)
        case .option, .list:
            return 1
        case .result:
            return 2
        case .leaf, .unit, .error, .stateCursor:
            return 0
        }
    }

    private static func takeRenderedChildren(
        _ rendered: inout [RenderedType],
        count: Int
    ) -> [RenderedType]? {
        guard rendered.count >= count else {
            return nil
        }
        if count == 0 {
            return []
        }
        let start = rendered.count - count
        let children = Array(rendered[start...].reversed())
        rendered.removeSubrange(start...)
        return children
    }

    private func analysis() -> Analysis? {
        guard !nodes.isEmpty, nodes.count <= Self.maximumNodes else {
            return nil
        }

        var frames: [AnalysisFrame] = []
        var wordCount = 0
        var maxDepth = 0
        for (index, node) in nodes.enumerated() {
            while frames.last?.remainingChildren == 0 {
                frames.removeLast()
            }

            let suppressWords: Bool
            if index == 0 {
                suppressWords = false
            } else {
                guard !frames.isEmpty, frames[frames.count - 1].remainingChildren > 0 else {
                    return nil
                }
                suppressWords = frames[frames.count - 1].suppressWords
                frames[frames.count - 1].remainingChildren -= 1
            }

            let depth = frames.count + 1
            guard depth <= Self.maximumDepth else {
                return nil
            }
            maxDepth = max(maxDepth, depth)

            switch node {
            case .structType(let descriptor):
                let isReservedSchemaName = descriptor.name == "QueryPage" || descriptor.name == "StatePage"
                    || Self.coreQueryViewNames.contains(descriptor.name)
                guard isReservedSchemaName
                        || Self.isCanonicalUserStructIdentifier(descriptor.name),
                      descriptor.fields.allSatisfy(Self.isCanonicalIdentifier),
                      Set(descriptor.fields).count == descriptor.fields.count else {
                    return nil
                }
            case .tuple(let arity):
                guard arity >= 2 else {
                    return nil
                }
            case .list(let descriptor):
                guard (1...64).contains(descriptor.capacity) else {
                    return nil
                }
            case .stateCursor(let key):
                guard key != .json else { return nil }
            case .error(let descriptor):
                guard descriptor.isCanonical else { return nil }
            case .option, .result, .leaf, .unit:
                break
            }

            let isHandle: Bool
            switch node {
            case .option, .result, .list:
                isHandle = true
            case .structType, .tuple, .leaf, .unit, .error, .stateCursor:
                isHandle = false
            }
            if !suppressWords && (isHandle || Self.childCount(of: node) == 0) {
                wordCount += 1
            }
            let children = Self.childCount(of: node)
            if children != 0 {
                frames.append(
                    AnalysisFrame(
                        remainingChildren: children,
                        suppressWords: suppressWords || isHandle
                    )
                )
            }
        }
        while frames.last?.remainingChildren == 0 {
            frames.removeLast()
        }
        guard frames.isEmpty else {
            return nil
        }

        var rendered: [RenderedType] = []
        for (index, node) in nodes.enumerated().reversed() {
            guard let children = Self.takeRenderedChildren(
                &rendered,
                count: Self.childCount(of: node)
            ) else {
                return nil
            }
            let result: RenderedType
            switch node {
            case .structType(let descriptor):
                let childTypeNames = children.map(\.canonicalTypeName)
                if descriptor.name == "StatePage" {
                    guard descriptor.fields == ["items", "next"], index + 3 < nodes.count,
                          case .list(let list) = nodes[index + 1], case .tuple(2) = nodes[index + 2],
                          case .leaf(let key) = nodes[index + 3], key != .json else { return nil }
                    var end = index + 4
                    var pending = 1
                    while pending > 0 {
                        guard end < nodes.count else { return nil }
                        pending += Self.childCount(of: nodes[end]) - 1
                        end += 1
                    }
                    guard end + 1 < nodes.count, nodes[end] == .option, nodes[end + 1] == .stateCursor(key),
                          children.count == 2 else { return nil }
                    let listName = children[0].canonicalTypeName
                    let suffix = "), \(list.capacity)>"
                    guard listName.hasPrefix("List<("), listName.hasSuffix(suffix) else { return nil }
                    let types = listName.dropFirst(6).dropLast(suffix.count)
                    result = RenderedType(canonicalTypeName: "StatePage<\(types), \(list.capacity)>", coreQueryViewName: nil, listCapacity: nil, listElementCoreQueryViewName: nil)
                } else if descriptor.name == "QueryPage" {
                    guard descriptor.fields == ["items", "next_offset"],
                          children.count == 2,
                          children[0].listCapacity == 64,
                          let viewName = children[0].listElementCoreQueryViewName,
                          children[1].canonicalTypeName == "Option<int>" else {
                        return nil
                    }
                    result = RenderedType(
                        canonicalTypeName: "QueryPage<\(viewName)>",
                        coreQueryViewName: nil,
                        listCapacity: nil,
                        listElementCoreQueryViewName: nil
                    )
                } else if Self.coreQueryViewNames.contains(descriptor.name) {
                    guard Self.isExactCoreQueryView(
                        descriptor,
                        childTypeNames: childTypeNames
                    ) else {
                        return nil
                    }
                    result = RenderedType(
                        canonicalTypeName: descriptor.name,
                        coreQueryViewName: descriptor.name,
                        listCapacity: nil,
                        listElementCoreQueryViewName: nil
                    )
                } else {
                    result = RenderedType(
                        canonicalTypeName: "struct \(descriptor.name)",
                        coreQueryViewName: nil,
                        listCapacity: nil,
                        listElementCoreQueryViewName: nil
                    )
                }
            case .tuple:
                result = RenderedType(
                    canonicalTypeName: "(\(children.map(\.canonicalTypeName).joined(separator: ", ")))",
                    coreQueryViewName: nil,
                    listCapacity: nil,
                    listElementCoreQueryViewName: nil
                )
            case .option:
                guard let child = children.first else {
                    return nil
                }
                result = RenderedType(
                    canonicalTypeName: "Option<\(child.canonicalTypeName)>",
                    coreQueryViewName: nil,
                    listCapacity: nil,
                    listElementCoreQueryViewName: nil
                )
            case .result:
                guard children.count == 2 else {
                    return nil
                }
                result = RenderedType(
                    canonicalTypeName:
                        "Result<\(children[0].canonicalTypeName), \(children[1].canonicalTypeName)>",
                    coreQueryViewName: nil,
                    listCapacity: nil,
                    listElementCoreQueryViewName: nil
                )
            case .list(let descriptor):
                guard let child = children.first else {
                    return nil
                }
                result = RenderedType(
                    canonicalTypeName: "List<\(child.canonicalTypeName), \(descriptor.capacity)>",
                    coreQueryViewName: nil,
                    listCapacity: descriptor.capacity,
                    listElementCoreQueryViewName: child.coreQueryViewName
                )
            case .stateCursor(let key):
                result = RenderedType(canonicalTypeName: "StateCursor<\(Self.canonicalLeafName(key))>", coreQueryViewName: nil, listCapacity: nil, listElementCoreQueryViewName: nil)
            case .unit:
                result = RenderedType(canonicalTypeName: "()", coreQueryViewName: nil, listCapacity: nil, listElementCoreQueryViewName: nil)
            case .error(let descriptor):
                result = RenderedType(canonicalTypeName: descriptor.identity, coreQueryViewName: nil, listCapacity: nil, listElementCoreQueryViewName: nil)
            case .leaf(let kind):
                result = RenderedType(
                    canonicalTypeName: Self.canonicalLeafName(kind),
                    coreQueryViewName: nil,
                    listCapacity: nil,
                    listElementCoreQueryViewName: nil
                )
            }
            rendered.append(result)
        }
        guard rendered.count == 1, let root = rendered.first else {
            return nil
        }
        return Analysis(
            nodeCount: nodes.count,
            wordCount: wordCount,
            maxDepth: maxDepth,
            canonicalTypeName: root.canonicalTypeName,
            coreQueryViewName: root.coreQueryViewName,
            listElementCoreQueryViewName: root.listElementCoreQueryViewName
        )
    }

    public var wordCount: Int? {
        analysis()?.wordCount
    }

    public var canonicalTypeName: String? {
        analysis()?.canonicalTypeName
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: ["nodes"],
            context: "Kotodama boundary type"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        nodes = try container.decode([ToriiEntrypointValueTypeNodeV1].self, forKey: .nodes)
        guard analysis() != nil else {
            throw DecodingError.dataCorruptedError(
                forKey: .nodes,
                in: container,
                debugDescription: "Kotodama boundary type is not a canonical V1 schema"
            )
        }
    }

    public func encode(to encoder: Encoder) throws {
        guard analysis() != nil else {
            throw EncodingError.invalidValue(
                self,
                .init(codingPath: encoder.codingPath,
                      debugDescription: "Kotodama boundary type is not a canonical V1 schema")
            )
        }
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(nodes, forKey: .nodes)
    }
}

public struct ToriiEntrypointArgumentFieldV1: Codable, Sendable, Equatable {
