public struct ToriiContractManifest: Codable, Sendable, Equatable {
    public var seiyakuName: String?
    public var codeHash: String?
    public var abiHash: String?
    public var compilerFingerprint: String?
    public var featuresBitmap: UInt64?
    public var accessSetHints: ToriiContractAccessSetHints?
    public var entrypoints: [ToriiContractEntrypointDescriptor]?
    public var states: [ToriiContractStateDescriptor]?
    public var errorTypes: [ToriiContractErrorTypeDescriptor]?
    public var errorMessages: [ToriiContractErrorMessage]?
    public var kotoba: [ToriiContractKotobaTranslationEntry]?
    public var provenance: ToriiContractManifestProvenance?

    public init(seiyakuName: String? = nil,
                codeHash: String? = nil,
                abiHash: String? = nil,
                compilerFingerprint: String? = nil,
                featuresBitmap: UInt64? = nil,
                accessSetHints: ToriiContractAccessSetHints? = nil,
                entrypoints: [ToriiContractEntrypointDescriptor]? = nil,
                states: [ToriiContractStateDescriptor]? = nil,
                errorTypes: [ToriiContractErrorTypeDescriptor]? = nil,
                errorMessages: [ToriiContractErrorMessage]? = nil,
                kotoba: [ToriiContractKotobaTranslationEntry]? = nil,
                provenance: ToriiContractManifestProvenance? = nil) {
        self.seiyakuName = seiyakuName
        self.codeHash = codeHash
        self.abiHash = abiHash
        self.compilerFingerprint = compilerFingerprint
        self.featuresBitmap = featuresBitmap
        self.accessSetHints = accessSetHints
        self.entrypoints = entrypoints
        self.states = states
        self.errorTypes = errorTypes
        self.errorMessages = errorMessages
        self.kotoba = kotoba
        self.provenance = provenance
    }

    private enum CodingKeys: String, CodingKey {
        case seiyakuName = "seiyaku_name"
        case codeHash = "code_hash"
        case abiHash = "abi_hash"
        case compilerFingerprint = "compiler_fingerprint"
        case featuresBitmap = "features_bitmap"
        case accessSetHints = "access_set_hints"
        case entrypoints
        case states
        case errorTypes = "error_types"
        case errorMessages = "error_messages"
        case kotoba
        case provenance
    }

    private var canonicalFailure: String? {
        if let seiyakuName,
           !ToriiEntrypointValueTypeV1.isCanonicalTypeDeclarationIdentifier(seiyakuName) {
            return "seiyaku_name must be a canonical non-reserved Kotodama declaration"
        }
        if let compilerFingerprint,
           !isExactContractManifestString(compilerFingerprint) {
            return "compiler_fingerprint must be an exact non-empty string"
        }
        if let featuresBitmap, (featuresBitmap & ~UInt64(3)) != 0 {
            return "features_bitmap contains unsupported Kotodama V1 bits"
        }
        if let entrypoints {
            let names = entrypoints.map(\.name)
            if Set(names).count != names.count {
                return "entrypoint names must be unique"
            }
            if entrypoints.filter({ $0.kind == .hajimari }).count > 1
                || entrypoints.filter({ $0.kind == .kaizen }).count > 1 {
                return "lifecycle entrypoints must be unique"
            }
            let kinds = Dictionary(uniqueKeysWithValues: entrypoints.map { ($0.name, $0.kind) })
            var triggerIds = Set<String>()
            for descriptor in entrypoints {
                for trigger in descriptor.triggers {
                    if !triggerIds.insert(trigger.id).inserted {
                        return "trigger ids must be globally unique"
                    }
                    if trigger.callback.namespace == nil,
                       kinds[trigger.callback.entrypoint] != .kotoage {
                        return "local trigger callbacks must target a declared kotoage entrypoint"
                    }
                }
            }
        }
        if let states {
            if Set(states.map(\.name)).count != states.count {
                return "state names must be unique"
            }
        }
        if let accessSetHints {
            let stateMapKeyTypes = Dictionary(
                uniqueKeysWithValues: (states ?? []).compactMap { state in
                    ToriiEntrypointValueTypeV1.topLevelStateMapKeyType(state.typeName)
                        .map { (state.name, $0) }
                }
            )
            let dynamicLists = [
                ("access_set_hints.dynamic_reads", accessSetHints.dynamicReads),
                ("access_set_hints.dynamic_writes", accessSetHints.dynamicWrites),
            ]
            for (field, hints) in dynamicLists {
                for index in hints.indices {
                    let hint = hints[index]
                    if hints[..<index].contains(hint) {
                        return "\(field) contains duplicate hint `\(hint.baseKey)`"
                    }
                    let prefix = "state:"
                    guard hint.baseKey.hasPrefix(prefix) else {
                        continue
                    }
                    let stateName = String(hint.baseKey.dropFirst(prefix.count))
                    guard let expectedKeyType = stateMapKeyTypes[stateName] else {
                        return "\(field) hint `\(hint.baseKey)` must reference a declared top-level StateMap"
                    }
                    if hint.keyType != expectedKeyType {
                        return "\(field) hint `\(hint.baseKey)` declares key_type `\(hint.keyType)` "
                            + "but its StateMap key type is `\(expectedKeyType)`"
                    }
                }
            }
        }
        if let errorTypes {
            if errorTypes.count > 256 || !errorTypes.allSatisfy(\.isCanonical) || Set(errorTypes.map(\.identity)).count != errorTypes.count {
                return "error_types must contain at most 256 unique canonical identities"
            }
        }
        let catalog = Dictionary(uniqueKeysWithValues: (errorTypes ?? []).map { ($0.identity, $0) })
        for state in states ?? [] {
            if !ToriiEntrypointValueTypeV1.isCanonicalStateTypeName(state.typeName, errorIdentities: Set(catalog.keys)) {
                return "state nominal error identity is not declared in error_types catalog"
            }
        }
        for entrypoint in entrypoints ?? [] {
            var schemas = (entrypoint.argumentSchema?.fields ?? []).map(\.type)
            if let schema = entrypoint.returnSchema { schemas.append(schema) }
            for schema in schemas {
                for node in schema.nodes {
                    if case .error(let error) = node, catalog[error.identity] != error {
                        return "boundary error schema does not match error_types catalog"
                    }
                }
            }
        }
        var previousMessage: ToriiContractErrorMessage?
        for entry in errorMessages ?? [] {
            guard entry.isCanonical, let error = catalog[entry.errorType],
                  error.variants.contains(where: { $0.code == entry.code }) else {
                return "error message must reference a declared variant and contain bounded text"
            }
            if let previous = previousMessage {
                let ordered = previous.errorType.utf8.lexicographicallyPrecedes(entry.errorType.utf8)
                    || (previous.errorType.utf8.elementsEqual(entry.errorType.utf8) && previous.code < entry.code)
                if !ordered { return "error messages must be sorted and unique by identity and code" }
            }
            previousMessage = entry
        }
        if let kotoba, Set(kotoba.map(\.messageId)).count != kotoba.count {
            return "kotoba message ids must be unique"
        }
        return nil
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "seiyaku_name", "code_hash", "abi_hash", "compiler_fingerprint",
                "features_bitmap", "access_set_hints", "entrypoints", "states",
                "error_types", "error_messages", "kotoba", "provenance",
            ],
            context: "contract manifest"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        if let seiyakuName = try container.decodeIfPresent(String.self, forKey: .seiyakuName) {
            let normalized = try ToriiValidation.normalizedNonEmpty(
                seiyakuName,
                field: "seiyaku_name",
                codingPath: container.codingPath + [CodingKeys.seiyakuName]
            )
            guard normalized == seiyakuName,
                  ToriiEntrypointValueTypeV1.isCanonicalTypeDeclarationIdentifier(normalized) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .seiyakuName,
                    in: container,
                    debugDescription: "seiyaku_name must be a canonical Kotodama identifier"
                )
            }
            self.seiyakuName = normalized
        } else {
            self.seiyakuName = nil
        }
        if let codeHash = try container.decodeIfPresent(String.self, forKey: .codeHash) {
            guard let normalized = ToriiCanonicalHashLiteral.normalizedHex(from: codeHash) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .codeHash,
                    in: container,
                    debugDescription: "code_hash must be one canonical checksummed Norito Hash literal"
                )
            }
            self.codeHash = normalized
        } else {
            self.codeHash = nil
        }
        if let abiHash = try container.decodeIfPresent(String.self, forKey: .abiHash) {
            guard let normalized = ToriiCanonicalHashLiteral.normalizedHex(from: abiHash) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .abiHash,
                    in: container,
                    debugDescription: "abi_hash must be one canonical checksummed Norito Hash literal"
                )
            }
            self.abiHash = normalized
        } else {
            self.abiHash = nil
        }
        compilerFingerprint = try container.decodeIfPresent(String.self, forKey: .compilerFingerprint)
        featuresBitmap = try container.decodeIfPresent(UInt64.self, forKey: .featuresBitmap)
        accessSetHints = try container.decodeIfPresent(ToriiContractAccessSetHints.self,
                                                       forKey: .accessSetHints)
        entrypoints = try container.decodeIfPresent(
            [ToriiContractEntrypointDescriptor].self,
            forKey: .entrypoints
        )
        states = try container.decodeIfPresent([ToriiContractStateDescriptor].self, forKey: .states)
        errorTypes = try container.decodeIfPresent(
            [ToriiContractErrorTypeDescriptor].self,
            forKey: .errorTypes
        )
        errorMessages = try container.decodeIfPresent([ToriiContractErrorMessage].self, forKey: .errorMessages)
        kotoba = try container.decodeIfPresent(
            [ToriiContractKotobaTranslationEntry].self,
            forKey: .kotoba
        )
        provenance = try container.decodeIfPresent(
            ToriiContractManifestProvenance.self,
            forKey: .provenance
        )
        if let canonicalFailure {
            throw DecodingError.dataCorrupted(
                .init(codingPath: container.codingPath,
                      debugDescription: "contract manifest is not canonical: \(canonicalFailure)")
            )
        }
    }

    public func encode(to encoder: Encoder) throws {
        if let canonicalFailure {
            throw EncodingError.invalidValue(
                self,
                .init(codingPath: encoder.codingPath,
                      debugDescription: "contract manifest is not canonical: \(canonicalFailure)")
            )
        }
        var container = encoder.container(keyedBy: CodingKeys.self)
        if let seiyakuName {
            guard ToriiEntrypointValueTypeV1.isCanonicalTypeDeclarationIdentifier(seiyakuName) else {
                throw EncodingError.invalidValue(
                    seiyakuName,
                    .init(codingPath: encoder.codingPath,
                          debugDescription: "seiyaku_name must be a canonical Kotodama identifier")
                )
            }
            try container.encode(
                try ToriiRequestValidation.normalizedNonEmpty(
                    seiyakuName,
                    field: "seiyaku_name"
                ),
                forKey: .seiyakuName
            )
        } else {
            try container.encodeNil(forKey: .seiyakuName)
        }
        if let codeHash {
            guard let literal = ToriiCanonicalHashLiteral.literal(fromNormalizedHex: codeHash) else {
                throw ToriiClientError.invalidPayload(
                    "code_hash must be canonical lowercase 64-hex with the Iroha hash marker bit set"
                )
            }
            try container.encode(literal, forKey: .codeHash)
        } else {
            try container.encodeNil(forKey: .codeHash)
        }
        if let abiHash {
            guard let literal = ToriiCanonicalHashLiteral.literal(fromNormalizedHex: abiHash) else {
                throw ToriiClientError.invalidPayload(
                    "abi_hash must be canonical lowercase 64-hex with the Iroha hash marker bit set"
                )
            }
            try container.encode(literal, forKey: .abiHash)
        } else {
            try container.encodeNil(forKey: .abiHash)
        }
        try container.encode(compilerFingerprint, forKey: .compilerFingerprint)
        try container.encode(featuresBitmap, forKey: .featuresBitmap)
        try container.encode(accessSetHints, forKey: .accessSetHints)
        try container.encode(entrypoints, forKey: .entrypoints)
        try container.encode(states, forKey: .states)
        try container.encode(errorTypes, forKey: .errorTypes)
        try container.encode(errorMessages, forKey: .errorMessages)
        try container.encode(kotoba, forKey: .kotoba)
        try container.encode(provenance, forKey: .provenance)
    }
}

public struct ToriiContractManifestRecord: Decodable, Sendable {
    public let networkId: NetworkId
    public let artifactId: ContractArtifactId
    public let manifest: ToriiContractManifest
    public let codeHash: String?
    public let abiHash: String?
    /// Optional complete artifact bytes, retained in canonical base64 after digest validation.
    public let codeBytes: String?

    private enum CodingKeys: String, CodingKey {
        case networkId = "network_id"
        case artifactId = "artifact_id"
        case manifest
        case codeHash = "code_hash"
        case abiHash = "abi_hash"
        case codeBytes = "code_bytes"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: ["network_id", "artifact_id", "manifest", "code_hash", "abi_hash", "code_bytes"],
            context: "contract manifest response"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        networkId = try container.decode(NetworkId.self, forKey: .networkId)
        artifactId = try container.decode(ContractArtifactId.self, forKey: .artifactId)
        manifest = try container.decode(ToriiContractManifest.self, forKey: .manifest)
        guard container.contains(.codeHash), container.contains(.abiHash) else {
            throw DecodingError.dataCorrupted(.init(codingPath: container.codingPath,
                debugDescription: "Contract manifest responses require code_hash and abi_hash conveniences."))
        }
        let rawCodeHash = try container.decodeIfPresent(String.self, forKey: .codeHash)
        let rawAbiHash = try container.decodeIfPresent(String.self, forKey: .abiHash)
        let normalizedCodeHash = try rawCodeHash.map { value in
            guard let normalized = ToriiCanonicalHashLiteral.normalizedConvenienceHex(value) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .codeHash,
                    in: container,
                    debugDescription: "code_hash must be canonical lowercase 64-hex"
                )
            }
            return normalized
        }
        let normalizedAbiHash = try rawAbiHash.map { value in
            guard let normalized = ToriiCanonicalHashLiteral.normalizedConvenienceHex(value) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .abiHash,
                    in: container,
                    debugDescription: "abi_hash must be canonical lowercase 64-hex"
                )
            }
            return normalized
        }
        guard normalizedCodeHash == manifest.codeHash,
              normalizedCodeHash == artifactId.codeHashHex,
              normalizedAbiHash == manifest.abiHash else {
            throw DecodingError.dataCorrupted(
                .init(codingPath: container.codingPath,
                      debugDescription: "top-level contract hash conveniences must exactly match the canonical manifest hashes")
            )
        }
        codeHash = manifest.codeHash
        abiHash = manifest.abiHash
        codeBytes = try container.decodeIfPresent(String.self, forKey: .codeBytes)
        if let codeBytes, !validContractArtifactBytes(codeBytes, artifactId: artifactId) {
            throw DecodingError.dataCorruptedError(forKey: .codeBytes, in: container,
                debugDescription: "code_bytes must be bounded canonical base64 matching the complete artifact hash.")
        }
    }
}

private func validContractArtifactBytes(_ encoded: String, artifactId: ContractArtifactId) -> Bool {
    let maximum = 16 * 1_024 * 1_024
    guard encoded.utf8.count <= ((maximum + 2) / 3) * 4,
          let bytes = Data(base64Encoded: encoded), !bytes.isEmpty,
          bytes.count <= maximum, bytes.base64EncodedString() == encoded else { return false }
    return IrohaHash.hash(Data("iroha:ivm:contract-artifact:v1\0".utf8) + bytes).hexLowercased() == artifactId.codeHashHex
}

/// Authenticated, bounded complete artifact bytes with exact network and dataspace identity.
public struct ToriiContractCodeBytes: Decodable, Sendable {
    public let networkId: NetworkId
    public let artifactId: ContractArtifactId
    public let codeB64: String

    private enum CodingKeys: String, CodingKey {
        case networkId = "network_id"
        case artifactId = "artifact_id"
        case codeB64 = "code_b64"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(from: decoder,
            allowed: ["network_id", "artifact_id", "code_b64"], context: "contract bytes response")
        let container = try decoder.container(keyedBy: CodingKeys.self)
        networkId = try container.decode(NetworkId.self, forKey: .networkId)
        artifactId = try container.decode(ContractArtifactId.self, forKey: .artifactId)
        let encoded = try container.decode(String.self, forKey: .codeB64)
        guard validContractArtifactBytes(encoded, artifactId: artifactId) else {
            throw DecodingError.dataCorruptedError(forKey: .codeB64, in: container,
                debugDescription: "Contract bytes must be bounded canonical base64 matching the complete artifact hash.")
        }
        codeB64 = encoded
    }
}

public enum ToriiContractAliasLeaseStatus: String, Decodable, Sendable, Equatable {
    case permanent
    case leasedActive = "leased_active"
    case leasedGrace = "leased_grace"
    case expiredPendingCleanup = "expired_pending_cleanup"
}

public struct ToriiContractAliasBinding: Decodable, Sendable, Equatable {
    public let alias: String
    public let status: ToriiContractAliasLeaseStatus
    public let leaseExpiryMs: UInt64?
    public let graceUntilMs: UInt64?
    public let boundAtMs: UInt64

    private enum CodingKeys: String, CodingKey {
        case alias
        case status
        case leaseExpiryMs = "lease_expiry_ms"
        case graceUntilMs = "grace_until_ms"
        case boundAtMs = "bound_at_ms"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: ["alias", "status", "lease_expiry_ms", "grace_until_ms", "bound_at_ms"],
            context: "contract alias binding"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        alias = try normalizeToriiContractAliasLiteral(
            container.decode(String.self, forKey: .alias),
            field: "contract_alias_binding.alias"
        )
        status = try container.decode(ToriiContractAliasLeaseStatus.self, forKey: .status)
        leaseExpiryMs = try container.decodeIfPresent(UInt64.self, forKey: .leaseExpiryMs)
        graceUntilMs = try container.decodeIfPresent(UInt64.self, forKey: .graceUntilMs)
        boundAtMs = try container.decode(UInt64.self, forKey: .boundAtMs)

        switch status {
        case .permanent:
            guard leaseExpiryMs == nil, graceUntilMs == nil else {
                throw DecodingError.dataCorruptedError(
                    forKey: .status,
                    in: container,
                    debugDescription: "permanent contract aliases must not have lease timestamps"
                )
            }
        case .leasedActive, .leasedGrace, .expiredPendingCleanup:
            guard let leaseExpiryMs,
                  let graceUntilMs,
                  leaseExpiryMs >= boundAtMs,
                  graceUntilMs >= leaseExpiryMs else {
                throw DecodingError.dataCorruptedError(
                    forKey: .leaseExpiryMs,
                    in: container,
                    debugDescription: "leased contract alias timestamps are incomplete or out of order"
                )
            }
        }
    }
}

public struct ToriiContractAliasResolution: Decodable, Sendable, Equatable {
    public let contractAlias: String
    public let contractAddress: String
    public let dataspace: String
    public let binding: ToriiContractAliasBinding?
    public let source: String?

    private enum CodingKeys: String, CodingKey {
        case contractAlias = "contract_alias"
        case contractAddress = "contract_address"
        case dataspace
        case binding = "contract_alias_binding"
        case source
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "contract_alias", "contract_address", "dataspace",
                "contract_alias_binding", "source",
            ],
            context: "contract alias resolution"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        contractAlias = try normalizeToriiContractAliasLiteral(
            container.decode(String.self, forKey: .contractAlias),
            field: "contract_alias"
        )
        contractAddress = try normalizeToriiContractAddressLiteral(
            container.decode(String.self, forKey: .contractAddress),
            field: "contract_address"
        )
        dataspace = try ToriiValidation.normalizedExactNonEmpty(
            container.decode(String.self, forKey: .dataspace),
            field: "dataspace",
            codingPath: container.codingPath + [CodingKeys.dataspace]
        )
        binding = try container.decodeIfPresent(ToriiContractAliasBinding.self, forKey: .binding)
        if let binding, binding.alias != contractAlias {
            throw DecodingError.dataCorruptedError(
                forKey: .binding,
                in: container,
                debugDescription: "contract alias binding must match the resolved alias"
            )
        }
        if let rawSource = try container.decodeIfPresent(String.self, forKey: .source) {
            source = try ToriiValidation.normalizedExactNonEmpty(
                rawSource,
                field: "source",
                codingPath: container.codingPath + [CodingKeys.source]
            )
        } else {
            source = nil
        }
    }
}

public enum ToriiContractStateTarget: Sendable, Equatable {
    case address(String)
    case alias(String)
}

public enum ToriiContractStateSelector: Sendable, Equatable {
    case path(String)
    case paths([String])
    case prefix(String)
}

public struct ToriiContractStateQuery: Sendable, Equatable {
    public let target: ToriiContractStateTarget
    public let selector: ToriiContractStateSelector
    public let includeValue: Bool
    public let offset: UInt64
    public let limit: UInt64
    public let decodeJSON: Bool

    public init(
        target: ToriiContractStateTarget,
        selector: ToriiContractStateSelector,
        includeValue: Bool = true,
        offset: UInt64 = 0,
        limit: UInt64 = 1_000,
        decodeJSON: Bool = false
    ) throws {
        switch target {
        case let .address(value):
            self.target = .address(try normalizeToriiContractAddressLiteral(
                value,
                field: "contract state.contract_address"
            ))
        case let .alias(value):
            self.target = .alias(try normalizeToriiContractAliasLiteral(
                value,
                field: "contract state.contract_alias"
            ))
        }

        switch selector {
        case let .path(path):
            self.selector = .path(try Self.normalizedPath(path, field: "path"))
        case let .paths(paths):
            guard !paths.isEmpty, paths.count <= 10_000 else {
                throw ToriiClientError.invalidPayload("paths must contain between 1 and 10,000 values.")
            }
            let normalized = try paths.enumerated().map {
                try Self.normalizedPath($0.element, field: "paths[\($0.offset)]")
            }
            guard Set(normalized).count == normalized.count else {
                throw ToriiClientError.invalidPayload("paths must not contain duplicate values.")
            }
            guard normalized.joined(separator: ",").utf8.count <= 65_536 else {
                throw ToriiClientError.invalidPayload(
                    "comma-separated paths must not exceed 65,536 UTF-8 bytes."
                )
            }
            self.selector = .paths(normalized)
        case let .prefix(prefix):
            self.selector = .prefix(try Self.normalizedPath(prefix, field: "prefix"))
        }

        guard (1...10_000).contains(limit) else {
            throw ToriiClientError.invalidPayload("limit must be between 1 and 10,000.")
        }
        switch self.selector {
        case .prefix:
            break
        case .path, .paths:
            guard offset == 0, limit == 1_000 else {
                throw ToriiClientError.invalidPayload(
                    "offset and limit are only valid for prefix contract-state queries."
                )
            }
        }
        self.includeValue = includeValue
        self.offset = offset
        self.limit = limit
        self.decodeJSON = decodeJSON
    }

    fileprivate func queryItems() -> [URLQueryItem] {
        var items = [URLQueryItem]()
        switch target {
        case let .address(value):
            items.append(URLQueryItem(name: "contract_address", value: value))
        case let .alias(value):
            items.append(URLQueryItem(name: "contract_alias", value: value))
        }
        switch selector {
        case let .path(value):
            items.append(URLQueryItem(name: "path", value: value))
        case let .paths(values):
            items.append(URLQueryItem(name: "paths", value: values.joined(separator: ",")))
        case let .prefix(value):
            items.append(URLQueryItem(name: "prefix", value: value))
            items.append(URLQueryItem(name: "offset", value: String(offset)))
            items.append(URLQueryItem(name: "limit", value: String(limit)))
        }
        items.append(URLQueryItem(name: "include_value", value: includeValue ? "true" : "false"))
        if decodeJSON {
            items.append(URLQueryItem(name: "decode", value: "json"))
        }
        return items
    }

    fileprivate static func normalizedPath(_ value: String, field: String) throws -> String {
        guard !value.isEmpty,
              value.utf8.count <= 4_096,
              value == value.trimmingCharacters(in: .whitespacesAndNewlines),
              !value.contains(","),
              !value.unicodeScalars.contains(where: CharacterSet.controlCharacters.contains)
        else {
            throw ToriiClientError.invalidPayload(
                "\(field) must be exact, non-empty contract-state path text without commas or controls."
            )
        }
        return value
    }
}

public struct ToriiContractStateEntry: Decodable, Sendable, Equatable {
    public let path: String
    public let found: Bool
    public let valueB64: String?
    public let valueLength: UInt64?
    public let valueJSON: ToriiJSONValue?

    private enum CodingKeys: String, CodingKey {
        case path
        case found
        case valueB64 = "value_b64"
        case valueLength = "value_len"
        case valueJSON = "value_json"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: ["path", "found", "value_b64", "value_len", "value_json"],
            context: "contract state entry"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        path = try ToriiContractStateQuery.normalizedPath(
            container.decode(String.self, forKey: .path),
            field: "entry.path"
        )
        found = try container.decode(Bool.self, forKey: .found)
        if let encoded = try container.decodeIfPresent(String.self, forKey: .valueB64) {
            guard let bytes = Data(base64Encoded: encoded),
                  bytes.base64EncodedString() == encoded else {
                throw DecodingError.dataCorruptedError(
                    forKey: .valueB64,
                    in: container,
                    debugDescription: "value_b64 must be canonical standard base64"
                )
            }
            valueB64 = encoded
            let decodedLength = try container.decode(UInt64.self, forKey: .valueLength)
            guard decodedLength == UInt64(bytes.count) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .valueLength,
                    in: container,
                    debugDescription: "value_len must match decoded value_b64 length"
                )
            }
            valueLength = decodedLength
        } else {
            guard try container.decodeIfPresent(UInt64.self, forKey: .valueLength) == nil else {
                throw DecodingError.dataCorruptedError(
                    forKey: .valueLength,
                    in: container,
                    debugDescription: "value_len requires value_b64"
                )
            }
            valueB64 = nil
            valueLength = nil
        }
        if container.contains(.valueJSON) {
            valueJSON = try container.decode(ToriiJSONValue.self, forKey: .valueJSON)
        } else {
            valueJSON = nil
        }
        guard found || (valueB64 == nil && valueJSON == nil) else {
            throw DecodingError.dataCorruptedError(
                forKey: .found,
                in: container,
                debugDescription: "missing entries must not carry values"
            )
        }
    }
}

public struct ToriiContractStateResponse: Decodable, Sendable, Equatable {
    public let contractAddress: String?
    public let contractAlias: String?
    public let path: String?
    public let paths: [String]?
    public let prefix: String?
    public let entries: [ToriiContractStateEntry]
    public let offset: UInt64
    public let limit: UInt64
    public let nextOffset: UInt64?

    public var hasMore: Bool { nextOffset != nil }

    private enum CodingKeys: String, CodingKey {
        case contractAddress = "contract_address"
        case contractAlias = "contract_alias"
        case path
        case paths
        case prefix
        case entries
        case offset
        case limit
        case nextOffset = "next_offset"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "contract_address", "contract_alias", "path", "paths", "prefix",
                "entries", "offset", "limit", "next_offset",
            ],
            context: "contract state response"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        contractAddress = try container.decodeIfPresent(String.self, forKey: .contractAddress).map {
            try normalizeToriiContractAddressLiteral($0, field: "contract_address")
        }
        contractAlias = try container.decodeIfPresent(String.self, forKey: .contractAlias).map {
            try normalizeToriiContractAliasLiteral($0, field: "contract_alias")
        }
        path = try container.decodeIfPresent(String.self, forKey: .path).map {
            try ToriiContractStateQuery.normalizedPath($0, field: "path")
        }
        paths = try container.decodeIfPresent([String].self, forKey: .paths).map { values in
            try values.enumerated().map {
                try ToriiContractStateQuery.normalizedPath($0.element, field: "paths[\($0.offset)]")
            }
        }
        prefix = try container.decodeIfPresent(String.self, forKey: .prefix).map {
            try ToriiContractStateQuery.normalizedPath($0, field: "prefix")
        }
        let selectorCount = [path != nil, paths != nil, prefix != nil].filter { $0 }.count
        guard selectorCount == 1 else {
            throw DecodingError.dataCorruptedError(
                forKey: .path,
                in: container,
                debugDescription: "contract state response must echo exactly one selector"
            )
        }
        if let paths {
            guard !paths.isEmpty, Set(paths).count == paths.count else {
                throw DecodingError.dataCorruptedError(
                    forKey: .paths,
                    in: container,
                    debugDescription: "paths must be non-empty and unique"
                )
            }
        }
        entries = try container.decode([ToriiContractStateEntry].self, forKey: .entries)
        offset = try container.decode(UInt64.self, forKey: .offset)
        limit = try container.decode(UInt64.self, forKey: .limit)
        nextOffset = try container.decodeIfPresent(UInt64.self, forKey: .nextOffset)
        guard (1...10_000).contains(limit), entries.count <= Int(limit) else {
            throw DecodingError.dataCorruptedError(
                forKey: .limit,
                in: container,
                debugDescription: "limit exceeds Torii's maximum of 10,000"
            )
        }
        if let nextOffset {
            let (expectedNextOffset, overflow) = offset.addingReportingOverflow(
                UInt64(entries.count)
            )
            guard prefix != nil,
                  !entries.isEmpty,
                  !overflow,
                  nextOffset == expectedNextOffset else {
                throw DecodingError.dataCorruptedError(
                    forKey: .nextOffset,
                    in: container,
                    debugDescription: "next_offset must advance a non-empty prefix page exactly"
                )
            }
        }
    }

    fileprivate func validateBinding(to query: ToriiContractStateQuery) throws {
        switch query.target {
        case let .address(expected):
            guard contractAddress == expected, contractAlias == nil else {
                throw ToriiClientError.invalidPayload(
                    "contract state response target does not match the requested address."
                )
            }
        case let .alias(expected):
            guard contractAlias == expected, contractAddress != nil else {
                throw ToriiClientError.invalidPayload(
                    "contract state response target does not match the requested alias."
                )
            }
        }

        switch (query.selector, path, paths, prefix) {
        case let (.path(expected), actual?, nil, nil):
            guard expected == actual,
                  offset == 0,
                  limit == 1,
                  entries.count == 1,
                  entries[0].path == expected,
                  entries[0].found,
                  nextOffset == nil else {
                throw ToriiClientError.invalidPayload("contract state path response is not bound to the query.")
            }
        case let (.paths(expected), nil, actual?, nil):
            guard expected == actual,
                  offset == 0,
                  limit == UInt64(expected.count),
                  entries.map(\.path) == expected,
                  nextOffset == nil else {
                throw ToriiClientError.invalidPayload("contract state paths response is not bound to the query.")
            }
        case let (.prefix(expected), nil, nil, actual?):
            guard expected == actual,
                  offset == query.offset,
                  limit == query.limit,
                  entries.count <= Int(query.limit),
                  entries.allSatisfy({ $0.path.hasPrefix(expected) }),
                  zip(entries, entries.dropFirst()).allSatisfy({ pair in
                      pair.0.path < pair.1.path
                  }) else {
                throw ToriiClientError.invalidPayload("contract state prefix response is not bound to the query.")
            }
        default:
            throw ToriiClientError.invalidPayload("contract state response selector does not match the query.")
        }

        if !query.includeValue,
           entries.contains(where: { $0.valueB64 != nil || $0.valueLength != nil }) {
            throw ToriiClientError.invalidPayload(
                "contract state response included raw values when include_value was false."
            )
        }
        if !query.decodeJSON, entries.contains(where: { $0.valueJSON != nil }) {
            throw ToriiClientError.invalidPayload(
                "contract state response included decoded JSON when decode was not requested."
            )
        }
    }
}

/// Caller-trusted exact contract-call intent used to validate an unsigned Torii draft.
///
/// Construct the invocation from a trusted contract artifact and argument schema.
/// `metadata` is the exact final transaction metadata, including caller-owned
/// entries and every deterministic system/event entry Torii is expected to add.
/// The intent is local-only and is never serialized in the request.
public struct ToriiContractCallDraftIntent: Sendable, Equatable {
    public let invocation: TransactionContractInvocation
    public let metadata: [String: ToriiJSONValue]

    public init(invocation: TransactionContractInvocation,
                metadata: [String: ToriiJSONValue]) throws {
        _ = try ToriiCanonicalTransactionDraft.compactMetadata(metadata)
        self.invocation = invocation
        self.metadata = metadata
    }
}

public struct ToriiContractCallRequest: Encodable, Sendable, Equatable {
    /// Detached drafts are intentionally short-lived so an authorization
    /// cannot be stockpiled and replayed later.
    public static let maximumDetachedTransactionTtlMs: UInt64 = 10 * 60 * 1_000
    public static let maximumDetachedCreationAgeMs: UInt64 = 5 * 60 * 1_000
    public static let maximumDetachedFutureSkewMs: UInt64 = 30 * 1_000
    public var authority: String
    public var publicKeyHex: String?
    public var signatureB64: String?
    /// Exact prepared transaction bytes authorized by the detached signature.
    public var transactionPayloadB64: String?
    public var contractAddress: String?
    public var contractAlias: String?
    public var entrypoint: String
    public var payload: ToriiJSONValue?
    public var metadata: [String: ToriiJSONValue]
    /// Exact local-only invocation and merged-metadata commitment required for
    /// every unsigned response.
    public var draftIntent: ToriiContractCallDraftIntent?
    public var creationTimeMs: UInt64?
    public var transactionTtlMs: UInt64?
    public var feePayment: FeePaymentIntent

    public init(authority: String,
                publicKeyHex: String? = nil,
                signatureB64: String? = nil,
                transactionPayloadB64: String? = nil,
                contractAddress: String? = nil,
                contractAlias: String? = nil,
                entrypoint: String,
                payload: ToriiJSONValue? = nil,
                metadata: [String: ToriiJSONValue] = [:],
                draftIntent: ToriiContractCallDraftIntent? = nil,
                creationTimeMs: UInt64? = nil,
                transactionTtlMs: UInt64? = nil,
                feePayment: FeePaymentIntent) {
        self.authority = authority
        self.publicKeyHex = publicKeyHex
        self.signatureB64 = signatureB64
        self.transactionPayloadB64 = transactionPayloadB64
        self.contractAddress = contractAddress
        self.contractAlias = contractAlias
        self.entrypoint = entrypoint
        self.payload = payload
        self.metadata = metadata
        self.draftIntent = draftIntent
        self.creationTimeMs = creationTimeMs
        self.transactionTtlMs = transactionTtlMs
        self.feePayment = feePayment
    }

    private enum CodingKeys: String, CodingKey {
        case authority
        case publicKeyHex = "public_key_hex"
        case signatureB64 = "signature_b64"
        case transactionPayloadB64 = "transaction_payload_b64"
        case contractAddress = "contract_address"
        case contractAlias = "contract_alias"
        case entrypoint
        case payload
        case metadata
        case creationTimeMs = "creation_time_ms"
        case transactionTtlMs = "transaction_ttl_ms"
        case feePayment = "fee_payment"
    }

    public func encode(to encoder: Encoder) throws {
        let normalizedAuthority = try normalizeToriiAccountIdQueryValue(authority, field: "authority")
        let normalizedPublicKeyHex = try ToriiRequestValidation.normalizedOptional32ByteHex(
            publicKeyHex,
            field: "public_key_hex"
        )
        let normalizedSignatureB64 = try signatureB64.map {
            try ToriiRequestValidation.normalizedExactBase64($0, field: "signature_b64")
        }
        let normalizedTransactionPayloadB64 = try transactionPayloadB64.map {
            try ToriiRequestValidation.normalizedExactBase64($0, field: "transaction_payload_b64")
        }
        let detachedFields = [normalizedPublicKeyHex, normalizedSignatureB64, normalizedTransactionPayloadB64]
            .compactMap { $0 }.count
        guard detachedFields == 0 || detachedFields == 3 else {
            throw ToriiClientError.invalidPayload(
                "detached contract calls require transaction_payload_b64, public_key_hex, and signature_b64 together."
            )
        }
        if detachedFields == 3, creationTimeMs == nil {
            throw ToriiClientError.invalidPayload(
                "detached contract calls require the prepared creation_time_ms."
            )
        }
        let normalizedTarget = try normalizeToriiContractTargetSelector(
            contractAddress: contractAddress,
            contractAlias: contractAlias,
            field: "contract call"
        )
        let normalizedEntrypoint = try ToriiRequestValidation.normalizedNonEmpty(
            entrypoint,
            field: "entrypoint"
        )
        if feePayment.gasLimit == nil || feePayment.gasLimit == 0 {
            throw ToriiClientError.invalidPayload(
                "fee_payment.gas_limit is required and must be greater than zero for a contract call."
            )
        }
        _ = try feePayment.canonicalJSONData()
        if creationTimeMs == 0 {
            throw ToriiClientError.invalidPayload("creation_time_ms must be greater than zero.")
        }
        if transactionTtlMs == 0 {
            throw ToriiClientError.invalidPayload("transaction_ttl_ms must be greater than zero.")
        }
        _ = try ToriiCanonicalTransactionDraft.compactMetadata(metadata)

        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(normalizedAuthority, forKey: .authority)
        try container.encodeIfPresent(normalizedPublicKeyHex, forKey: .publicKeyHex)
        try container.encodeIfPresent(normalizedSignatureB64, forKey: .signatureB64)
        try container.encodeIfPresent(normalizedTransactionPayloadB64, forKey: .transactionPayloadB64)
        try container.encodeIfPresent(normalizedTarget.contractAddress, forKey: .contractAddress)
        try container.encodeIfPresent(normalizedTarget.contractAlias, forKey: .contractAlias)
        try container.encode(normalizedEntrypoint, forKey: .entrypoint)
        try container.encodeIfPresent(payload, forKey: .payload)
        if !metadata.isEmpty {
            try container.encode(metadata, forKey: .metadata)
        }
        try container.encodeIfPresent(creationTimeMs, forKey: .creationTimeMs)
        try container.encodeIfPresent(transactionTtlMs, forKey: .transactionTtlMs)
        try container.encode(feePayment, forKey: .feePayment)
    }

    fileprivate func normalizedForDetachedPreparation(
        nowMilliseconds: UInt64
    ) throws -> Self {
        guard publicKeyHex == nil, signatureB64 == nil, transactionPayloadB64 == nil else {
            throw ToriiClientError.invalidPayload(
                "detached contract-call preparation must not include transaction bytes, a public key, or a signature."
            )
        }
        let normalizedAuthority = try normalizeToriiAccountIdQueryValue(
            authority,
            field: "authority"
        )
        guard !authority.contains("@"), normalizedAuthority == authority else {
            throw ToriiClientError.invalidPayload(
                "authority must be an exact canonical I105 account id for detached signing."
            )
        }
        let normalizedTarget = try normalizeToriiContractTargetSelector(
            contractAddress: contractAddress,
            contractAlias: contractAlias,
            field: "contract call"
        )
        let normalizedEntrypoint = try ToriiRequestValidation.normalizedNonEmpty(
            entrypoint,
            field: "entrypoint"
        )
        guard normalizedEntrypoint == entrypoint else {
            throw ToriiClientError.invalidPayload(
                "entrypoint must not contain surrounding whitespace."
            )
        }
        guard feePayment.gasLimit != nil, feePayment.gasLimit != 0 else {
            throw ToriiClientError.invalidPayload(
                "detached contract-call preparation requires a positive fee_payment.gas_limit."
            )
        }
        _ = try feePayment.canonicalJSONData()
        guard let creationTimeMs else {
            throw ToriiClientError.invalidPayload(
                "detached contract-call preparation requires an explicit creation_time_ms."
            )
        }
        let oldestAccepted = nowMilliseconds > Self.maximumDetachedCreationAgeMs
            ? nowMilliseconds - Self.maximumDetachedCreationAgeMs
            : 0
        let (newestAccepted, futureOverflow) = nowMilliseconds.addingReportingOverflow(
            Self.maximumDetachedFutureSkewMs
        )
        guard !futureOverflow,
              creationTimeMs >= oldestAccepted,
              creationTimeMs <= newestAccepted else {
            throw ToriiClientError.invalidPayload(
                "detached contract-call creation_time_ms is outside the permitted local-clock window."
            )
        }
        guard let transactionTtlMs,
              transactionTtlMs > 0,
              transactionTtlMs <= Self.maximumDetachedTransactionTtlMs else {
            throw ToriiClientError.invalidPayload(
                "detached contract-call preparation requires transaction_ttl_ms between 1 and \(Self.maximumDetachedTransactionTtlMs)."
            )
        }
        guard let draftIntent else {
            throw ToriiClientError.invalidPayload(
                "detached contract-call preparation requires an exact caller-trusted draftIntent."
            )
        }
        let invocation = draftIntent.invocation
        guard invocation.entrypoint == normalizedEntrypoint,
              (payload != nil) == (invocation.arguments != nil),
              normalizedTarget.contractAddress.map({ $0 == invocation.contractAddress }) != false,
              draftIntent.metadata["contract_address"] == .string(invocation.contractAddress),
              draftIntent.metadata["contract_code_hash"] == .string(invocation.expectedCodeHash.hexLowercased()),
              draftIntent.metadata["contract_entrypoint"] == .string(normalizedEntrypoint),
              draftIntent.metadata["contract_alias"] == normalizedTarget.contractAlias.map(ToriiJSONValue.string),
              (draftIntent.metadata["contract_payload"] != nil) == (payload != nil) else {
            throw ToriiClientError.invalidPayload(
                "draftIntent invocation or system metadata does not match the contract-call request."
            )
        }
        let reservedMetadataKeys = Set([
            "fee_sponsor", "fee_sponsor_account", "gas_asset_id", "gas_limit",
        ])
        for (key, value) in metadata {
            guard !key.hasPrefix("contract_"),
                  !key.hasPrefix("validation_fee_"),
                  !reservedMetadataKeys.contains(key),
                  draftIntent.metadata[key] == value else {
                throw ToriiClientError.invalidPayload(
                    "caller metadata contains a reserved key or differs from draftIntent."
                )
            }
        }
        let normalized = Self(
            authority: normalizedAuthority,
            contractAddress: normalizedTarget.contractAddress,
            contractAlias: normalizedTarget.contractAlias,
            entrypoint: normalizedEntrypoint,
            payload: payload,
            metadata: metadata,
            draftIntent: draftIntent,
            creationTimeMs: creationTimeMs,
            transactionTtlMs: transactionTtlMs,
            feePayment: feePayment
        )
        _ = try JSONEncoder().encode(normalized)
        return normalized
    }

    /// Mirrors Torii's `contract_payload_digest_hex`: compact, key-sorted JSON
    /// followed by BLAKE3. Detached signing must bind this digest before the
    /// caller authorizes server-prepared transaction bytes.
    public func canonicalContractPayloadDigestHex() throws -> String {
        let encodedPayload = try payload.map { try JSONEncoder().encode($0) } ?? Data()
        let canonical = try NoritoNativeBridge.shared.canonicalizeJSONBlake3(encodedPayload)
        guard canonical.hash.count == 32 else {
            throw ToriiClientError.invalidPayload(
                "native canonical JSON/BLAKE3 is unavailable for detached contract-call payload binding."
            )
        }
        return canonical.hash.map { String(format: "%02x", $0) }.joined()
    }
}

public struct ToriiContractOperationReceipt: Decodable, Sendable {
    public let operationKind: String
    public let status: String
    public let transport: String
    public let dataspace: String
    public let contractAlias: String?
    public let contractAddress: String?
    public let codeHashHex: String?
    public let abiHashHex: String?
    public let txHashHex: String?
    public let entrypoint: String?
    public let entrypointHashHex: String?
    public let gasLimit: UInt64?
    public let gasUsed: UInt64?
    public let feePayment: FeePaymentIntent?
    public let payloadDigestHex: String

    private enum CodingKeys: String, CodingKey {
        case operationKind = "operation_kind"
        case status
        case transport
        case dataspace
        case contractAlias = "contract_alias"
        case contractAddress = "contract_address"
        case codeHashHex = "code_hash_hex"
        case abiHashHex = "abi_hash_hex"
        case txHashHex = "tx_hash_hex"
        case entrypoint
        case entrypointHashHex = "entrypoint_hash_hex"
        case gasLimit = "gas_limit"
        case gasUsed = "gas_used"
        case feePayment = "fee_payment"
        case payloadDigestHex = "payload_digest_hex"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "operation_kind", "status", "transport", "dataspace",
                "contract_alias", "contract_address", "code_hash_hex", "abi_hash_hex",
                "tx_hash_hex", "entrypoint", "entrypoint_hash_hex", "gas_limit",
                "gas_used", "fee_payment", "payload_digest_hex",
            ],
            context: "contract call operation receipt"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)

        func requiredString(_ key: CodingKeys, field: String) throws -> String {
            try ToriiValidation.normalizedExactNonEmpty(
                container.decode(String.self, forKey: key),
                field: field,
                codingPath: container.codingPath + [key]
            )
        }

        func optionalString(_ key: CodingKeys, field: String) throws -> String? {
            guard let value = try container.decodeIfPresent(String.self, forKey: key) else {
                return nil
            }
            return try ToriiValidation.normalizedExactNonEmpty(
                value,
                field: field,
                codingPath: container.codingPath + [key]
            )
        }

        func optionalHash(_ key: CodingKeys, field: String) throws -> String? {
            guard let value = try container.decodeIfPresent(String.self, forKey: key) else {
                return nil
            }
            return try exactDetachedAssetTransferHash(
                value,
                field: field,
                codingPath: container.codingPath + [key]
            )
        }

        operationKind = try requiredString(.operationKind, field: "operation_kind")
        status = try requiredString(.status, field: "status")
        transport = try requiredString(.transport, field: "transport")
        dataspace = try requiredString(.dataspace, field: "dataspace")
        contractAlias = try optionalString(.contractAlias, field: "contract_alias").map {
            try normalizeToriiContractAliasLiteral($0, field: "contract_alias")
        }
        contractAddress = try optionalString(.contractAddress, field: "contract_address").map {
            try normalizeToriiContractAddressLiteral($0, field: "contract_address")
        }
        codeHashHex = try optionalHash(.codeHashHex, field: "code_hash_hex")
        abiHashHex = try optionalHash(.abiHashHex, field: "abi_hash_hex")
        txHashHex = try optionalHash(.txHashHex, field: "tx_hash_hex")
        entrypoint = try optionalString(.entrypoint, field: "entrypoint")
        entrypointHashHex = try optionalHash(.entrypointHashHex, field: "entrypoint_hash_hex")
        gasLimit = try container.decodeIfPresent(UInt64.self, forKey: .gasLimit)
        if gasLimit == 0 {
            throw DecodingError.dataCorruptedError(
                forKey: .gasLimit,
                in: container,
                debugDescription: "gas_limit must be greater than zero"
            )
        }
        gasUsed = try container.decodeIfPresent(UInt64.self, forKey: .gasUsed)
        feePayment = try container.decodeIfPresent(FeePaymentIntent.self, forKey: .feePayment)
        payloadDigestHex = try exactDetachedAssetTransferHash(
            container.decode(String.self, forKey: .payloadDigestHex),
            field: "payload_digest_hex",
            codingPath: container.codingPath + [CodingKeys.payloadDigestHex]
        )
    }
}

public struct ToriiContractCallResponse: Decodable, Sendable {
    public let ok: Bool
    public let submitted: Bool
    public let dataspace: String
    public let contractAddress: String?
    public let codeHashHex: String
    public let abiHashHex: String
    public let creationTimeMs: UInt64
    public let txHashHex: String?
    public let pipelineStatus: ToriiPipelineTransactionStatus?
    public let transactionTtlMs: UInt64?
    public let entrypointHashHex: String?
    public let transactionPayloadB64: String?
    public let signingMessageB64: String?
    public let entrypoint: String?
    public let operationReceipt: ToriiContractOperationReceipt

    private enum CodingKeys: String, CodingKey {
        case ok
        case submitted
        case dataspace
        case contractAddress = "contract_address"
        case codeHashHex = "code_hash_hex"
        case abiHashHex = "abi_hash_hex"
        case creationTimeMs = "creation_time_ms"
        case txHashHex = "tx_hash_hex"
        case pipelineStatus = "pipeline_status"
        case transactionTtlMs = "transaction_ttl_ms"
        case entrypointHashHex = "entrypoint_hash_hex"
        case transactionPayloadB64 = "transaction_payload_b64"
        case signingMessageB64 = "signing_message_b64"
        case entrypoint
        case operationReceipt = "operation_receipt"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "ok", "submitted", "dataspace", "contract_address", "code_hash_hex",
                "abi_hash_hex", "creation_time_ms", "transaction_ttl_ms", "tx_hash_hex",
                "pipeline_status", "entrypoint_hash_hex", "transaction_payload_b64",
                "signing_message_b64", "entrypoint",
                "operation_receipt",
            ],
            context: "contract call response"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        ok = try container.decode(Bool.self, forKey: .ok)
        submitted = try container.decode(Bool.self, forKey: .submitted)
        dataspace = try ToriiValidation.normalizedExactNonEmpty(
            try container.decode(String.self, forKey: .dataspace),
            field: "dataspace",
            codingPath: container.codingPath + [CodingKeys.dataspace]
        )
        if let contractAddress = try container.decodeIfPresent(String.self, forKey: .contractAddress) {
            self.contractAddress = try normalizeToriiContractAddressLiteral(
                contractAddress,
                field: "contract_address"
            )
        } else {
            self.contractAddress = nil
        }
        self.codeHashHex = try exactDetachedAssetTransferHash(
            container.decode(String.self, forKey: .codeHashHex),
            field: "code_hash_hex",
            codingPath: container.codingPath + [CodingKeys.codeHashHex]
        )
        self.abiHashHex = try exactDetachedAssetTransferHash(
            container.decode(String.self, forKey: .abiHashHex),
            field: "abi_hash_hex",
            codingPath: container.codingPath + [CodingKeys.abiHashHex]
        )
        creationTimeMs = try container.decode(UInt64.self, forKey: .creationTimeMs)
        if let txHashHex = try container.decodeIfPresent(String.self, forKey: .txHashHex) {
            self.txHashHex = try exactDetachedAssetTransferHash(
                txHashHex,
                field: "tx_hash_hex",
                codingPath: container.codingPath + [CodingKeys.txHashHex]
            )
        } else {
            self.txHashHex = nil
        }
        self.pipelineStatus = try container.decodeIfPresent(ToriiPipelineTransactionStatus.self, forKey: .pipelineStatus)
        transactionTtlMs = try container.decodeIfPresent(UInt64.self, forKey: .transactionTtlMs)
        if transactionTtlMs == 0 { throw ToriiClientError.invalidPayload("transaction_ttl_ms must be nonzero.") }
        if let entrypointHashHex = try container.decodeIfPresent(String.self, forKey: .entrypointHashHex) {
            self.entrypointHashHex = try exactDetachedAssetTransferHash(
                entrypointHashHex,
                field: "entrypoint_hash_hex",
                codingPath: container.codingPath + [CodingKeys.entrypointHashHex]
            )
        } else {
            self.entrypointHashHex = nil
        }
        transactionPayloadB64 = try container.decodeIfPresent(
            String.self,
            forKey: .transactionPayloadB64
        )
        signingMessageB64 = try container.decodeIfPresent(
            String.self,
            forKey: .signingMessageB64
        )
        if let entrypoint = try container.decodeIfPresent(String.self, forKey: .entrypoint) {
            self.entrypoint = try ToriiValidation.normalizedExactNonEmpty(
                entrypoint,
                field: "entrypoint",
                codingPath: container.codingPath + [CodingKeys.entrypoint]
            )
        } else {
            self.entrypoint = nil
        }
        operationReceipt = try container.decode(ToriiContractOperationReceipt.self, forKey: .operationReceipt)

        if submitted {
            guard txHashHex != nil,
                  pipelineStatus == nil,
                  transactionPayloadB64 == nil,
                  signingMessageB64 == nil else {
                throw DecodingError.dataCorruptedError(
                    forKey: .submitted,
                    in: container,
                    debugDescription: "submitted contract call must contain the final transaction hash without synthetic pipeline status"
                )
            }
        } else {
            guard txHashHex == nil,
                  entrypointHashHex == nil,
                  pipelineStatus == nil,
                  operationReceipt.txHashHex == nil,
                  operationReceipt.entrypointHashHex == nil,
                  let transactionPayloadB64,
                  let signingMessageB64 else {
                throw DecodingError.dataCorruptedError(
                    forKey: .submitted,
                    in: container,
                    debugDescription: "unsigned contract call must contain exactly one payload and signing-message pair and no transaction hashes"
                )
            }
            do {
                _ = try ToriiCanonicalTransactionDraft.decode(
                    transactionPayloadB64: transactionPayloadB64,
                    signingMessageB64: signingMessageB64,

                    context: "contract call response"
                )
            } catch {
                throw DecodingError.dataCorruptedError(
                    forKey: .transactionPayloadB64,
                    in: container,
                    debugDescription: "contract call draft transaction material is invalid: \(error)"
                )
            }
        }
    }
}

/// A server-prepared contract call whose exact signing bytes and all public
/// operation bindings are retained for a detached Ed25519 signature.
/// Preparation requires Ordinary single-route admission before exposing signing bytes.
public struct ToriiContractCallDraft: Sendable, Equatable {
    public let request: ToriiContractCallRequest
    public let transactionPayload: Data
    public let signingMessage: Data
    public let networkId: NetworkId
    public let resolvedContractAddress: String
    public let dataspace: String
    public let codeHashHex: String
    public let abiHashHex: String
    public let payloadDigestHex: String

    fileprivate let receiptContractAlias: String?
    fileprivate let receiptFeePayment: FeePaymentIntent

    fileprivate init(
        preparedRequest: ToriiContractCallRequest,
        response: ToriiContractCallResponse,
        expectedNetworkId: NetworkId
    ) throws {
        guard let trustedIntent = preparedRequest.draftIntent else {
            throw ToriiClientError.invalidPayload(
                "contract call preparation is missing its caller-trusted draft intent."
            )
        }
        let trustedInvocation = trustedIntent.invocation
        let expectedPayloadDigestHex = try preparedRequest.canonicalContractPayloadDigestHex()
        guard response.ok,
              !response.submitted,
              response.txHashHex == nil,
              response.pipelineStatus == nil,
              response.operationReceipt.operationKind == "contract_call",
              response.operationReceipt.status == "pending_signature",
              response.operationReceipt.transport == "torii",
              response.operationReceipt.txHashHex == nil,
              response.operationReceipt.gasUsed == nil,
              let contractAddress = response.contractAddress,
              contractAddress == trustedInvocation.contractAddress,
              response.codeHashHex == trustedInvocation.expectedCodeHash.hexLowercased(),
              response.operationReceipt.contractAddress == contractAddress,
              response.operationReceipt.dataspace == response.dataspace,
              response.operationReceipt.codeHashHex == response.codeHashHex,
              response.operationReceipt.abiHashHex == response.abiHashHex,
              response.operationReceipt.entrypoint == response.entrypoint,
              response.operationReceipt.entrypointHashHex == nil,
              let receiptFeePayment = response.operationReceipt.feePayment,
              preparedRequest.feePayment.hasSamePayerAndGasBound(as: receiptFeePayment),
              response.operationReceipt.gasLimit == receiptFeePayment.gasLimit,
              response.operationReceipt.payloadDigestHex == expectedPayloadDigestHex,
              let entrypoint = response.entrypoint,
              entrypoint == trustedInvocation.entrypoint,
              entrypoint == preparedRequest.entrypoint,
              response.codeHashHex.contains(where: { $0 != "0" }),
              response.abiHashHex.contains(where: { $0 != "0" }),
              response.operationReceipt.payloadDigestHex.contains(where: { $0 != "0" }),
              let transactionPayloadB64 = response.transactionPayloadB64,
              let signingMessageB64 = response.signingMessageB64,
              response.creationTimeMs > 0,
              response.transactionTtlMs == preparedRequest.transactionTtlMs,
              preparedRequest.creationTimeMs.map({ $0 == response.creationTimeMs }) != false
        else {
            throw ToriiClientError.invalidPayload(
                "contract call preparation response is not a canonical pending-signature draft."
            )
        }
        switch (preparedRequest.contractAlias, preparedRequest.contractAddress) {
        case let (alias?, nil):
            guard response.operationReceipt.contractAlias == alias else {
                throw ToriiClientError.invalidPayload(
                    "contract call draft is not bound to the requested contract alias."
                )
            }
        case let (nil, address?):
            guard address == contractAddress,
                  response.operationReceipt.contractAlias == nil else {
                throw ToriiClientError.invalidPayload(
                    "contract call draft is not bound to the requested contract address."
                )
            }
        default:
            throw ToriiClientError.invalidPayload("contract call draft target is invalid.")
        }

        let draft: ToriiCanonicalTransactionDraft
        do {
            draft = try ToriiCanonicalTransactionDraft.decode(
                transactionPayloadB64: transactionPayloadB64,
                signingMessageB64: signingMessageB64,

                context: "contract call response"
            )
            try Self.validateTransactionPayloadBindings(
                draft.payload,
                request: preparedRequest,
                response: response,
                expectedNetworkId: expectedNetworkId
            )
        } catch {
            throw ToriiClientError.invalidPayload(
                "contract call preparation did not contain the exact requested canonical transaction payload: \(error)"
            )
        }

        var deterministicRequest = preparedRequest
        deterministicRequest.creationTimeMs = response.creationTimeMs
        deterministicRequest.transactionTtlMs = response.transactionTtlMs
        deterministicRequest.feePayment = receiptFeePayment
        self.request = deterministicRequest
        transactionPayload = draft.transactionPayload
        signingMessage = draft.signingMessage
        networkId = draft.payload.networkId
        self.resolvedContractAddress = contractAddress
        self.dataspace = response.dataspace
        self.codeHashHex = response.codeHashHex
        self.abiHashHex = response.abiHashHex
        self.payloadDigestHex = response.operationReceipt.payloadDigestHex
        self.receiptContractAlias = response.operationReceipt.contractAlias
        self.receiptFeePayment = receiptFeePayment
    }

    fileprivate func validateSubmittedResponse(
        _ response: ToriiContractCallResponse,
        finalization: DetachedTransactionFinalization
    ) throws {
        let finalizedTransactionHashHex = Self.lowercaseHex(finalization.transactionHash)
        let finalizedEntrypointHashHex = Self.lowercaseHex(finalization.entrypointHash)
        guard response.ok,
              response.submitted,
              response.contractAddress == resolvedContractAddress,
              response.dataspace == dataspace,
              response.codeHashHex == codeHashHex,
              response.abiHashHex == abiHashHex,
              response.creationTimeMs == request.creationTimeMs,
              response.transactionTtlMs == request.transactionTtlMs,
              response.entrypoint == request.entrypoint,
              response.entrypointHashHex == finalizedEntrypointHashHex,
              response.transactionPayloadB64 == nil,
              response.signingMessageB64 == nil,
              let txHash = response.txHashHex,
              txHash == finalizedTransactionHashHex,
              response.pipelineStatus == nil,
              response.operationReceipt.operationKind == "contract_call",
              response.operationReceipt.status == "submitted",
              response.operationReceipt.transport == "torii",
              response.operationReceipt.dataspace == dataspace,
              response.operationReceipt.contractAlias == receiptContractAlias,
              response.operationReceipt.contractAddress == resolvedContractAddress,
              response.operationReceipt.codeHashHex == codeHashHex,
              response.operationReceipt.abiHashHex == abiHashHex,
              response.operationReceipt.txHashHex == txHash,
              response.operationReceipt.entrypoint == request.entrypoint,
              response.operationReceipt.entrypointHashHex == finalizedEntrypointHashHex,
              response.operationReceipt.gasLimit == request.feePayment.gasLimit,
              response.operationReceipt.gasUsed == nil,
              response.operationReceipt.feePayment == receiptFeePayment,
              response.operationReceipt.payloadDigestHex == payloadDigestHex,
              finalization.payloadSigningHash == signingMessage,
              txHash.contains(where: { $0 != "0" })
        else {
            throw ToriiClientError.invalidPayload(
                "submitted contract call is not exactly bound to its detached-signature draft."
            )
        }
    }

    private static func validateTransactionPayloadBindings(
        _ payload: ToriiCanonicalTransactionDraft.Payload,
        request: ToriiContractCallRequest,
        response: ToriiContractCallResponse,
        expectedNetworkId: NetworkId
    ) throws {
        try ToriiCanonicalTransactionDraft.requireAuthority(
            payload,
            equals: request.authority,
            context: "contract call draft"
        )
        guard let receiptFeePayment = response.operationReceipt.feePayment,
              expectedNetworkId == payload.networkId,
              payload.creationTimeMs == response.creationTimeMs,
              payload.timeToLiveMs == response.transactionTtlMs,
              payload.nonce == nil,
              payload.feePayment == (try receiptFeePayment.compactNorito()),
              let resolvedContractAddress = response.contractAddress else {
            throw ToriiClientError.invalidPayload(
                "contract-call transaction header differs from the exact request or response."
            )
        }
        try validateContractExecutable(
            payload.executable,
            contractAddress: resolvedContractAddress,
            codeHashHex: response.codeHashHex,
            entrypoint: request.entrypoint,
            expectedArgumentRecord: request.draftIntent?.invocation.arguments
        )
        guard let trustedIntent = request.draftIntent,
              payload.metadata == trustedIntent.metadata else {
            throw ToriiClientError.invalidPayload(
                "contract-call transaction metadata differs from the exact request."
            )
        }
    }

    private static func validateContractExecutable(
        _ bytes: Data,
        contractAddress: String,
        codeHashHex: String,
        entrypoint: String,
        expectedArgumentRecord: Data?
    ) throws {
        var executable = ToriiVerifyingKeyCompactReader(bytes)
        guard try executable.takeUInt32("contract executable variant") == 1 else {
            throw ToriiClientError.invalidPayload("contract-call draft changed executable kind.")
        }
        var invocation = ToriiVerifyingKeyCompactReader(
            try executable.takeField("contract invocation")
        )
        let decodedAddress = try ToriiCanonicalTransactionDraft.decodeString(
            try invocation.takeField("contract invocation address"),
            field: "contract invocation address"
        )
        let expectedCodeHash = try invocation.takeField("contract invocation code hash")
        let decodedEntrypoint = try ToriiCanonicalTransactionDraft.decodeString(
            try invocation.takeField("contract invocation entrypoint"),
            field: "contract invocation entrypoint"
        )
        let arguments = try invocation.takeField("contract invocation arguments")
        guard executable.isFinished,
              invocation.isFinished,
              decodedAddress == contractAddress,
              expectedCodeHash.hexLowercased() == codeHashHex,
              expectedCodeHash.count == 32, expectedCodeHash.last.map({ $0 & 1 == 1 }) == true,
              decodedEntrypoint == entrypoint else {
            throw ToriiClientError.invalidPayload(
                "contract-call executable differs from the resolved contract binding."
            )
        }
        var option = ToriiVerifyingKeyCompactReader(arguments)
        let tag = try option.takeUInt8("contract invocation arguments tag")
        switch (tag, expectedArgumentRecord) {
        case (0, nil):
            guard option.isFinished else {
                throw ToriiClientError.invalidPayload("contract arguments None contains trailing bytes.")
            }
        case (1, let expectedArgumentRecord?):
            var record = ToriiVerifyingKeyCompactReader(
                try option.takeField("contract invocation arguments record")
            )
            let byteCount = try record.takeUInt64("contract invocation arguments length")
            guard byteCount <= UInt64(TransactionContractInvocation.maximumArgumentsBytes),
                  let argumentCount = Int(exactly: byteCount) else {
                throw ToriiClientError.invalidPayload("contract arguments record exceeds the byte limit.")
            }
            let actualArgumentRecord = try record.takeBytes(
                argumentCount,
                field: "contract invocation arguments"
            )
            guard actualArgumentRecord == expectedArgumentRecord,
                  record.isFinished,
                  option.isFinished else {
                throw ToriiClientError.invalidPayload(
                    "contract arguments record differs from the exact trusted request commitment."
                )
            }
        default:
            throw ToriiClientError.invalidPayload(
                "contract-call argument presence differs from the exact request."
            )
        }
    }

    fileprivate static func lowercaseHex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }
}

public struct ToriiDetachedContractCallSubmission: Sendable {
    public let response: ToriiContractCallResponse
    public let signedTransaction: Data
    public let finalization: DetachedTransactionFinalization

    public var transactionHashHex: String {
        ToriiContractCallDraft.lowercaseHex(finalization.transactionHash)
    }

    public var entrypointHashHex: String {
        ToriiContractCallDraft.lowercaseHex(finalization.entrypointHash)
    }
}

fileprivate enum ToriiAssetTransferSigningMode: Equatable {
    case unsignedPreparation
    case optionalExactPair
}

fileprivate func normalizeDetachedAssetTransferAccount(
    _ value: String,
    field: String
) throws -> String {
    guard !value.isEmpty, value.utf8.count <= 512 else {
        throw ToriiClientError.invalidPayload(
            "\(field) must be a non-empty canonical I105 account id no longer than 512 bytes."
        )
    }

    let normalized = try normalizeToriiAccountIdQueryValue(value, field: field)
    guard !value.contains("@"), normalized == value else {
        throw ToriiClientError.invalidPayload(
            "\(field) must be an exact canonical I105 account id."
        )
    }
    return normalized
}

fileprivate func normalizeDetachedAssetTransferDefinition(
    _ value: String
) throws -> String {
    guard !value.isEmpty, value.utf8.count <= 64 else {
        throw ToriiClientError.invalidPayload(
            "asset_definition_id must be non-empty and no longer than 64 bytes."
        )
    }
    let normalized = try normalizeToriiAssetDefinitionIdValue(
        value,
        field: "asset_definition_id"
    )
    guard normalized == value else {
        throw ToriiClientError.invalidPayload(
            "asset_definition_id must be exact canonical Base58 text."
        )
    }
    return normalized
}

fileprivate func normalizeDetachedAssetTransferScope(_ value: String) throws -> String {
    guard !value.isEmpty, value.utf8.count <= 30 else {
        throw ToriiClientError.invalidPayload(
            "asset_balance_scope must be exactly global or dataspace:<u64>."
        )
    }
    if value == "global" {
        return value
    }
    let prefix = "dataspace:"
    guard value.hasPrefix(prefix) else {
        throw ToriiClientError.invalidPayload(
            "asset_balance_scope must be exactly global or dataspace:<u64>."
        )
    }
    let digits = String(value.dropFirst(prefix.count))
    guard !digits.isEmpty,
          digits.unicodeScalars.allSatisfy({ (48...57).contains($0.value) }),
          digits == "0" || digits.first != "0",
          let parsed = UInt64(digits),
          String(parsed) == digits else {
        throw ToriiClientError.invalidPayload(
            "asset_balance_scope must contain a canonical decimal u64 dataspace id."
        )
    }
    return value
}

fileprivate func normalizeDetachedAssetTransferAmount(_ value: String) throws -> String {
    guard !value.isEmpty, value.utf8.count <= 155 else {
        throw ToriiClientError.invalidPayload(
            "amount must be non-empty canonical Kotodama V1 Quantity text no longer than 155 bytes."
        )
    }
    let quantity: KotodamaQuantity
    do {
        quantity = try KotodamaQuantity(value)
    } catch {
        throw ToriiClientError.invalidPayload(
            "amount must be an in-range canonical Kotodama V1 Quantity."
        )
    }
    guard quantity.canonicalString == value, value != "0" else {
        throw ToriiClientError.invalidPayload(
            "amount must use the exact canonical representation of a strictly positive Quantity."
        )
    }
    return value
}

fileprivate func normalizeDetachedAssetTransferMemo(_ value: String?) throws -> String? {
    guard let value else { return nil }
    guard !value.isEmpty, value.utf8.count <= 256 else {
        throw ToriiClientError.invalidPayload(
            "memo must contain between 1 and 256 UTF-8 bytes."
        )
    }
    guard !value.unicodeScalars.contains(where: CharacterSet.controlCharacters.contains) else {
        throw ToriiClientError.invalidPayload(
            "memo must not contain Unicode control characters."
        )
    }
    return value
}

fileprivate func exactDetachedAssetTransferHash(
    _ value: String,
    field: String,
    codingPath: [CodingKey]
) throws -> String {
    let normalized = try ToriiValidation.normalized32ByteHex(
        value,
        field: field,
        codingPath: codingPath
    )
    guard normalized == value, !value.hasPrefix("0x") else {
        throw DecodingError.dataCorrupted(
            DecodingError.Context(
                codingPath: codingPath,
                debugDescription: "\(field) must be exactly 64 lowercase hexadecimal characters"
            )
        )
    }
    return value
}

/// Exact wire request for the two-phase, single-instruction Torii asset-transfer API.
public struct ToriiAssetTransferRequest: Codable, Sendable, Equatable {
    public static let maximumTransactionTtlMs: UInt64 = 10 * 60 * 1_000
    public static let maximumCreationAgeMs: UInt64 = 5 * 60 * 1_000
    public static let maximumFutureSkewMs: UInt64 = 30 * 1_000

    public var authority: String
    public var assetDefinitionId: String
    public var assetBalanceScope: String
    public var amount: String
    public var destination: String
    public var memo: String?
    public var feePayment: FeePaymentIntent
    public var creationTimeMs: UInt64
    public var transactionTtlMs: UInt64
    public var publicKeyHex: String?
    public var signatureBase64: String?

    public init(
        authority: String,
        assetDefinitionId: String,
        assetBalanceScope: String,
        amount: String,
        destination: String,
        memo: String? = nil,
        feePayment: FeePaymentIntent,
        creationTimeMs: UInt64,
        transactionTtlMs: UInt64,
        publicKeyHex: String? = nil,
        signatureBase64: String? = nil
    ) {
        self.authority = authority
        self.assetDefinitionId = assetDefinitionId
        self.assetBalanceScope = assetBalanceScope
        self.amount = amount
        self.destination = destination
        self.memo = memo
        self.feePayment = feePayment
        self.creationTimeMs = creationTimeMs
        self.transactionTtlMs = transactionTtlMs
        self.publicKeyHex = publicKeyHex
        self.signatureBase64 = signatureBase64
    }

    private enum CodingKeys: String, CodingKey {
        case authority
        case assetDefinitionId = "asset_definition_id"
        case assetBalanceScope = "asset_balance_scope"
        case amount
        case destination
        case memo
        case feePayment = "fee_payment"
        case creationTimeMs = "creation_time_ms"
        case transactionTtlMs = "transaction_ttl_ms"
        case publicKeyHex = "public_key_hex"
        case signatureBase64 = "signature_base64"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "authority", "asset_definition_id", "asset_balance_scope", "amount",
                "destination", "memo", "fee_payment", "creation_time_ms",
                "transaction_ttl_ms", "public_key_hex", "signature_base64",
            ],
            context: "asset transfer request"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let decoded = Self(
            authority: try container.decode(String.self, forKey: .authority),
            assetDefinitionId: try container.decode(String.self, forKey: .assetDefinitionId),
            assetBalanceScope: try container.decode(String.self, forKey: .assetBalanceScope),
            amount: try container.decode(String.self, forKey: .amount),
            destination: try container.decode(String.self, forKey: .destination),
            memo: try container.decodeIfPresent(String.self, forKey: .memo),
            feePayment: try container.decode(FeePaymentIntent.self, forKey: .feePayment),
            creationTimeMs: try container.decode(UInt64.self, forKey: .creationTimeMs),
            transactionTtlMs: try container.decode(UInt64.self, forKey: .transactionTtlMs),
            publicKeyHex: try container.decodeIfPresent(String.self, forKey: .publicKeyHex),
            signatureBase64: try container.decodeIfPresent(String.self, forKey: .signatureBase64)
        )
        self = try decoded.validated(
            signingMode: .optionalExactPair,
            nowMilliseconds: nil
        )
    }

    public func encode(to encoder: Encoder) throws {
        let normalized = try validated(signingMode: .optionalExactPair, nowMilliseconds: nil)
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(normalized.authority, forKey: .authority)
        try container.encode(normalized.assetDefinitionId, forKey: .assetDefinitionId)
        try container.encode(normalized.assetBalanceScope, forKey: .assetBalanceScope)
        try container.encode(normalized.amount, forKey: .amount)
        try container.encode(normalized.destination, forKey: .destination)
        try container.encodeIfPresent(normalized.memo, forKey: .memo)
        try container.encode(normalized.feePayment, forKey: .feePayment)
        try container.encode(normalized.creationTimeMs, forKey: .creationTimeMs)
        try container.encode(normalized.transactionTtlMs, forKey: .transactionTtlMs)
        try container.encodeIfPresent(normalized.publicKeyHex, forKey: .publicKeyHex)
        try container.encodeIfPresent(normalized.signatureBase64, forKey: .signatureBase64)
    }

    fileprivate func normalizedForPreparation(nowMilliseconds: UInt64) throws -> Self {
        try validated(signingMode: .unsignedPreparation, nowMilliseconds: nowMilliseconds)
    }

    fileprivate func normalizedForSubmission(
        publicKeyHex: String,
        signatureBase64: String,
        nowMilliseconds: UInt64
    ) throws -> Self {
        var submitted = self
        submitted.publicKeyHex = publicKeyHex
        submitted.signatureBase64 = signatureBase64
        return try submitted.validated(
            signingMode: .optionalExactPair,
            nowMilliseconds: nowMilliseconds
        )
    }

    fileprivate func normalizedSignedEvidence() throws -> Self {
        try validated(signingMode: .optionalExactPair, nowMilliseconds: nil)
    }

    fileprivate func revalidatedSignedSubmission(nowMilliseconds: UInt64) throws -> Self {
        try validated(
            signingMode: .optionalExactPair,
            nowMilliseconds: nowMilliseconds
        )
    }

    fileprivate func matches(intent: ToriiAssetTransferIntent) -> Bool {
        intent.authority == authority
            && intent.assetDefinitionId == assetDefinitionId
            && intent.assetBalanceScope == assetBalanceScope
            && intent.amount == amount
            && intent.destination == destination
            && intent.memo == memo
            && intent.feePayment == feePayment
            && intent.creationTimeMs == creationTimeMs
            && intent.transactionTtlMs == transactionTtlMs
    }

    private func validated(
        signingMode: ToriiAssetTransferSigningMode,
        nowMilliseconds: UInt64?
    ) throws -> Self {
        let authority = try normalizeDetachedAssetTransferAccount(authority, field: "authority")
        let assetDefinitionId = try normalizeDetachedAssetTransferDefinition(assetDefinitionId)
        let assetBalanceScope = try normalizeDetachedAssetTransferScope(assetBalanceScope)
        let amount = try normalizeDetachedAssetTransferAmount(amount)
        let destination = try normalizeDetachedAssetTransferAccount(destination, field: "destination")
        let memo = try normalizeDetachedAssetTransferMemo(memo)
        _ = try feePayment.canonicalJSONData()
        guard creationTimeMs > 0 else {
            throw ToriiClientError.invalidPayload("creation_time_ms must be greater than zero.")
        }
        guard (1...Self.maximumTransactionTtlMs).contains(transactionTtlMs) else {
            throw ToriiClientError.invalidPayload(
                "transaction_ttl_ms must be between 1 and \(Self.maximumTransactionTtlMs)."
            )
        }
        let (expiresAtMs, expiryOverflow) = creationTimeMs.addingReportingOverflow(transactionTtlMs)
        guard !expiryOverflow else {
            throw ToriiClientError.invalidPayload(
                "creation_time_ms plus transaction_ttl_ms must not overflow UInt64."
            )
        }
        if let nowMilliseconds {
            let oldest = nowMilliseconds > Self.maximumCreationAgeMs
                ? nowMilliseconds - Self.maximumCreationAgeMs
                : 0
            let (newest, newestOverflow) = nowMilliseconds.addingReportingOverflow(
                Self.maximumFutureSkewMs
            )
            guard !newestOverflow,
                  creationTimeMs >= oldest,
                  creationTimeMs <= newest else {
                throw ToriiClientError.invalidPayload(
                    "creation_time_ms is outside the permitted five-minute age and thirty-second future-skew window."
                )
            }
            guard expiresAtMs > nowMilliseconds else {
                throw ToriiClientError.invalidPayload("asset transfer draft is already expired.")
            }
        }

        let normalizedPublicKey: String?
        let normalizedSignature: String?
        switch (publicKeyHex, signatureBase64) {
        case (nil, nil):
            normalizedPublicKey = nil
            normalizedSignature = nil
        case let (publicKeyHex?, signatureBase64?):
            let exactPublicKey = try ToriiRequestValidation.exactLowercase32ByteHex(
                publicKeyHex,
                field: "public_key_hex"
            )
            guard let publicKey = Data(hexString: exactPublicKey),
                  publicKey.count == 32,
                  publicKey.contains(where: { $0 != 0 }) else {
                throw ToriiClientError.invalidPayload(
                    "public_key_hex must encode a nonzero 32-byte Ed25519 public key."
                )
            }
            let exactSignature = try ToriiRequestValidation.normalizedExactBase64(
                signatureBase64,
                field: "signature_base64"
            )
            guard let signature = Data(base64Encoded: exactSignature),
                  signature.count == 64,
                  signature.contains(where: { $0 != 0 }) else {
                throw ToriiClientError.invalidPayload(
                    "signature_base64 must encode a nonzero 64-byte Ed25519 signature."
                )
            }
            normalizedPublicKey = exactPublicKey
            normalizedSignature = exactSignature
        default:
            throw ToriiClientError.invalidPayload(
                "public_key_hex and signature_base64 must either both be omitted or both be supplied."
            )
        }
        if signingMode == .unsignedPreparation,
           normalizedPublicKey != nil || normalizedSignature != nil {
            throw ToriiClientError.invalidPayload(
                "asset transfer preparation must not include a public key or signature."
            )
        }
        return Self(
            authority: authority,
            assetDefinitionId: assetDefinitionId,
            assetBalanceScope: assetBalanceScope,
            amount: amount,
            destination: destination,
            memo: memo,
            feePayment: feePayment,
            creationTimeMs: creationTimeMs,
            transactionTtlMs: transactionTtlMs,
            publicKeyHex: normalizedPublicKey,
            signatureBase64: normalizedSignature
        )
    }
}

public struct ToriiAssetTransferIntent: Decodable, Sendable, Equatable {
    public let chainId: String
    public let authority: String
    public let assetDefinitionId: String
    public let assetBalanceScope: String
    public let amount: String
    public let destination: String
    public let memo: String?
    public let feePayment: FeePaymentIntent
    public let creationTimeMs: UInt64
    public let transactionTtlMs: UInt64

    private enum CodingKeys: String, CodingKey {
        case chainId = "chain_id"
        case authority
        case assetDefinitionId = "asset_definition_id"
        case assetBalanceScope = "asset_balance_scope"
        case amount
        case destination
        case memo
        case feePayment = "fee_payment"
        case creationTimeMs = "creation_time_ms"
        case transactionTtlMs = "transaction_ttl_ms"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "chain_id", "authority", "asset_definition_id", "asset_balance_scope",
                "amount", "destination", "memo", "fee_payment", "creation_time_ms",
                "transaction_ttl_ms",
            ],
            context: "asset transfer intent"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let chainId = try container.decode(String.self, forKey: .chainId)
        guard !chainId.isEmpty,
              chainId == chainId.trimmingCharacters(in: .whitespacesAndNewlines),
              chainId.utf8.count <= 512 else {
            throw DecodingError.dataCorruptedError(
                forKey: .chainId,
                in: container,
                debugDescription: "chain_id must be exact non-empty bounded text"
            )
        }
        self.chainId = chainId
        authority = try normalizeDetachedAssetTransferAccount(
            container.decode(String.self, forKey: .authority),
            field: "authority"
        )
        assetDefinitionId = try normalizeDetachedAssetTransferDefinition(
            container.decode(String.self, forKey: .assetDefinitionId)
        )
        assetBalanceScope = try normalizeDetachedAssetTransferScope(
            container.decode(String.self, forKey: .assetBalanceScope)
        )
        amount = try normalizeDetachedAssetTransferAmount(
            container.decode(String.self, forKey: .amount)
        )
        destination = try normalizeDetachedAssetTransferAccount(
            container.decode(String.self, forKey: .destination),
            field: "destination"
        )
        memo = try normalizeDetachedAssetTransferMemo(
            container.decodeIfPresent(String.self, forKey: .memo)
        )
        feePayment = try container.decode(FeePaymentIntent.self, forKey: .feePayment)
        creationTimeMs = try container.decode(UInt64.self, forKey: .creationTimeMs)
        transactionTtlMs = try container.decode(UInt64.self, forKey: .transactionTtlMs)
        guard creationTimeMs > 0,
              (1...ToriiAssetTransferRequest.maximumTransactionTtlMs).contains(transactionTtlMs),
              !creationTimeMs.addingReportingOverflow(transactionTtlMs).overflow else {
            throw DecodingError.dataCorruptedError(
                forKey: .transactionTtlMs,
                in: container,
                debugDescription: "asset transfer intent time bounds are invalid"
            )
        }
    }
}

public struct ToriiAssetTransferReceipt: Decodable, Sendable, Equatable {
    public let operationKind: String
    public let status: String
    public let transport: String
    public let intent: ToriiAssetTransferIntent
    public let payloadSigningHashHex: String
    public let transactionHashHex: String?
    public let entrypointHashHex: String?

    private enum CodingKeys: String, CodingKey {
        case operationKind = "operation_kind"
        case status
        case transport
        case intent
        case payloadSigningHashHex = "payload_signing_hash_hex"
        case transactionHashHex = "transaction_hash_hex"
        case entrypointHashHex = "entrypoint_hash_hex"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "operation_kind", "status", "transport", "intent",
                "payload_signing_hash_hex", "transaction_hash_hex",
                "entrypoint_hash_hex",
            ],
            context: "asset transfer receipt"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        operationKind = try container.decode(String.self, forKey: .operationKind)
        status = try container.decode(String.self, forKey: .status)
        transport = try container.decode(String.self, forKey: .transport)
        intent = try container.decode(ToriiAssetTransferIntent.self, forKey: .intent)
        payloadSigningHashHex = try exactDetachedAssetTransferHash(
            container.decode(String.self, forKey: .payloadSigningHashHex),
            field: "payload_signing_hash_hex",
            codingPath: container.codingPath + [CodingKeys.payloadSigningHashHex]
        )
        transactionHashHex = try Self.decodeOptionalHash(.transactionHashHex, container: container)
        entrypointHashHex = try Self.decodeOptionalHash(.entrypointHashHex, container: container)
    }

    private static func decodeOptionalHash(
        _ key: CodingKeys,
        container: KeyedDecodingContainer<CodingKeys>
    ) throws -> String? {
        guard let value = try container.decodeIfPresent(String.self, forKey: key) else {
            return nil
        }
        return try exactDetachedAssetTransferHash(
            value,
            field: key.stringValue,
            codingPath: container.codingPath + [key]
        )
    }
}

public struct ToriiAssetTransferResponse: Decodable, Sendable {
    fileprivate static let maximumTransactionBytes = 16 * 1_024 * 1_024

    public let ok: Bool
    public let submitted: Bool
    public let intent: ToriiAssetTransferIntent
    public let transactionPayloadB64: String?
    public let signingMessageB64: String?
    public let transactionHashHex: String?
    public let entrypointHashHex: String?
    public let pipelineStatus: ToriiPipelineTransactionStatus?
    public let receipt: ToriiAssetTransferReceipt
    public fileprivate(set) var signedTransaction: Data?
    public fileprivate(set) var finalization: DetachedTransactionFinalization?

    private enum CodingKeys: String, CodingKey {
        case ok
        case submitted
        case intent
        case transactionPayloadB64 = "transaction_payload_b64"
        case signingMessageB64 = "signing_message_b64"
        case transactionHashHex = "transaction_hash_hex"
        case entrypointHashHex = "entrypoint_hash_hex"
        case pipelineStatus = "pipeline_status"
        case receipt
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "ok", "submitted", "intent", "transaction_payload_b64",
                "signing_message_b64", "transaction_hash_hex",
                "entrypoint_hash_hex", "pipeline_status", "receipt",
            ],
            context: "asset transfer response"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        ok = try container.decode(Bool.self, forKey: .ok)
        submitted = try container.decode(Bool.self, forKey: .submitted)
        intent = try container.decode(ToriiAssetTransferIntent.self, forKey: .intent)
        transactionPayloadB64 = try container.decodeIfPresent(
            String.self,
            forKey: .transactionPayloadB64
        )
        signingMessageB64 = try container.decodeIfPresent(
            String.self,
            forKey: .signingMessageB64
        )
        transactionHashHex = try Self.decodeOptionalHash(.transactionHashHex, container: container)
        entrypointHashHex = try Self.decodeOptionalHash(.entrypointHashHex, container: container)
        pipelineStatus = try container.decodeIfPresent(
            ToriiPipelineTransactionStatus.self,
            forKey: .pipelineStatus
        )
        receipt = try container.decode(ToriiAssetTransferReceipt.self, forKey: .receipt)
        signedTransaction = nil
        finalization = nil

        let receiptPayloadHashIsNonzero = receipt.payloadSigningHashHex.contains { $0 != "0" }
        guard ok,
              receipt.operationKind == "asset_transfer",
              receipt.transport == "torii",
              receipt.intent == intent,
              receiptPayloadHashIsNonzero else {
            throw DecodingError.dataCorruptedError(
                forKey: .receipt,
                in: container,
                debugDescription: "asset transfer response receipt is not canonically bound"
            )
        }

        if submitted {
            let hasCanonicalQueuedStatus = pipelineStatus.map {
                $0.state == .queued
                    && $0.scope == "local"
                    && $0.resolvedFrom == "queue"
                    && $0.status.blockHeight == nil
                    && receipt.status == "submitted"
            } == true
            let hasCanonicalAppliedReplayStatus = pipelineStatus.map {
                $0.state == .applied
                    && $0.scope == "local"
                    && $0.resolvedFrom == "state"
                    && $0.status.blockHeight.map({ $0 > 0 }) != false
                    && receipt.status == "applied"
            } == true
            guard transactionPayloadB64 == nil,
                  signingMessageB64 == nil,
                  let transactionHashHex,
                  let entrypointHashHex,
                  transactionHashHex == entrypointHashHex,
                  transactionHashHex.contains(where: { $0 != "0" }),
                  let pipelineStatus,
                  pipelineStatus.hash == transactionHashHex,
                  hasCanonicalQueuedStatus || hasCanonicalAppliedReplayStatus,
                  receipt.transactionHashHex == transactionHashHex,
                  receipt.entrypointHashHex == entrypointHashHex else {
                throw DecodingError.dataCorruptedError(
                    forKey: .submitted,
                    in: container,
                    debugDescription: "submitted asset transfer response has an invalid phase shape"
                )
            }
        } else {
            guard let transactionPayloadB64,
                  let signingMessageB64,
                  transactionHashHex == nil,
                  entrypointHashHex == nil,
                  pipelineStatus == nil,
                  receipt.status == "pending_signature",
                  receipt.transactionHashHex == nil,
                  receipt.entrypointHashHex == nil else {
                throw DecodingError.dataCorruptedError(
                    forKey: .submitted,
                    in: container,
                    debugDescription: "prepared asset transfer response has an invalid phase shape"
                )
            }
            do {
                let draft = try ToriiCanonicalTransactionDraft.decode(
                    transactionPayloadB64: transactionPayloadB64,
                    signingMessageB64: signingMessageB64,

                    context: "asset transfer response"
                )
                guard receipt.payloadSigningHashHex == draft.signingMessage.hexLowercased() else {
                    throw ToriiClientError.invalidPayload(
                        "asset transfer receipt changed the transaction payload hash."
                    )
                }
            } catch {
                throw DecodingError.dataCorruptedError(
                    forKey: .transactionPayloadB64,
                    in: container,
                    debugDescription: "asset transfer draft transaction material is invalid: \(error)"
                )
            }
        }
    }

    private static func decodeOptionalHash(
        _ key: CodingKeys,
        container: KeyedDecodingContainer<CodingKeys>
    ) throws -> String? {
        guard let value = try container.decodeIfPresent(String.self, forKey: key) else {
            return nil
        }
        return try exactDetachedAssetTransferHash(
            value,
            field: key.stringValue,
            codingPath: container.codingPath + [key]
        )
    }
}

/// One exact canonical Torii asset-transfer payload and signing message.
public struct ToriiAssetTransferDraft: Sendable, Equatable {
    public let request: ToriiAssetTransferRequest
    public let intent: ToriiAssetTransferIntent
    public let networkId: NetworkId
    public let transactionPayload: Data
    public let signingMessage: Data
    public let payloadSigningHashHex: String

    fileprivate init(
        preparedRequest: ToriiAssetTransferRequest,
        response: ToriiAssetTransferResponse,
        expectedNetworkId: NetworkId
    ) throws {
        guard response.ok,
              !response.submitted,
              preparedRequest.matches(intent: response.intent),
              let transactionPayloadB64 = response.transactionPayloadB64,
              let signingMessageB64 = response.signingMessageB64,
              response.transactionHashHex == nil,
              response.entrypointHashHex == nil,
              response.pipelineStatus == nil,
              response.receipt.operationKind == "asset_transfer",
              response.receipt.status == "pending_signature",
              response.receipt.transport == "torii",
              response.receipt.intent == response.intent,
              response.receipt.transactionHashHex == nil,
              response.receipt.entrypointHashHex == nil else {
            throw ToriiClientError.invalidPayload(
                "asset transfer preparation response is not a canonical pending-signature draft."
            )
        }
        let draft: ToriiCanonicalTransactionDraft
        do {
            draft = try ToriiCanonicalTransactionDraft.decode(
                transactionPayloadB64: transactionPayloadB64,
                signingMessageB64: signingMessageB64,

                context: "asset transfer response"
            )
            try Self.validateTransactionPayloadBindings(
                draft.payload,
                request: preparedRequest,
                expectedNetworkId: expectedNetworkId
            )
        } catch {
            throw ToriiClientError.invalidPayload(
                "asset transfer preparation did not contain the exact requested canonical transaction payload: \(error)"
            )
        }
        let payloadSigningHashHex = draft.signingMessage.hexLowercased()
        guard response.receipt.payloadSigningHashHex == payloadSigningHashHex else {
            throw ToriiClientError.invalidPayload(
                "asset transfer receipt changed the exact transaction payload hash."
            )
        }
        request = preparedRequest
        intent = response.intent
        networkId = expectedNetworkId
        transactionPayload = draft.transactionPayload
        signingMessage = draft.signingMessage
        self.payloadSigningHashHex = payloadSigningHashHex
    }

    fileprivate func validateSubmittedResponse(
        _ response: ToriiAssetTransferResponse,
        finalization: DetachedTransactionFinalization
    ) throws {
        try Self.validateSubmittedBindings(
            response,
            request: request,
            preparedIntent: intent,
            signingMessage: signingMessage,
            payloadSigningHashHex: payloadSigningHashHex,
            finalization: finalization
        )
    }

    static func validateTransactionPayloadBindings(
        _ payload: ToriiCanonicalTransactionDraft.Payload,
        request: ToriiAssetTransferRequest,
        expectedNetworkId: NetworkId
    ) throws {
        try ToriiCanonicalTransactionDraft.requireAuthority(
            payload,
            equals: request.authority,
            context: "asset transfer draft"
        )
        let expectedMetadata: [String: ToriiJSONValue]
        if let memo = request.memo {
            expectedMetadata = ["memo": .string(memo)]
        } else {
            expectedMetadata = [:]
        }
        guard payload.networkId == expectedNetworkId,
              payload.creationTimeMs == request.creationTimeMs,
              payload.timeToLiveMs == request.transactionTtlMs,
              payload.nonce == nil,
              payload.feePayment == (try request.feePayment.compactNorito()),
              payload.metadata == expectedMetadata else {
            throw ToriiClientError.invalidPayload(
                "asset-transfer transaction header or metadata differs from the exact request."
            )
        }
        try validateTransferExecutable(payload.executable, request: request)
    }

    static func validateSubmittedBindings(
        _ response: ToriiAssetTransferResponse,
        request: ToriiAssetTransferRequest,
        preparedIntent: ToriiAssetTransferIntent,
        signingMessage: Data,
        payloadSigningHashHex: String,
        finalization: DetachedTransactionFinalization
    ) throws {
        let transactionHashHex = Self.lowercaseHex(finalization.transactionHash)
        let entrypointHashHex = Self.lowercaseHex(finalization.entrypointHash)
        let hasCanonicalSubmissionStatus = response.pipelineStatus.map {
            Self.isCanonicalSubmissionStatus($0, receiptStatus: response.receipt.status)
        } == true
        guard response.ok,
              response.submitted,
              request.matches(intent: response.intent),
              response.intent == preparedIntent,
              response.transactionPayloadB64 == nil,
              response.signingMessageB64 == nil,
              response.transactionHashHex == transactionHashHex,
              response.entrypointHashHex == entrypointHashHex,
              transactionHashHex.contains(where: { $0 != "0" }),
              finalization.payloadSigningHash == signingMessage,
              let pipelineStatus = response.pipelineStatus,
              pipelineStatus.hash == transactionHashHex,
              hasCanonicalSubmissionStatus,
              response.receipt.operationKind == "asset_transfer",
              response.receipt.transport == "torii",
              response.receipt.intent == preparedIntent,
              response.receipt.payloadSigningHashHex == payloadSigningHashHex,
              response.receipt.transactionHashHex == transactionHashHex,
              response.receipt.entrypointHashHex == entrypointHashHex else {
            throw ToriiClientError.invalidPayload(
                "submitted asset transfer is not exactly bound to its canonical detached draft."
            )
        }
    }

    fileprivate static func isCanonicalSubmissionStatus(
        _ status: ToriiPipelineTransactionStatus,
        receiptStatus: String
    ) -> Bool {
        guard status.scope == "local" else {
            return false
        }
        switch status.state {
        case .queued:
            return receiptStatus == "submitted"
                && status.resolvedFrom == "queue"
                && status.status.blockHeight == nil
        case .applied:
            return receiptStatus == "applied"
                && status.resolvedFrom == "state"
                && status.status.blockHeight.map({ $0 > 0 }) != false
        default:
            return false
        }
    }

    static func validateAuthoritativeFinality(
        _ status: ToriiPipelineTransactionStatus,
        expectedTransactionHashHex: String
    ) throws {
        guard status.hash == expectedTransactionHashHex,
              status.state == .applied,
              status.scope == "global",
              status.resolvedFrom == "state",
              status.status.blockHeight.map({ $0 > 0 }) == true else {
            throw ToriiClientError.invalidPayload(
                "detached asset transfer did not reach authoritative applied finality."
            )
        }
    }

    static func validateDetachedSignature(
        publicKeyHex: String,
        signatureBase64: String,
        authority: String,
        signingPayload: Data
    ) throws -> (
        publicKey: Data,
        signature: Data,
        exactPublicKeyHex: String,
        exactSignatureBase64: String
    ) {
        let exactPublicKey = try ToriiRequestValidation.exactLowercase32ByteHex(
            publicKeyHex,
            field: "public_key_hex"
        )
        guard let publicKey = Data(hexString: exactPublicKey),
              publicKey.count == 32,
              publicKey.contains(where: { $0 != 0 }) else {
            throw ToriiClientError.invalidPayload(
                "public_key_hex must encode a nonzero 32-byte Ed25519 public key."
            )
        }
        let exactSignature = try ToriiRequestValidation.normalizedExactBase64(
            signatureBase64,
            field: "signature_base64"
        )
        guard let signature = Data(base64Encoded: exactSignature),
              signature.count == 64,
              signature.contains(where: { $0 != 0 }) else {
            throw ToriiClientError.invalidPayload(
                "signature_base64 must encode a nonzero 64-byte Ed25519 signature."
            )
        }
        guard let prefix = try? AccountAddress.inspectI105NetworkPrefix(
            authority,
            expectedPrefix: nil
        ).chainDiscriminant,
              let derivedAuthority = try? AccountId.makeI105(
                publicKey: publicKey,
                networkPrefix: prefix
              ),
              derivedAuthority == authority else {
            throw ToriiClientError.invalidPayload(
                "public_key_hex does not control the detached asset-transfer authority."
            )
        }
        guard let verifyingKey = try? Curve25519.Signing.PublicKey(
            rawRepresentation: publicKey
        ),
              verifyingKey.isValidSignature(signature, for: signingPayload) else {
            throw ToriiClientError.invalidPayload(
                "signature_base64 is not a valid Ed25519 signature of the exact transfer draft."
            )
        }
        return (publicKey, signature, exactPublicKey, exactSignature)
    }

    private static func validateTransferExecutable(
        _ bytes: Data,
        request: ToriiAssetTransferRequest
    ) throws {
        var executable = ToriiVerifyingKeyCompactReader(bytes)
        guard try executable.takeUInt32("asset transfer executable variant") == 0 else {
            throw ToriiClientError.invalidPayload("asset transfer draft changed executable kind.")
        }
        var instructions = ToriiVerifyingKeyCompactReader(
            try executable.takeField("asset transfer instructions")
        )
        guard try instructions.takeUInt64("asset transfer instruction count") == 1 else {
            throw ToriiClientError.invalidPayload("asset transfer draft must contain one instruction.")
        }
        var instruction = ToriiVerifyingKeyCompactReader(
            try instructions.takeField("asset transfer instruction")
        )
        let wireName = try ToriiCanonicalTransactionDraft.decodeString(
            try instruction.takeField("asset transfer wire name"),
            field: "asset transfer wire name"
        )
        var frameContainer = CanonicalNoritoReader(
            data: try instruction.takeField("asset transfer frame container")
        )
        let frame = try frameContainer.readField()
        guard wireName == "iroha.transfer",
              executable.isFinished,
              instructions.isFinished,
              instruction.isFinished,
              frameContainer.remaining() == 0,
              let decodedFrame = noritoDecodeFrame(frame),
              decodedFrame.header.schema == noritoSchemaHash(
                  forTypeName: "iroha_data_model::isi::transfer::TransferBox"
              ),
              decodedFrame.header.flags == NoritoHeader.compactLen,
              decodedFrame.header.compression == .none,
              decodedFrame.paddingLength == 0,
              noritoEncode(
                  typeName: "iroha_data_model::isi::transfer::TransferBox",
                  payload: decodedFrame.payload,
                  flags: NoritoHeader.compactLen
              ) == frame else {
            throw ToriiClientError.invalidPayload("asset transfer instruction frame is not canonical.")
        }
        var transfer = ToriiVerifyingKeyCompactReader(decodedFrame.payload)
        guard try transfer.takeUInt32("asset transfer variant") == 2 else {
            throw ToriiClientError.invalidPayload("asset transfer instruction changed transfer kind.")
        }
        var body = ToriiVerifyingKeyCompactReader(
            try transfer.takeField("asset transfer body")
        )
        let source = try body.takeField("asset transfer source")
        let quantity = try body.takeField("asset transfer quantity")
        let destination = try body.takeField("asset transfer destination")
        guard transfer.isFinished,
              body.isFinished,
              source == (try encodeExpectedSourceAsset(request)),
              quantity == (try CanonicalNorito.encodeCompactQuantity(request.amount)),
              destination == (try AccountAddress.parseEncoded(request.destination)
                  .compactNoritoAccountControllerPayload()) else {
            throw ToriiClientError.invalidPayload(
                "asset transfer instruction differs from the exact source, amount, or destination."
            )
        }
    }

    private static func encodeExpectedSourceAsset(
        _ request: ToriiAssetTransferRequest
    ) throws -> Data {
        guard let definition = AssetDefinitionAddress.decode(request.assetDefinitionId) else {
            throw ToriiClientError.invalidPayload("asset definition is not canonical.")
        }
        var source = CompactNoritoWriter()
        source.writeField(
            try AccountAddress.parseEncoded(request.authority)
                .compactNoritoAccountControllerPayload()
        )
        var encodedDefinition = CompactNoritoWriter()
        encodedDefinition.writeByteFields(definition)
        source.writeField(encodedDefinition.data)
        var scope = CompactNoritoWriter()
        if request.assetBalanceScope == "global" {
            scope.writeUInt32LE(0)
        } else {
            let literal = String(request.assetBalanceScope.dropFirst("dataspace:".count))
            guard let dataspace = UInt64(literal) else {
                throw ToriiClientError.invalidPayload("asset balance scope is not canonical.")
            }
            scope.writeUInt32LE(1)
            var dataspacePayload = CompactNoritoWriter()
            dataspacePayload.writeUInt64LE(dataspace)
            scope.writeField(dataspacePayload.data)
        }
        source.writeField(scope.data)
        return source.data
    }

    fileprivate static func lowercaseHex(_ data: Data) -> String {
        data.map { String(format: "%02x", $0) }.joined()
    }
}

/// Durable, public-only evidence produced before a detached asset-transfer POST.
///
/// Persist this value before calling `submitFinalizedDetachedAssetTransfer`. It
/// contains no private key material, but it does contain the exact signed
/// request and transaction bytes needed to reconcile an uncertain submission
/// without creating a second payment.
public struct ToriiDetachedAssetTransferSubmissionEvidence: Codable, Sendable, Equatable {
    public static let schema = "iroha.detached_asset_transfer_submission_evidence.v1"

    /// Exact replay-protection identity selected by the canonical transaction domain.
    public let networkId: NetworkId
    /// Protocol chain label returned by Torii and bound to its operation receipt.
    public let chainId: String
    /// Exact canonical request, including the public key and detached signature.
    public let submittedRequest: ToriiAssetTransferRequest
    /// Exact canonical versioned signed transaction reconstructed locally.
    public let signedTransaction: Data
    /// Deterministic hashes bound to `signedTransaction`.
    public let finalization: DetachedTransactionFinalization

    /// Canonical padded base64 suitable for durable JSON or database storage.
    public var signedTransactionBase64: String {
        signedTransaction.base64EncodedString()
    }

    public var payloadSigningHashHex: String {
        ToriiAssetTransferDraft.lowercaseHex(finalization.payloadSigningHash)
    }

    public var transactionHashHex: String {
        ToriiAssetTransferDraft.lowercaseHex(finalization.transactionHash)
    }

    public var entrypointHashHex: String {
        ToriiAssetTransferDraft.lowercaseHex(finalization.entrypointHash)
    }

    /// Last instant at which Torii may admit this exact signed payload.
    public var expiresAtMs: UInt64 {
        let (value, overflow) = submittedRequest.creationTimeMs.addingReportingOverflow(
            submittedRequest.transactionTtlMs
        )
        return overflow ? UInt64.max : value
    }

    public init(
        networkId: NetworkId,
        chainId: String,
        submittedRequest: ToriiAssetTransferRequest,
        signedTransaction: Data,
        finalization: DetachedTransactionFinalization
    ) throws {
        self.networkId = networkId
        self.chainId = chainId
        self.submittedRequest = submittedRequest
        self.signedTransaction = Data(signedTransaction)
        self.finalization = finalization
        try validateIntrinsicBindings()
    }

    private enum CodingKeys: String, CodingKey {
        case schema
        case networkId = "network_id"
        case chainId = "chain_id"
        case submittedRequest = "submitted_request"
        case signedTransactionBase64 = "signed_transaction_base64"
        case payloadSigningHashHex = "payload_signing_hash_hex"
        case transactionHashHex = "transaction_hash_hex"
        case entrypointHashHex = "entrypoint_hash_hex"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownContractManifestFields(
            from: decoder,
            allowed: [
                "schema", "network_id", "chain_id", "submitted_request", "signed_transaction_base64",
                "payload_signing_hash_hex", "transaction_hash_hex", "entrypoint_hash_hex",
            ],
            context: "detached asset-transfer submission evidence"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        guard try container.decode(String.self, forKey: .schema) == Self.schema else {
            throw DecodingError.dataCorruptedError(
                forKey: .schema,
                in: container,
                debugDescription: "unsupported detached asset-transfer evidence schema"
            )
        }
        let encodedTransaction = try container.decode(
            String.self,
            forKey: .signedTransactionBase64
        )
        let maximumEncodedBytes =
            ((ToriiAssetTransferResponse.maximumTransactionBytes + 2) / 3) * 4
        guard !encodedTransaction.isEmpty,
              encodedTransaction.utf8.count <= maximumEncodedBytes,
              let signedTransaction = Data(base64Encoded: encodedTransaction),
              !signedTransaction.isEmpty,
              signedTransaction.count <= ToriiAssetTransferResponse.maximumTransactionBytes,
              signedTransaction.base64EncodedString() == encodedTransaction else {
            throw DecodingError.dataCorruptedError(
                forKey: .signedTransactionBase64,
                in: container,
                debugDescription: "signed_transaction_base64 must be canonical bounded base64"
            )
        }

        func decodeHash(_ key: CodingKeys) throws -> Data {
            let exact = try exactDetachedAssetTransferHash(
                container.decode(String.self, forKey: key),
                field: key.stringValue,
                codingPath: container.codingPath + [key]
            )
            guard let bytes = Data(hexString: exact), bytes.count == 32 else {
                throw DecodingError.dataCorruptedError(
                    forKey: key,
                    in: container,
                    debugDescription: "evidence hash must contain exactly 32 bytes"
                )
            }
            return bytes
        }

        try self.init(
            networkId: container.decode(NetworkId.self, forKey: .networkId),
            chainId: container.decode(String.self, forKey: .chainId),
            submittedRequest: container.decode(
                ToriiAssetTransferRequest.self,
                forKey: .submittedRequest
            ),
            signedTransaction: signedTransaction,
            finalization: DetachedTransactionFinalization(
                payloadSigningHash: decodeHash(.payloadSigningHashHex),
                transactionHash: decodeHash(.transactionHashHex),
                entrypointHash: decodeHash(.entrypointHashHex)
            )
        )
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(Self.schema, forKey: .schema)
        try container.encode(networkId, forKey: .networkId)
        try container.encode(chainId, forKey: .chainId)
        try container.encode(submittedRequest, forKey: .submittedRequest)
        try container.encode(signedTransactionBase64, forKey: .signedTransactionBase64)
        try container.encode(payloadSigningHashHex, forKey: .payloadSigningHashHex)
        try container.encode(transactionHashHex, forKey: .transactionHashHex)
        try container.encode(entrypointHashHex, forKey: .entrypointHashHex)
    }

    fileprivate func validateIntrinsicBindings() throws {
        let normalizedRequest = try submittedRequest.normalizedSignedEvidence()
        guard normalizedRequest == submittedRequest,
              let publicKeyHex = submittedRequest.publicKeyHex,
              let signatureBase64 = submittedRequest.signatureBase64,
              !chainId.isEmpty,
              chainId == chainId.trimmingCharacters(in: .whitespacesAndNewlines),
              chainId.utf8.count <= 512,
              !signedTransaction.isEmpty,
              signedTransaction.count <= ToriiAssetTransferResponse.maximumTransactionBytes,
              finalization.payloadSigningHash.count == 32,
              finalization.payloadSigningHash.contains(where: { $0 != 0 }),
              finalization.transactionHash.count == 32,
              finalization.transactionHash.contains(where: { $0 != 0 }),
              finalization.entrypointHash == finalization.transactionHash else {
            throw ToriiClientError.invalidPayload(
                "detached asset-transfer submission evidence is not canonical."
            )
        }
        let validatedSignature = try ToriiAssetTransferDraft.validateDetachedSignature(
            publicKeyHex: publicKeyHex,
            signatureBase64: signatureBase64,
            authority: submittedRequest.authority,
            signingPayload: finalization.payloadSigningHash
        )
        let transactionPayload = try ToriiCanonicalTransactionDraft.transactionPayload(
            fromVersionedSignedTransaction: signedTransaction,

            context: "detached asset-transfer evidence"
        )
        let reproduced = try ToriiCanonicalTransactionDraft.finalize(
            transactionPayload: transactionPayload,
            publicKey: validatedSignature.publicKey,
            signature: validatedSignature.signature
        )
        guard reproduced.signedTransaction == signedTransaction,
              reproduced.finalization == finalization,
              IrohaHash.hash(transactionPayload) == finalization.payloadSigningHash else {
            throw ToriiClientError.invalidPayload(
                "detached asset-transfer evidence hashes or signature differ from its transaction."
            )
        }
        let draft = try ToriiCanonicalTransactionDraft.decode(
            transactionPayloadB64: transactionPayload.base64EncodedString(),
            signingMessageB64: finalization.payloadSigningHash.base64EncodedString(),

            context: "detached asset-transfer evidence"
        )
        try ToriiAssetTransferDraft.validateTransactionPayloadBindings(
            draft.payload,
            request: submittedRequest,
            expectedNetworkId: networkId
        )
    }

    fileprivate func validateSubmittedResponse(
        _ response: ToriiAssetTransferResponse
    ) throws {
        let transactionHashHex = self.transactionHashHex
        let entrypointHashHex = self.entrypointHashHex
        let hasCanonicalSubmissionStatus = response.pipelineStatus.map {
            ToriiAssetTransferDraft.isCanonicalSubmissionStatus(
                $0,
                receiptStatus: response.receipt.status
            )
        } == true
        guard response.ok,
              response.submitted,
              submittedRequest.matches(intent: response.intent),
              response.intent.chainId == chainId,
              response.transactionPayloadB64 == nil,
              response.signingMessageB64 == nil,
              response.transactionHashHex == transactionHashHex,
              response.entrypointHashHex == entrypointHashHex,
              let pipelineStatus = response.pipelineStatus,
              pipelineStatus.hash == transactionHashHex,
              hasCanonicalSubmissionStatus,
              response.receipt.operationKind == "asset_transfer",
              response.receipt.transport == "torii",
              response.receipt.intent == response.intent,
              response.receipt.payloadSigningHashHex == payloadSigningHashHex,
              response.receipt.transactionHashHex == transactionHashHex,
              response.receipt.entrypointHashHex == entrypointHashHex else {
            throw ToriiClientError.invalidPayload(
                "submitted asset transfer is not exactly bound to its durable evidence."
            )
        }
    }
}

/// The exact transfer may have reached Torii, but no trustworthy submit receipt
/// was received. Never create a replacement payment from this error; persist its
/// evidence and reconcile `transactionHashHex` instead.
public struct ToriiDetachedAssetTransferSubmissionUncertainError: Error, Sendable {
    public let evidence: ToriiDetachedAssetTransferSubmissionEvidence
    public let cause: ToriiClientError

    public init(
        evidence: ToriiDetachedAssetTransferSubmissionEvidence,
        cause: ToriiClientError
    ) {
        self.evidence = evidence
        self.cause = cause
    }
}

/// Durable evidence was absent from pipeline state after its authoritative
/// transaction TTL elapsed. The exact transaction can no longer be admitted or
/// applied, so callers may terminate recovery without risking a late duplicate.
public struct ToriiDetachedAssetTransferRecoveryExpiredError: Error, Sendable {
    public let evidence: ToriiDetachedAssetTransferSubmissionEvidence

    public init(evidence: ToriiDetachedAssetTransferSubmissionEvidence) {
        self.evidence = evidence
    }
}

extension ToriiDetachedAssetTransferRecoveryExpiredError: LocalizedError {
    public var errorDescription: String? {
        "Detached asset-transfer \(evidence.transactionHashHex) is absent from pipeline state and its authoritative transaction TTL has elapsed."
    }
}

extension ToriiDetachedAssetTransferSubmissionUncertainError: LocalizedError {
    public var errorDescription: String? {
        "Detached asset-transfer submission is uncertain; reconcile transaction \(evidence.transactionHashHex) before creating another payment."
    }
}

public struct ToriiMultisigAccountSelector: Encodable, Sendable, Equatable {
    public var multisigAccountId: String?
    public var multisigAccountAlias: String?

    public init(multisigAccountId: String? = nil,
                multisigAccountAlias: String? = nil) {
        self.multisigAccountId = multisigAccountId
        self.multisigAccountAlias = multisigAccountAlias
    }

    private enum CodingKeys: String, CodingKey {
        case multisigAccountId = "multisig_account_id"
        case multisigAccountAlias = "multisig_account_alias"
    }

    fileprivate func normalizedPayload(field: String) throws -> (multisigAccountId: String?, multisigAccountAlias: String?) {
        let normalizedAccountId = try multisigAccountId.map {
            try normalizeToriiAccountIdQueryValue($0, field: "\(field).multisig_account_id")
        }
        let normalizedAlias = try multisigAccountAlias.map {
            try normalizeToriiAccountAliasLiteral($0, field: "\(field).multisig_account_alias")
        }
        guard (normalizedAccountId == nil) != (normalizedAlias == nil) else {
            throw ToriiClientError.invalidPayload(
                "\(field) requires exactly one of multisig_account_id or multisig_account_alias."
            )
        }
        return (normalizedAccountId, normalizedAlias)
    }

    public func encode(to encoder: Encoder) throws {
        let normalized = try normalizedPayload(field: "multisig selector")
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encodeIfPresent(normalized.multisigAccountId, forKey: .multisigAccountId)
        try container.encodeIfPresent(normalized.multisigAccountAlias, forKey: .multisigAccountAlias)
    }
}

/// An independently constructed commitment to the exact unsigned transaction
/// that a multisig write route is allowed to return for signing.
///
/// The commitment is client-only and is never serialized in the request. Its
/// executable must include the exact resolved account, proposal instructions,
/// and any state-derived contract argument record. This avoids trusting Torii's
/// response as its own proof of the operation the caller intended.
public struct ToriiMultisigUnsignedTransactionIntent: Sendable, Equatable {
    /// First-release `TransactionBuilder` default used by all multisig write routes.
    public static let transactionTtlMs: UInt64 = 100_000

    public let networkId: NetworkId
    public let resolvedMultisigAccountId: String
    public let instructionsHash: String
    public let executable: Data
    public let metadata: [String: ToriiJSONValue]

    public init(networkId: NetworkId,
                resolvedMultisigAccountId: String,
                instructionsHash: String,
                executable: Data,
                metadata: [String: ToriiJSONValue]) throws {
        let normalizedAccountId = try normalizeToriiAccountIdQueryValue(
            resolvedMultisigAccountId,
            field: "resolvedMultisigAccountId"
        )
        guard !resolvedMultisigAccountId.contains("@"),
              normalizedAccountId == resolvedMultisigAccountId else {
            throw ToriiClientError.invalidPayload(
                "resolvedMultisigAccountId must be an exact canonical I105 account id."
            )
        }
        let normalizedInstructionsHash = try ToriiRequestValidation.normalized32ByteHex(
            instructionsHash,
            field: "instructionsHash"
        )
        guard normalizedInstructionsHash == instructionsHash else {
            throw ToriiClientError.invalidPayload(
                "instructionsHash must be exact lowercase 32-byte hexadecimal text."
            )
        }
        try ToriiCanonicalTransactionDraft.requireNonemptyInstructionExecutable(
            executable,
            context: "multisig unsigned transaction intent"
        )
        _ = try ToriiCanonicalTransactionDraft.compactMetadata(metadata)
        self.networkId = networkId
        self.resolvedMultisigAccountId = normalizedAccountId
        self.instructionsHash = normalizedInstructionsHash
        self.executable = Data(executable)
        self.metadata = metadata
    }
}

public struct ToriiMultisigProposeInstruction: Encodable, Sendable, Equatable {
    private enum Payload: Sendable, Equatable {
        case json(ToriiJSONValue)
        case nativeBase64(String)
    }

    private let payload: Payload

    public init(json: ToriiJSONValue) throws {
        guard case .object = json else {
            throw ToriiClientError.invalidPayload(
                "multisig propose JSON instructions must be structured InstructionBox objects or native InstructionBox base64 strings."
            )
        }
        self.payload = .json(json)
    }

    public init(object: [String: ToriiJSONValue]) throws {
        try self.init(json: .object(object))
    }

    public init(noritoInstructionBoxBytes: Data) throws {
        guard !noritoInstructionBoxBytes.isEmpty else {
            throw ToriiClientError.invalidPayload("noritoInstructionBoxBytes must be non-empty.")
        }
        try self.init(base64: noritoInstructionBoxBytes.base64EncodedString())
    }

    public init(base64: String) throws {
        self.payload = .nativeBase64(
            try ToriiRequestValidation.normalizedBase64(base64, field: "instruction base64")
        )
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        switch payload {
        case let .json(json):
            try container.encode(json)
        case let .nativeBase64(base64):
            try container.encode(base64)
        }
    }
}

public struct ToriiMultisigProposeRequest: Encodable, Sendable {
    public var selector: ToriiMultisigAccountSelector
    public var signerAccountId: String
    public var publicKeyHex: String?
    public var signatureB64: String?
    public var creationTimeMs: UInt64?
    public var feePayment: FeePaymentIntent
    public var memo: String?
    public var validationFeeAssessment: RetailFeeAssessmentV1?
    public var instructions: [ToriiMultisigProposeInstruction]
    /// Local-only exact transaction commitment required before an unsigned
    /// response can be exposed for signing. It is not part of the Torii DTO.
    public var unsignedTransactionIntent: ToriiMultisigUnsignedTransactionIntent?

    public init(selector: ToriiMultisigAccountSelector,
                signerAccountId: String,
                publicKeyHex: String? = nil,
                signatureB64: String? = nil,
                creationTimeMs: UInt64? = nil,
                memo: String? = nil,
                validationFeeAssessment: RetailFeeAssessmentV1? = nil,
                instructions: [ToriiMultisigProposeInstruction],
                feePayment: FeePaymentIntent,
                unsignedTransactionIntent: ToriiMultisigUnsignedTransactionIntent? = nil) {
        self.selector = selector
        self.signerAccountId = signerAccountId
        self.publicKeyHex = publicKeyHex
        self.signatureB64 = signatureB64
        self.creationTimeMs = creationTimeMs
        self.feePayment = feePayment
        self.memo = memo
        self.validationFeeAssessment = validationFeeAssessment
        self.instructions = instructions
        self.unsignedTransactionIntent = unsignedTransactionIntent
    }

    public init(selector: ToriiMultisigAccountSelector,
                signerAccountId: String,
                publicKeyHex: String? = nil,
                signatureB64: String? = nil,
                creationTimeMs: UInt64? = nil,
                memo: String? = nil,
                validationFeeAssessment: RetailFeeAssessmentV1? = nil,
                noritoInstructionBoxBytes: [Data],
                feePayment: FeePaymentIntent,
                unsignedTransactionIntent: ToriiMultisigUnsignedTransactionIntent? = nil) throws {
        try self.init(
            selector: selector,
            signerAccountId: signerAccountId,
            publicKeyHex: publicKeyHex,
            signatureB64: signatureB64,
            creationTimeMs: creationTimeMs,
            memo: memo,
            validationFeeAssessment: validationFeeAssessment,
            instructions: noritoInstructionBoxBytes.map {
                try ToriiMultisigProposeInstruction(noritoInstructionBoxBytes: $0)
            },
            feePayment: feePayment,
            unsignedTransactionIntent: unsignedTransactionIntent
        )
    }

    private enum CodingKeys: String, CodingKey {
        case multisigAccountId = "multisig_account_id"
        case multisigAccountAlias = "multisig_account_alias"
        case signerAccountId = "signer_account_id"
        case publicKeyHex = "public_key_hex"
        case signatureB64 = "signature_b64"
        case creationTimeMs = "creation_time_ms"
        case feePayment = "fee_payment"
        case memo
        case validationFeeAssessment = "validation_fee_assessment"
        case instructions
    }

    public func encode(to encoder: Encoder) throws {
        let normalizedSelector = try selector.normalizedPayload(field: "multisig propose selector")
        let normalizedSignerAccountId = try normalizeToriiAccountIdQueryValue(
            signerAccountId,
            field: "signer_account_id"
        )
        let normalizedPublicKeyHex = try ToriiRequestValidation.normalizedOptional32ByteHex(publicKeyHex, field: "public_key_hex")
        let normalizedSignatureB64 = try signatureB64.map {
            try ToriiRequestValidation.normalizedExactBase64($0, field: "signature_b64")
        }
        _ = try feePayment.canonicalJSONData()
        let normalizedMemo = try ToriiRequestValidation.normalizedOptionalNonEmpty(memo, field: "memo")
        if let validationFeeAssessment {
            // Require the native typed parser before an assessment enters a proposal.
            _ = try validationFeeAssessment.marker()
        }
        guard !instructions.isEmpty else {
            throw ToriiClientError.invalidPayload("instructions must not be empty.")
        }

        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encodeIfPresent(normalizedSelector.multisigAccountId, forKey: .multisigAccountId)
        try container.encodeIfPresent(normalizedSelector.multisigAccountAlias, forKey: .multisigAccountAlias)
        try container.encode(normalizedSignerAccountId, forKey: .signerAccountId)
        try container.encodeIfPresent(normalizedPublicKeyHex, forKey: .publicKeyHex)
        try container.encodeIfPresent(normalizedSignatureB64, forKey: .signatureB64)
        try container.encodeIfPresent(creationTimeMs, forKey: .creationTimeMs)
        try container.encode(feePayment, forKey: .feePayment)
        try container.encodeIfPresent(normalizedMemo, forKey: .memo)
        try container.encodeIfPresent(validationFeeAssessment, forKey: .validationFeeAssessment)
        try container.encode(instructions, forKey: .instructions)
    }
}

public struct ToriiMultisigContractCallProposeRequest: Encodable, Sendable {
