/// Nexus fee configuration Torii serves in pipeline preflight.
///
/// Fee amounts are canonical decimal quantity strings; `settlementMode` is `direct` or
/// `lane_relay_burn`.
public struct ToriiPipelinePreflightFees: Decodable, Sendable, Equatable {
    /// Settlement modes Torii serves.
    public static let settlementModes: Set<String> = ["direct", "lane_relay_burn"]

    public let feeAssetId: String
    public let feeSinkAccountId: String
    public let baseFee: String
    public let perByteFee: String
    public let perInstructionFee: String
    public let perGasUnitFee: String
    public let sponsorVaultCustodyAccountId: String
    public let settlementMode: String
    public let successfulClaimFeeExemptAuthorities: [String]

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case feeAssetId = "fee_asset_id"
        case feeSinkAccountId = "fee_sink_account_id"
        case baseFee = "base_fee"
        case perByteFee = "per_byte_fee"
        case perInstructionFee = "per_instruction_fee"
        case perGasUnitFee = "per_gas_unit_fee"
        case sponsorVaultCustodyAccountId = "sponsor_vault_custody_account_id"
        case settlementMode = "settlement_mode"
        case successfulClaimFeeExemptAuthorities = "successful_claim_fee_exempt_authorities"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: Set(CodingKeys.allCases.map(\.rawValue)),
            debugName: "pipeline preflight fees"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        feeAssetId = try decodePipelinePreflightString(container, .feeAssetId)
        let feeSinkAccountId = try container.decode(String.self, forKey: .feeSinkAccountId)
        guard (try? exactCanonicalToriiAccountAddress(feeSinkAccountId)) != nil else {
            throw DecodingError.dataCorruptedError(
                forKey: .feeSinkAccountId,
                in: container,
                debugDescription: "fee_sink_account_id must be an exact canonical I105 account id"
            )
        }
        self.feeSinkAccountId = feeSinkAccountId
        baseFee = try decodePipelinePreflightString(container, .baseFee)
        perByteFee = try decodePipelinePreflightString(container, .perByteFee)
        perInstructionFee = try decodePipelinePreflightString(container, .perInstructionFee)
        perGasUnitFee = try decodePipelinePreflightString(container, .perGasUnitFee)
        let sponsorVaultCustodyAccountId = try container.decode(
            String.self,
            forKey: .sponsorVaultCustodyAccountId
        )
        guard (try? exactCanonicalToriiAccountAddress(sponsorVaultCustodyAccountId)) != nil else {
            throw DecodingError.dataCorruptedError(
                forKey: .sponsorVaultCustodyAccountId,
                in: container,
                debugDescription: "sponsor_vault_custody_account_id must be an exact canonical I105 account id"
            )
        }
        self.sponsorVaultCustodyAccountId = sponsorVaultCustodyAccountId
        let settlementMode = try container.decode(String.self, forKey: .settlementMode)
        guard Self.settlementModes.contains(settlementMode) else {
            throw DecodingError.dataCorruptedError(
                forKey: .settlementMode,
                in: container,
                debugDescription: "settlement_mode must be one of: direct, lane_relay_burn"
            )
        }
        self.settlementMode = settlementMode
        let authorities = try container.decode(
            [String].self,
            forKey: .successfulClaimFeeExemptAuthorities
        )
        guard authorities.allSatisfy({
            (try? exactCanonicalToriiAccountAddress($0)) != nil
        }) else {
            throw DecodingError.dataCorruptedError(
                forKey: .successfulClaimFeeExemptAuthorities,
                in: container,
                debugDescription: "successful_claim_fee_exempt_authorities must contain only exact canonical I105 account ids"
            )
        }
        successfulClaimFeeExemptAuthorities = authorities
    }
}

/// Typed `GET /v1/pipeline/preflight` body.
///
/// Every object carries exactly the fields Torii serves; any other field is rejected as
/// protocol drift.
public struct ToriiPipelinePreflight: Decodable, Sendable, Equatable {
    /// Target block cadences a peer with queued work may go without committing a non-empty
    /// block before `isStatusStalled(_:)` reports a stall.
    ///
    /// Torii serves one consensus timing value, `sumeragi.block_cadence_ms` (the signed-genesis
    /// target block time), so `stallThresholdMs` is `stallBlockCadences * blockCadenceMs`. With
    /// work queued a healthy chain commits about once per cadence. At the Sumeragi defaults
    /// (1 s block time, 5 s payload retry, 2-3 s base view timer) one crashed leader delays the
    /// next commit by roughly 11-14 s plus execution (`specs/sumeragi.md` §8.2 P4, §9.3); twenty
    /// cadences keep such a single view change from being reported as a stall. Callers that
    /// know their deployment's local timers pass their own threshold to
    /// `ToriiStatusPayload.isQueueStalled(stallThresholdMs:)`.
    public static let stallBlockCadences = 20

    public let schemaVersion: Int
    public let chainHeight: Int
    public let sumeragi: ToriiPipelinePreflightSumeragi
    public let admission: ToriiPipelinePreflightAdmission
    public let block: ToriiPipelinePreflightBlock
    public let pipeline: ToriiPipelinePreflightPipeline
    public let queue: ToriiPipelinePreflightQueue
    public let fees: ToriiPipelinePreflightFees

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case schemaVersion = "schema_version"
        case chainHeight = "chain_height"
        case sumeragi
        case admission
        case block
        case pipeline
        case queue
        case fees
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: Set(CodingKeys.allCases.map(\.rawValue)),
            debugName: "pipeline preflight"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        schemaVersion = try decodePipelinePreflightUnsigned(
            container,
            .schemaVersion,
            positive: true
        )
        chainHeight = try decodePipelinePreflightUnsigned(container, .chainHeight)
        sumeragi = try container.decode(ToriiPipelinePreflightSumeragi.self, forKey: .sumeragi)
        admission = try container.decode(ToriiPipelinePreflightAdmission.self, forKey: .admission)
        block = try container.decode(ToriiPipelinePreflightBlock.self, forKey: .block)
        pipeline = try container.decode(ToriiPipelinePreflightPipeline.self, forKey: .pipeline)
        queue = try container.decode(ToriiPipelinePreflightQueue.self, forKey: .queue)
        fees = try container.decode(ToriiPipelinePreflightFees.self, forKey: .fees)
    }

    /// SDK-derived stall threshold, not a served field: `stallBlockCadences` times
    /// `sumeragi.blockCadenceMs`, saturated at `Int.max`.
    public var stallThresholdMs: Int {
        let (threshold, overflow) = sumeragi.blockCadenceMs.multipliedReportingOverflow(
            by: Self.stallBlockCadences
        )
        return overflow ? Int.max : threshold
    }

    /// Report queued work with no non-empty block committed for longer than `stallThresholdMs`.
    public func isStatusStalled(_ status: ToriiStatusPayload) -> Bool {
        status.isQueueStalled(stallThresholdMs: stallThresholdMs)
    }
}

struct ToriiStatusState {
    private var previous: ToriiStatusPayload?
    private var latestSequence: UInt64 = 0
    private var nextSequence: UInt64 = 1

    mutating func reserveSequence() -> UInt64 {
        defer { nextSequence &+= 1 }
        return nextSequence
    }

    mutating func record(_ payload: ToriiStatusPayload, sequence: UInt64) -> ToriiStatusMetrics {
        if sequence > latestSequence {
            let metrics = ToriiStatusMetrics.fromSamples(previous: previous, current: payload)
            previous = payload
            latestSequence = sequence
            return metrics
        } else {
            // Stale sample: ignore for timeline and report zero deltas.
            return ToriiStatusMetrics.fromSamples(previous: nil, current: payload)
        }
    }
}

private enum ToriiDataModelValidation {
    case unknown
    case matched(version: Int, schemaHash: String)
    case dataModelMismatch(expected: Int, actual: Int?)
    case schemaMismatch(expected: String, actual: String?)
}

public struct ToriiGovernanceInstruction: Decodable, Sendable {
    public let wireId: String
    public let payloadHex: String

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case wireId = "wire_id"
        case payloadHex = "payload_hex"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: Set(CodingKeys.allCases.map(\.stringValue)),
            debugName: "governance instruction"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        wireId = try container.decode(String.self, forKey: .wireId)
        guard !wireId.isEmpty,
              wireId.unicodeScalars.allSatisfy({ scalar in
                  !CharacterSet.whitespacesAndNewlines.contains(scalar)
                      && !CharacterSet.controlCharacters.contains(scalar)
              }) else {
            throw DecodingError.dataCorruptedError(
                forKey: .wireId,
                in: container,
                debugDescription: "wire_id must be exact non-empty text without whitespace or control characters"
            )
        }
        payloadHex = try container.decode(String.self, forKey: .payloadHex)
        guard !payloadHex.isEmpty,
              payloadHex.count.isMultiple(of: 2),
              payloadHex.unicodeScalars.allSatisfy({ scalar in
                  (48...57).contains(scalar.value) || (97...102).contains(scalar.value)
              }) else {
            throw DecodingError.dataCorruptedError(
                forKey: .payloadHex,
                in: container,
                debugDescription: "payload_hex must be exact non-empty lowercase hexadecimal"
            )
        }
    }
}

public struct ToriiGovernanceDeployContractProposalRequest: Encodable, Sendable {
    public var proposalOperator: String
    public var contractAddress: String?
    public var contractAlias: String?
    public var codeHash: Data
    public var abiHash: Data
    public var abiVersion: UInt16
    public var manifestProvenance: ToriiContractManifestProvenance?

    private enum CodingKeys: String, CodingKey {
        case proposalOperator = "proposal_operator"
        case contractAddress = "contract_address"
        case contractAlias = "contract_alias"
        case codeHash = "code_hash"
        case abiHash = "abi_hash"
        case abiVersion = "abi_version"
        case manifestProvenance = "manifest_provenance"
    }

    public init(proposalOperator: String,
                contractAddress: String? = nil,
                contractAlias: String? = nil,
                codeHash: Data,
                abiHash: Data,
                abiVersion: UInt16 = 1,
                manifestProvenance: ToriiContractManifestProvenance? = nil) {
        self.proposalOperator = proposalOperator
        self.contractAddress = contractAddress
        self.contractAlias = contractAlias
        self.codeHash = codeHash
        self.abiHash = abiHash
        self.abiVersion = abiVersion
        self.manifestProvenance = manifestProvenance
    }

    public func encode(to encoder: Encoder) throws {
        do {
            _ = try exactCanonicalToriiAccountAddress(proposalOperator)
        } catch {
            throw ToriiClientError.invalidPayload(
                "proposal_operator must be an exact canonical account identifier."
            )
        }
        let normalizedTarget = try normalizeToriiContractTargetSelector(
            contractAddress: contractAddress,
            contractAlias: contractAlias,
            field: "governanceProposeDeployContract"
        )
        if let contractAddress = normalizedTarget.contractAddress,
           !ContractAddressV1.isCanonical(contractAddress) {
            throw ToriiClientError.invalidPayload("contract_address must be a canonical ABI V1 address.")
        }
        guard codeHash.count == 32 else {
            throw ToriiClientError.invalidPayload("code_hash must contain exactly 32 bytes.")
        }
        guard abiHash.count == 32 else {
            throw ToriiClientError.invalidPayload("abi_hash must contain exactly 32 bytes.")
        }
        guard abiVersion == 1 else {
            throw ToriiClientError.invalidPayload("abi_version must be exactly 1.")
        }
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(proposalOperator, forKey: .proposalOperator)
        try container.encodeIfPresent(normalizedTarget.contractAddress, forKey: .contractAddress)
        try container.encodeIfPresent(normalizedTarget.contractAlias, forKey: .contractAlias)
        try container.encode(codeHash.hexLowercased(), forKey: .codeHash)
        try container.encode(abiHash.hexLowercased(), forKey: .abiHash)
        try container.encode(abiVersion, forKey: .abiVersion)
        try container.encodeIfPresent(manifestProvenance, forKey: .manifestProvenance)
    }
}

public struct ToriiGovernanceProposalResponse: Decodable, Sendable {
    public let proposalId: String
    public let txInstructions: [ToriiGovernanceInstruction]

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case proposalId = "proposal_id"
        case txInstructions = "tx_instructions"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: Set(CodingKeys.allCases.map(\.stringValue)),
            debugName: "governance proposal response"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let proposalId = try container.decode(String.self, forKey: .proposalId)
        self.proposalId = try exactDetachedAssetTransferHash(
            proposalId,
            field: "proposal_id",
            codingPath: container.codingPath + [CodingKeys.proposalId]
        )
        let txInstructions = try container.decode(
            [ToriiGovernanceInstruction].self,
            forKey: .txInstructions
        )
        guard txInstructions.count == 1,
              txInstructions[0].wireId == "iroha.instruction.v1::governance::ProposeDeployContract" else {
            throw DecodingError.dataCorruptedError(
                forKey: .txInstructions,
                in: container,
                debugDescription: "governance proposal response must contain exactly one full ProposeDeployContract wire instruction"
            )
        }
        self.txInstructions = txInstructions
    }
}

public struct ToriiGovernanceBallotResponse: Decodable, Sendable {
    public let drafted: Bool
    public let txInstructions: [ToriiGovernanceInstruction]

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case drafted
        case txInstructions = "tx_instructions"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: Set(CodingKeys.allCases.map(\.stringValue)),
            debugName: "governance ballot draft response"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let drafted = try container.decode(Bool.self, forKey: .drafted)
        guard drafted else {
            throw DecodingError.dataCorruptedError(
                forKey: .drafted,
