public struct ToriiSubmitTransactionResponse: Decodable, Sendable {
    public struct Payload: Decodable, Sendable {
        public let entrypointHash: String
        public let signedTransactionHash: String?
        public let submittedAtMs: UInt64
        public let submittedAtHeight: UInt64
        public let signer: String
        public let signerValue: ToriiJSONValue

        private enum CodingKeys: String, CodingKey {
            case entrypointHash = "entrypoint_hash"
            case signedTransactionHash = "signed_transaction_hash"
            case submittedAtMs = "submitted_at_ms"
            case submittedAtHeight = "submitted_at_height"
            case signer
        }

        public init(entrypointHash: String,
                    submittedAtMs: UInt64,
                    submittedAtHeight: UInt64,
                    signer: String,
                    signedTransactionHash: String? = nil,
                    signerValue: ToriiJSONValue? = nil) {
            self.entrypointHash = entrypointHash
            self.signedTransactionHash = signedTransactionHash
            self.submittedAtMs = submittedAtMs
            self.submittedAtHeight = submittedAtHeight
            self.signer = signer
            self.signerValue = signerValue ?? .string(signer)
        }

        public init(from decoder: Decoder) throws {
            try rejectUnknownJSONFields(
                from: decoder,
                allowed: [
                    "entrypoint_hash", "signed_transaction_hash", "submitted_at_ms",
                    "submitted_at_height", "signer",
                ],
                debugName: "transaction submission receipt payload"
            )
            let container = try decoder.container(keyedBy: CodingKeys.self)
            entrypointHash = try ToriiSubmitTransactionResponse.decodeReceiptTransactionHash(
                from: container,
                key: .entrypointHash,
                field: "payload.entrypoint_hash"
            )
            signedTransactionHash = try ToriiSubmitTransactionResponse.decodeOptionalReceiptTransactionHash(
                from: container,
                key: .signedTransactionHash,
                field: "payload.signed_transaction_hash"
            )
            submittedAtMs = try ToriiSubmitTransactionResponse.decodeReceiptUInt64(
                from: container,
                key: .submittedAtMs,
                field: "payload.submitted_at_ms"
            )
            submittedAtHeight = try ToriiSubmitTransactionResponse.decodeReceiptUInt64(
                from: container,
                key: .submittedAtHeight,
                field: "payload.submitted_at_height"
            )
            signerValue = try container.decode(ToriiJSONValue.self, forKey: .signer)
            signer = try ToriiSubmitTransactionResponse.receiptFieldString(
                signerValue,
                field: "payload.signer",
                codingPath: container.codingPath + [CodingKeys.signer]
            )
        }
    }

    public let payload: Payload
    public let signature: String
    public let signatureValue: ToriiJSONValue

    private enum CodingKeys: String, CodingKey {
        case payload
        case signature
    }

    public init(payload: Payload,
                signature: String,
                signatureValue: ToriiJSONValue? = nil) {
        self.payload = payload
        self.signature = signature
        self.signatureValue = signatureValue ?? .string(signature)
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: ["payload", "signature"],
            debugName: "transaction submission receipt"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        payload = try container.decode(Payload.self, forKey: .payload)
        signatureValue = try container.decode(ToriiJSONValue.self, forKey: .signature)
        signature = try Self.receiptFieldString(
            signatureValue,
            field: "signature",
            codingPath: container.codingPath + [CodingKeys.signature]
        )
    }

    /// Convenience accessor for the canonical transaction entrypoint hash.
    public var hash: String { payload.entrypointHash }

    private static func decodeReceiptTransactionHash<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        key: K,
        field: String
    ) throws -> String {
        let value = try container.decode(String.self, forKey: key)
        guard value.utf8.count == 64,
              value.utf8.allSatisfy({ byte in
                  (0x30 ... 0x39).contains(byte) || (0x61 ... 0x66).contains(byte)
              }),
              let marker = value.utf8.last,
              [UInt8(ascii: "1"), UInt8(ascii: "3"), UInt8(ascii: "5"),
               UInt8(ascii: "7"), UInt8(ascii: "9"), UInt8(ascii: "b"),
               UInt8(ascii: "d"), UInt8(ascii: "f")].contains(marker) else {
            throw DecodingError.dataCorruptedError(
                forKey: key,
                in: container,
                debugDescription: "\(field) must be one canonical typed transaction hash"
            )
        }
        return value
    }

    private static func decodeOptionalReceiptTransactionHash<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        key: K,
        field: String
    ) throws -> String? {
        guard container.contains(key) else {
            throw DecodingError.keyNotFound(
                key,
                .init(
                    codingPath: container.codingPath,
                    debugDescription: "\(field) is required even when null"
                )
            )
        }
        guard try !container.decodeNil(forKey: key) else {
            return nil
        }
        return try decodeReceiptTransactionHash(from: container, key: key, field: field)
    }

    private static func decodeReceiptUInt64<K: CodingKey>(
        from container: KeyedDecodingContainer<K>,
        key: K,
        field: String
    ) throws -> UInt64 {
        do {
            return try container.decode(UInt64.self, forKey: key)
        } catch {
            throw DecodingError.dataCorrupted(
                .init(codingPath: container.codingPath + [key],
                      debugDescription: "\(field) must be an unsigned integer")
            )
        }
    }

    private static func receiptFieldString(_ value: ToriiJSONValue,
                                           field: String,
                                           codingPath: [CodingKey]) throws -> String {
        if case let .string(string) = value {
            return string
        }
        guard value != .null else {
            throw DecodingError.valueNotFound(
                ToriiJSONValue.self,
                .init(codingPath: codingPath,
                      debugDescription: "\(field) must not be null")
            )
        }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        do {
            let data = try encoder.encode(value)
            if let string = String(data: data, encoding: .utf8) {
                return string
            }
        } catch {
            throw DecodingError.dataCorrupted(
                .init(codingPath: codingPath,
                      debugDescription: "\(field) could not be encoded as JSON: \(error)")
            )
        }
        throw DecodingError.dataCorrupted(
            .init(codingPath: codingPath,
                  debugDescription: "\(field) could not be encoded as UTF-8 JSON")
        )
    }
}

/// Public pipeline metadata. Rejection and execution details require an authorized signed query.
public struct ToriiPipelineTransactionStatus: Decodable, Sendable {
    public struct Status: Decodable, Sendable {
        public let kind: String
        public let blockHeight: UInt64?

        private static let supportedKinds: Set<String> = [
            "Queued", "Approved", "Committed", "Applied", "Rejected", "Expired",
        ]

        private enum CodingKeys: String, CodingKey {
            case kind
            case blockHeight = "block_height"
        }

        public init(from decoder: Decoder) throws {
            try rejectUnknownJSONFields(
                from: decoder,
                allowed: ["kind", "block_height"],
                debugName: "pipeline transaction status.status"
            )
            let container = try decoder.container(keyedBy: CodingKeys.self)
            let decodedKind = try container.decode(String.self, forKey: .kind)
            guard Self.supportedKinds.contains(decodedKind) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .kind,
                    in: container,
                    debugDescription: "pipeline transaction status.status.kind is unsupported"
                )
            }
            kind = decodedKind

            if container.contains(.blockHeight) {
                guard try !container.decodeNil(forKey: .blockHeight) else {
                    throw DecodingError.valueNotFound(
                        UInt64.self,
                        .init(
                            codingPath: container.codingPath + [CodingKeys.blockHeight],
                            debugDescription: "pipeline transaction status.status.block_height must not be null"
                        )
                    )
                }
                let decodedHeight = try container.decode(UInt64.self, forKey: .blockHeight)
                guard decodedHeight > 0 else {
                    throw DecodingError.dataCorruptedError(
                        forKey: .blockHeight,
                        in: container,
                        debugDescription: "pipeline transaction status.status.block_height must be positive"
                    )
                }
                blockHeight = decodedHeight
            } else {
                blockHeight = nil
            }
        }

        public var state: PipelineTransactionState {
            PipelineTransactionState(kind: kind)
        }
    }

    public let hash: String
    public let status: Status
    public let scope: String
    public let resolvedFrom: String

    private enum CodingKeys: String, CodingKey {
        case hash
        case status
        case scope
        case resolvedFrom = "resolved_from"
    }

    public init(from decoder: Decoder) throws {
        try rejectUnknownJSONFields(
            from: decoder,
            allowed: ["hash", "status", "scope", "resolved_from"],
            debugName: "pipeline transaction status"
        )
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let decodedHash = try container.decode(String.self, forKey: .hash)
        let isCanonicalHash = decodedHash.utf8.count == 64
            && decodedHash.utf8.allSatisfy {
                (0x30 ... 0x39).contains($0) || (0x61 ... 0x66).contains($0)
            }
            && decodedHash.utf8.last.map {
                [UInt8(ascii: "1"), UInt8(ascii: "3"), UInt8(ascii: "5"),
                 UInt8(ascii: "7"), UInt8(ascii: "9"), UInt8(ascii: "b"),
                 UInt8(ascii: "d"), UInt8(ascii: "f")].contains($0)
            } == true
        guard isCanonicalHash else {
            throw DecodingError.dataCorruptedError(
                forKey: .hash,
                in: container,
                debugDescription: "pipeline transaction status.hash must be one canonical typed transaction hash"
            )
        }
        hash = decodedHash
        status = try container.decode(Status.self, forKey: .status)

        let decodedScope = try container.decode(String.self, forKey: .scope)
        guard ["local", "global"].contains(decodedScope) else {
            throw DecodingError.dataCorruptedError(
                forKey: .scope,
                in: container,
                debugDescription: "pipeline transaction status.scope is unsupported"
            )
        }
        scope = decodedScope

        let decodedResolvedFrom = try container.decode(String.self, forKey: .resolvedFrom)
        guard ["cache", "queue", "state"].contains(decodedResolvedFrom) else {
            throw DecodingError.dataCorruptedError(
                forKey: .resolvedFrom,
                in: container,
                debugDescription: "pipeline transaction status.resolved_from is unsupported"
            )
        }
        resolvedFrom = decodedResolvedFrom
    }

    public var state: PipelineTransactionState {
        status.state
    }

    public var isTerminal: Bool {
        guard resolvedFrom == "state" else { return false }
        switch state {
        case .applied:
            return status.blockHeight.map { $0 > 0 } == true
        case .rejected, .expired:
            return true
        default:
            return false
        }
    }

    public var isApplied: Bool {
        state == .applied && resolvedFrom == "state" && status.blockHeight.map { $0 > 0 } == true
    }

    public var isRejected: Bool {
        state == .rejected && resolvedFrom == "state"
    }

}

public struct ToriiPipelineRecovery: Decodable, Sendable {
    public struct Dag: Decodable, Sendable {
        public let fingerprint: String
        public let key_count: UInt64

        private enum CodingKeys: String, CodingKey {
            case fingerprint
            case key_count = "key_count"
        }
    }

    public struct TransactionSnapshot: Decodable, Sendable {
        public let hash: String
        public let reads: [String]
        public let writes: [String]
    }

    public let format: String
    public let height: UInt64
    public let dag: Dag
    public let txs: [TransactionSnapshot]
}

public enum PipelineTransactionState: Hashable, Sendable {
    case queued
    case approved
    case committed
    case applied
    case rejected
    case expired
    case other(String)

    public init(kind: String) {
        switch kind {
        case "Queued": self = .queued
        case "Approved": self = .approved
        case "Committed": self = .committed
        case "Applied": self = .applied
        case "Rejected": self = .rejected
        case "Expired": self = .expired
        default: self = .other(kind)
        }
    }

    public var kind: String {
        switch self {
        case .queued: return "Queued"
        case .approved: return "Approved"
        case .committed: return "Committed"
        case .applied: return "Applied"
        case .rejected: return "Rejected"
        case .expired: return "Expired"
        case .other(let value): return value
        }
    }

    public var isKnownTerminalSuccess: Bool {
        self == .applied
    }

    public var isKnownTerminalFailure: Bool {
        switch self {
        case .rejected, .expired:
            return true
        default:
            return false
        }
    }

    public var isTerminalSuccess: Bool {
        self == .applied
    }

    public var isTerminalFailure: Bool {
        switch self {
        case .rejected, .expired:
            return true
        default:
            return false
        }
    }
}

