/// A terminal error emitted after a Torii server-sent event stream has started.
public struct ToriiStreamError: Error, Sendable, Equatable {
    /// Stable machine-readable stream error code.
    public let code: String
    /// Human-readable terminal error message.
    public let message: String
    /// Number of broadcast messages skipped before termination, when reported.
    public let droppedMessages: UInt64?
    /// Whether the server can replay the missing portion of this stream.
    public let replayAvailable: Bool
}

extension ToriiStreamError: LocalizedError {
    public var errorDescription: String? { message }
}

public enum ToriiClientError: Error, Sendable {
    /// No secure RAM-LFE input-encryption profile is currently available.
    case ramLfeEncryptionUnavailable
    case invalidURL(String)
    case transport(Swift.Error)
    case invalidResponse
    case emptyBody
    /// Torii answered with a non-success status and, usually, its standard
    /// `{code, message, details}` error envelope.
    case api(ToriiAPIError)
    /// A collection query was rejected locally before anything was sent.
    case invalidQuery(ToriiListQueryError)
    case decoding(Swift.Error)
    case invalidPayload(String)
    case stream(ToriiStreamError)
    case dataModelMismatch(expected: Int, actual: Int?)
    case transactionSchemaMismatch(expected: String, actual: String?)
}

public extension ToriiClientError {
    /// HTTP status of a Torii error response.
    var status: Int? {
        if case let .api(error) = self {
            return error.status
        }
        return nil
    }

    /// Stable error code: the envelope `code` (or `X-Iroha-Reject-Code` when
    /// the body had none) of a Torii response, the Torii code of a locally
    /// rejected query control, or the code of a terminal stream error.
    var code: String? {
        switch self {
        case let .api(error): return error.code ?? error.rejectCode
        case let .invalidQuery(error): return error.code
        case let .stream(error): return error.code
        default: return nil
        }
    }

    /// Structured `details` of a Torii error envelope.
    var details: ToriiAPIError.Details? {
        if case let .api(error) = self {
            return error.details
        }
        return nil
    }
}

extension ToriiClientError: LocalizedError {
    public var errorDescription: String? {
        switch self {
        case .ramLfeEncryptionUnavailable:
            return "ram_lfe_encryption_unavailable: No secure RAM-LFE input-encryption profile is available."
        case .invalidURL(let value):
            return "Failed to construct Torii URL from path '\(value)'."
        case .transport(let error):
            return error.localizedDescription
        case .invalidResponse:
            return "Torii response was not an HTTP response."
        case .emptyBody:
            return "Torii response body was unexpectedly empty."
        case let .api(error):
            return error.description
        case let .invalidQuery(error):
            return error.description
        case .decoding(let error):
            return "Failed to decode Torii response: \(Self.describeDecodingError(error))"
        case .invalidPayload(let reason):
            return "Torii response payload was invalid: \(reason)"
        case .stream(let error):
            return "Torii event stream terminated with \(error.code): \(error.message)"
        case let .dataModelMismatch(expected, actual):
            if let actual {
                return "Torii data model version mismatch (expected \(expected), got \(actual))."
            }
            return "Torii data model version mismatch (expected \(expected), missing on node)."
        case let .transactionSchemaMismatch(expected, actual):
            if let actual {
                return "Torii signed transaction schema hash mismatch (expected \(expected), got \(actual))."
            }
            return "Torii signed transaction schema hash mismatch (expected \(expected), missing on node)."
        }
    }

    static func describeDecodingError(_ error: Swift.Error) -> String {
        func path(_ codingPath: [CodingKey]) -> String {
            let joined = codingPath.map(\.stringValue).joined(separator: ".")
            return joined.isEmpty ? "<root>" : joined
        }

        switch error {
        case let DecodingError.keyNotFound(key, context):
            let fullPath = path(context.codingPath + [key])
            return "missing key \(fullPath): \(context.debugDescription)"
        case let DecodingError.typeMismatch(type, context):
            return "type mismatch at \(path(context.codingPath)); expected \(type): \(context.debugDescription)"
        case let DecodingError.valueNotFound(type, context):
            return "missing value at \(path(context.codingPath)); expected \(type): \(context.debugDescription)"
        case let DecodingError.dataCorrupted(context):
            return "data corrupted at \(path(context.codingPath)): \(context.debugDescription)"
        default:
            return String(describing: error)
        }
    }
}

public enum ToriiWireFormatPreference: Sendable, Equatable {
    case noritoPreferred
    case jsonPreferred
    case noritoOnly
    case jsonOnly

    public var acceptHeader: String {
        switch self {
        case .noritoPreferred:
            return "application/x-norito, application/json;q=0.8"
        case .jsonPreferred:
            return "application/json, application/x-norito;q=0.8"
        case .noritoOnly:
            return "application/x-norito"
        case .jsonOnly:
            return "application/json"
        }
    }
}

public protocol ToriiTransactionSubmitting: AnyObject {
    func submitTransaction(data: Data,
                           idempotencyKey: String?) async throws -> ToriiSubmitTransactionResponse?
    @discardableResult
    func submitTransaction(data: Data,
                           idempotencyKey: String?,
                           completion: @escaping (Swift.Result<ToriiSubmitTransactionResponse?, Swift.Error>) -> Void) -> Task<Void, Never>
}

public protocol ToriiTransactionEntrypointSubmitting: ToriiTransactionSubmitting {
    func submitTransactionEntrypoint(data: Data,
                                     idempotencyKey: String?) async throws -> ToriiSubmitTransactionResponse?
    @discardableResult
    func submitTransactionEntrypoint(data: Data,
                                     idempotencyKey: String?,
                                     completion: @escaping (Swift.Result<ToriiSubmitTransactionResponse?, Swift.Error>) -> Void) -> Task<Void, Never>
}

public extension ToriiTransactionSubmitting where Self: Sendable {
    func submitTransaction(data: Data) async throws -> ToriiSubmitTransactionResponse? {
        try await submitTransaction(data: data, idempotencyKey: nil)
    }

    @discardableResult
    func submitTransaction(data: Data,
                           completion: @escaping (Swift.Result<ToriiSubmitTransactionResponse?, Swift.Error>) -> Void) -> Task<Void, Never> {
        submitTransaction(data: data, idempotencyKey: nil, completion: completion)
    }

    @discardableResult
    func submitTransaction(data: Data,
                           idempotencyKey: String? = nil,
                           completion: @escaping (Swift.Result<ToriiSubmitTransactionResponse?, Swift.Error>) -> Void) -> Task<Void, Never> {
        runCompletionTask(operation: { [self] in
            try await submitTransaction(data: data, idempotencyKey: idempotencyKey)
        }, completion: completion)
    }
}

public extension ToriiTransactionEntrypointSubmitting where Self: Sendable {
    func submitTransactionEntrypoint(data: Data) async throws -> ToriiSubmitTransactionResponse? {
        try await submitTransactionEntrypoint(data: data, idempotencyKey: nil)
    }

    @discardableResult
    func submitTransactionEntrypoint(data: Data,
                                     completion: @escaping (Swift.Result<ToriiSubmitTransactionResponse?, Swift.Error>) -> Void) -> Task<Void, Never> {
        submitTransactionEntrypoint(data: data, idempotencyKey: nil, completion: completion)
