                                     idempotencyKey: String? = nil,
                                     completion: @escaping (Swift.Result<ToriiSubmitTransactionResponse?, Swift.Error>) -> Void) -> Task<Void, Never> {
        runCompletionTask(operation: { [self] in
            try await submitTransactionEntrypoint(data: data, idempotencyKey: idempotencyKey)
        }, completion: completion)
    }
}

public final class ToriiClient: ToriiTransactionEntrypointSubmitting, @unchecked Sendable {
    private enum ServerClockObservationSource: Sendable, Equatable {
        case authoritativeTimeEndpoint
        case httpDateFallback
    }

    private struct ObservedServerClock: Sendable {
        let serverEpochMs: UInt64
        let observedLocalEpochMs: UInt64
        let observedMonotonicMs: UInt64
        let source: ServerClockObservationSource
    }

    private static let sharedServerClockQueue = DispatchQueue(label: "org.hyperledger.iroha.torii.shared-server-clock")
    private static var sharedObservedServerClocks: [String: ObservedServerClock] = [:]

    /// Base URL for all requests. Normalized to directory URL (ends with "/") to ensure
    /// correct relative URL resolution per RFC 3986.
    public let baseURL: URL
    /// Immutable trust context for endpoints that return bytes to be signed locally.
    public let localSigningContext: ToriiLocalSigningContext?
    /// Default local account signer for exact-network authenticated application requests.
    public let canonicalRequestAuth: ToriiCanonicalRequestAuth?
    /// Timestamp and nonce source for canonical request signatures; `nil`
    /// uses the client clock and a random nonce for every request.
    private let canonicalRequestFreshness: ToriiCanonicalRequestFreshness?
    /// Immutable exact-network signer used only by operator-authenticated APIs.
    public let operatorSigningContext: ToriiOperatorSigningContext?
    /// Default HTTP headers applied to every Torii request.
    public let defaultHeaders: [String: String]
    /// Wire-format preference used for dual-format Torii routes.
    public let wireFormatPreference: ToriiWireFormatPreference
    private let session: URLSession
    private let currentTimeMilliseconds: @Sendable () -> UInt64
    private let currentMonotonicMilliseconds: @Sendable () -> UInt64
    private let serverClockCacheKey: String
    /// Guarded by `statusStateQueue`; `getStatusSnapshot()` may run concurrently.
    private var statusState = ToriiStatusState()
    private let statusStateQueue = DispatchQueue(label: "org.hyperledger.iroha.torii.status-state")
    private var dataModelValidation = ToriiDataModelValidation.unknown
    private let dataModelQueue = DispatchQueue(label: "org.hyperledger.iroha.torii.data-model")
    private let serverClockQueue = DispatchQueue(label: "org.hyperledger.iroha.torii.server-clock")
    private var observedServerClock: ObservedServerClock?
    private static let feeQuoteResponseMaximumBytes = 64 * 1024
    private static let feeSponsorProgramResponseMaximumBytes = 64 * 1024
    private static let contractCallResponseMaximumBytes = 32 * 1_024 * 1_024
    private static let assetTransferResponseMaximumBytes = 32 * 1_024 * 1_024
    private static let accountOnboardingCurrentStateResponseMaximumBytes = 4 * 1_024

    public init(baseURL: URL,
                session: URLSession = .shared,
                defaultHeaders: [String: String] = [:],
                localSigningContext: ToriiLocalSigningContext? = nil,
                canonicalRequestAuth: ToriiCanonicalRequestAuth? = nil,
                canonicalRequestFreshness: ToriiCanonicalRequestFreshness? = nil,
                operatorSigningContext: ToriiOperatorSigningContext? = nil,
                wireFormatPreference: ToriiWireFormatPreference = .noritoPreferred,
                currentTimeMilliseconds: @escaping @Sendable () -> UInt64 = {
                    UInt64(max(0, Date().timeIntervalSince1970 * 1_000).rounded())
                },
                currentMonotonicMilliseconds: @escaping @Sendable () -> UInt64 = {
                    UInt64(max(0, ProcessInfo.processInfo.systemUptime * 1_000).rounded())
                }) {
        // Normalize to directory URL for correct relative URL resolution.
        // Without trailing slash, URL(string:relativeTo:) replaces the last path component
        // instead of appending (per RFC 3986).
        self.baseURL = baseURL.hasDirectoryPath ? baseURL : baseURL.appendingPathComponent("")
        self.localSigningContext = localSigningContext
        self.canonicalRequestAuth = canonicalRequestAuth
        self.canonicalRequestFreshness = canonicalRequestFreshness
        self.operatorSigningContext = operatorSigningContext
        self.serverClockCacheKey = Self.serverClockCacheKey(for: self.baseURL)
        self.session = session
        self.currentTimeMilliseconds = currentTimeMilliseconds
        self.currentMonotonicMilliseconds = currentMonotonicMilliseconds
        self.defaultHeaders = ToriiClientAuthentication.normalizedHeaders(defaultHeaders).filter {
            $0.key.caseInsensitiveCompare(ToriiAccountOnboardingTokenHeader) != .orderedSame
        }
        self.wireFormatPreference = wireFormatPreference
    }

    public convenience init(
        baseURL: URL,
        session: URLSession = .shared,
        authentication: ToriiClientAuthentication,
        localSigningContext: ToriiLocalSigningContext? = nil,
        canonicalRequestAuth: ToriiCanonicalRequestAuth? = nil,
        canonicalRequestFreshness: ToriiCanonicalRequestFreshness? = nil,
        operatorSigningContext: ToriiOperatorSigningContext? = nil,
        wireFormatPreference: ToriiWireFormatPreference = .noritoPreferred
    ) {
        self.init(baseURL: baseURL,
                  session: session,
                  defaultHeaders: authentication.headers,
                  localSigningContext: localSigningContext,
                  canonicalRequestAuth: canonicalRequestAuth,
                  canonicalRequestFreshness: canonicalRequestFreshness,
                  operatorSigningContext: operatorSigningContext,
                  wireFormatPreference: wireFormatPreference)
    }

    /// Invalidates the underlying URLSession and cancels all outstanding tasks.
    /// Call this method when you are done using the client to release resources.
    public func invalidateAndCancel() {
        session.invalidateAndCancel()
    }

    /// Returns a creation timestamp that tracks observed server time when available and
    /// otherwise uses the local wall clock. A small safety margin keeps locally
    /// built transactions from being rejected when the device clock is slightly ahead.
    public func recommendedCreationTimeMs(safetyMarginMs: UInt64 = 10_000,
                                          maxObservedLagMs: UInt64 = 20_000) -> UInt64 {
        let localNowMs = currentEpochMs()
        let monotonicNowMs = currentMonotonicMs()
        let baseMs = serverClockQueue.sync { () -> UInt64 in
            let clock = observedServerClock ?? Self.sharedObservedServerClock(for: serverClockCacheKey)
            guard let clock else { return localNowMs }
            let elapsedSinceObservation = monotonicNowMs >= clock.observedMonotonicMs
                ? monotonicNowMs - clock.observedMonotonicMs
                : 0
            let (estimatedServerNow, overflow) = clock.serverEpochMs.addingReportingOverflow(elapsedSinceObservation)
            let clampedEstimatedServerNow = overflow ? UInt64.max : estimatedServerNow
            if clock.source == .authoritativeTimeEndpoint {
                return clampedEstimatedServerNow
            }
            let observedLagMs = localNowMs >= clampedEstimatedServerNow
                ? localNowMs - clampedEstimatedServerNow
                : 0
            guard observedLagMs <= maxObservedLagMs else {
                return localNowMs
            }
            return min(localNowMs, clampedEstimatedServerNow)
        }
        return baseMs > safetyMarginMs ? baseMs - safetyMarginMs : 0
    }

