    }

    public func callContract(
        _ requestBody: ToriiContractCallRequest,
        canonicalAuth: ToriiCanonicalRequestAuth? = nil
    ) async throws -> ToriiContractCallResponse {
        guard let canonicalAuth = canonicalAuth ?? canonicalRequestAuth else {
            throw ToriiClientError.invalidPayload(
                "contract calls require canonical account authentication."
            )
        }
        guard canonicalAuth.accountId == (try normalizeToriiAccountIdQueryValue(requestBody.authority, field: "authority")) else {
            throw ToriiClientError.invalidPayload(
                "canonicalAuth.accountId must identify the contract-call authority."
            )
        }
        let request = try makeCanonicalAccountRequest(path: "/v1/contracts/call",
                                      method: .post,
                                      queryItems: nil,
                                      body: try JSONEncoder().encode(requestBody),
                                      headers: [
                                        "Content-Type": "application/json",
                                        "Accept": "application/json",
                                      ],
                                      canonicalAuth: canonicalAuth)
        let (data, response) = try await sendBoundedResponse(
            request,
            context: "contract call",
            maximumBytes: Self.contractCallResponseMaximumBytes
        )
        try ensureStatus(response, equals: 200, responseBody: data)
        try ensureResponseMediaType(response, equals: "application/json")
        try rejectDuplicateJSONKeys(data, context: "contract call response")
        let decoded = try decodeJSON(ToriiContractCallResponse.self, from: data)
        if !decoded.submitted {
            guard let localSigningContext else {
                throw ToriiClientError.invalidPayload(
                    "unsigned contract-call responses require a local signing context to bind the transaction network."
                )
            }
            let normalized = try requestBody.normalizedForDetachedPreparation(
                nowMilliseconds: currentEpochMs()
            )
            _ = try ToriiContractCallDraft(
                preparedRequest: normalized,
                response: decoded,
                expectedNetworkId: localSigningContext.networkId
            )
        }
        return decoded
    }

    public func resolveContractAlias(
        _ contractAlias: String,
        canonicalAuth: ToriiCanonicalRequestAuth
    ) async throws -> ToriiContractAliasResolution {
        let normalizedAlias = try normalizeToriiContractAliasLiteral(
            contractAlias,
            field: "contract_alias"
        )
        struct Request: Encodable {
            let contractAlias: String
            enum CodingKeys: String, CodingKey {
                case contractAlias = "contract_alias"
            }
        }
        let body = try JSONEncoder().encode(Request(contractAlias: normalizedAlias))
        let request = try makeVpnRequest(
            path: "/v1/contracts/aliases/resolve",
            method: .post,
            body: body,
            canonicalAuth: canonicalAuth
        )
        let (data, response) = try await send(request)
        try ensureStatus(response, equals: 200, responseBody: data)
        try ensureResponseMediaType(response, equals: "application/json")
        try rejectDuplicateJSONKeys(data, context: "contract alias resolution response")
        let resolution = try decodeJSON(ToriiContractAliasResolution.self, from: data)
        guard resolution.contractAlias == normalizedAlias else {
            throw ToriiClientError.invalidPayload(
                "contract alias resolution is not bound to the requested alias."
            )
        }
        return resolution
    }

