    public func submitDetachedContractCall(
        _ draft: ToriiContractCallDraft,
        publicKeyHex: String,
        signatureB64: String,
        canonicalAuth: ToriiCanonicalRequestAuth? = nil
    ) async throws -> ToriiDetachedContractCallSubmission {
        let exactPublicKey = try ToriiRequestValidation.exactLowercase32ByteHex(
            publicKeyHex,
            field: "public_key_hex"
        )
        guard let publicKey = Data(hexString: exactPublicKey),
              publicKey.count == 32,
              publicKey.contains(where: { $0 != 0 }) else {
            throw ToriiClientError.invalidPayload(
                "public_key_hex must encode a nonzero 32-byte Ed25519 public key."
            )
        }
        let exactSignature = try ToriiRequestValidation.normalizedExactBase64(
            signatureB64,
            field: "signature_b64"
        )
        guard let signature = Data(base64Encoded: exactSignature),
              signature.count == 64,
              signature.contains(where: { $0 != 0 }) else {
            throw ToriiClientError.invalidPayload(
                "signature_b64 must encode a nonzero 64-byte Ed25519 signature."
            )
        }
        guard let prefix = try? AccountAddress.inspectI105NetworkPrefix(
            draft.request.authority,
            expectedPrefix: nil
        ).chainDiscriminant,
              let derivedAuthority = try? AccountId.makeI105(
                  publicKey: publicKey,
                  networkPrefix: prefix
              ),
              derivedAuthority == draft.request.authority else {
            throw ToriiClientError.invalidPayload(
                "public_key_hex does not control the detached contract-call authority."
            )
        }
        let finalized = try ToriiCanonicalTransactionDraft.finalize(
            transactionPayload: draft.transactionPayload,
            publicKey: publicKey,
            signature: signature
        )
        guard finalized.finalization.payloadSigningHash == draft.signingMessage else {
            throw ToriiClientError.invalidPayload(
                "finalized transaction payload differs from the exact contract-call draft."
            )
        }

        var request = draft.request
        request.publicKeyHex = exactPublicKey
        request.signatureB64 = exactSignature
        request.transactionPayloadB64 = draft.transactionPayload.base64EncodedString()
        let response = try await callContract(request, canonicalAuth: canonicalAuth)
        try draft.validateSubmittedResponse(
            response,
            finalization: finalized.finalization
        )
        return ToriiDetachedContractCallSubmission(
            response: response,
            signedTransaction: finalized.signedTransaction,
            finalization: finalized.finalization
        )
    }

    public func waitForDetachedContractCallFinality(
        _ draft: ToriiContractCallDraft,
        submission: ToriiDetachedContractCallSubmission,
        pollOptions: PipelineStatusPollOptions = .default
    ) async throws -> ToriiPipelineTransactionStatus {
        try draft.validateSubmittedResponse(
            submission.response,
            finalization: submission.finalization
        )
        guard let txHash = submission.response.txHashHex else {
            throw ToriiClientError.invalidPayload(
                "submitted detached contract call is missing its transaction hash."
            )
        }
        let status = try await waitForTransactionStatus(
            hashHex: txHash,
            pollOptions: pollOptions
        )
        guard status.hash == txHash,
              status.state == .applied,
              status.scope == "global",
              status.resolvedFrom == "state",
              status.status.blockHeight.map({ $0 > 0 }) == true else {
            throw ToriiClientError.invalidPayload(
                "detached contract call did not reach authoritative applied finality."
            )
        }
        return status
    }

    public func prepareDetachedAssetTransfer(
        _ request: ToriiAssetTransferRequest
    ) async throws -> ToriiAssetTransferDraft {
        guard let localSigningContext else {
            throw ToriiClientError.invalidPayload(
                "detached asset-transfer preparation requires an immutable ToriiLocalSigningContext"
            )
        }
        let normalized = try request.normalizedForPreparation(
            nowMilliseconds: recommendedCreationTimeMs(safetyMarginMs: 0)
        )
        let response = try await postDetachedAssetTransfer(normalized)
        return try ToriiAssetTransferDraft(
            preparedRequest: normalized,
            response: response,
            expectedNetworkId: localSigningContext.networkId
        )
    }

    public func submitDetachedAssetTransfer(
        _ draft: ToriiAssetTransferDraft,
        signingKey: SigningKey
    ) async throws -> ToriiAssetTransferResponse {
        let evidence = try finalizeDetachedAssetTransfer(draft, signingKey: signingKey)
        return try await submitFinalizedDetachedAssetTransfer(evidence)
    }

    /// Finalize and verify the exact server-provided transaction payload without performing
    /// any network request. Persist the returned evidence before submission.
    public func finalizeDetachedAssetTransfer(
        _ draft: ToriiAssetTransferDraft,
        signingKey: SigningKey
    ) throws -> ToriiDetachedAssetTransferSubmissionEvidence {
        guard signingKey.algorithm == .ed25519 else {
            throw ToriiClientError.invalidPayload(
                "detached asset transfers require an Ed25519 signing key."
            )
        }
        let publicKey = try signingKey.publicKey()
        guard publicKey.count == 32, publicKey.contains(where: { $0 != 0 }) else {
            throw ToriiClientError.invalidPayload(
                "Ed25519 signing key returned an invalid public key."
            )
        }
        let signature = try signingKey.sign(draft.signingMessage)
        return try finalizeDetachedAssetTransfer(
            draft,
            publicKeyHex: ToriiAssetTransferDraft.lowercaseHex(publicKey),
            signatureBase64: signature.base64EncodedString()
        )
    }

    public func submitDetachedAssetTransfer(
        _ draft: ToriiAssetTransferDraft,
        publicKeyHex: String,
        signatureBase64: String
    ) async throws -> ToriiAssetTransferResponse {
        let evidence = try finalizeDetachedAssetTransfer(
            draft,
            publicKeyHex: publicKeyHex,
            signatureBase64: signatureBase64
        )
        return try await submitFinalizedDetachedAssetTransfer(evidence)
    }

    /// Finalize an externally produced Ed25519 signature against the exact
    /// canonical transaction payload without contacting Torii.
    public func finalizeDetachedAssetTransfer(
        _ draft: ToriiAssetTransferDraft,
        publicKeyHex: String,
        signatureBase64: String
    ) throws -> ToriiDetachedAssetTransferSubmissionEvidence {
        let validatedSignature = try ToriiAssetTransferDraft.validateDetachedSignature(
            publicKeyHex: publicKeyHex,
            signatureBase64: signatureBase64,
            authority: draft.request.authority,
            signingPayload: draft.signingMessage
        )
        let publicKey = validatedSignature.publicKey
        let signature = validatedSignature.signature

        let finalized = try ToriiCanonicalTransactionDraft.finalize(
            transactionPayload: draft.transactionPayload,
            publicKey: publicKey,
            signature: signature
        )
        guard finalized.finalization.payloadSigningHash == draft.signingMessage,
              !finalized.signedTransaction.isEmpty else {
            throw ToriiClientError.invalidPayload(
                "finalized asset-transfer transaction payload differs from the exact draft."
            )
        }

        let submittedRequest = try draft.request.normalizedForSubmission(
            publicKeyHex: validatedSignature.exactPublicKeyHex,
            signatureBase64: validatedSignature.exactSignatureBase64,
            nowMilliseconds: recommendedCreationTimeMs(safetyMarginMs: 0)
        )
        return try ToriiDetachedAssetTransferSubmissionEvidence(
            networkId: draft.networkId,
            chainId: draft.intent.chainId,
            submittedRequest: submittedRequest,
            signedTransaction: finalized.signedTransaction,
            finalization: finalized.finalization
        )
    }

    /// Submit exact evidence that the caller had an opportunity to persist.
    /// Ambiguous delivery failures carry this same evidence for reconciliation.
    public func submitFinalizedDetachedAssetTransfer(
        _ evidence: ToriiDetachedAssetTransferSubmissionEvidence
    ) async throws -> ToriiAssetTransferResponse {
        try await submitFinalizedDetachedAssetTransfer(
            evidence,
            validationTimeMs: recommendedCreationTimeMs(safetyMarginMs: 0)
        )
    }

    private func submitFinalizedDetachedAssetTransfer(
        _ evidence: ToriiDetachedAssetTransferSubmissionEvidence,
        validationTimeMs: UInt64
    ) async throws -> ToriiAssetTransferResponse {
        try evidence.validateIntrinsicBindings()
        let currentRequest = try evidence.submittedRequest.revalidatedSignedSubmission(
            nowMilliseconds: validationTimeMs
        )
        guard currentRequest == evidence.submittedRequest else {
            throw ToriiClientError.invalidPayload(
                "detached asset-transfer evidence changed during submission validation."
            )
        }
        let request = try makeDetachedAssetTransferRequest(evidence.submittedRequest)
        try validateDetachedAssetTransferTransport(request)
        do {
            var response = try await sendDetachedAssetTransferRequest(request)
            do {
                try evidence.validateSubmittedResponse(response)
            } catch let validationError as ToriiClientError {
                throw ToriiDetachedAssetTransferSubmissionUncertainError(
                    evidence: evidence,
                    cause: validationError
                )
            }
            response.signedTransaction = Data(evidence.signedTransaction)
            response.finalization = evidence.finalization
            return response
        } catch let uncertain as ToriiDetachedAssetTransferSubmissionUncertainError {
            throw uncertain
        } catch {
            guard let cause = Self.uncertainDetachedAssetTransferPostCause(error) else {
                throw error
            }
            throw ToriiDetachedAssetTransferSubmissionUncertainError(
                evidence: evidence,
                cause: cause
            )
        }
    }

    /// Reconcile durable evidence without rebuilding or resubmitting a payment.
    public func reconcileDetachedAssetTransferSubmission(
        _ evidence: ToriiDetachedAssetTransferSubmissionEvidence,
        pollOptions: PipelineStatusPollOptions = .default
    ) async throws -> ToriiPipelineTransactionStatus {
        try evidence.validateIntrinsicBindings()
        return try await reconcileValidatedDetachedAssetTransferEvidence(
            evidence,
            pollOptions: pollOptions
        )
    }

    /// Recover a persisted transfer without rebuilding or resigning it.
    ///
    /// Recovery first checks the exact transaction hash. It replays the same
    /// signed request only when the hash is absent and Torii's authoritative
    /// clock says the request is still within every admission window. A replay
    /// conflict or ambiguous response is reconciled by hash and never causes a
    /// replacement payment.
    public func recoverDetachedAssetTransferSubmission(
        _ evidence: ToriiDetachedAssetTransferSubmissionEvidence,
        pollOptions: PipelineStatusPollOptions = .default
    ) async throws -> ToriiPipelineTransactionStatus {
        try evidence.validateIntrinsicBindings()
        if let status = try await getTransactionStatus(hashHex: evidence.transactionHashHex) {
            return try await resolveDetachedAssetTransferRecoveryStatus(
                status,
                evidence: evidence,
                pollOptions: pollOptions
            )
        }

        let authoritativeNowMs = try await getTimeNow().now
        if evidence.expiresAtMs <= authoritativeNowMs {
            throw ToriiDetachedAssetTransferRecoveryExpiredError(evidence: evidence)
        }

        do {
            _ = try evidence.submittedRequest.revalidatedSignedSubmission(
                nowMilliseconds: authoritativeNowMs
            )
        } catch {
            // The exact request may have been admitted elsewhere and can still
            // finalize until its TTL elapses. Poll only; never replace or alter it.
            return try await reconcileValidatedDetachedAssetTransferEvidence(
                evidence,
                pollOptions: pollOptions
            )
        }

        do {
            _ = try await submitFinalizedDetachedAssetTransfer(
                evidence,
                validationTimeMs: authoritativeNowMs
            )
        } catch is ToriiDetachedAssetTransferSubmissionUncertainError {
            return try await reconcileValidatedDetachedAssetTransferEvidence(
                evidence,
                pollOptions: pollOptions
            )
        } catch {
            let racedStatus: ToriiPipelineTransactionStatus?
            do {
                racedStatus = try await getTransactionStatus(hashHex: evidence.transactionHashHex)
            } catch let statusError as ToriiClientError {
                throw ToriiDetachedAssetTransferSubmissionUncertainError(
                    evidence: evidence,
                    cause: statusError
                )
            } catch {
                throw ToriiDetachedAssetTransferSubmissionUncertainError(
                    evidence: evidence,
                    cause: .transport(error)
                )
            }
            if let racedStatus {
                return try await resolveDetachedAssetTransferRecoveryStatus(
                    racedStatus,
                    evidence: evidence,
                    pollOptions: pollOptions
                )
            }
            let cause: ToriiClientError
            if let clientError = error as? ToriiClientError {
                cause = clientError
            } else {
                cause = .transport(error)
            }
            // A durable request could already be in flight on another Torii
            // ingress even when this replay receives a definite rejection and
            // the immediate global status lookup is still empty. Preserve the
            // exact evidence until authoritative TTL expiry rather than letting
            // callers mistake this race for permission to create a replacement.
            throw ToriiDetachedAssetTransferSubmissionUncertainError(
                evidence: evidence,
                cause: cause
            )
        }
        return try await reconcileValidatedDetachedAssetTransferEvidence(
            evidence,
            pollOptions: pollOptions
        )
    }

    private func resolveDetachedAssetTransferRecoveryStatus(
        _ status: ToriiPipelineTransactionStatus,
        evidence: ToriiDetachedAssetTransferSubmissionEvidence,
        pollOptions: PipelineStatusPollOptions
    ) async throws -> ToriiPipelineTransactionStatus {
        switch status.state {
        case .applied:
            try ToriiAssetTransferDraft.validateAuthoritativeFinality(
                status,
                expectedTransactionHashHex: evidence.transactionHashHex
            )
            return status
        case .rejected, .expired:
            throw PipelineStatusError.failure(
                hash: evidence.transactionHashHex,
                status: status.status.kind,
                payload: status
            )
        case .queued, .approved, .committed:
            return try await reconcileValidatedDetachedAssetTransferEvidence(
                evidence,
                pollOptions: pollOptions
            )
        case .other(let kind):
            throw ToriiClientError.invalidPayload(
                "pipeline status has unsupported kind \(kind)."
            )
        }
    }

    private func reconcileValidatedDetachedAssetTransferEvidence(
        _ evidence: ToriiDetachedAssetTransferSubmissionEvidence,
        pollOptions: PipelineStatusPollOptions
    ) async throws -> ToriiPipelineTransactionStatus {
        let status = try await waitForTransactionStatus(
            hashHex: evidence.transactionHashHex,
            pollOptions: pollOptions
        )
        try ToriiAssetTransferDraft.validateAuthoritativeFinality(
            status,
            expectedTransactionHashHex: evidence.transactionHashHex
        )
        return status
    }

    public func waitForDetachedAssetTransferFinality(
        _ draft: ToriiAssetTransferDraft,
        submittedResponse: ToriiAssetTransferResponse,
        pollOptions: PipelineStatusPollOptions = .default
    ) async throws -> ToriiPipelineTransactionStatus {
        guard let finalization = submittedResponse.finalization,
              submittedResponse.signedTransaction?.isEmpty == false else {
            throw ToriiClientError.invalidPayload(
                "asset-transfer response was not produced by native detached finalization."
            )
        }
        try draft.validateSubmittedResponse(
            submittedResponse,
            finalization: finalization
        )
        guard let transactionHashHex = submittedResponse.transactionHashHex else {
            throw ToriiClientError.invalidPayload(
                "submitted detached asset transfer is missing its final transaction hash."
            )
        }
        let status = try await waitForTransactionStatus(
            hashHex: transactionHashHex,
            pollOptions: pollOptions
        )
        try ToriiAssetTransferDraft.validateAuthoritativeFinality(
            status,
            expectedTransactionHashHex: transactionHashHex
        )
        return status
    }

    private func postDetachedAssetTransfer(
        _ requestBody: ToriiAssetTransferRequest
    ) async throws -> ToriiAssetTransferResponse {
        let request = try makeDetachedAssetTransferRequest(requestBody)
        return try await sendDetachedAssetTransferRequest(request)
    }

    private func makeDetachedAssetTransferRequest(
        _ requestBody: ToriiAssetTransferRequest
    ) throws -> URLRequest {
        try makeRequest(
            path: "/v1/assets/transfer",
            method: .post,
            queryItems: nil,
            body: try JSONEncoder().encode(requestBody),
            headers: [
                "Content-Type": "application/json",
                "Accept": "application/json",
            ]
        )
    }

    private func validateDetachedAssetTransferTransport(_ request: URLRequest) throws {
        if let url = request.url,
           let violation = IrohaTransportSecurity.httpViolation(
               context: "ToriiClient",
               baseURL: baseURL,
               targetURL: url,
               headers: request.allHTTPHeaderFields ?? [:],
               body: request.httpBody
           ) {
            throw ToriiClientError.invalidPayload(violation)
        }
    }

    private func sendDetachedAssetTransferRequest(
        _ request: URLRequest
    ) async throws -> ToriiAssetTransferResponse {
        let (data, response) = try await sendBoundedResponse(
            request,
            context: "asset transfer",
            maximumBytes: Self.assetTransferResponseMaximumBytes
        )
        try ensureStatus(response, equals: 200, responseBody: data)
        try ensureResponseMediaType(response, equals: "application/json")
        try rejectDuplicateJSONKeys(data, context: "asset transfer response")
        return try decodeJSON(ToriiAssetTransferResponse.self, from: data)
    }

    static func uncertainDetachedAssetTransferPostCause(
        _ error: Swift.Error
    ) -> ToriiClientError? {
        if error is CancellationError {
            return .transport(error)
        }
        guard let error = error as? ToriiClientError else { return nil }
        switch error {
        case .transport, .invalidResponse, .emptyBody, .decoding, .invalidPayload:
            return error
        case let .api(apiError)
            where apiError.status == 408 || apiError.status == 409 || apiError.status == 425
                || apiError.status == 429 || (500...599).contains(apiError.status):
            return error
        case .ramLfeEncryptionUnavailable, .invalidURL, .api, .invalidQuery, .stream,
             .dataModelMismatch, .transactionSchemaMismatch:
            return nil
        }
    }

    private func rejectDuplicateJSONKeys(
        _ data: Data,
        context: String,
        requireAllNumbersInteger: Bool = false
    ) throws {
        guard !data.isEmpty else {
            throw ToriiClientError.emptyBody
        }
        do {
            try StrictJSONDuplicateKeyRejector.rejectDuplicateObjectKeys(
                in: data,
                requireAllNumbersInteger: requireAllNumbersInteger
            )
        } catch {
            let numericRequirement = requireAllNumbersInteger ? " and with integer numeric tokens" : ""
            throw ToriiClientError.invalidPayload(
                "\(context) must be valid UTF-8 JSON without duplicate object keys\(numericRequirement)."
            )
        }
    }

