        guard !noritoBody.isEmpty else {
            throw ToriiClientError.invalidPayload("noritoBody must be a non-empty MultisigProposeDtoV1 frame.")
        }
        let request = try makeRequest(path: "/v1/multisig/propose",
                                      method: .post,
                                      queryItems: nil,
                                      body: noritoBody,
