    /// Quote one exact unsigned transaction payload using canonical account authentication.
    public func quoteFees(
        unsignedPayload: [String: ToriiJSONValue],
        canonicalAuth: ToriiCanonicalRequestAuth
    ) async throws -> FeeQuoteResponse {
        for retiredIdentity in ["chain", "chainId", "chain_id"]
            where unsignedPayload[retiredIdentity] != nil {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload.\(retiredIdentity) is retired; use TransactionDomain::Network."
            )
        }
        let allowedFields: Set<String> = [
            "domain", "authority", "creation_time_ms", "instructions",
            "time_to_live_ms", "nonce", "fee_payment", "metadata", "attachments",
        ]
        let requiredFields: Set<String> = [
            "domain", "authority", "creation_time_ms", "instructions",
            "time_to_live_ms", "fee_payment", "metadata", "attachments",
        ]
        guard Set(unsignedPayload.keys).isSubset(of: allowedFields),
              requiredFields.isSubset(of: Set(unsignedPayload.keys)) else {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload must use the exact TransactionPayload field set."
            )
        }
        guard case let .object(domain)? = unsignedPayload["domain"],
              Set(domain.keys) == Set(["kind", "value"]),
              case let .string(kind)? = domain["kind"],
              kind == "network",
              case let .string(networkIdLiteral)? = domain["value"] else {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload.domain must be the exact TransactionDomain::Network object."
            )
        }
        do {
            _ = try NetworkId(literal: networkIdLiteral)
        } catch {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload.domain.value must be an exact canonical NetworkId literal."
            )
        }
        guard case let .number(creationTime)? = unsignedPayload["creation_time_ms"],
              creationTime.isFinite,
              creationTime >= 0,
              creationTime.rounded(.towardZero) == creationTime,
              case .object? = unsignedPayload["instructions"],
              case let .object(metadata)? = unsignedPayload["metadata"] else {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload contains a malformed canonical TransactionPayload field."
            )
        }
        guard case let .string(authority)? = unsignedPayload["authority"],
              (try? exactCanonicalToriiAccountAddress(authority)) != nil else {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload.authority must be an exact canonical I105 account id."
            )
        }
        if (try? exactCanonicalToriiAccountAddress(canonicalAuth.accountId)) != nil {
            guard (try? toriiAccountIdsHaveSameIdentity(
                authority,
                canonicalAuth.accountId
            )) == true else {
                throw ToriiClientError.invalidPayload(
                    "canonicalAuth.accountId must identify unsignedPayload.authority."
                )
            }
        } else {
            guard canonicalRequestAccountHeaderValue(canonicalAuth.accountId)
                    == canonicalAuth.accountId else {
                throw ToriiClientError.invalidPayload(
                    "canonicalAuth.accountId must be an exact canonical I105 account id or active ASCII alias."
                )
            }
        }
        guard let feeValue = unsignedPayload["fee_payment"] else {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload.fee_payment must be an exact FeePaymentIntent object."
            )
        }
        let draftIntent = try feeValue.decode(as: FeePaymentIntent.self)
        guard case let .number(timeToLiveMs)? = unsignedPayload["time_to_live_ms"],
              timeToLiveMs.isFinite,
              timeToLiveMs > 0,
              timeToLiveMs.rounded(.towardZero) == timeToLiveMs else {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload.time_to_live_ms must be a positive integer."
            )
        }
        for optionalInteger in ["nonce"] {
            guard let value = unsignedPayload[optionalInteger] else { continue }
            switch value {
            case .null:
                break
            case let .number(number)
                where number.isFinite && number > 0 && number.rounded(.towardZero) == number:
                break
            default:
                throw ToriiClientError.invalidPayload(
                    "unsignedPayload.\(optionalInteger) must be a positive integer when present."
                )
            }
        }
        if let attachments = unsignedPayload["attachments"] {
            if case .null = attachments {
                // An explicit JSON null is the canonical `Option::None` value.
            } else if case let .string(encoded) = attachments,
                      let decoded = Data(base64Encoded: encoded),
                      !decoded.isEmpty,
                      decoded.base64EncodedString() == encoded {
                // `ProofAttachmentList` uses canonical Norito bytes in padded base64 JSON.
            } else {
                throw ToriiClientError.invalidPayload(
                    "unsignedPayload.attachments must be canonical base64 when present."
                )
            }
        }
        if metadata.keys.contains(where: { ["fee_sponsor", "gas_limit", "gas_asset_id"].contains($0) }) {
            throw ToriiClientError.invalidPayload(
                "unsignedPayload.metadata contains a retired fee field."
            )
        }
        let body = try ToriiJSONValue.object([
            "payload": .object(unsignedPayload),
        ]).encodedData()
        let request = try makeVpnRequest(
            path: "/v1/fees/quote",
            method: .post,
            body: body,
            canonicalAuth: canonicalAuth
        )
        let (data, response) = try await sendBoundedResponse(
            request,
            context: "fee quote",
            maximumBytes: Self.feeQuoteResponseMaximumBytes
        )
        try ensureStatus(response, equals: 200, responseBody: data)
        try ensureResponseMediaType(response, equals: "application/json")
        try rejectDuplicateJSONKeys(
            data,
            context: "fee quote response"
        )
        let quote = try decodeJSON(FeeQuoteResponse.self, from: data)
        _ = try quote.applying(to: draftIntent, authority: authority)
        return quote
    }

    /// Quote and replace only `fee_payment`, rejecting payer, revision, or gas substitution.
    public func quoteAndApplyFees(
        unsignedPayload: [String: ToriiJSONValue],
        canonicalAuth: ToriiCanonicalRequestAuth
    ) async throws -> (payload: [String: ToriiJSONValue], quote: FeeQuoteResponse) {
        guard let draftValue = unsignedPayload["fee_payment"] else {
            throw ToriiClientError.invalidPayload("unsignedPayload.fee_payment is required.")
        }
        let draftIntent = try draftValue.decode(as: FeePaymentIntent.self)
        guard case let .string(authority)? = unsignedPayload["authority"] else {
            throw ToriiClientError.invalidPayload("unsignedPayload.authority is required.")
        }
        let quote = try await quoteFees(
            unsignedPayload: unsignedPayload,
            canonicalAuth: canonicalAuth
        )
        let quotedIntent = try quote.applying(
            to: draftIntent,
            authority: authority
        )
        let quotedJSON = try JSONDecoder().decode(
            ToriiJSONValue.self,
            from: quotedIntent.canonicalJSONData()
        )
        var quotedPayload = unsignedPayload
        quotedPayload["fee_payment"] = quotedJSON
        return (quotedPayload, quote)
    }

    /// Fetch one exact on-chain sponsor program by canonical `sponsor/program` id.
    public func getFeeSponsorProgram(
        id: FeeSponsorProgramId,
        canonicalAuth: ToriiCanonicalRequestAuth
    ) async throws -> FeeSponsorProgram {
        let body = try ToriiJSONValue.object([
            "program_id": .string(id.description),
        ]).encodedData()
        let request = try makeVpnRequest(
            path: "/v1/fee-sponsor-programs/by-id",
            method: .post,
            body: body,
            canonicalAuth: canonicalAuth
        )
        let (data, response) = try await sendBoundedResponse(
            request,
            context: "fee sponsor program",
            maximumBytes: Self.feeSponsorProgramResponseMaximumBytes
        )
        try ensureStatus(response, equals: 200, responseBody: data)
        try ensureResponseMediaType(response, equals: "application/json")
        try rejectDuplicateJSONKeys(
            data,
            context: "fee sponsor program response"
        )
        let program = try decodeJSON(FeeSponsorProgram.self, from: data)
        guard program.id == id else {
            throw ToriiClientError.invalidPayload(
                "fee sponsor program response id does not match the requested program"
            )
        }
        return program
    }

    public func fetchContractCodeBytes(artifactId: ContractArtifactId, canonicalAuth: ToriiCanonicalRequestAuth) async throws -> ToriiContractCodeBytes {
        guard let localSigningContext else {
            throw ToriiClientError.invalidPayload("Artifact reads require a locally selected network identity.")
        }
        let request = try makeCanonicalAccountRequest(path: "/v1/contracts/artifacts/\(artifactId.dataspaceId)/\(artifactId.codeHashHex)/bytes", canonicalAuth: canonicalAuth)
        let (data, response) = try await sendBoundedResponse(request, context: "contract bytes", maximumBytes: 24 * 1_024 * 1_024)
        try ensureStatus(response, equals: 200, responseBody: data)
        try ensureResponseMediaType(response, equals: "application/json")
        try rejectDuplicateJSONKeys(data, context: "contract bytes response")
        let record = try decodeJSON(ToriiContractCodeBytes.self, from: data)
        guard record.networkId == localSigningContext.networkId, record.artifactId == artifactId else {
            throw ToriiClientError.invalidPayload("Contract bytes response differs from the selected network or exact artifact.")
        }
        return record
    }

