    /// Fetch Torii's authoritative committed Exact12 manifest as the exact
    /// canonical Norito bytes selected by the server.
    ///
    /// This authority-bearing route is deliberately unavailable over HTTP,
    /// JSON, redirects, mock catalogs, or without the loaded exact ABI25
    /// artifact. The returned model retains the response bytes and binds every
    /// compiled row to that artifact's natively validated local catalog and the
    /// expected network from `localSigningContext`.
    public func getPrivacyExact12CapabilityManifestV1(
        canonicalAuth: ToriiCanonicalRequestAuth
    ) async throws
        -> PrivacyExact12CapabilityManifestV1
    {
        guard baseURL.scheme?.lowercased() == "https" else {
            throw ToriiClientError.invalidPayload(
                "privacy capability authority requires an HTTPS Torii base URL"
            )
        }
        guard let localSigningContext else {
            throw ToriiClientError.invalidPayload(
                "privacy capability authority requires the expected local signing network"
            )
        }
        // Fail before network I/O when the bridge is absent, stale, or missing
        // any of the exact six privacy ABI25 symbols.
        _ = try PrivacyNativeBridge.compiledProfileCatalogV1()
        let request = try makePrivacyExact12CapabilityRequestV1(canonicalAuth: canonicalAuth)
        let (data, response) = try await sendBoundedResponse(
            request,
            context: "privacy Exact12 capabilities",
            maximumBytes: PrivacyExact12CapabilityManifestV1.maximumArchiveBytes
        )
        try ensureStatus(response, equals: 200, responseBody: data)
        guard response.url?.absoluteString == request.url?.absoluteString else {
            throw ToriiClientError.invalidPayload(
                "privacy Exact12 capability response did not originate from the exact signed URL"
            )
        }
        let contentType = response.value(forHTTPHeaderField: "Content-Type")?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard contentType == "application/x-norito" else {
            throw ToriiClientError.invalidPayload(
                "privacy Exact12 capabilities must use exact application/x-norito without parameters"
            )
        }
        let contentEncoding = response.value(forHTTPHeaderField: "Content-Encoding")?
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        guard contentEncoding == nil || contentEncoding == "identity" else {
            throw ToriiClientError.invalidPayload(
                "privacy Exact12 capabilities must preserve the identity representation"
            )
        }
        guard let declaredLength = try Self.validatedContentLength(
            response,
            context: "privacy Exact12 capabilities",
            maximumBytes: PrivacyExact12CapabilityManifestV1.maximumArchiveBytes
        ), declaredLength > 0, declaredLength == data.count else {
            throw ToriiClientError.invalidPayload(
                "privacy Exact12 capabilities require an exact positive Content-Length"
            )
        }
        guard !data.isEmpty else { throw ToriiClientError.emptyBody }
        return try PrivacyExact12CapabilityManifestV1.fromAuthenticatedToriiResponseV1(
            data, expectedNetworkId: localSigningContext.networkId
        )
    }

    /// Build the exact signed request without fetching or granting admission.
    /// Kept separate so transport policy is testable without a native artifact.
    func makePrivacyExact12CapabilityRequestV1(
        canonicalAuth: ToriiCanonicalRequestAuth
    ) throws -> URLRequest {
        var request = try makeRequest(
            path: "/v1/privacy/capabilities",
            method: .get,
            headers: [
                "Accept": "application/x-norito",
                "Cache-Control": "no-cache, no-store",
            ]
        )
        request.cachePolicy = .reloadIgnoringLocalCacheData
        try applyCanonicalAuth(canonicalAuth, to: &request, body: nil)
        return request
    }

    private func sendBoundedResponse(
        _ request: URLRequest,
        context: String,
        maximumBytes: Int
    ) async throws -> (Data, HTTPURLResponse) {
        precondition(maximumBytes > 0)
        if let url = request.url,
           let violation = IrohaTransportSecurity.httpViolation(
               context: "ToriiClient",
               baseURL: baseURL,
               targetURL: url,
               headers: request.allHTTPHeaderFields ?? [:],
               body: request.httpBody
           )
        {
            throw ToriiClientError.invalidPayload(violation)
        }

        do {
            let observedAtLocalMs = currentEpochMs()
            let (bytes, response) = try await session.bytes(
                for: request,
                delegate: ToriiRejectRedirectTaskDelegate.shared
            )
            guard let http = response as? HTTPURLResponse else {
                bytes.task.cancel()
                throw ToriiClientError.invalidResponse
            }
            recordObservedServerClock(from: http, observedAtLocalMs: observedAtLocalMs)

            let declaredLength: Int?
            do {
                declaredLength = try Self.validatedContentLength(
                    http,
                    context: context,
                    maximumBytes: maximumBytes
                )
            } catch {
                bytes.task.cancel()
                throw error
            }

            var data = Data()
            data.reserveCapacity(min(declaredLength ?? 64 * 1024, 64 * 1024))
            do {
                for try await byte in bytes {
                    guard data.count < maximumBytes else {
                        bytes.task.cancel()
                        throw ToriiClientError.invalidPayload(
                            "\(context) response exceeded the \(maximumBytes)-byte limit"
                        )
                    }
                    data.append(byte)
                }
            } catch {
                bytes.task.cancel()
                throw error
            }

            let contentEncoding = http.value(forHTTPHeaderField: "Content-Encoding")?
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
            let hasIdentityRepresentation = contentEncoding == nil
                || contentEncoding?.isEmpty == true
                || contentEncoding == "identity"
            if hasIdentityRepresentation, let declaredLength, data.count != declaredLength {
                bytes.task.cancel()
                throw ToriiClientError.invalidPayload(
                    "\(context) response length did not match its Content-Length header"
                )
            }
            return (data, http)
        } catch let error as ToriiClientError {
            throw error
        } catch {
            if error is CancellationError || Self.isCancelledTransportError(error) {
                throw CancellationError()
            }
            throw ToriiClientError.transport(error)
        }
    }

    private static func validatedContentLength(
        _ response: HTTPURLResponse,
        context: String,
        maximumBytes: Int
    ) throws -> Int? {
        guard let raw = response.value(forHTTPHeaderField: "Content-Length") else {
            return nil
        }
        let isCanonical = !raw.isEmpty
            && raw.utf8.allSatisfy { (48...57).contains($0) }
            && (raw == "0" || !raw.hasPrefix("0"))
        guard isCanonical, let value = UInt64(raw), value <= UInt64(Int.max) else {
            throw ToriiClientError.invalidPayload(
                "\(context) response has a malformed or noncanonical Content-Length header"
            )
        }
        guard value <= UInt64(maximumBytes) else {
            throw ToriiClientError.invalidPayload(
                "\(context) response declares more than the \(maximumBytes)-byte limit"
            )
        }
        return Int(value)
    }

    private func exactJSONResponse(
        _ request: URLRequest,
        context: String,
        maximumBytes: Int
    ) async throws -> Data {
        let (data, response) = try await sendBoundedResponse(
            request,
            context: context,
            maximumBytes: maximumBytes
        )
        try ensureStatus(response, equals: 200, responseBody: data)
        try ensureResponseMediaType(response, equals: "application/json")
        guard !data.isEmpty else { throw ToriiClientError.emptyBody }
        return data
    }

    private func submitNoritoTransactionPayload(path: String,
                                                data: Data,
                                                idempotencyKey: String?,
                                                exactSuccessStatus: Int? = nil) async throws -> ToriiSubmitTransactionResponse? {
        try await submitTransactionPayload(path: path,
                                           data: data,
                                           contentType: "application/x-norito",
                                           idempotencyKey: idempotencyKey,
                                           exactSuccessStatus: exactSuccessStatus)
    }

    private func submitTransactionPayload(path: String,
                                          data: Data,
                                          contentType: String,
                                          idempotencyKey: String?,
                                          exactSuccessStatus: Int? = nil) async throws -> ToriiSubmitTransactionResponse? {
        try await ensureDataModelValidation()
        var headers: [String: String] = [
            "Content-Type": contentType,
            "Accept": wireFormatPreference.acceptHeader
        ]
        if let key = idempotencyKey, !key.isEmpty {
            headers["Idempotency-Key"] = key
        }
        let request = try makeRequest(path: path,
                                      method: .post,
                                      body: data,
                                      headers: headers)
        let (responseData, response) = try await send(request, rejectRedirects: true)
        if let exactSuccessStatus {
            try ensureStatus(response, equals: exactSuccessStatus, responseBody: responseData)
        } else {
            try ensureStatus(response, in: 200..<300, responseBody: responseData)
        }
        guard !responseData.isEmpty else { return nil }
        let contentType = response.value(forHTTPHeaderField: "Content-Type")?.lowercased() ?? ""
        if contentType.contains("application/x-norito") {
            guard let jsonString = NoritoNativeBridge.shared.decodeTransactionReceipt(responseData),
                  let jsonData = jsonString.data(using: .utf8) else {
                throw ToriiClientError.invalidPayload("failed to decode Norito receipt")
            }
            do {
                return try decodeJSON(ToriiSubmitTransactionResponse.self, from: jsonData)
            } catch let error as ToriiClientError {
                if case let .decoding(underlying) = error {
                    throw ToriiClientError.invalidPayload(
                        "transaction receipt decode failed; \(responseBodyDescriptor(jsonData)); reason=\(ToriiClientError.describeDecodingError(underlying))"
                    )
                }
                throw error
            }
        }
        do {
            return try decodeJSON(ToriiSubmitTransactionResponse.self, from: responseData)
        } catch let error as ToriiClientError {
            if case let .decoding(underlying) = error {
                throw ToriiClientError.invalidPayload(
                    "transaction receipt decode failed; \(responseBodyDescriptor(responseData)); reason=\(ToriiClientError.describeDecodingError(underlying))"
                )
            }
            throw error
        }
    }

    public func getTransactionStatus(hashHex: String) async throws -> ToriiPipelineTransactionStatus? {
        let normalizedHash = try ToriiRequestValidation.exactTransactionHashHex(
            hashHex,
            field: "hashHex"
        )
        let request = try makeRequest(
            path: "/v1/pipeline/transactions/status",
            queryItems: [
                URLQueryItem(name: "hash", value: normalizedHash),
                URLQueryItem(name: "scope", value: "global"),
            ],
            headers: ["Accept": "application/json"]
        )
        let (data, response) = try await send(request)
        if response.statusCode == 404 { return nil }
        try ensureStatus(response, equals: 200, responseBody: data)
        guard !data.isEmpty else { throw ToriiClientError.emptyBody }
        try rejectDuplicateJSONKeys(data, context: "pipeline transaction status response")
        let status = try decodeJSON(ToriiPipelineTransactionStatus.self, from: data)
        try validatePipelineStatusObservation(status, expectedHash: normalizedHash)
        return status
    }

    /// Pipeline status events of one transaction, filtered on Torii with
    /// `tx_hash = "<hash>"`. Every event is checked against the requested hash.
    @available(iOS 15.0, macOS 12.0, *)
    public func streamTransactionStatusEvents(
        hashHex: String
    ) -> AsyncThrowingStream<ToriiEventMessage<ToriiPipelineTransactionEvent>, Error> {
        let normalizedHash = Result {
            try ToriiRequestValidation.exactTransactionHashHex(hashHex, field: "hashHex")
        }
        return serverSentEventStream(
            request: {
                try self.makeEventStreamRequest(
                    filter: .expression(ToriiEventFields.txHash == (try normalizedHash.get()))
                )
            },
            parse: { lines in
                guard let message = try self.parseEventMessage(from: lines, context: "transaction-status SSE"),
                      case let .transaction(event) = message.event else {
                    return nil
                }
                guard event.hash == (try normalizedHash.get()) else {
                    throw ToriiClientError.invalidPayload(
                        "pipeline status event hash does not match the requested transaction hash."
                    )
                }
                return message.replacingEvent(event)
            }
        )
    }

