    public func getStatusSnapshot() async throws -> ToriiStatusSnapshot {
        let sequence = statusStateQueue.sync { statusState.reserveSequence() }
        let request = try makeRequest(path: "/status",
                                      headers: ["Accept": "application/json"])
        let data = try await data(for: request)
        let payload = try decodeJSON(ToriiStatusPayload.self, from: data)
        let metrics = statusStateQueue.sync { statusState.record(payload, sequence: sequence) }
        return ToriiStatusSnapshot(timestamp: Date(), status: payload, metrics: metrics)
    }

    // MARK: - Async helpers

    private enum HTTPMethod: String {
        case get = "GET"
        case post = "POST"
        case put = "PUT"
        case delete = "DELETE"
    }

    private func resolveDaManifestBundle(storageTicketHex: String?,
                                         manifestBundle: ToriiDaManifestBundle?) async throws -> ToriiDaManifestBundle {
        if let manifestBundle {
            return manifestBundle
        }
        guard let ticket = storageTicketHex else {
            throw ToriiClientError.invalidPayload("storageTicketHex is required when manifestBundle is not provided")
        }
        return try await getDaManifestBundle(storageTicketHex: ticket)
    }

    private static func resolveChunkerHandle(preferred: String?,
                                             manifest: ToriiDaManifestBundle) throws -> String {
        if let provided = preferred?.trimmingCharacters(in: .whitespacesAndNewlines),
           !provided.isEmpty {
            return provided
        }
        if let inferred = manifest.inferChunkerHandle() {
            return inferred
        }
        throw ToriiClientError.invalidPayload("chunkerHandle is required when the manifest omits chunking metadata")
    }

    private func normalizeDaCommitmentListRequest(_ request: ToriiDaCommitmentListRequest) throws -> ToriiDaCommitmentListRequest {
        if let limit = request.limit, limit == 0 {
            throw ToriiClientError.invalidPayload("DA commitment-list limit must be nonzero")
        }
        return request
    }

    private func normalizeDaCommitmentProofRequest(_ request: ToriiDaCommitmentProofRequest) throws -> ToriiDaCommitmentProofRequest {
        let normalizedManifest = try request.manifestHash.map {
            try ToriiClient.normalizeHex32($0, field: "manifest_hash")
        }
        return ToriiDaCommitmentProofRequest(
            manifestHash: normalizedManifest,
            laneId: request.laneId,
            epoch: request.epoch,
            sequence: request.sequence
        )
    }

    private func normalizeDaPinIntentListRequest(_ request: ToriiDaPinIntentListRequest) throws -> ToriiDaPinIntentListRequest {
        if let limit = request.limit, limit == 0 {
            throw ToriiClientError.invalidPayload("DA pin-intent-list limit must be nonzero")
        }
        return request
    }

    private func normalizeDaPinIntentQueryRequest(_ request: ToriiDaPinIntentQueryRequest) throws -> ToriiDaPinIntentQueryRequest {
        let normalizedManifest = try request.manifestHash.map {
            try ToriiClient.normalizeHex32($0, field: "manifest_hash")
        }
        let normalizedTicket = try request.storageTicket.map {
            try ToriiClient.normalizeHex32($0, field: "storage_ticket")
        }
        let normalizedAlias = try request.alias.map { alias in
            try requireDaPinIntentAlias(alias, field: "DA pin-intent query alias")
        }
        return ToriiDaPinIntentQueryRequest(
            manifestHash: normalizedManifest,
            storageTicket: normalizedTicket,
            alias: normalizedAlias,
            laneId: request.laneId,
            epoch: request.epoch,
            sequence: request.sequence
        )
    }

    private static func normalizeStorageTicketHex(_ ticket: String) throws -> String {
        var body = ticket.trimmingCharacters(in: .whitespacesAndNewlines)
        if body.hasPrefix("0x") || body.hasPrefix("0X") {
            body = String(body.dropFirst(2))
        }
        guard body.count == 64, Data(hexString: body) != nil else {
            throw ToriiClientError.invalidPayload("storageTicketHex must be a 32-byte hex string")
        }
        return body.lowercased()
    }

    private static func normalizeHex32(_ hex: String, field: String) throws -> String {
        var body = hex.trimmingCharacters(in: .whitespacesAndNewlines)
        if body.hasPrefix("0x") || body.hasPrefix("0X") {
            body = String(body.dropFirst(2))
        }
        guard body.count == 64, Data(hexString: body) != nil else {
            throw ToriiClientError.invalidPayload("\(field) must be a 32-byte hex string")
        }
        return body.lowercased()
    }

    private func buildIdentifierResolveRequest(policyId: String,
                                               encryptedInputHex: String,
                                               outputOpening: ToriiRamLfeOutputOpening) throws -> ToriiIdentifierLookupRequest {
        let normalizedPolicyId = try ToriiRequestValidation.normalizedNonEmpty(policyId, field: "policyId")
        let normalizedEncryptedInput = try ToriiRequestValidation.normalizedEvenLengthHex(
            encryptedInputHex,
            field: "encryptedInputHex"
        )
        return ToriiIdentifierLookupRequest(
            policyId: normalizedPolicyId,
            encryptedInputHex: normalizedEncryptedInput,
            outputOpening: outputOpening
        )
    }

    private func buildRamLfeExecuteRequest(encryptedInputHex: String) throws -> ToriiRamLfeExecuteRequest {
        let normalizedEncryptedInput = try ToriiRequestValidation.normalizedEvenLengthHex(
            encryptedInputHex,
            field: "encryptedInputHex"
        )
        return ToriiRamLfeExecuteRequest(encryptedInputHex: normalizedEncryptedInput)
    }

    private func makeRequest(path: String,
                             method: HTTPMethod = .get,
                             queryItems: [URLQueryItem]? = nil,
                             body: Data? = nil,
                             headers: [String: String] = [:]) throws -> URLRequest {
        // Remove leading slash to make path relative (required for URL(string:relativeTo:))
        let relativePath = path.hasPrefix("/") ? String(path.dropFirst()) : path

        // URL(string:relativeTo:) preserves percent-encoding without double-encoding.
        // baseURL is normalized to directory URL in init, so relative resolution works correctly.
        guard let url = URL(string: relativePath, relativeTo: baseURL),
              var urlComponents = URLComponents(url: url, resolvingAgainstBaseURL: true) else {
            throw ToriiClientError.invalidURL(path)
        }

        if let items = queryItems, !items.isEmpty {
            urlComponents.queryItems = items
            // `URLQueryItem` leaves `+` literal, but Torii form-decodes `+` as a
            // space; escape it so values such as filter literals arrive intact.
            urlComponents.percentEncodedQuery = urlComponents.percentEncodedQuery?
                .replacingOccurrences(of: "+", with: "%2B")
        }
        guard let finalURL = urlComponents.url else {
            throw ToriiClientError.invalidURL(path)
        }

        var request = URLRequest(url: finalURL)
        request.httpMethod = method.rawValue
        request.httpBody = body
        var finalHeaders = defaultHeaders
        headers.forEach { key, value in
            ToriiClientAuthentication.setHeader(&finalHeaders, key: key, value: value)
        }
        finalHeaders.forEach { key, value in
            request.setValue(value, forHTTPHeaderField: key)
        }
        return request
    }

    /// Build a request for a dataspace-visible route.
    ///
    /// These routes remain anonymously readable for public dataspaces. When a
    /// default canonical account signer is configured, signing the exact GET
    /// lets Torii add every restricted dataspace visible to that principal.
    private func makeDataspaceVisibleRequest(
        path: String,
        queryItems: [URLQueryItem]? = nil,
        headers: [String: String] = [:]
    ) throws -> URLRequest {
        guard let canonicalRequestAuth else {
            return try makeRequest(
                path: path,
                queryItems: queryItems,
                headers: headers
            )
        }
        return try makeCanonicalAccountRequest(
            path: path,
            queryItems: queryItems,
            headers: headers,
            canonicalAuth: canonicalRequestAuth
        )
    }

    /// Build one fresh, empty-body, exact-network operator-authenticated GET.
    ///
    /// Dispatch remains the caller's responsibility so every invocation signs
    /// exactly once immediately before the one-shot request is sent.
    func makeOperatorGetRequest(
        path: String,
        queryItems: [URLQueryItem]? = nil,
        headers: [String: String] = [:]
    ) throws -> URLRequest {
        let managedHeaders = [
            "Authorization",
            "X-API-Token",
            "X-Iroha-Account",
            "X-Iroha-Signature",
            "X-Iroha-Timestamp-Ms",
            "X-Iroha-Nonce",
            "X-Iroha-Witness",
            "X-Iroha-Operator-Public-Key",
            "X-Iroha-Operator-Timestamp-Ms",
            "X-Iroha-Operator-Nonce",
            "X-Iroha-Operator-Signature",
        ]
        guard !(Array(defaultHeaders.keys) + Array(headers.keys)).contains(where: { candidate in
            managedHeaders.contains { $0.caseInsensitiveCompare(candidate) == .orderedSame }
        }) else {
            throw ToriiClientError.invalidPayload(
                "Operator requests reject token, account, witness, and precomputed operator authentication headers."
            )
        }
        guard let operatorSigningContext else {
            throw ToriiClientError.invalidPayload(
                "This Torii API requires an immutable ToriiOperatorSigningContext."
            )
        }

        var request = try makeRequest(
            path: path,
            method: .get,
            queryItems: queryItems,
            headers: headers
        )
        guard let url = request.url else {
            throw ToriiClientError.invalidURL(path)
        }
        let authHeaders = try operatorSigningContext.buildHeaders(
            method: HTTPMethod.get.rawValue,
            url: url,
            body: Data(),
            timestampMs: currentEpochMs()
        )
        for (key, value) in authHeaders {
            request.setValue(value, forHTTPHeaderField: key)
        }
        return request
    }

    private func makeVpnRequest(path: String,
                                method: HTTPMethod = .get,
                                body: Data? = nil,
                                canonicalAuth: ToriiCanonicalRequestAuth) throws -> URLRequest {
        var headers: [String: String] = ["Accept": "application/json"]
        if body != nil {
            headers["Content-Type"] = "application/json"
        }
        var request = try makeRequest(path: path,
                                      method: method,
                                      body: body,
                                      headers: headers)
        try applyCanonicalAuth(canonicalAuth, to: &request, body: body)
        return request
    }

    private func makeCanonicalAccountRequest(
        path: String,
        method: HTTPMethod = .get,
        queryItems: [URLQueryItem]? = nil,
        body: Data? = nil,
        headers: [String: String] = [:],
        canonicalAuth: ToriiCanonicalRequestAuth
    ) throws -> URLRequest {
        let managedHeaders = [
            ToriiCanonicalRequest.headerAccount,
            ToriiCanonicalRequest.headerSignature,
            ToriiCanonicalRequest.headerTimestampMs,
            ToriiCanonicalRequest.headerNonce
        ]
        guard !(Array(defaultHeaders.keys) + Array(headers.keys)).contains(where: { candidate in
            managedHeaders.contains { $0.caseInsensitiveCompare(candidate) == .orderedSame }
        }) else {
            throw ToriiClientError.invalidPayload(
                "Canonical signing headers must be generated locally and cannot be precomputed."
            )
        }
        let principal: (address: AccountAddress, chainDiscriminant: UInt16)
        do {
            principal = try exactCanonicalToriiAccountAddress(canonicalAuth.accountId)
        } catch {
            throw ToriiClientError.invalidPayload(
                "canonicalAuth.accountId must be an exact canonical I105 account id."
            )
        }
        guard try principal.address.toI105(networkPrefix: principal.chainDiscriminant)
                == canonicalAuth.accountId else {
            throw ToriiClientError.invalidPayload(
                "canonicalAuth.accountId must retain its exact network prefix."
            )
        }
        var request = try makeRequest(
            path: path,
            method: method,
            queryItems: queryItems,
            body: body,
            headers: headers
        )
        try applyCanonicalAuth(canonicalAuth, to: &request, body: body)
        return request
    }

    private func requireSecureVpnRequest(_ request: URLRequest) throws -> URLRequest {
        guard request.url?.scheme?.lowercased() == "https" else {
            throw ToriiClientError.invalidPayload(
                "Sora VPN Torii requests require an HTTPS base URL."
            )
        }
        return request
    }

    private func applyCanonicalAuth(_ auth: ToriiCanonicalRequestAuth,
                                    to request: inout URLRequest,
                                    body: Data?,
                                    expectedNetworkId: NetworkId? = nil) throws {
        guard let url = request.url else {
            throw ToriiClientError.invalidURL("")
        }
        guard let localSigningContext else {
            throw ToriiClientError.invalidPayload(
                "Canonical request authentication requires ToriiLocalSigningContext."
            )
        }
        if let expectedNetworkId,
           expectedNetworkId != localSigningContext.networkId {
            throw ToriiClientError.invalidPayload(
                "Canonical request network must equal ToriiLocalSigningContext.networkId."
            )
        }
        let headers = try ToriiCanonicalRequest.buildHeaders(
            method: request.httpMethod ?? "GET",
            url: url,
            body: body,
            accountId: auth.accountId,
            privateKey: auth.privateKey,
            networkId: localSigningContext.networkId,
            timestampMs: canonicalRequestFreshness?.timestampMs() ?? currentEpochMs(),
            nonce: canonicalRequestFreshness?.nonce() ?? ToriiCanonicalRequestFreshness.randomNonce()
        )
        for (key, value) in headers {
            request.setValue(value, forHTTPHeaderField: key)
        }
    }

    private func sendExactParliamentCastingProof(
        _ request: URLRequest,
        maximumBytes: Int
    ) async throws -> (Data, HTTPURLResponse) {
        precondition(maximumBytes > 0)
        if let url = request.url,
           let violation = IrohaTransportSecurity.httpViolation(
               context: "ToriiClient Parliament casting proof",
               baseURL: baseURL,
               targetURL: url,
               headers: request.allHTTPHeaderFields ?? [:],
               body: request.httpBody
           ) {
            throw ToriiClientError.invalidPayload(violation)
        }

        let bytes: URLSession.AsyncBytes
        let response: URLResponse
        do {
            (bytes, response) = try await session.bytes(
                for: request,
                delegate: ToriiRejectRedirectTaskDelegate.shared
            )
        } catch {
            if error is CancellationError || Self.isCancelledTransportError(error) {
                throw CancellationError()
            }
            throw ToriiClientError.transport(error)
        }
        guard let http = response as? HTTPURLResponse else {
            bytes.task.cancel()
            throw ToriiClientError.invalidResponse
        }
        recordObservedServerClock(from: http, observedAtLocalMs: currentEpochMs())

        if http.statusCode != 200 {
            var errorBody = Data()
            do {
                for try await byte in bytes {
                    guard errorBody.count < 64 * 1024 else {
                        bytes.task.cancel()
                        break
                    }
                    errorBody.append(byte)
                }
            } catch {
                bytes.task.cancel()
                if error is CancellationError { throw CancellationError() }
                throw ToriiClientError.transport(error)
            }
            throw apiError(http, responseBody: errorBody)
        }

        guard http.value(forHTTPHeaderField: "Content-Type") == "application/x-norito" else {
            bytes.task.cancel()
            throw ToriiClientError.invalidPayload(
                "Parliament timed-OVN casting proof response Content-Type must be exactly application/x-norito."
            )
        }
        let hasContentEncoding = http.allHeaderFields.keys.contains { key in
            guard let name = key as? String else { return false }
            return name.caseInsensitiveCompare("Content-Encoding") == .orderedSame
        }
        guard !hasContentEncoding else {
            bytes.task.cancel()
            throw ToriiClientError.invalidPayload(
                "Parliament timed-OVN casting proof response must use identity encoding."
            )
        }

        let declaredLength: Int?
        if let rawLength = http.value(forHTTPHeaderField: "Content-Length") {
            let canonical = !rawLength.isEmpty
                && rawLength.utf8.allSatisfy { (48...57).contains($0) }
                && (rawLength == "0" || !rawLength.hasPrefix("0"))
            guard canonical,
                  let value = Int(rawLength),
                  value <= maximumBytes else {
                bytes.task.cancel()
                throw ToriiClientError.invalidPayload(
                    "Parliament timed-OVN casting proof Content-Length is invalid or exceeds 8 MiB."
                )
            }
            declaredLength = value
        } else {
            declaredLength = nil
        }

        var data = Data()
        data.reserveCapacity(min(declaredLength ?? 64 * 1024, 64 * 1024))
        do {
            for try await byte in bytes {
                guard data.count < maximumBytes else {
                    bytes.task.cancel()
                    throw ToriiClientError.invalidPayload(
                        "Parliament timed-OVN casting proof response exceeds its 8 MiB bound."
                    )
                }
                data.append(byte)
            }
        } catch let error as ToriiClientError {
            bytes.task.cancel()
            throw error
        } catch {
            bytes.task.cancel()
            if error is CancellationError { throw CancellationError() }
            throw ToriiClientError.transport(error)
        }
        guard !data.isEmpty else {
            throw ToriiClientError.emptyBody
        }
        if let declaredLength, declaredLength != data.count {
            throw ToriiClientError.invalidPayload(
                "Parliament timed-OVN casting proof Content-Length does not match the body."
            )
        }
        return (data, http)
    }

    private func send(_ request: URLRequest,
                      rejectRedirects: Bool = true) async throws -> (Data, HTTPURLResponse) {
        if let url = request.url,
           let violation = IrohaTransportSecurity.httpViolation(context: "ToriiClient",
                                                                baseURL: baseURL,
                                                                targetURL: url,
                                                                headers: request.allHTTPHeaderFields ?? [:],
                                                                body: request.httpBody) {
            throw ToriiClientError.invalidPayload(violation)
        }
        do {
            let observedAtLocalMs = currentEpochMs()
            let delegate: URLSessionTaskDelegate? = rejectRedirects
                ? ToriiRejectRedirectTaskDelegate.shared
                : nil
            let (data, response) = try await session.data(for: request, delegate: delegate)
            guard let http = response as? HTTPURLResponse else {
                throw ToriiClientError.invalidResponse
            }
            recordObservedServerClock(from: http, observedAtLocalMs: observedAtLocalMs)
            return (data, http)
        } catch {
            if error is CancellationError || Self.isCancelledTransportError(error) {
                throw CancellationError()
            }
            throw ToriiClientError.transport(error)
        }
    }

    private static func validatedAccountOnboardingToken(_ token: String) throws -> String {
        let bytes = token.utf8
        guard (32...256).contains(bytes.count),
              bytes.allSatisfy({ (0x21...0x7E).contains($0) }) else {
            throw ToriiClientError.invalidPayload(
                "onboardingToken must contain 32...256 printable ASCII bytes without spaces or normalization."
            )
        }
        return token
    }

    private static func redacting(_ data: Data, sensitiveValue: String) -> Data {
        guard let text = String(data: data, encoding: .utf8),
              text.contains(sensitiveValue) else {
            return data
        }
        return Data(text.replacingOccurrences(of: sensitiveValue, with: "<redacted>").utf8)
    }

    private static func redactingJSON(_ data: Data, sensitiveValue: String) -> Data {
        let textRedacted = redacting(data, sensitiveValue: sensitiveValue)
        guard let object = try? JSONSerialization.jsonObject(with: textRedacted),
              JSONSerialization.isValidJSONObject(object),
              let encoded = try? JSONSerialization.data(
                  withJSONObject: redactingJSONValue(object, sensitiveValue: sensitiveValue)
              ) else {
            return Data("\"<invalid JSON response>\"".utf8)
        }
        return encoded
    }

    private static func redactingJSONValue(_ value: Any, sensitiveValue: String) -> Any {
        if let text = value as? String {
            return text.replacingOccurrences(of: sensitiveValue, with: "<redacted>")
        }
        if let values = value as? [Any] {
            return values.map { redactingJSONValue($0, sensitiveValue: sensitiveValue) }
        }
        if let values = value as? [String: Any] {
            var redacted: [String: Any] = [:]
            for (key, item) in values {
                let redactedKey = key.replacingOccurrences(
                    of: sensitiveValue,
                    with: "<redacted>"
                )
                redacted[redactedKey] = redactingJSONValue(item, sensitiveValue: sensitiveValue)
            }
            return redacted
        }
        return value
    }

    private static func isCancelledTransportError(_ error: Error) -> Bool {
        if let urlError = error as? URLError {
            return urlError.code == .cancelled
        }
        let nsError = error as NSError
        return nsError.domain == NSURLErrorDomain && nsError.code == NSURLErrorCancelled
    }

    private func recordObservedServerClock(from response: HTTPURLResponse, observedAtLocalMs: UInt64) {
        guard let rawDateHeader = response.value(forHTTPHeaderField: "Date"),
              let parsedDate = Self.parseHTTPDate(rawDateHeader)
        else {
            return
        }
        let serverEpochMs = Self.epochMs(for: parsedDate)
        recordObservedServerClock(
            serverEpochMs: serverEpochMs,
            observedAtLocalMs: observedAtLocalMs,
            observedAtMonotonicMs: currentMonotonicMs(),
            source: .httpDateFallback
        )
    }

    private func recordObservedServerClock(
        serverEpochMs: UInt64,
        observedAtLocalMs: UInt64,
        observedAtMonotonicMs: UInt64,
        source: ServerClockObservationSource
    ) {
        guard serverEpochMs > 0 else { return }
        serverClockQueue.sync {
            let existing = observedServerClock
                ?? Self.sharedObservedServerClock(for: serverClockCacheKey)
            if source == .httpDateFallback,
               existing?.source == .authoritativeTimeEndpoint {
                observedServerClock = existing
                return
            }
            let clock = ObservedServerClock(
                serverEpochMs: serverEpochMs,
                observedLocalEpochMs: observedAtLocalMs,
                observedMonotonicMs: observedAtMonotonicMs,
                source: source
            )
            observedServerClock = clock
            Self.setSharedObservedServerClock(clock, for: serverClockCacheKey)
        }
    }

    private static func parseHTTPDate(_ rawValue: String) -> Date? {
        let trimmed = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        let formats = [
            "EEE',' dd MMM yyyy HH':'mm':'ss zzz",
            "EEEE',' dd-MMM-yy HH':'mm':'ss zzz",
            "EEE MMM d HH':'mm':'ss yyyy"
        ]
        for format in formats {
            let formatter = DateFormatter()
            formatter.locale = Locale(identifier: "en_US_POSIX")
            formatter.timeZone = TimeZone(secondsFromGMT: 0)
            formatter.dateFormat = format
            if let parsed = formatter.date(from: trimmed) {
                return parsed
            }
        }
        return nil
    }

    private func currentEpochMs() -> UInt64 {
        currentTimeMilliseconds()
    }

    private func currentMonotonicMs() -> UInt64 {
        currentMonotonicMilliseconds()
    }

    private static func epochMs(for date: Date) -> UInt64 {
        let millis = date.timeIntervalSince1970 * 1_000
        if millis < 0 {
            return 0
        }
        return UInt64(millis.rounded())
    }

    private static func serverClockCacheKey(for baseURL: URL) -> String {
        let scheme = baseURL.scheme?.lowercased() ?? "https"
        let host = baseURL.host?.lowercased() ?? baseURL.absoluteString.lowercased()
        if let port = baseURL.port {
            return "\(scheme)://\(host):\(port)"
        }
        return "\(scheme)://\(host)"
    }

    private static func sharedObservedServerClock(for key: String) -> ObservedServerClock? {
        sharedServerClockQueue.sync { sharedObservedServerClocks[key] }
    }

    private static func setSharedObservedServerClock(_ clock: ObservedServerClock, for key: String) {
        sharedServerClockQueue.sync {
            sharedObservedServerClocks[key] = clock
        }
    }

    private func rejectCode(from response: HTTPURLResponse) -> String? {
        guard let raw = response
            .value(forHTTPHeaderField: "x-iroha-reject-code")?
            .trimmingCharacters(in: .whitespacesAndNewlines),
            !raw.isEmpty
        else {
            return nil
        }
        // Only the authoritative Torii response header has reject-code
        // provenance. Error-envelope fields remain diagnostic message data:
        // a proxy can synthesize arbitrary JSON and must never make a POST
        // rejection definitive or a status 404 prove canonical absence.
        return raw
    }

    private static func trimErrorBodyText(_ text: String, maxLength: Int = 512) -> String {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.count > maxLength else { return trimmed }
        let index = trimmed.index(trimmed.startIndex, offsetBy: maxLength)
        return "\(trimmed[..<index])..."
    }

    private static func extractErrorMessage(from jsonObject: Any) -> String? {
        if let text = jsonObject as? String {
            let trimmed = trimErrorBodyText(text)
            return trimmed.isEmpty ? nil : trimmed
        }
        if let list = jsonObject as? [Any] {
            for value in list {
                if let nested = extractErrorMessage(from: value) {
                    return nested
                }
            }
            return nil
        }
        guard let object = jsonObject as? [String: Any] else { return nil }
        let candidateKeys = [
            "message",
            "error",
            "errors",
            "detail",
            "details",
            "reason",
            "rejection_reason",
            "description"
        ]
        var caseInsensitiveValues: [String: Any] = [:]
        for (key, value) in object {
            let normalized = key.lowercased()
            if caseInsensitiveValues[normalized] == nil {
                caseInsensitiveValues[normalized] = value
            }
        }
        for key in candidateKeys {
            guard let value = caseInsensitiveValues[key] else { continue }
            if let nested = extractErrorMessage(from: value) {
                return nested
            }
        }
        return nil
    }

    private static func httpStatusMessage(response: HTTPURLResponse, responseBody: Data?) -> String {
        let defaultMessage = HTTPURLResponse.localizedString(forStatusCode: response.statusCode)
        guard let responseBody, !responseBody.isEmpty else { return defaultMessage }
        if let jsonObject = try? JSONSerialization.jsonObject(with: responseBody, options: []) {
            if let detail = extractErrorMessage(from: jsonObject), !detail.isEmpty {
                return detail
            }
            if JSONSerialization.isValidJSONObject(jsonObject),
               let compact = try? JSONSerialization.data(withJSONObject: jsonObject, options: [.sortedKeys]),
               let jsonText = String(data: compact, encoding: .utf8) {
                let detail = trimErrorBodyText(jsonText)
                if !detail.isEmpty {
                    return detail
                }
            }
        }
        if let text = String(data: responseBody, encoding: .utf8) {
            let detail = trimErrorBodyText(text)
            if !detail.isEmpty {
                return detail
            }
        }
        let byteLimit = 256
        let hex = responseBody.prefix(byteLimit).map { String(format: "%02x", $0) }.joined()
        if !hex.isEmpty {
            return responseBody.count > byteLimit ? "body_hex=\(hex)..." : "body_hex=\(hex)"
        }
        return defaultMessage
    }

    private func ensureStatus(_ response: HTTPURLResponse,
                              in range: Range<Int>,
                              responseBody: Data? = nil) throws {
        guard range.contains(response.statusCode) else {
            throw apiError(response, responseBody: responseBody)
        }
    }

    private func ensureStatus(_ response: HTTPURLResponse,
                              equals code: Int,
                              responseBody: Data? = nil,
                              sensitiveValue: String? = nil) throws {
        guard response.statusCode == code else {
            throw apiError(response, responseBody: responseBody, sensitiveValue: sensitiveValue)
        }
    }

    /// The `.api` error for a non-success response, parsed from Torii's
    /// `{code, message, details}` envelope when the body is one.
    private func apiError(_ response: HTTPURLResponse,
                          responseBody: Data?,
                          sensitiveValue: String? = nil) -> ToriiClientError {
        let error = ToriiAPIError.parse(
            status: response.statusCode,
            body: responseBody,
            rejectCode: rejectCode(from: response)
        ) {
            Self.httpStatusMessage(response: response, responseBody: responseBody)
        }
        return .api(error.redacting(sensitiveValue))
    }

    /// The `.api` error for a failure whose body must not be interpreted:
    /// only the status and the authoritative reject-code header are kept.
    private func statusOnlyAPIError(_ response: HTTPURLResponse) -> ToriiClientError {
        .api(ToriiAPIError(
            status: response.statusCode,
            message: HTTPURLResponse.localizedString(forStatusCode: response.statusCode),
            rejectCode: rejectCode(from: response)
        ))
    }

    private static func redacting(_ value: String?, sensitiveValue: String?) -> String? {
        guard let value,
              let sensitiveValue,
              !sensitiveValue.isEmpty else {
            return value
        }
        return value.replacingOccurrences(of: sensitiveValue, with: "<redacted>")
    }

    private func ensureResponseMediaType(
        _ response: HTTPURLResponse,
        equals expected: String
    ) throws {
        guard let rawValue = response.value(forHTTPHeaderField: "Content-Type") else {
            throw ToriiClientError.invalidPayload(
                "response Content-Type must be \(expected)"
            )
        }
        // Foundation comma-folds repeated Content-Type fields. Content-Type is a
        // singleton representation header, so reject both repeated equal values
        // and conflicting values instead of selecting one implicitly.
        guard Self.isUnambiguousMediaType(rawValue, expected: expected) else {
            throw ToriiClientError.invalidPayload(
                "response Content-Type must be one \(expected) media type"
            )
        }
    }

    private static func isUnambiguousMediaType(
        _ rawValue: String,
        expected: String
    ) -> Bool {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(rawValue.unicodeScalars.count)
        for scalar in rawValue.unicodeScalars {
            guard scalar.value <= UInt8.max else { return false }
            bytes.append(UInt8(scalar.value))
        }
        guard !bytes.contains(UInt8(ascii: ",")) else { return false }

        let expectedBytes = Array(expected.utf8)
        var index = 0
        func skipOWS() {
            while index < bytes.count && (bytes[index] == 0x20 || bytes[index] == 0x09) {
                index += 1
            }
        }
        func isToken(_ byte: UInt8) -> Bool {
            switch byte {
            case 0x30...0x39, 0x41...0x5A, 0x61...0x7A,
                 0x21, 0x23, 0x24, 0x25, 0x26, 0x27, 0x2A, 0x2B,
                 0x2D, 0x2E, 0x5E, 0x5F, 0x60, 0x7C, 0x7E:
                return true
            default:
                return false
            }
        }
        func isQuotedText(_ byte: UInt8) -> Bool {
            byte == 0x09 || (0x20...0x21).contains(byte)
                || (0x23...0x5B).contains(byte) || (0x5D...0x7E).contains(byte)
                || (0x80...0xFF).contains(byte)
        }
        func isQuotedPair(_ byte: UInt8) -> Bool {
            byte == 0x09 || (0x20...0x7E).contains(byte) || (0x80...0xFF).contains(byte)
        }

        skipOWS()
        guard index + expectedBytes.count <= bytes.count else { return false }
        for offset in expectedBytes.indices {
            let actual = bytes[index + offset]
            let folded = (0x41...0x5A).contains(actual) ? actual + 0x20 : actual
            guard folded == expectedBytes[offset] else { return false }
        }
        index += expectedBytes.count
        skipOWS()
        while index < bytes.count {
            guard bytes[index] == UInt8(ascii: ";") else { return false }
            index += 1
            skipOWS()
            let nameStart = index
            while index < bytes.count && isToken(bytes[index]) { index += 1 }
            guard index > nameStart,
                  index < bytes.count,
                  bytes[index] == UInt8(ascii: "=") else { return false }
            index += 1
            guard index < bytes.count else { return false }
            if bytes[index] == UInt8(ascii: "\"") {
                index += 1
                var closed = false
                while index < bytes.count {
                    let byte = bytes[index]
                    if byte == UInt8(ascii: "\"") {
                        index += 1
                        closed = true
                        break
                    }
                    if byte == UInt8(ascii: "\\") {
                        index += 1
                        guard index < bytes.count, isQuotedPair(bytes[index]) else { return false }
                    } else if !isQuotedText(byte) {
                        return false
                    }
                    index += 1
                }
                guard closed else { return false }
            } else {
                let valueStart = index
                while index < bytes.count && isToken(bytes[index]) { index += 1 }
                guard index > valueStart else { return false }
            }
            skipOWS()
        }
        return true
    }

    private func data(for request: URLRequest,
                      acceptedStatus: Range<Int> = 200..<300,
                      allowEmptyBody: Bool = false,
                      rejectRedirects: Bool = true) async throws -> Data {
        let (data, response) = try await send(request, rejectRedirects: rejectRedirects)
        try ensureStatus(response, in: acceptedStatus, responseBody: data)
        if data.isEmpty && !allowEmptyBody {
            throw ToriiClientError.emptyBody
        }
        return data
    }

    private func decodeUTF8String(from data: Data, context: String) throws -> String {
        guard let text = String(data: data, encoding: .utf8) else {
            throw ToriiClientError.invalidPayload("\(context) response is not valid UTF-8.")
        }
        return text
    }

    private func responseBodyDescriptor(_ data: Data) -> String {
        let digest = Data(SHA256.hash(data: data)).hexEncodedString()
        return "body_len=\(data.count) body_sha256=\(digest)"
    }

    private func decodeJSON<T: Decodable>(_ type: T.Type, from data: Data) throws -> T {
        do {
            let decoder = JSONDecoder()
            decoder.userInfo[exactJSONNumberLexemesUserInfoKey] =
                try ExactJSONNumberLexemeScanner.scan(data)
            return try decoder.decode(T.self, from: data)
        } catch {
            throw ToriiClientError.decoding(error)
        }
    }

    private func encodePathComponent(_ value: String) -> String {
        var allowed = CharacterSet.urlPathAllowed
        allowed.remove(charactersIn: "/:@?&=#%")
        return value.addingPercentEncoding(withAllowedCharacters: allowed) ?? value
    }

    private func encodeAccountIdPath(_ accountId: String) throws -> String {
        let canonical = try normalizeToriiAccountIdQueryValue(accountId, field: "accountId")
        return encodePathComponent(canonical)
    }

    private func canonicalizeUaidLiteral(_ literal: String) throws -> String {
        let exact = try requireToriiExactNonEmptyQueryValue(literal, field: "uaid")
        let lowercaseHex = CharacterSet(charactersIn: "0123456789abcdef")
        let digest = exact.hasPrefix("uaid:") ? String(exact.dropFirst(5)) : ""
        guard exact.count == 69,
              digest.count == 64,
              digest.unicodeScalars.allSatisfy({ lowercaseHex.contains($0) }) else {
            throw ToriiClientError.invalidPayload(
                "uaid must be an exact canonical uaid:<64 lowercase hex> literal."
            )
        }
        guard let last = digest.last,
              "13579bdf".contains(last) else {
            throw ToriiClientError.invalidPayload("uaid must have least significant bit set to 1.")
        }
        return exact
    }

    private func postAuthenticatedGovernanceJSON<Request: Encodable, Response: Decodable>(
        path: String,
        body: Request,
        canonicalAuth: ToriiCanonicalRequestAuth,
        responseType: Response.Type
    ) async throws -> Response {
        let payload = try JSONEncoder().encode(body)
        let request = try makeCanonicalAccountRequest(
            path: path,
            method: .post,
            body: payload,
            headers: ["Content-Type": "application/json"],
            canonicalAuth: canonicalAuth
        )
        let (data, response) = try await send(request)
        try ensureStatus(response, in: 200..<300, responseBody: data)
        return try decodeJSON(Response.self, from: data)
    }

    private func postGovernanceBallotJSON<Request: Encodable, Response: Decodable>(
        path: String,
        body: Request,
        networkId: NetworkId,
        authority: String,
        canonicalAuth: ToriiCanonicalRequestAuth,
        responseType: Response.Type
    ) async throws -> Response {
        guard let localSigningContext else {
            throw ToriiClientError.invalidPayload(
                "governance ballot drafting requires an immutable ToriiLocalSigningContext"
            )
        }
        guard networkId == localSigningContext.networkId else {
            throw ToriiClientError.invalidPayload(
                "governance ballot network_id must equal the client's exact NetworkId"
            )
        }
        let canonicalAuthority: String
        let canonicalPrincipal: String
        do {
            let parsedAuthority = try exactCanonicalToriiAccountAddress(authority)
            canonicalAuthority = try parsedAuthority.address.toI105(
                networkPrefix: parsedAuthority.chainDiscriminant
            )
            let parsedPrincipal = try exactCanonicalToriiAccountAddress(canonicalAuth.accountId)
            canonicalPrincipal = try parsedPrincipal.address.toI105(
                networkPrefix: parsedPrincipal.chainDiscriminant
            )
        } catch {
            throw ToriiClientError.invalidPayload(
                "governance ballot authority and canonicalAuth.accountId must be canonical I105 account ids"
            )
        }
        guard canonicalAuthority == authority,
              canonicalPrincipal == canonicalAuth.accountId,
              canonicalAuthority == canonicalPrincipal else {
            throw ToriiClientError.invalidPayload(
                "canonicalAuth.accountId must equal governance ballot authority"
            )
        }

        let payload = try JSONEncoder().encode(body)
        var request = try makeRequest(
            path: path,
            method: .post,
            body: payload,
            headers: ["Content-Type": "application/json"]
        )
        try applyCanonicalAuth(
            canonicalAuth,
            to: &request,
            body: payload,
            expectedNetworkId: networkId
        )
        let (data, response) = try await send(request)
        try ensureStatus(response, in: 200..<300, responseBody: data)
        return try decodeJSON(Response.self, from: data)
    }

    private func getGovernanceJSON<Response: Decodable>(path: String,
                                                        queryItems: [URLQueryItem]? = nil,
                                                        canonicalAuth: ToriiCanonicalRequestAuth,
                                                        responseType: Response.Type) async throws -> Response {
        let request = try makeCanonicalAccountRequest(
            path: path, queryItems: queryItems, canonicalAuth: canonicalAuth
        )
        let (data, response) = try await send(request)
        try ensureStatus(response, in: 200..<300, responseBody: data)
        return try decodeJSON(Response.self, from: data)
    }

    /// Decode one `/v1/events/sse` event; a terminal `stream_error` event throws.
    private func parseEventMessage(from lines: [String], context: String) throws -> ToriiEventMessage<ToriiEvent>? {
        guard let parsed = try parseServerSentEvent(from: lines) else {
            return nil
        }
        try throwIfTerminalStreamError(parsed, context: context)
        guard let payloadString = parsed.data else {
            return nil
        }
        guard let payloadData = payloadString.data(using: .utf8) else {
            throw ToriiClientError.invalidPayload("SSE payload is not valid UTF-8.")
        }
        return ToriiEventMessage(event: try decodeJSON(ToriiEvent.self, from: payloadData),
                                 eventName: parsed.eventName,
                                 eventId: parsed.id,
                                 retryHintMilliseconds: parsed.retry,
                                 rawEvent: parsed.raw)
    }

    private struct ToriiSseParsedEvent {
        let eventName: String?
        let data: String?
        let id: String?
        let retry: Int?
        let raw: String
    }

    private struct ToriiStreamErrorCodingKey: CodingKey {
        let stringValue: String
        let intValue: Int? = nil

        init?(stringValue: String) {
            self.stringValue = stringValue
        }

        init?(intValue: Int) {
            return nil
        }
    }

    private struct ToriiStreamErrorEnvelope: Decodable {
        let code: String
        let message: String
        let droppedMessages: UInt64?
        let replayAvailable: Bool

        private enum CodingKeys: String, CodingKey {
            case code
            case message
            case droppedMessages = "dropped_messages"
            case replayAvailable = "replay_available"
        }

        init(from decoder: Decoder) throws {
            let dynamic = try decoder.container(keyedBy: ToriiStreamErrorCodingKey.self)
            let expected = Set(["code", "message", "dropped_messages", "replay_available"])
            let actual = Set(dynamic.allKeys.map(\.stringValue))
            guard actual == expected else {
                throw DecodingError.dataCorrupted(
                    .init(codingPath: decoder.codingPath,
                          debugDescription: "A v1 stream error must contain exactly code, message, dropped_messages, and replay_available.")
                )
            }

            let container = try decoder.container(keyedBy: CodingKeys.self)
            code = try container.decode(String.self, forKey: .code)
            message = try container.decode(String.self, forKey: .message)
            droppedMessages = try container.decodeIfPresent(UInt64.self, forKey: .droppedMessages)
            replayAvailable = try container.decode(Bool.self, forKey: .replayAvailable)

            guard Self.isExactText(code, token: true) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .code,
                    in: container,
                    debugDescription: "Stream error code must be a non-empty exact token."
                )
            }
            guard Self.isExactText(message, token: false) else {
                throw DecodingError.dataCorruptedError(
                    forKey: .message,
                    in: container,
                    debugDescription: "Stream error message must be non-empty exact text."
                )
            }
        }

        private static func isExactText(_ value: String, token: Bool) -> Bool {
            guard !value.isEmpty,
                  value.trimmingCharacters(in: .whitespacesAndNewlines) == value,
                  !value.unicodeScalars.contains(where: CharacterSet.controlCharacters.contains) else {
                return false
            }
            return !token || !value.unicodeScalars.contains(where: CharacterSet.whitespacesAndNewlines.contains)
        }
    }

    private func throwIfTerminalStreamError(_ parsed: ToriiSseParsedEvent,
                                            context: String) throws {
        guard parsed.eventName == "stream_error" else {
            return
        }
        guard let payloadString = parsed.data,
              let payloadData = payloadString.data(using: .utf8) else {
            throw ToriiClientError.invalidPayload("\(context) terminal stream error must contain UTF-8 JSON data.")
        }

        do {
            try StrictJSONDuplicateKeyRejector.rejectDuplicateObjectKeys(in: payloadData)
        } catch {
            throw ToriiClientError.invalidPayload(
                "\(context) terminal stream error must be valid JSON without duplicate object keys."
            )
        }

        let envelope: ToriiStreamErrorEnvelope
        do {
            envelope = try JSONDecoder().decode(ToriiStreamErrorEnvelope.self, from: payloadData)
        } catch {
            throw ToriiClientError.invalidPayload(
                "\(context) terminal stream error is malformed: \(ToriiClientError.describeDecodingError(error))"
            )
        }

        throw ToriiClientError.stream(
            ToriiStreamError(code: envelope.code,
                             message: envelope.message,
                             droppedMessages: envelope.droppedMessages,
                             replayAvailable: envelope.replayAvailable)
        )
    }

    private func parseServerSentEvent(from lines: [String]) throws -> ToriiSseParsedEvent? {
        guard !lines.isEmpty else { return nil }
        var dataChunks: [String] = []
        var eventName: String?
        var identifier: String?
        var retry: Int?

        for entry in lines {
            let trimmedEntry = entry.trimmingCharacters(in: .whitespaces)
            if trimmedEntry.hasPrefix(":") {
                continue
            }
            let components = entry.split(separator: ":", maxSplits: 1, omittingEmptySubsequences: false)
            let rawField = components.first.map(String.init) ?? ""
            let field = rawField.trimmingCharacters(in: .whitespaces)
            let value = components.count > 1 ? components[1].trimmingCharacters(in: .whitespaces) : ""
            switch field {
            case "data":
                dataChunks.append(value)
            case "event":
                eventName = value.isEmpty ? nil : value
            case "id":
                identifier = value.isEmpty ? nil : value
            case "retry":
                if let parsed = Int(value) {
                    retry = parsed
                }
            default:
                continue
            }
        }

        if dataChunks.isEmpty && eventName == nil && identifier == nil && retry == nil {
            return nil
        }

        let dataString = dataChunks.isEmpty ? nil : dataChunks.joined(separator: "\n")
        return ToriiSseParsedEvent(eventName: eventName,
                                   data: dataString,
                                   id: identifier,
                                   retry: retry,
                                   raw: lines.joined(separator: "\n"))
    }

    private func parseExplorerTransactionEvent(from lines: [String]) throws -> ToriiExplorerTransactionItem? {
        guard let parsed = try parseServerSentEvent(from: lines) else {
            return nil
        }
        guard let payloadString = parsed.data else {
            return nil
        }
        guard let payloadData = payloadString.data(using: .utf8) else {
            throw ToriiClientError.invalidPayload("SSE payload is not valid UTF-8.")
        }
        return try decodeJSON(ToriiExplorerTransactionItem.self, from: payloadData)
    }

    private func parseExplorerInstructionEvent(from lines: [String]) throws -> ToriiExplorerInstructionItem? {
        guard let parsed = try parseServerSentEvent(from: lines) else {
            return nil
        }
        guard let payloadString = parsed.data else {
            return nil
        }
        guard let payloadData = payloadString.data(using: .utf8) else {
            throw ToriiClientError.invalidPayload("SSE payload is not valid UTF-8.")
        }
        return try decodeJSON(ToriiExplorerInstructionItem.self, from: payloadData)
    }

    @discardableResult
    func runTask<T>(_ completion: @escaping (Result<T, Swift.Error>) -> Void,
                            operation: @Sendable @escaping () async throws -> T) -> Task<Void, Never> {
        runCompletionTask(operation: operation, completion: completion)
    }
}

private struct TransferSummaryDeduper {
    let limit: Int
    private var keys: Set<String> = []
    private var order: [String] = []

    init(limit: Int) {
        self.limit = limit
    }

    mutating func shouldYield(_ summary: ToriiExplorerTransferSummary) -> Bool {
        guard limit > 0 else {
            return true
        }
        let key = Self.makeKey(summary)
        if keys.contains(key) {
            return false
        }
        keys.insert(key)
        order.append(key)
        if keys.count > limit {
            let overflow = keys.count - limit
            for _ in 0..<overflow {
                guard let oldest = order.first else {
                    break
                }
                order.removeFirst()
                keys.remove(oldest)
            }
        }
        return true
    }

    private static func makeKey(_ summary: ToriiExplorerTransferSummary) -> String {
        "\(summary.transactionHash)|\(summary.instructionIndex)|\(summary.transferIndex)|\(summary.senderAccountId)|\(summary.receiverAccountId)|\(summary.assetDefinitionId)|\(summary.amount)"
    }
}

private struct CompletionBox<Value>: @unchecked Sendable {
    let completion: (Result<Value, Swift.Error>) -> Void

    func call(_ result: Result<Value, Swift.Error>) {
        completion(result)
    }
}

private struct SendableResult<Value>: @unchecked Sendable {
    let result: Result<Value, Swift.Error>
}

@discardableResult
private func runCompletionTask<Value>(operation: @Sendable @escaping () async throws -> Value,
                                      completion: @escaping (Result<Value, Swift.Error>) -> Void) -> Task<Void, Never> {
    let completionBox = CompletionBox(completion: completion)

    return Task {
        do {
            let value = try await operation()
            guard !Task.isCancelled else { return }
            let result = SendableResult(result: .success(value))
            await MainActor.run {
                completionBox.call(result.result)
            }
        } catch {
            guard !Task.isCancelled else { return }
            let result = SendableResult<Value>(result: .failure(error))
            await MainActor.run {
                completionBox.call(result.result)
            }
        }
    }
}

// MARK: - Collection queries

extension ToriiClient {
    /// Read one page of a collection with `POST <collection>/query`.
    ///
    /// The request is signed with `canonicalRequestAuth` when one is
    /// configured; anonymous reads see public dataspaces only.
    func fetchCollectionPage<Item: Decodable & Sendable>(
        route: ToriiCollectionRoute,
        query: ToriiListQuery,
        as itemType: Item.Type
    ) async throws -> ToriiPage<Item> {
        let body: Data
        do {
            body = try query.requestBody()
        } catch let error as ToriiListQueryError {
            throw ToriiClientError.invalidQuery(error)
        }
        let path = try collectionPath(for: route) + "/query"
        let headers = ["Content-Type": "application/json", "Accept": "application/json"]
        let request: URLRequest
        if let canonicalRequestAuth {
            request = try makeCanonicalAccountRequest(
                path: path,
                method: .post,
                body: body,
                headers: headers,
                canonicalAuth: canonicalRequestAuth
            )
        } else {
            request = try makeRequest(path: path, method: .post, body: body, headers: headers)
        }
        let (data, response) = try await send(request)
        try ensureStatus(response, in: 200..<300, responseBody: data)
        try ensureResponseMediaType(response, equals: "application/json")
        try rejectDuplicateJSONKeys(data, context: "collection page")
        let page = try decodeJSON(ToriiPage<Item>.self, from: data)
        if case let .uaid(uaid) = route, let rows = page.items as? [ToriiUaidManifestRecord] {
            let canonical = try canonicalizeUaidLiteral(uaid)
            guard rows.allSatisfy({ $0.manifest.uaid == canonical }) else {
                throw ToriiClientError.invalidPayload("Manifest rows must match the requested UAID.")
            }
        }
        return page
    }

    /// The URL path of a collection.
    func collectionPath(for route: ToriiCollectionRoute) throws -> String {
        switch route {
        case let .fixed(path):
            return path
        case let .account(accountId, suffix):
            return "/v1/accounts/\(try encodeAccountIdPath(accountId))/\(suffix)"
        case let .uaid(uaid):
            return "/v1/space-directory/uaids/\(encodePathComponent(try canonicalizeUaidLiteral(uaid)))/manifests"
        case let .assetDefinition(definitionId, suffix):
            let exact = try requireToriiExactNonEmptyQueryValue(definitionId, field: "assetDefinitionId")
            return "/v1/assets/\(encodePathComponent(exact))/\(suffix)"
        }
    }

    /// Validate and canonicalize an I105 account id literal; aliases are rejected
    /// because rows are keyed by the canonical id.
    func canonicalAccountIdLiteral(_ accountId: String, field: String) throws -> String {
        guard !accountId.contains("@") else {
            throw ToriiClientError.invalidPayload(
                "\(field) must be a canonical I105 account id; resolve aliases with resolveAccountAlias(_:) first."
            )
        }
        return try normalizeToriiAccountIdQueryValue(accountId, field: field)
    }
}
